/* ════════════════════════════════════════════════════════════════════
   Zenin Design System — Dual-Token Theme Architecture
   ────────────────────────────────────────────────────────────────────
   Color tokens live in two places:
     :root                       → dark theme (default)
     html.light-theme-active     → light theme (every color token mirrored)
   Components MUST reference `var(--token)`, never raw hex/rgba.
   Status, icon, and data-text tokens flip per-theme so text never
   becomes invisible. Add new colors here, not in components.
   ═══════════════════════════════════════════════════════════════════ */
:root {
  color-scheme: dark;
  /* ── Surfaces (dark — Brand v2 monochrome) ─────────────────────── */
  --color-bg-base:              #0A0A0A;
  --color-surface-card:         #111111;
  --color-surface-card-strong:  #141414;
  --color-surface-panel:        #111111;
  --color-surface-elevated:     #171717;
  --color-surface-depth:        #0A0A0A;
  --color-surface-hover:        rgba(255, 255, 255, 0.04);
  --color-surface-overlay:      rgba(10, 10, 10, 0.92);
  /* ── Borders (dark) ─────────────────────────────────────────────── */
  --color-border-subtle:        rgba(255, 255, 255, 0.06);
  --color-border-medium:        #262626;
  --color-border-strong:        #404040;
  --color-border-default:       var(--color-border-medium);
  /* ── Text (dark) ────────────────────────────────────────────────── */
  --color-text-primary:         #FFFFFF;
  --color-text-secondary:       #A3A3A3;
  --color-text-muted:           #9a9a9a;   /* AA 6.9:1 on #080808 */
  /* ── Sidebar nav semantic tokens (Brand v2 active/hover inversion) ── */
  --sidebar-active-bg:          #FFFFFF;
  --sidebar-active-text:        #111111;
  --sidebar-hover-bg:           rgba(255, 255, 255, 0.05);
  --sidebar-hover-text:         #FFFFFF;
  --sidebar-text:               #A3A3A3;
  --sidebar-text-muted:         #9a9a9a;
  --color-text-dim:             #808080;   /* disabled / AA 5.0:1 on #080808 */
  --color-text-inverse:         #0A0A0A;
  --color-text-danger:          #ef4444;
  /* ── Icons (dark — inherit text tokens) ─────────────────────────── */
  --color-icon-primary:         var(--color-text-primary);
  --color-icon-secondary:       var(--color-text-secondary);
  --color-icon-muted:           var(--color-text-muted);
  /* ── Interaction (replaces legacy --color-accent / brand) ───────── */
  --color-interactive:          #FFFFFF;                  /* primary fill    */
  --color-interactive-hover:    #E5E5E5;
  --color-interactive-soft:     rgba(255, 255, 255, 0.08);
  --color-focus:                #FFFFFF;                  /* focus ring      */
  --color-selected:             rgba(255, 255, 255, 0.08);
  --color-selected-strong:      rgba(255, 255, 255, 0.12);

  /* ── Design-audit semantic tokens (P0) ─────────────────────────── */
  --color-surface-row:          rgba(255, 255, 255, 0.02);
  --color-focus-ring:           #FFFFFF;
  --color-focus-ring-offset:    #0A0A0A;
  --control-height-compact:     34px;
  --control-height-standard:    40px;
  --control-height-touch:       44px;
  --type-page-title:            28px;
  --type-section-title:         18px;
  --type-card-title:            15px;
  --type-body:                  14px;
  --type-meta:                  12px;
  --type-label:                 11px;
  --type-metric:                28px;

  /* ── Status (semantic only — Brand v2) ──────────────────────────── */
  --color-success:              #10b981;
  --color-danger:               #ef4444;
  --color-warning:              #f59e0b;
  --color-green:                var(--color-success);
  --color-red:                  var(--color-danger);
  --color-amber:                var(--color-warning);
  --color-success-soft:         rgba(16, 185, 129, 0.14);
  --color-danger-soft:          rgba(239, 68, 68, 0.14);
  --color-warning-soft:         rgba(245, 158, 11, 0.14);
  /* ── Data-text aliases (monochrome + semantic only — Brand v2) ──── */
  --color-data-primary:         #FFFFFF;
  --color-data-secondary:       #A3A3A3;
  --color-data-muted:           #808080;
  --color-data-slate:           #A3A3A3;   /* alias of secondary — legacy  */
  --color-data-slate-bright:    #FFFFFF;   /* alias of primary  — legacy  */
  --color-data-slate-dim:       #808080;   /* alias of muted    — legacy  */
  --color-data-up:              var(--color-success);
  --color-data-green:           var(--color-success);
  --color-data-green-bright:    #34d399;
  --color-data-down:            var(--color-danger);
  --color-data-red:             var(--color-danger);
  --color-data-red-bright:      #f87171;
  --color-data-amber:           var(--color-warning);
  --color-data-amber-bright:    #fbbf24;
  --font-brand:    'Geist', 'Inter', -apple-system, sans-serif;
  --font-mono:     'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

  /* ── Density & Shape Tokens ─────────────────────────────────────── */
  --card-padding-compact:  16px;
  --card-padding-standard: 18px;
  --card-padding-large:    24px;
  --card-radius-compact:   3px;
  --card-radius-standard:  3px;
  --card-radius-large:     3px;
  --section-gap:    20px;
  --grid-gap:       16px;
  --control-height-sm: 34px;
  --control-height-md: 40px;
  --table-row-height:  52px;

  /* ── Spacing Scale (4px base) ──────────────────────────────────── */
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-10: 40px;
  --space-12: 48px;

  /* ── Font-size Scale (normalized: 11/12/14/16/18/22/32; 13·14·15 muddle
       collapsed to a single 14px body step for clear hierarchy) ──────── */
  --fs-xs:       11px;   /* metadata / captions floor — no longer sub-11 */
  --fs-sm:       12px;   /* secondary metadata */
  --fs-12:       12px;   /* canonical 12px step — formerly an off-scale orphan */
  --fs-body:     14px;   /* canonical body (merged from 13px) */
  --fs-base:     14px;   /* alias of --fs-body */
  --fs-md:       14px;   /* merged into body — removes the 15px orphan step */
  --fs-lg:       16px;
  --fs-xl:       18px;
  --fs-2xl:      22px;
  --fs-display:  32px;

  /* ── Font-weight Scale (Brand v2: headings use 500/600 only) ─────── */
  --fw-regular:   400;
  --fw-medium:    500;
  --fw-semibold:  600;
  /* NOTE: 700/800/900 are intentionally NOT tokenized. Brandv2.md L188
     restricts headings to font-medium/font-semibold. Existing heavier
     weights are legacy drift to be migrated, not endorsed. */

  /* ── Density Modes (row heights) ───────────────────────────────── */
  --row-height-compact:     28px;
  --row-height-cozy:        32px;
  --row-height-comfortable: 40px;

  /* ── Elevation Ramp ─────────────────────────────────────────────── */
  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.32);
  --shadow-2: 0 6px 14px rgba(0, 0, 0, 0.44);
  --shadow-3: 0 24px 64px rgba(0, 0, 0, 0.62);

  /* ── Responsive Breakpoint Scale ───────────────────────────────── */
  --bp-sm:  640px;
  --bp-md:  768px;
  --bp-lg:  1024px;
  --bp-xl:  1280px;
  --bp-2xl: 1500px;

  /* ── Radius Scale (canonical 2/4/8/12/16) ──────────────────────── */
  --radius-sm:    2px;
  --radius-md:    4px;
  --radius-lg:    8px;
  --radius-xl:    12px;
  --radius-2xl:   16px;
  --radius-full:  999px;
  /* Legacy card-radius-* tokens retained as aliases (all were 3px);
     migrate consumers to --radius-* over time. */
  --card-radius-compact:   var(--radius-md);
  --card-radius-standard:  var(--radius-md);
  --card-radius-large:     var(--radius-md);

  /* ── Z-index Layers (semantic stacking contract) ──────────────────
     Consumers MUST use these instead of raw integers. Order enforces:
     base < dropdown < sticky < overlay < modal < toast < tooltip.    */
  --z-base:      1;
  --z-dropdown:  100;
  --z-sticky:    140;
  --z-overlay:   1000;
  --z-modal:     1300;
  --z-toast:     2000;
  --z-tooltip:   2100;

  /* ── Motion (duration + easing) ─────────────────────────────────── */
  --duration-instant: 80ms;
  --duration-fast:    120ms;   /* hover, small state changes */
  --duration-base:    180ms;   /* open / close (modals, drawers) */
  --duration-slow:    240ms;
  --ease-standard:    cubic-bezier(0.4, 0, 0.2, 1);
  --ease-in:          cubic-bezier(0.4, 0, 1, 1);
  --ease-out:         cubic-bezier(0, 0, 0.2, 1);

  /* ── Sidebar metrics ────────────────────────────────────────────  */
  --sidebar-width:        270px;
  --sidebar-width-collapsed: 100px;
  --sidebar-collapse-bp:  1100px;

  font-family: var(--font-brand);
  background:  var(--color-bg-base);
  color: var(--color-text-primary);
  font-size: 81.25%; /* 13px base — dense institutional scale (was 90%/14.4px) */
}

.cardCompact {
  padding: var(--card-padding-compact);
  border-radius: var(--card-radius-compact);
}

.cardStandard {
  padding: var(--card-padding-standard);
  border-radius: var(--card-radius-standard);
}

.cardLarge {
  padding: var(--card-padding-large);
  border-radius: var(--card-radius-large);
}

.metricCard {
  min-height: 84px;
  max-height: 110px;
}

.dashboardPanel {
  padding: var(--card-padding-standard);
  border-radius: var(--card-radius-standard);
}

.chartPanel {
  padding: var(--card-padding-large);
  border-radius: var(--card-radius-large);
}

* {
  box-sizing: border-box;
}

/* ── Overflow remediation (systemic) ──────────────────────────────────
   Flex/grid items default to min-width: auto, which prevents them from
   shrinking below their content's intrinsic size and causes horizontal
   page overflow with long tickers, numbers, URLs, headlines, and emails.
   Forcing min-width: 0 lets the item shrink so wrapping/truncation can
   engage. We scope it to the common layout containers so individual
   components don't need to repeat the rule. */
main * {
  min-width: 0;
}

/* Long text wraps gracefully instead of breaking the layout. */
p, li, span, td, th, label, button, a {
  overflow-wrap: anywhere;
  word-break: break-word;
}

/* Elements explicitly marked as truncated keep ellipsis. */
.truncate, .ellipsis {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Financial numeric typography (Phase 5 standard) ──────────────────
   Apply `.numeric` to every financial figure: mono stack + tabular
   figures + right alignment. This guarantees decimal/column alignment
   across all financial surfaces (Phase 5 of the design-system plan).  */
.numeric,
.num {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
}
.numeric--right,
.num-right {
  text-align: right;
}
.numeric--positive,
.num-positive {
  color: var(--color-success);
}
.numeric--negative,
.num-negative {
  color: var(--color-danger);
}

/* ── Tables: prevent layout blow-out ──────────────────────────────────
   Tables use auto layout by default, which sizes columns to content and
   overflows on long values. Fixed layout + horizontal scroll on the
   wrapper keeps tables readable at any width. Sticky headers stay put. */
table {
  table-layout: auto;
  border-collapse: collapse;
  width: 100%;
}

thead th {
  position: sticky;
  top: 0;
  z-index: 2;
}

body {
  margin: 0;
  height: 100%;
  background: var(--color-bg-base);
  color: var(--color-text-primary);
  overflow: hidden;
}

html,
body,
#root {
  height: 100%;
  color-scheme: dark;
  background: var(--color-bg-base);
  font-synthesis: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4 {
  text-wrap: balance;
}

p, .description, .helper-text {
  text-wrap: pretty;
}

:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

/* ── Perps calculator: decision workspace, not an empty terminal canvas ── */
.perps-calculator-module {
  display: grid;
  gap: var(--space-5);
  min-width: 0;
}
.perps-calculator-module .workspace-page-header { padding-top: 0; }
.perps-header-status { color: var(--color-text-secondary); font-size: var(--fs-xs); }
.perps-tab-strip {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  border-bottom: 1px solid var(--color-border-subtle);
  scrollbar-width: thin;
}
.perps-tab { flex: 0 0 auto; min-height: 40px; padding-inline: 14px; border: 1px solid transparent; border-bottom: 0; border-radius: var(--radius-md) var(--radius-md) 0 0; background: transparent; color: var(--color-text-secondary); font-weight: var(--fw-semibold); cursor: pointer; }
.perps-tab:hover { color: var(--color-text-primary); background: var(--color-surface-hover); }
.perps-tab.active { color: var(--color-text-primary); border-color: var(--color-border-medium); background: var(--color-surface-card); }
.perps-tab-content { min-width: 0; }
.perps-calc-grid { display: grid; grid-template-columns: minmax(340px, .9fr) minmax(0, 1.1fr); gap: var(--space-5); align-items: start; }
.perps-input-panel,
.perps-result-panel,
.perps-arb-venue,
.perps-fee-table-wrap,
.perps-venue-matrix {
  background: var(--color-surface-card);
  border-color: var(--color-border-subtle);
  box-shadow: none;
}
.perps-input-panel,
.perps-result-panel { min-height: 0; }
.perps-result-panel { display: grid; align-content: start; gap: var(--space-4); }
.perps-field-input { background: var(--color-surface-elevated); color: var(--color-text-primary); border-color: var(--color-border-medium); }
.perps-field-input:focus { border-color: var(--color-focus); outline: 2px solid var(--color-focus); outline-offset: 1px; }
.perps-field-label { color: var(--color-text-secondary); }
.perps-recalc-btn { min-height: var(--control-height-standard); background: var(--color-text-primary); color: var(--color-bg-base); border-color: var(--color-text-primary); }
.perps-recalc-btn:hover:not(:disabled) { background: var(--color-info); border-color: var(--color-info); }
.perps-latency-empty { min-height: 0; border-color: var(--color-info-border); background: var(--color-info-soft); }
.perps-methodology-note { border: 1px solid var(--color-border-subtle); border-radius: var(--radius-md); padding: var(--space-3) var(--space-4); color: var(--color-text-secondary); background: var(--color-surface-row); }
.perps-methodology-note strong { color: var(--color-text-primary); }
.perps-arb-venues { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-5); }
.perps-arb-venue { min-height: 0; }
.perps-fee-comparator { display: grid; gap: var(--space-4); max-width: 1120px; }
.perps-data-table th { color: var(--color-text-secondary); background: var(--color-surface-row); }
.perps-data-table td { color: var(--color-text-secondary); }
.perps-data-table td:first-child { color: var(--color-text-primary); }
.perps-fee-footer { color: var(--color-text-secondary); background: var(--color-surface-row); }
.perps-save-feedback { color: var(--color-success); background: var(--color-success-soft); border-color: var(--color-success-border); }
body.light-theme-active .perps-calculator-module .perps-input-panel,
body.light-theme-active .perps-calculator-module .perps-result-panel,
body.light-theme-active .perps-calculator-module .perps-arb-venue,
body.light-theme-active .perps-calculator-module .perps-venue-matrix,
body.light-theme-active .perps-calculator-module .perps-fee-table-wrap { background: var(--color-surface-card); }
body.light-theme-active .perps-calculator-module .perps-field-input { background: #fff; color: var(--color-text-primary); }
@media (max-width: 960px) {
  .perps-calc-grid, .perps-arb-venues { grid-template-columns: 1fr; }
}
@media (max-width: 639px) {
  .perps-calculator-module { gap: var(--space-4); }
  .perps-calculator-module .workspace-page-header__actions { width: 100%; }
  .perps-calculator-module .workspace-page-header__actions button { width: 100%; }
  .perps-result-tiles.four { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* ═══════════════════════════════════════════════════════════════════════
   Workspace hierarchy system — single final authority for responsive shell,
   status color, and shared dashboard primitives. This intentionally sits last
   while legacy module rules are migrated; it prevents breakpoint collisions.
   ═══════════════════════════════════════════════════════════════════════ */
:root {
  --workspace-gutter: 24px;
  --workspace-max-width: none;
  --mobile-header-safe-space: calc(env(safe-area-inset-top, 0px) + 72px);
  --color-info: #38bdf8;
  --color-info-soft: rgba(56, 189, 248, 0.14);
  --color-info-border: rgba(56, 189, 248, 0.42);
  --color-stale: #fbbf24;
  --color-stale-soft: rgba(251, 191, 36, 0.14);
  --color-stale-border: rgba(251, 191, 36, 0.42);
  --color-success-border: rgba(52, 211, 153, 0.45);
  --color-danger-border: rgba(248, 113, 113, 0.48);
  --color-warning-border: rgba(251, 191, 36, 0.48);
}

body.light-theme-active {
  --color-info: #0369a1;
  --color-info-soft: rgba(3, 105, 161, 0.10);
  --color-info-border: rgba(3, 105, 161, 0.35);
  --color-stale: #a16207;
  --color-stale-soft: rgba(161, 98, 7, 0.11);
  --color-stale-border: rgba(161, 98, 7, 0.36);
  --color-success-border: rgba(5, 150, 105, 0.36);
  --color-danger-border: rgba(220, 38, 38, 0.36);
  --color-warning-border: rgba(217, 119, 6, 0.38);
}

.app-layout {
  width: 100%;
  max-width: none;
  margin: 0;
}

.main-content {
  padding: 16px var(--workspace-gutter) 48px;
}

.view-container,
.workspace-page,
.portfolio-module,
.analytics-layout,
.intelligence-workspace,
.journal-v2,
.tax-workbench,
.options-calculator-layout {
  width: min(100%, var(--workspace-max-width));
  max-width: none;
  margin-inline: auto;
}

/* Normal product pages should use the canvas, not a decorative grid. */
.analytics-layout,
.home-exec {
  background-image: none;
}

.workspace-page-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--space-6);
  padding-block: var(--space-3) var(--space-5);
  border-bottom: 1px solid var(--color-border-subtle);
}

.workspace-page-header__copy { min-width: 0; }
.workspace-page-header__eyebrow,
.workspace-context-rail__heading,
.workspace-attention-list__tone {
  color: var(--color-text-muted);
  font-size: var(--fs-xs);
  font-weight: var(--fw-semibold);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.workspace-page-header h1 { margin: 4px 0 0; color: var(--color-text-primary); font-size: var(--fs-display); line-height: 1.08; letter-spacing: -.025em; }
.workspace-page-header p { max-width: 70ch; margin: var(--space-2) 0 0; color: var(--color-text-secondary); font-size: var(--fs-body); line-height: 1.55; }
.workspace-page-header__status { margin-top: var(--space-3); }
.workspace-page-header__actions { display: flex; align-items: center; justify-content: flex-end; gap: var(--space-2); flex-wrap: wrap; }
.workspace-page-header__primary > button { min-height: var(--control-height-standard); }
.workspace-page-header__secondary { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }

.workspace-metric-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 0;
  border-block: 1px solid var(--color-border-subtle);
}
.workspace-metric-strip__item {
  min-width: 0;
  padding: var(--space-4) var(--space-5);
  border-inline-start: 1px solid var(--color-border-subtle);
  background: transparent;
}
.workspace-metric-strip__item:first-child { border-inline-start: 0; }
.workspace-metric-strip__item.is-featured { background: var(--color-surface-hover); }
.workspace-metric-strip__label-row { display: flex; align-items: center; gap: 6px; color: var(--color-text-muted); font-size: var(--fs-xs); font-weight: var(--fw-semibold); letter-spacing: .06em; text-transform: uppercase; }
.workspace-metric-strip__item strong { display: block; margin-top: 6px; color: var(--color-text-primary); font-size: var(--fs-xl); font-variant-numeric: tabular-nums; white-space: nowrap; }
.workspace-metric-strip__item small { display: block; margin-top: 4px; color: var(--color-text-secondary); font-size: var(--fs-xs); }
.workspace-metric-strip__item.tone-success strong { color: var(--color-success); }
.workspace-metric-strip__item.tone-risk strong { color: var(--color-danger); }
.workspace-metric-strip__item.tone-warning strong,
.workspace-metric-strip__item.tone-stale strong { color: var(--color-stale); }
.workspace-metric-strip__item.tone-info strong { color: var(--color-info); }

.metric-help { display: inline-grid; place-items: center; width: 22px; height: 22px; padding: 0; border: 0; border-radius: var(--radius-full); background: transparent; color: var(--color-text-secondary); cursor: help; }
.metric-help:hover, .metric-help:focus-visible { color: var(--color-info); background: var(--color-info-soft); outline: 2px solid var(--color-focus); outline-offset: 2px; }
.metric-help__content { display: grid; gap: 6px; max-width: 280px; line-height: 1.45; }
.metric-help__content strong { color: var(--color-text-primary); }
.metric-help__content span { color: var(--color-text-secondary); }

.workspace-attention-list { display: grid; gap: var(--space-2); margin: 0; padding: 0; list-style: none; }
.workspace-attention-list__item { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: var(--space-4); align-items: center; padding: var(--space-4); border: 1px solid var(--color-border-subtle); border-radius: var(--radius-md); background: var(--color-surface-row); }
.workspace-attention-list__item.tone-risk { border-color: var(--color-danger-border); background: var(--color-danger-soft); }
