.home-exec-timeframe-strip button,
.home-exec-triage-tools button,
.portfolio-v2-range-btn,
.analytics-tab-btn,
.journal-tab-btn,
.tax-v2-filter-btn,
.btn, .button-secondary {
  min-height: 34px;
  padding: 0 12px;
  border-radius: var(--radius-md) !important;
  border: 1px solid var(--color-border-medium) !important;
  background: transparent !important;
  color: rgba(255, 255, 255, 0.56) !important;
  font-size: 10px !important;
  font-weight: 800 !important;
  letter-spacing: 0.08em !important;
  text-transform: uppercase !important;
  cursor: pointer;
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease;
}

.home-exec-btn:active:not(:disabled),
.home-exec-link:active,
.portfolio-v2-link:active {
  transform: translateY(1px);
}
.home-exec-btn:disabled,
.home-exec-btn[aria-busy="true"] {
  opacity: 0.6;
  cursor: default;
  pointer-events: none;
}
@media (prefers-reduced-motion: reduce) {
  .home-exec-btn:active:not(:disabled) { transform: none; }
}

.home-exec-btn:hover,
.home-exec-toggle:hover,
.home-exec-timeframe-strip button:hover,
.home-exec-triage-tools button:hover,
.portfolio-v2-range-btn:hover,
.analytics-tab-btn:hover,
.journal-tab-btn:hover,
.tax-v2-filter-btn:hover {
