}

.home-exec-btn.primary,
.home-exec-btn.active,
.home-exec-timeframe-strip button.active,
.home-exec-toggle.active,
.portfolio-v2-range-btn.active,
.analytics-tab-btn.active,
.journal-tab-btn.active,
.tax-v2-filter-btn.active {
  background: var(--color-interactive-soft) !important;
  border-color: var(--color-border-medium) !important;
  color: var(--color-data-primary) !important;
}

/* ── Home exec container ────────────────────────────────────────────── */
.home-exec {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* ── Hero chips / badge pills ───────────────────────────────────────── */
.home-exec-hero-chip {
  border-radius: var(--radius-md) !important;
  border: 1px solid var(--color-border-medium) !important;
}
.home-exec-hero-chip.positive {
  background: rgba(16, 185, 129, 0.1) !important;
  border-color: rgba(16, 185, 129, 0.2) !important;
}
.home-exec-hero-chip.negative {
