  background: var(--color-surface-card) !important;
  border: 1px solid var(--color-border-medium) !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.6) !important;
}

/* ── Table rows ─────────────────────────────────────────────────────── */
.home-exec-log-table,
.active-trades-table,
.journal-trades-table {
  width: 100%;
  border-collapse: collapse;
}

.home-exec-log-table td,
.home-exec-log-table th,
.active-trades-table td,
.active-trades-table th {
