}

/* ── Sidebar nav ────────────────────────────────────────────────────── */
.sidebar,
.main-sidebar,
.app-sidebar {
  background: var(--color-surface-card) !important;
  border-right: 1px solid var(--color-border-subtle) !important;
}

/* ── Main layout / app wrapper ──────────────────────────────────────── */
.main-layout,
.app-layout,
.app-wrapper {
  background: transparent !important;
}

/* ── Topbar / header bar ────────────────────────────────────────────── */
.topbar,
.top-nav,
.app-topbar {
