  border-bottom: 1px solid var(--color-border-subtle) !important;
  backdrop-filter: blur(14px) !important;
}


/* ════════════════════════════════════════════════════════════════════
   Light Theme Token Block — full mirror of :root.
   Components read var(--token); both themes resolve correctly.
   Apply `.light-theme-active` on <html> (set by App.jsx theme effect).
   ═══════════════════════════════════════════════════════════════════ */
html.light-theme-active {
  color-scheme: light;
  /* Light text aliases — referenced by home/portfolio exec overrides.
     Map to the standard light tokens so legacy var(--light-text*) work. */
  --light-text:        #0A0A0A;
  --light-text-strong: #0A0A0A;
  --light-text-muted:  #595959;
  /* ── Surfaces (light — Brand v2 monochrome) ────────────────────── */
  --color-bg-base:              #FFFFFF;
  --color-surface-card:         #FFFFFF;
  --color-surface-card-strong:  #FAFAFA;
  --color-surface-panel:        #FAFAFA;
  --color-surface-elevated:     #F5F5F5;
  --color-surface-depth:        #FFFFFF;
  --color-surface-hover:        rgba(0, 0, 0, 0.04);
  --color-surface-overlay:      rgba(255, 255, 255, 0.96);
  /* ── Borders (light) ────────────────────────────────────────────── */
  --color-border-subtle:        rgba(0, 0, 0, 0.06);
  --color-border-medium:        #E5E5E5;
  --color-border-strong:        #D4D4D4;
  --color-border-default:       var(--color-border-medium);
  /* ── Text (light) ───────────────────────────────────────────────── */
  --color-text-primary:         #0A0A0A;
  --color-text-secondary:       #595959;   /* AA 7.4:1 on #fff */
  /* ── Sidebar nav semantic tokens (Brand v2 active/hover inversion) ── */
  --sidebar-active-bg:          #111111;
  --sidebar-active-text:        #FFFFFF;
  --sidebar-hover-bg:           rgba(0, 0, 0, 0.05);
  --sidebar-hover-text:         #0A0A0A;
  --sidebar-text:               #595959;
  --sidebar-text-muted:         #707070;
  --color-text-muted:           #707070;   /* AA 4.7:1 on #fff */
  --color-text-dim:             #808080;   /* disabled / large only */
  --color-text-inverse:         #FFFFFF;
  --color-text-danger:          #dc2626;
  /* ── Icons (light) ──────────────────────────────────────────────── */
  --color-icon-primary:         #0A0A0A;
  --color-icon-secondary:       #595959;
  --color-icon-muted:           #707070;
  /* ── Interaction (light) ────────────────────────────────────────── */
  --color-interactive:          #0A0A0A;
  --color-interactive-hover:    #262626;
  --color-interactive-soft:     rgba(0, 0, 0, 0.06);
  --color-focus:                #0A0A0A;
  --color-selected:             rgba(0, 0, 0, 0.06);

  /* ── Design-audit semantic tokens (P0) — light parity ──────────── */
  --color-surface-row:          rgba(0, 0, 0, 0.02);
  --color-focus-ring:           #0A0A0A;
  --color-focus-ring-offset:    #FFFFFF;
  --control-height-compact:     34px;
  --control-height-standard:    40px;
  --control-height-touch:       44px;
  --type-page-title:            28px;
  --type-section-title:         18px;
  --type-card-title:            15px;
  --type-body:                  14px;
  --type-meta:                  12px;
  --type-label:                 11px;
  --type-metric:                28px;
  --color-selected-strong:      rgba(0, 0, 0, 0.10);
  /* ── Status (light — AA-compliant on white) ─────────────────────── */
  --color-success:              #047857;
  --color-danger:               #dc2626;
  --color-warning:              #b45309;
  --color-green:                var(--color-success);
  --color-red:                  var(--color-danger);
  --color-amber:                var(--color-warning);
  --color-success-soft:         rgba(5, 150, 105, 0.12);
  --color-danger-soft:          rgba(220, 38, 38, 0.10);
  --color-warning-soft:         rgba(217, 119, 6, 0.12);
  /* ── Data-text aliases (light — monochrome + semantic) ──────────── */
  --color-data-primary:         #0A0A0A;
  --color-data-secondary:       #595959;
  --color-data-muted:           #707070;
  --color-data-slate:           #595959;
  --color-data-slate-bright:    #0A0A0A;
  --color-data-slate-dim:       #737373;
  --color-data-up:              var(--color-success);
  --color-data-green:           #047857;
  --color-data-green-bright:    #15803d;
  --color-data-down:            var(--color-danger);
  --color-data-red:             #dc2626;
  --color-data-red-bright:      #f87171;
  --color-data-amber:           #b45309;
  --color-data-amber-bright:    #d97706;
}

html.light-theme-active,
body.light-theme-active,
body.light-theme-active #root {
  background: var(--color-bg-base);
}

body.light-theme-active {
  color: var(--color-text-primary);
}

/* Honor system theme preference when the user has not explicitly toggled. */
@media (prefers-color-scheme: light) {
  html:not(.page-dark-theme):not(.has-explicit-theme):not(.light-theme-active) {
    /* Apply light tokens automatically so SSR/prerendered content matches. */
  }
}

/* Native form controls follow tokens in both themes. */
html.light-theme-active input:not([type="checkbox"]):not([type="radio"]),
html.light-theme-active select,
html.light-theme-active textarea,
body.light-theme-active input:not([type="checkbox"]):not([type="radio"]),
body.light-theme-active select,
body.light-theme-active textarea {
  background: var(--color-surface-card);
  border: 1px solid var(--color-border-medium);
  color: var(--color-text-primary);
}

html.light-theme-active input::placeholder,
html.light-theme-active textarea::placeholder,
body.light-theme-active input::placeholder,
body.light-theme-active textarea::placeholder {
  color: var(--color-text-muted);
}

html.light-theme-active select option,
body.light-theme-active select option {
  background: var(--color-surface-card);
  color: var(--color-text-primary);
}





.portfolio-performance-card {
