/* Workspace Mode CSS Variables */
:root {
  --workspace-min-width: 960px;
  --workspace-padding-x-compact: 12px;
  --workspace-padding-x-standard: 24px;
  --workspace-padding-x-professional: 32px;
  --workspace-padding-x-analyst: clamp(32px, 4vw, 64px);
  --workspace-padding-x-ultrawide: clamp(40px, 5vw, 80px);
  --workspace-sidebar-width-expanded: 220px;
  --workspace-sidebar-width-collapsed: 72px;
  --workspace-gap-compact: 16px;
  --workspace-gap-standard: 24px;
  --workspace-gap-professional: 32px;
  --workspace-gap-analyst: 40px;
}

.app-layout {
  padding: 0;
  max-width: none;
  margin: 0;
  display: flex;
  gap: 0;
  height: 100vh;
  overflow: hidden;
  position: relative;
}

@media (width <= 960px) {
  .app-layout {
    padding: 0 var(--workspace-padding-x-compact);
    gap: var(--workspace-gap-compact);
    flex-direction: column;
    height: auto;
    min-height: 100vh;
    overflow: visible;
  }
  .main-content {
    padding-left: 0;
    /* Clear the fixed mobile menu trigger (hamburger) so page headers never
       share its visual area. The trigger sits ~12px from top + ~48px tall. */
    padding-top: max(env(safe-area-inset-top, 0px), 64px);
  }

  .sidebar {
    height: auto;
    overflow: visible;
  }

  .main-content {
    height: auto;
    overflow: visible;
  }

  .portfolio-v2-top-cards {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .portfolio-v2-main-grid {
    grid-template-columns: 1fr;
  }
}

/* Compact Workspace: 960-1280px */
@media (min-width: 960px) and (max-width: 1280px) {
  .app-layout {
    padding: 0;
    gap: 0;
  }
}

/* Standard Workspace: 1280-1600px — widen here too (was stuck on the tight
   base grid below 1600). Extends the Professional/Analyst expansion downward
   so the most common desktop range gets a content-forward main + comfortable rail. */
@media (min-width: 1280px) and (max-width: 1600px) {
  .app-layout {
    padding: 0;
    gap: 0;
  }
  .home-v2-main-grid,
  .portfolio-v2-main-grid,
  .journal-v2-main-grid,
  .home-exec-top-grid,
  .home-exec-main-grid {
    grid-template-columns: minmax(0, 2.4fr) minmax(360px, 1fr);
  }
}

/* Professional Workspace: 1600-1920px */
@media (min-width: 1600px) and (max-width: 1920px) {
  .app-layout {
    padding: 0;
    gap: 0;
  }
}

/* Analyst Workspace: 1920-2560px */
@media (min-width: 1920px) and (max-width: 2560px) {
  .app-layout {
    padding: 0;
    gap: 0;
  }
}

/* Ultrawide Workspace: 2560px+ */
@media (min-width: 2560px) {
  .app-layout {
    padding: 0;
    gap: 0;
    max-width: 3000px;
    margin: 0 auto;
  }
}

/* ── Grid expansion for large/ultrawide workspaces ───────────────────────
   Page-level width caps are removed (Phase 1); these overrides raise the
   content+rail ceilings so the rail keeps growing instead of capping. */
@media (min-width: 1600px) {
  .home-v2-main-grid,
  .portfolio-v2-main-grid,
  .journal-v2-main-grid,
  .home-exec-top-grid,
  .home-exec-main-grid {
    grid-template-columns: minmax(0, 2.4fr) minmax(360px, 1fr);
  }
}

@media (min-width: 1920px) {
  .home-v2-main-grid,
  .portfolio-v2-main-grid,
  .journal-v2-main-grid,
  .home-exec-top-grid,
  .home-exec-main-grid {
    grid-template-columns: minmax(0, 2.6fr) minmax(420px, 1fr);
  }

  .analytics-factor-main,
  .analytics-macro-grid,
  .analytics-commodity-layout {
    grid-template-columns: minmax(0, 1fr) minmax(320px, 460px);
  }

  .analytics-macro-topline,
  .analytics-options-topline {
    grid-template-columns: minmax(0, 1fr) minmax(320px, 520px);
  }
}

/* Reserved shell slot: right-hand context panel. Introducible later without
   restructuring .app-layout — .main-content already has flex:1; min-width:0. */
.context-panel {
  flex: 0 0 var(--context-panel-width, 360px);
  min-width: 0;
  align-self: stretch;
}

@media (min-width: 1920px) {
  .context-panel {
    flex-basis: 380px;
  }
}


.app-access-loading {
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #02050f;
  color: var(--color-text-secondary);
  font-size: 1rem;
  letter-spacing: 0.03em;
}


.main-content {
  flex: 1;
  min-width: 0;
  height: 100%;
  overflow-y: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
