}

.analytics-pill-group {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.analytics-chip-button {
  height: 30px;
  padding: 0 10px;
  border-radius: var(--radius-full);
  font-size: 12px;
}

.analytics-chip-button.active {
  border-color: var(--color-border-strong);
  background: var(--color-surface-selected);
