  font-size: 13px;
}

.analytics-select.compact {
  width: auto;
  min-height: 36px;
  min-width: 92px;
}

.analytics-static-chip {
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  border-radius: var(--radius-full);
  padding: 0 10px;
  border: 1px solid var(--color-border-medium);
  background: rgba(10, 10, 10, 0.58);
  color: var(--color-text-secondary);
  font-size: 12px;
  font-weight: 700;
}

.analytics-table-actions {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
  margin-bottom: 10px;
  flex-wrap: wrap;
}

.analytics-table-action-right {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}

.analytics-table-wrap {
  overflow: auto;
  max-height: 540px;
}

.analytics-data-table {
  width: 100%;
  min-width: 420px;
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
}

.analytics-data-table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: rgba(5,5,5,0.98);
  text-align: left;
  padding: 0 0 10px;
  font-size: 11px;
  color: var(--color-text-muted);
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-bottom: 1px solid var(--color-border-medium);
}

.analytics-data-table th.numeric,
.analytics-data-table td.numeric {
  text-align: right;
}

.analytics-data-table tbody tr {
  transition: background 0.16s ease;
}

.analytics-data-table tbody tr:hover {
  background: var(--color-interactive-soft);
}

.analytics-data-table tbody tr.analytics-clickable-row {
  cursor: pointer;
}

.analytics-data-table tbody tr.analytics-clickable-row:focus-within,
.analytics-data-table tbody tr.analytics-clickable-row:hover {
  background: var(--color-interactive-soft);
}

.analytics-data-table td {
  padding: 12px 0;
  font-size: 13px;
  color: var(--color-text-secondary);
  border-bottom: var(--color-border-medium);
}

.analytics-empty-state,
.analytics-error-state {
  display: grid;
  gap: 9px;
  padding: 18px 6px 6px;
}

.analytics-empty-title {
  color: var(--color-text-secondary);
  font-weight: 800;
}

.analytics-loading-skeleton {
  display: grid;
  gap: 10px;
}

.analytics-skeleton-line {
  height: 12px;
  width: 52%;
  border-radius: var(--radius-full);
  background: var(--color-surface-elevated);
}

.analytics-skeleton-line.wide {
  width: 84%;
}

.analytics-skeleton-label {
  color: var(--color-text-muted);
  font-size: 13px;
}

.analytics-chart-shell {
  position: relative;
}

.analytics-line-chart {
  width: 100%;
  height: 240px;
  border-radius: var(--radius-md);
  background: linear-gradient(180deg, rgba(5,5,5,0.95), rgba(0,0,0,1));
  border: 1px solid var(--color-border-subtle);
}

.analytics-chart-tooltip {
  position: absolute;
  top: 14px;
  right: 14px;
  display: grid;
  gap: 2px;
  min-width: 120px;
  padding: 9px 10px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-strong);
  background: rgba(5,5,5,0.98);
  color: var(--color-text-muted);
  font-size: 11px;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.18s ease, transform 0.18s ease;
  pointer-events: none;
}

.analytics-chart-tooltip strong {
  color: var(--color-text-secondary);
  font-size: 16px;
  font-variant-numeric: tabular-nums;
}

.analytics-chart-shell:hover .analytics-chart-tooltip {
  opacity: 1;
  transform: translateY(0);
}

.analytics-chart-footer {
  margin-top: 12px;
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}

.analytics-alert-empty {
  display: grid;
  gap: 12px;
}

@media (max-width: 900px) {
  .analytics-layout {
    padding: 20px;
  }

  .analytics-control-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .analytics-layout {
    padding: 16px;
    border-radius: var(--radius-md);
  }

  .analytics-page-header,
  .analytics-card-head,
  .analytics-table-actions {
    align-items: stretch;
  }

  .analytics-header-meta {
    width: 100%;
  }
}













































































.watchlist-add-overlay {
  position: fixed;
  inset: 0;
  z-index: 1300;
