  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.watchlist-add-modal {
  width: min(440px, 96vw);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-medium);
  background: var(--color-surface-depth);
  box-shadow: 0 20px 48px rgba(2, 6, 23, 0.6);
  overflow: hidden;
}

.watchlist-add-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--color-border-medium);
  padding: 12px 14px;
}

.watchlist-add-header h3 {
  margin: 0;
  font-size: 0.96rem;
  color: var(--color-text-primary);
}

.watchlist-add-body {
  padding: 14px;
  display: grid;
  gap: 10px;
}

.watchlist-add-help {
  margin: 0;
  font-size: 0.78rem;
