}

/* Field rows: two-up on wide, stack on narrow */
.watchlist-add-field-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

@media (max-width: 420px) {
  .watchlist-add-field-row {
    grid-template-columns: 1fr;
  }
}

/* Header: symbol chip + title on one clean line */
.watchlist-add-header h3 {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: nowrap;
  white-space: nowrap;
