.watchlist-add-divider {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 2px 0;
  color: var(--color-text-muted);
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.watchlist-add-divider::before,
.watchlist-add-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: rgba(148, 163, 184, 0.18);
}

/* Labelled fields inside the add-to-watchlist modal */
.watchlist-add-modal .settings-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.watchlist-add-modal .settings-field > span {
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--color-text-secondary);
}

.watchlist-add-modal .settings-field select,
.watchlist-add-modal .settings-field input {
  width: 100%;
  min-height: 38px;
  padding: 8px 11px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-medium, rgba(148, 163, 184, 0.32));
  background: rgba(2, 6, 23, 0.85);
  color: var(--color-text-primary);
  font-size: 0.88rem;
  font-weight: 600;
  transition: border-color 140ms ease, background-color 140ms ease;
}

.watchlist-add-modal .settings-field select:hover,
.watchlist-add-modal .settings-field input:hover {
  border-color: var(--color-border-strong, rgba(148, 163, 184, 0.55));
}

.watchlist-add-modal .settings-field select:focus,
.watchlist-add-modal .settings-field input:focus {
  outline: none;
  border-color: var(--color-interactive, var(--color-text-secondary));
