  background-image: linear-gradient(45deg, transparent 50%, var(--color-text-secondary) 50%), linear-gradient(135deg, var(--color-text-secondary) 50%, transparent 50%);
  background-position: calc(100% - 16px) 17px, calc(100% - 11px) 17px;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 30px;
  cursor: pointer;
}

.watchlist-add-help {
  margin: 0;
  font-size: 0.76rem;
  line-height: 1.4;
  color: var(--color-text-muted);
}

.watchlist-add-error {
  margin: 0;
  font-size: 0.78rem;
  color: var(--color-data-red-bright);
}

/* ============================================================================
   Universal Asset Collection modal (WatchlistCollectModal) — Brand v2.
   Monochrome, desktop-first, dense. Single accent = active selection only.
   ========================================================================== */
.wc-overlay {
  position: fixed;
  inset: 0;
  z-index: var(--z-modal, 1300);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: var(--color-surface-overlay, rgba(10, 10, 10, 0.92));
  -webkit-backdrop-filter: blur(4px);
  backdrop-filter: blur(4px);
}

.wc-modal {
  display: flex;
  flex-direction: column;
  width: min(620px, 100%);
  max-height: min(86vh, 760px);
  background: var(--color-surface-card, #111);
  border: 1px solid var(--color-border-medium, #262626);
  border-radius: var(--radius-lg, 8px);
  box-shadow: var(--shadow-3, 0 24px 64px rgba(0, 0, 0, 0.62));
  overflow: hidden;
}

/* Header */
.wc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid var(--color-border-subtle, rgba(255, 255, 255, 0.06));
}

.wc-header h3 {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--color-text-primary);
}

.wc-close {
  background: transparent;
  border: 0;
  color: var(--color-text-muted);
  font-size: 1.35rem;
  line-height: 1;
  cursor: pointer;
  padding: 0 4px;
  transition: color 140ms ease;
}
.wc-close:hover { color: var(--color-text-primary); }

/* Asset summary — pinned */
.wc-summary {
  flex: 0 0 auto;
  padding: 14px 16px;
  border-bottom: 1px solid var(--color-border-medium, #262626);
  background: var(--color-surface-card-strong, #141414);
}

.wc-summary-id {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.wc-summary-symbol {
  font-family: var(--font-mono);
  font-size: 1.15rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--color-text-primary);
}

.wc-summary-kind {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-full);
  padding: 2px 8px;
}

.wc-summary-name {
  margin-top: 2px;
  font-size: 0.82rem;
  color: var(--color-text-secondary);
}

.wc-summary-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin-top: 8px;
  font-size: 0.72rem;
  color: var(--color-text-muted);
}
.wc-summary-meta span { white-space: nowrap; }
.wc-summary-price {
  font-family: var(--font-mono);
  color: var(--color-text-primary);
  font-weight: 600;
}

.wc-membership {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.wc-membership-label {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-dim);
}
.wc-membership-chips { display: flex; flex-wrap: wrap; gap: 6px; }

/* Chips */
.wc-chip {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-medium);
  background: transparent;
  color: var(--color-text-secondary);
  font-size: 0.72rem;
  font-weight: 600;
  cursor: default;
}
.wc-chip--muted { color: var(--color-text-muted); }
.wc-chip--suggest { cursor: pointer; transition: border-color 140ms ease, color 140ms ease, background-color 140ms ease; }
.wc-chip--suggest:hover { border-color: var(--color-border-strong); color: var(--color-text-primary); }
.wc-chip--suggest.is-active {
  border-color: var(--color-interactive);
  background: var(--color-interactive-soft);
  color: var(--color-text-primary);
}

/* Scrollable body */
.wc-body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.wc-section { display: flex; flex-direction: column; gap: 8px; }

