  display: flex;
  align-items: center;
  justify-content: space-between;
}

.wc-label {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-text-secondary);
}
.wc-req { color: var(--color-text-primary); }
.wc-optional {
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--color-text-dim);
  text-transform: none;
}

.wc-inline-action {
  background: transparent;
  border: 0;
  color: var(--color-text-secondary);
  font-size: 0.72rem;
  font-weight: 700;
  cursor: pointer;
  padding: 2px 4px;
  transition: color 140ms ease;
}
.wc-inline-action:hover { color: var(--color-text-primary); }

.wc-input,
.wc-select {
  width: 100%;
  min-height: 38px;
  padding: 8px 11px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-medium);
  background: var(--color-surface-depth, #0A0A0A);
  color: var(--color-text-primary);
  font-size: 0.86rem;
  transition: border-color 140ms ease;
}
.wc-input:focus,
.wc-select:focus {
  outline: none;
  border-color: var(--color-interactive);
  box-shadow: 0 0 0 2px var(--color-interactive-soft);
}

.wc-select {
  appearance: none;
  -webkit-appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--color-text-secondary) 50%), linear-gradient(135deg, var(--color-text-secondary) 50%, transparent 50%);
  background-position: calc(100% - 16px) 17px, calc(100% - 11px) 17px;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 30px;
  cursor: pointer;
}

.wc-suggested {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.wc-suggested-label {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-dim);
  margin-right: 2px;
}

.wc-create { display: flex; flex-direction: column; gap: 6px; }
.wc-hint { margin: 0; font-size: 0.72rem; color: var(--color-text-muted); line-height: 1.4; }

/* Theme cards (few themes) */
.wc-theme-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 8px;
}
.wc-theme-card {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md, 4px);
  background: var(--color-surface-depth, #0A0A0A);
  text-align: left;
  cursor: pointer;
  transition: border-color 140ms ease, background-color 140ms ease;
}
.wc-theme-card:hover,
.wc-theme-card.is-cursor { border-color: var(--color-border-strong); }
.wc-theme-card.is-active {
  border-color: var(--color-interactive);
  background: var(--color-interactive-soft);
}
.wc-theme-mono {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: var(--color-text-muted);
}
.wc-theme-name {
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--color-text-primary);
}
.wc-theme-sub {
  font-size: 0.68rem;
  color: var(--color-text-muted);
  font-variant-numeric: tabular-nums;
}

/* Theme list (many themes) */
.wc-theme-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 240px;
  overflow-y: auto;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md, 4px);
  padding: 4px;
}
.wc-theme-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 10px;
  border: 0;
  border-radius: var(--radius-md);
  background: transparent;
  text-align: left;
  cursor: pointer;
  transition: background-color 120ms ease;
}
.wc-theme-row:hover,
.wc-theme-row.is-cursor { background: var(--color-surface-hover); }
.wc-theme-row.is-active {
  background: var(--color-interactive-soft);
  box-shadow: inset 2px 0 0 var(--color-interactive);
}

/* Empty states */
.wc-empty {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 18px 14px;
  border: 1px dashed var(--color-border-medium);
  border-radius: var(--radius-md, 4px);
  text-align: center;
  color: var(--color-text-muted);
  font-size: 0.78rem;
}
.wc-empty strong { color: var(--color-text-secondary); font-size: 0.82rem; }
.wc-empty--inline { padding: 12px; border-style: dashed; }

/* Destination preview */
.wc-destination { gap: 6px; }
.wc-dest-ok,
.wc-dest-dup { display: flex; flex-direction: column; gap: 4px; }
.wc-dest-path {
  font-size: 0.84rem;
  color: var(--color-text-primary);
  font-weight: 600;
}
.wc-dest-arrow { color: var(--color-text-dim); margin: 0 4px; }
.wc-dest-count {
  font-size: 0.72rem;
  color: var(--color-text-muted);
  font-variant-numeric: tabular-nums;
}
.wc-dest-warn { font-size: 0.74rem; color: var(--color-data-amber-bright); }

.wc-error { margin: 0; font-size: 0.78rem; color: var(--color-data-red-bright); }

/* Sticky footer */
.wc-footer {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid var(--color-border-medium, #262626);
  background: var(--color-surface-card-strong, #141414);
}

.wc-btn {
  min-height: 36px;
  padding: 0 16px;
  border-radius: var(--radius-md);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: background-color 140ms ease, border-color 140ms ease, color 140ms ease;
}
.wc-btn:disabled { opacity: 0.45; cursor: not-allowed; }

.wc-btn--ghost {
  background: transparent;
  border: 1px solid transparent;
  color: var(--color-text-muted);
}
.wc-btn--ghost:hover { color: var(--color-text-primary); }

.wc-btn--secondary {
  background: transparent;
  border: 1px solid var(--color-border-medium);
  color: var(--color-text-secondary);
}
.wc-btn--secondary:hover:not(:disabled) {
  border-color: var(--color-border-strong);
  color: var(--color-text-primary);
}

.wc-btn--primary {
  background: var(--color-interactive);
  border: 1px solid var(--color-interactive);
  color: var(--color-text-inverse);
}
.wc-btn--primary:hover:not(:disabled) { background: var(--color-interactive-hover); }

@media (max-width: 520px) {
  .wc-footer { flex-wrap: wrap; }
  .wc-theme-grid { grid-template-columns: 1fr 1fr; }
}

.connect-empty-actions {
  display: flex;
  gap: 10px;
  margin-top: 14px;
}

/* Primary / secondary action buttons — defined globally so they render as
   real buttons in Home, Portfolio, and the connect nudge (dark + light). */
.settings-primary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  padding: 0 16px;
  border-radius: var(--radius-md);
  font-size: 0.86rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  cursor: pointer;
  border: 1px solid transparent;
  background: var(--color-interactive);
  color: var(--color-text-inverse);
  transition: background-color 140ms ease, border-color 140ms ease, color 140ms ease;
}

.settings-primary-btn:hover {
  background: var(--color-interactive-hover);
}

.settings-primary-btn:focus-visible {
  outline: 2px solid var(--color-focus, #FFFFFF);
  outline-offset: 2px;
}

.settings-secondary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  padding: 0 16px;
  border-radius: var(--radius-md);
  font-size: 0.86rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  cursor: pointer;
  background: transparent;
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border-medium);
  transition: background-color 140ms ease, border-color 140ms ease, color 140ms ease;
}

.settings-secondary-btn:hover {
  border-color: var(--color-border-strong);
  color: var(--color-text-primary);
}

.settings-secondary-btn:focus-visible {
  outline: 2px solid var(--color-focus, #FFFFFF);
  outline-offset: 2px;
}

/* Compact secondary action — recedes next to a primary CTA. Monochrome,
   reused across empty-state scaffolds and inline panel actions (Brandv2). */
.settings-mini-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: flex-start;
  min-height: 32px;
  padding: 0 12px;
  border-radius: var(--radius-md);
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  cursor: pointer;
  background: transparent;
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border-medium);
  transition: border-color 140ms ease, color 140ms ease, background 140ms ease;
}

.settings-mini-btn:hover {
  border-color: var(--color-border-strong);
  color: var(--color-text-primary);
  background: var(--color-surface-hover);
}

.settings-mini-btn:focus-visible {
  outline: 2px solid var(--color-focus, #FFFFFF);
  outline-offset: 2px;
}

/* Keep spacing inside the connect nudge consistent. */
.connect-empty-actions .settings-primary-btn,
.connect-empty-actions .settings-secondary-btn {
  margin-top: 0;
}

html.light-theme-active .settings-primary-btn {
  background: var(--color-text-primary);
  color: var(--color-surface-card);
}

html.light-theme-active .settings-primary-btn:hover {
  background: #262626;
}

html.light-theme-active .settings-secondary-btn {
  background: transparent;
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border-medium);
}

html.light-theme-active .settings-secondary-btn:hover {
  border-color: var(--color-border-strong);
  color: var(--color-text-primary);
}

.connected-accounts-list {
  display: grid;
  gap: 8px;
}

.connected-account-item {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  padding: 8px 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  background: rgba(15, 23, 42, 0.55);
}

.connected-account-item strong {
  display: block;
  margin-bottom: 2px;
  font-size: 0.9rem;
}

.connected-account-item p {
  margin: 0;
  color: var(--color-text-muted);
  font-size: 0.77rem;
}

.connected-account-item span {
  color: var(--color-data-primary);
  font-size: 0.78rem;
}

.connected-account-trust-item {
  display: block;
  padding: 12px 14px;
}

.connected-account-trust-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 6px;
}

.connected-account-trust-title {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.connected-account-trust-title strong {
  font-size: 0.95rem;
  margin: 0;
}

.connected-account-trust-actions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.connected-account-trust-meta {
  margin: 0 0 8px;
  color: var(--color-text-muted);
  font-size: 0.75rem;
}

.provider-trust-pill {
  display: inline-flex;
  align-items: center;
  border-radius: var(--radius-full);
  padding: 2px 10px;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  line-height: 1.6;
  white-space: nowrap;
}

.provider-trust-pill-verified {
  color: var(--color-text-primary);
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-subtle);
}

.provider-trust-pill-unverified {
  color: var(--color-text-muted);
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-subtle);
}

.provider-trust-pill-rejected {
  color: var(--color-text-secondary);
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-subtle);
}

.connected-account-permissions {
  margin: 6px 0 8px;
}

.connected-account-permissions-label {
  display: block;
  color: var(--color-text-secondary);
  font-size: 0.74rem;
  margin-bottom: 4px;
}

.connected-account-permissions-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px 12px;
}

.connected-account-permissions-list li {
  font-size: 0.76rem;
  color: var(--color-text-muted);
}

.connected-account-permissions-list li.perm-ok {
  color: var(--color-text-primary);
}

.connected-account-permissions-list li.perm-no {
  color: var(--color-text-muted);
}

.connected-account-permissions-list li.perm-warn {
  color: var(--color-text-secondary);
}

.connected-account-proof {
  border-top: 1px solid var(--color-border-medium);
  padding-top: 6px;
  margin-top: 4px;
}

.connected-account-proof-head {
  margin: 0 0 2px;
  color: var(--color-text-secondary);
  font-size: 0.78rem;
  font-weight: 600;
}

.connected-account-proof-detail {
  margin: 0;
  color: var(--color-text-muted);
  font-size: 0.74rem;
}









.connection-row-trust-note {
  color: var(--color-text-muted);
  font-size: 0.72rem;
  margin-top: 2px;
}

/* Briefing module */
.briefing-module .briefing-summary {
  margin: 0 0 10px;
  color: var(--color-text-secondary);
  font-size: 0.9rem;
  line-height: 1.5;
}

.briefing-tags {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.briefing-tag {
  display: inline-flex;
  align-items: center;
  border-radius: var(--radius-full);
  padding: 2px 10px;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--color-text-muted);
  background: color-mix(in srgb, var(--color-surface-elevated) 50%, transparent);
  border: 1px solid rgba(255, 255, 255, 0.165);
}

.briefing-tag-regime {
  color: var(--color-data-primary);
  border-color: color-mix(in srgb, var(--color-text-secondary) 30%, transparent);
}

.briefing-tag-risk-normal { color: var(--color-data-green-bright); border-color: rgba(34, 197, 94, 0.28); }
.briefing-tag-risk-moderate { color: var(--color-data-amber-bright); border-color: rgba(245, 158, 11, 0.26); }
.briefing-tag-risk-elevated { color: var(--color-data-red-bright); border-color: rgba(239, 68, 68, 0.28); }

.briefing-mark-read-link {
  background: none;
  border: none;
  color: var(--color-data-primary);
  font-size: 0.72rem;
  cursor: pointer;
  padding: 2px 4px;
}

/* Normalized briefing status strip (generated time, data age, read state, next action). */
.briefing-status-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}
.briefing-tag-age-fresh { color: var(--color-data-green-bright); border-color: color-mix(in srgb, var(--color-data-green-bright) 30%, transparent); }
.briefing-tag-age-recent { color: var(--color-text-secondary); }
.briefing-tag-age-aging { color: var(--color-data-amber-bright); border-color: rgba(245, 158, 11, 0.26); }
.briefing-tag-age-stale { color: var(--color-data-red-bright); border-color: rgba(239, 68, 68, 0.28); }
.briefing-tag-unread { color: var(--color-data-amber-bright); border-color: rgba(245, 158, 11, 0.26); }
.briefing-tag-read { color: var(--color-text-muted); }
.briefing-status-action {
  margin-left: auto;
  border: 1px solid var(--color-border-default);
  background: transparent;
  color: var(--color-text-secondary);
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  padding: 4px 10px;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard);
}
.briefing-status-action:hover {
  background: var(--color-surface-hover);
  color: var(--color-text-primary);
}

.briefing-sections {
  display: grid;
  gap: 14px;
}

.briefing-error-state {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
  padding: 10px 12px;
  border: 1px solid rgba(248, 113, 113, 0.32);
  border-radius: var(--radius-lg);
  background: rgba(127, 29, 29, 0.14);
  color: var(--color-data-red-bright);
  font-size: 0.82rem;
}

.briefing-skeleton {
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.09) 25%, rgba(255, 255, 255, 0.15) 50%, rgba(255, 255, 255, 0.09) 75%);
  background-size: 200% 100%;
  animation: briefing-skeleton-shimmer 1.4s infinite;
  border-radius: var(--radius-md);
}

@keyframes briefing-skeleton-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

.briefing-skeleton.summary {
  height: 18px;
  width: 70%;
  margin-bottom: 10px;
}

.briefing-skeleton.tags {
  height: 22px;
  width: 40%;
  margin-bottom: 14px;
}

.briefing-skeleton.section-title {
  height: 14px;
  width: 120px;
}

.briefing-skeleton.section-count {
  height: 14px;
  width: 24px;
}

.briefing-section-item .briefing-skeleton.item {
  height: 14px;
  width: 60%;
}

.briefing-section {
  border: 1px solid rgba(255, 255, 255, 0.112);
  border-radius: var(--radius-lg);
  padding: 12px 14px;
  background: color-mix(in srgb, var(--color-surface-elevated) 45%, transparent);
}

.briefing-section-head h3 {
  margin: 0 0 6px;
  font-size: 0.92rem;
  color: var(--color-text-secondary);
}

.briefing-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.briefing-section-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: transparent;
  border: none;
  padding: 0;
  color: inherit;
  cursor: pointer;
  font: inherit;
}
.briefing-section-toggle span { color: var(--color-interactive); font-size: 0.78em; }
.briefing-section-toggle h3 { margin: 0; }
.briefing-section-count {
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-full);
  padding: 1px 8px;
}
.briefing-section.is-collapsed {
  padding: 12px 14px;
}
.briefing-sort-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin: 4px 0 8px;
}
.briefing-sort-label {
  font-size: var(--fs-xs);
  color: var(--color-text-dim);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-weight: 800;
}
.briefing-sort-chip {
  background: transparent;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  color: var(--color-text-secondary);
  padding: 4px 10px;
  font-size: var(--fs-xs);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
}
.briefing-sort-chip:hover { border-color: var(--color-interactive); }
.briefing-sort-chip.active {
  background: color-mix(in srgb, var(--color-interactive-soft) 12%, transparent);
  border-color: var(--color-interactive);
  color: var(--color-text-primary);
}

.briefing-section-insight {
  margin: 0 0 8px;
  color: var(--color-text-muted);
  font-size: 0.78rem;
}

.briefing-section-items {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 6px;
}

.briefing-section-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 6px 8px;
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--color-surface-elevated) 40%, transparent);
  flex-wrap: wrap;
}

.briefing-section-item-copy {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 0;
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.briefing-section-item-copy:hover,
.briefing-section-item-copy:focus-visible {
  background: color-mix(in srgb, var(--color-interactive-soft) 8%, transparent);
  outline: none;
}

.briefing-section-item-copy strong {
  font-size: 0.84rem;
}

.briefing-section-item-copy span {
  color: var(--color-text-muted);
  font-size: 0.74rem;
}

.briefing-item-status {
  text-transform: capitalize;
}

.briefing-item-priority {
  text-transform: capitalize;
  padding: 1px 6px;
  border-radius: var(--radius-full);
  font-size: 0.68rem;
}

.briefing-item-priority-high { color: var(--color-data-red-bright); background: rgba(239, 68, 68, 0.12); }
.briefing-item-priority-medium { color: var(--color-data-amber-bright); background: rgba(245, 158, 11, 0.12); }
.briefing-item-priority-low { color: var(--color-data-green-bright); background: rgba(34, 197, 94, 0.12); }

.briefing-section-item-actions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.briefing-section-empty {
  margin: 0;
  color: var(--color-text-muted);
  font-size: 0.76rem;
  font-style: italic;
}

/* ── Briefing guided workspace (empty / first-run state) ───────────
   Matches the populated .briefing-section card vocabulary so the empty
   state reads as intentional scaffolding, not raw markup. Monochrome,
   semantic tokens only — no cyan, no gradients (Brandv2). */
.briefing-guided-workspace {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 4px;
}

.briefing-guided-block {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px 16px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: color-mix(in srgb, var(--color-surface-elevated) 40%, transparent);
}

.briefing-guided-placeholder {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 2px;
  flex: 1 1 auto;
}

.briefing-guided-placeholder p {
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 0.84rem;
  line-height: 1.55;
}

/* The final "Quick Prompt Templates" block is the conversion CTA — give it a
   subtle primary emphasis via a left accent rule and a stronger surface,
   without introducing color. */
.briefing-guided-cta {
  grid-column: 1 / -1;
  border-color: var(--color-border-strong);
  background: color-mix(in srgb, var(--color-surface-elevated) 72%, transparent);
  box-shadow: inset 3px 0 0 var(--color-interactive);
}

.briefing-guided-prompts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.briefing-guided-generate {
  align-self: flex-start;
  margin-top: 2px;
}

/* Narrow viewports collapse to a single column. */
@media (max-width: 880px) {
  .briefing-guided-workspace {
    grid-template-columns: 1fr;
  }
}

/* ── Decision threads guided workspace (empty / first-run state) ────
   Shares the briefing guided card vocabulary so both empty states read
   as the same intentional scaffold. Monochrome, semantic tokens only. */
.decision-guided-workspace {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 4px;
}

.decision-guided-block {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px 16px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: color-mix(in srgb, var(--color-surface-elevated) 40%, transparent);
}

/* The primary "Start a Decision" CTA spans the full width and carries the
   left accent rule — the monochrome emphasis cue reused from the briefing. */
.decision-guided-cta {
  grid-column: 1 / -1;
  border-color: var(--color-border-strong);
  background: color-mix(in srgb, var(--color-surface-elevated) 72%, transparent);
  box-shadow: inset 3px 0 0 var(--color-interactive);
}

.decision-guided-create-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 2px;
}

.decision-guided-create-row .decision-thread-input {
  flex: 1 1 220px;
}
.decision-guided-create-row .decision-thread-input-symbol {
  flex: 0 0 120px;
}
.decision-guided-create-row .decision-thread-select {
  flex: 0 0 auto;
}
.decision-guided-create-row .settings-primary-btn {
  flex: 0 0 auto;
}

.decision-guided-placeholder {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 2px;
  flex: 1 1 auto;
}

.decision-guided-placeholder p {
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 0.84rem;
  line-height: 1.55;
}

.decision-guided-templates {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.decision-guided-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

/* Statistics: three-up metric strip inside the card. Echoes the workspace
   MetricStrip — strong value over a muted, tracked label. */
.decision-guided-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  margin-top: 2px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--color-border-medium);
}

.decision-guided-stats > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 12px;
  background: color-mix(in srgb, var(--color-surface-elevated) 40%, transparent);
}

.decision-guided-stats strong {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-text-primary);
  line-height: 1;
}

.decision-guided-stats span {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

@media (max-width: 880px) {
  .decision-guided-workspace {
    grid-template-columns: 1fr;
  }
}

/* Decision threads module */
.decision-threads-module .decision-thread-create-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.decision-thread-input,
.decision-thread-select {
  background: color-mix(in srgb, var(--color-surface-elevated) 60%, transparent);
  border: 1px solid rgba(255, 255, 255, 0.165);
  color: var(--color-text-secondary);
  border-radius: var(--radius-md);
  padding: 6px 10px;
  font-size: 0.82rem;
}

.decision-thread-input { flex: 1; min-width: 220px; }
.decision-thread-input-symbol { max-width: 120px; }
.decision-thread-select { min-width: 120px; }

.decision-threads-board {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 10px;
}

@media (max-width: 1100px) {
  .decision-threads-board { grid-template-columns: repeat(3, 1fr); }
}
@media (width <= 720px) {
  .decision-threads-board { grid-template-columns: 1fr; }
}

.decision-threads-column {
  border: 1px solid rgba(255, 255, 255, 0.112);
  border-radius: var(--radius-lg);
  background: color-mix(in srgb, var(--color-surface-elevated) 40%, transparent);
  display: flex;
  flex-direction: column;
  min-height: 120px;
}

.decision-threads-column-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.112);
  font-size: 0.76rem;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.decision-threads-column-count {
  color: var(--color-text-muted);
}

.decision-threads-column-pnl {
  display: block;
  padding: 4px 10px;
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  font-variant-numeric: tabular-nums;
  color: var(--color-text-muted);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.decision-threads-column-pnl.positive { color: var(--color-success); }
.decision-threads-column-pnl.negative { color: var(--color-danger); }

.decision-threads-column.is-drag-over {
  outline: 2px dashed var(--color-interactive);
  outline-offset: -2px;
  background: color-mix(in srgb, var(--color-interactive-soft) 6%, transparent);
}
.decision-threads-column.is-over-wip .decision-threads-column-count {
  color: var(--color-amber);
  font-weight: 800;
}

.decision-threads-column-body {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px;
}

.decision-thread-card {
  display: flex;
  flex-direction: column;
  gap: 3px;
  text-align: left;
  background: color-mix(in srgb, var(--color-surface-elevated) 60%, transparent);
  border: 1px solid rgba(255, 255, 255, 0.135);
  border-radius: var(--radius-md);
  padding: 8px 10px;
  cursor: pointer;
  color: var(--color-text-secondary);
}

.decision-thread-card:hover {
  border-color: color-mix(in srgb, var(--color-text-secondary) 40%, transparent);
}

.decision-thread-card-selected {
  border-color: color-mix(in srgb, var(--color-text-secondary) 60%, transparent);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.188);
}

.decision-thread-card strong {
  font-size: 0.82rem;
  font-weight: 600;
}

.decision-thread-card-symbol {
  font-size: 0.72rem;
  color: var(--color-data-primary);
}

.decision-thread-card-meta {
  font-size: 0.7rem;
  color: var(--color-text-muted);
}

.decision-thread-card-priority-high { border-color: rgba(239, 68, 68, 0.42); background: var(--color-danger-soft); }
.decision-thread-card-priority-medium { border-color: rgba(245, 158, 11, 0.36); background: var(--color-warning-soft); }
.decision-thread-card-priority-low { border-color: rgba(34, 197, 94, 0.34); background: var(--color-success-soft); }

.decision-threads-column-empty {
  color: var(--color-text-secondary);
  font-size: 0.72rem;
  text-align: center;
  padding: 6px;
}

.decision-thread-detail {
  margin-top: 16px;
  border: 1px solid rgba(255, 255, 255, 0.135);
  border-radius: var(--radius-lg);
  background: color-mix(in srgb, var(--color-surface-elevated) 50%, transparent);
  padding: 14px 16px;
}

.decision-thread-detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.decision-thread-detail-head strong {
  display: block;
  font-size: 0.95rem;
  margin-bottom: 2px;
}

.decision-thread-detail-meta,
.decision-thread-detail-due {
  display: block;
  color: var(--color-text-muted);
  font-size: 0.74rem;
}

.decision-thread-detail-due {
  color: var(--color-data-amber-bright);
  margin-top: 2px;
}

.decision-thread-detail-close {
  background: none;
  border: none;
  color: var(--color-text-muted);
  font-size: 1.1rem;
  cursor: pointer;
}

.decision-thread-detail-body {
  display: grid;
  gap: 12px;
}

.decision-thread-detail-links {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  font-size: 0.74rem;
  color: var(--color-text-muted);
}

.decision-thread-outcome {
  border-top: 1px solid rgba(255, 255, 255, 0.112);
  padding-top: 8px;
}

.decision-thread-outcome h4 {
  margin: 0 0 4px;
  font-size: 0.82rem;
  color: var(--color-text-secondary);
}

.decision-thread-outcome p {
  margin: 0 0 2px;
  font-size: 0.76rem;
  color: var(--color-text-muted);
}

.decision-thread-review-form {
  border-top: 1px solid rgba(255, 255, 255, 0.112);
  padding-top: 10px;
}

.decision-thread-review-form h4 {
  margin: 0 0 8px;
  font-size: 0.82rem;
  color: var(--color-text-secondary);
}

.decision-review-hint {
  margin: 0 0 8px;
  font-size: 0.76rem;
  color: var(--color-text-tertiary, var(--color-text-secondary));
}

.decision-thread-review-form textarea {
  width: 100%;
  background: color-mix(in srgb, var(--color-surface-elevated) 60%, transparent);
  border: 1px solid rgba(255, 255, 255, 0.165);
  color: var(--color-text-secondary);
  border-radius: var(--radius-md);
  padding: 6px 10px;
  font-size: 0.8rem;
  margin-top: 8px;
  resize: vertical;
}

.decision-error-state {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
  padding: 10px 12px;
  border: 1px solid rgba(248, 113, 113, 0.32);
  border-radius: var(--radius-lg);
  background: rgba(127, 29, 29, 0.14);
  color: var(--color-data-red-bright);
  font-size: 0.82rem;
}

.decision-skeleton {
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.09) 25%, rgba(255, 255, 255, 0.15) 50%, rgba(255, 255, 255, 0.09) 75%);
  background-size: 200% 100%;
  animation: decision-skeleton-shimmer 1.4s infinite;
  border-radius: var(--radius-md);
}

@keyframes decision-skeleton-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

.decision-thread-card-skeleton {
  display: grid;
  gap: 8px;
  pointer-events: none;
}

.decision-thread-card-skeleton .decision-skeleton.title {
  height: 12px;
  width: 80%;
}

.decision-thread-card-skeleton .decision-skeleton.meta {
  height: 10px;
  width: 50%;
}

.decision-threads-board.is-loading .decision-threads-column {
  opacity: 0.8;
}

.decision-outcomes-panel {
  display: grid;
  gap: 12px;
  margin-bottom: 14px;
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 7px;
  background: rgba(2, 6, 23, 0.48);
}

.decision-outcomes-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.decision-outcomes-head strong {
  font-size: 0.92rem;
  color: var(--color-text-secondary);
}

.decision-outcomes-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(90px, 1fr));
  gap: 10px;
}

.decision-outcomes-summary div {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px;
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--color-surface-elevated) 50%, transparent);
}

.decision-outcomes-summary strong {
  font-size: 1rem;
  color: var(--color-text-primary);
}

.decision-outcomes-summary span {
  font-size: 0.7rem;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.decision-outcomes-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 6px;
}

.decision-outcome-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px;
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--color-surface-elevated) 40%, transparent);
}

.decision-outcome-row strong {
  display: block;
  font-size: 0.82rem;
  color: var(--color-text-secondary);
}

.decision-outcome-row span {
  font-size: 0.72rem;
  color: var(--color-text-muted);
}

.decision-outcome-pnl {
  font-size: 0.84rem;
  font-weight: 800;
}

.decision-outcomes-empty {
  margin: 0;
  color: var(--color-text-muted);
  font-size: 0.78rem;
  font-style: italic;
}

/* Persona onboarding modal */
.persona-onboarding-overlay {
  position: fixed;
  inset: 0;
  background: rgba(2, 6, 23, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1400;
  padding: 20px;
}

.persona-onboarding-modal {
  background: rgba(15, 23, 42, 0.98);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 560px;
  padding: 22px 24px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.persona-onboarding-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

.persona-onboarding-head strong {
  display: block;
  font-size: 1.05rem;
  margin-bottom: 4px;
}

.persona-onboarding-head p {
  margin: 0;
  color: var(--color-text-muted);
  font-size: 0.82rem;
  line-height: 1.5;
}

.persona-onboarding-skip {
  background: none;
  border: none;
  color: var(--color-text-muted);
  font-size: 0.78rem;
  cursor: pointer;
  padding: 2px 6px;
}

.persona-onboarding-options {
  display: grid;
  gap: 10px;
}

.persona-onboarding-option {
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-align: left;
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg);
  padding: 12px 14px;
  cursor: pointer;
  color: var(--color-text-secondary);
}

.persona-onboarding-option:hover {
  border-color: var(--color-border-strong);
}

.persona-onboarding-option-selected {
  border-color: var(--color-border-strong);
  box-shadow: 0 0 0 1px var(--color-border-strong);
}

.persona-onboarding-option strong {
  font-size: 0.92rem;
}

.persona-onboarding-flow {
  color: var(--color-data-primary);
  font-size: 0.76rem;
}

.persona-onboarding-detail {
  color: var(--color-text-muted);
  font-size: 0.76rem;
  line-height: 1.45;
}

.persona-onboarding-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 16px;
}

/* Light-theme hardening: the modal previously hardcoded a dark navy surface
   and cyan accents that broke against the light page. Route to tokens so it
   reads correctly in both themes. */
html.light-theme-active .persona-onboarding-overlay {
  background: rgba(15, 23, 42, 0.45);
}
html.light-theme-active .persona-onboarding-modal {
  background: var(--color-surface-card);
  border-color: var(--color-border-medium);
  box-shadow: 0 20px 60px rgba(15, 23, 42, 0.18);
}
html.light-theme-active .persona-onboarding-head p,
html.light-theme-active .persona-onboarding-detail {
  color: var(--color-text-secondary);
}
html.light-theme-active .persona-onboarding-skip {
  color: var(--color-text-secondary);
}
html.light-theme-active .persona-onboarding-option {
  background: var(--color-surface-overlay);
  border-color: var(--color-border-subtle);
  color: var(--color-text-primary);
}
html.light-theme-active .persona-onboarding-option:hover {
  border-color: var(--color-border-strong);
}
html.light-theme-active .persona-onboarding-option-selected {
  border-color: var(--color-border-strong);
  box-shadow: 0 0 0 1px var(--color-border-strong);
}
html.light-theme-active .persona-onboarding-flow {
  color: var(--color-data-primary);
}

.connect-account-overlay {
  position: fixed;
  inset: 0;
  z-index: 140;
  background: var(--color-surface-depth);
  backdrop-filter: blur(10px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.connect-account-window {
  width: min(980px, 96vw);
  background: linear-gradient(180deg, var(--color-surface-card), var(--color-surface-card));
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: 0 28px 80px var(--color-shadow);
}

.connect-account-body {
  padding: 22px 24px 24px;
  display: grid;
  gap: 14px;
}

.view-container {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.placeholder-view {
  background: rgba(0, 0, 0, 0.88);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  padding: 48px;
  text-align: center;
}

.placeholder-view h2 {
  margin-top: 0;
}

/* ── Search Section ────────────────────────────────────────────────── */
.search-section {
  margin-bottom: 28px;
  position: relative;
}

.search-controls {
  display: flex;
  align-items: center;
  background: rgba(0, 0, 0, 0.88);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  padding: 4px 6px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  margin-bottom: 8px;
}

.search-controls:focus-within {
  border-color: var(--color-data-secondary);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.1);
}

.search-input {
  flex: 1;
  padding: 10px 12px;
  border: none;
  background: transparent;
  color: var(--color-text-secondary);
  font-size: 1rem;
  outline: none;
}

.search-type-buttons {
  display: flex;
  background: rgba(0, 0, 0, 0.5);
  border-radius: var(--radius-md);
  padding: 2px;
  gap: 2px;
  margin-left: 8px;
}

.search-type-button {
  padding: 6px 14px;
  border: none;
  border-radius: var(--radius-lg);
  background: transparent;
  color: var(--color-text-muted);
  font-size: 0.8rem;
  font-weight: 700;
  transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease, opacity 0.2s ease, transform 0.2s ease;
  cursor: pointer;
  white-space: nowrap;
}

.search-type-button:hover {
  color: var(--color-text-secondary);
}

.search-type-button.active {
  background: var(--color-data-secondary);
  color: var(--color-text-primary);
}

.search-type-select-wrap {
  display: grid;
  gap: 4px;
  min-width: 172px;
  margin-left: 8px;
}

.search-type-select-wrap span {
  color: var(--color-text-muted);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.search-type-select-shell {
  position: relative;
  display: flex;
  align-items: center;
}

.search-type-select {
  appearance: none;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-xl);
  background: rgba(15, 23, 42, 0.68);
  color: var(--color-text-secondary);
  font-size: 0.84rem;
  font-weight: 700;
  padding: 9px 34px 9px 12px;
  width: 100%;
  cursor: pointer;
}

.search-type-select:focus {
  outline: 1px solid rgba(255, 255, 255, 0.55);
  border-color: rgba(255, 255, 255, 0.5);
}

.search-type-select-caret {
  position: absolute;
  right: 11px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-text-muted);
  font-size: 0.82rem;
  pointer-events: none;
}

.search-context-hint {
  margin: -2px 2px 10px;
  color: var(--color-text-muted);
  font-size: 0.77rem;
  line-height: 1.35;
}

.search-context-hint-button {
  border: none;
  background: transparent;
  color: var(--color-text-secondary);
  font-weight: 700;
  padding: 0;
  margin: 0;
  cursor: pointer;
  font: inherit;
}

.search-context-hint-button:hover {
  color: var(--color-text-primary);
}

.search-context-hint-button:focus-visible {
  outline: 1px solid rgba(255, 255, 255, 0.55);
  outline-offset: 3px;
  border-radius: var(--radius-md);
}

.search-results {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: rgba(0, 0, 0, 0.96);
  border: 1px solid var(--color-border-medium);
  border-top: none;
  border-radius: 0 0 12px 12px;
  margin-top: -1px;
  max-height: 600px;
  overflow-y: auto;
  z-index: 100;
}

.search-category-group {
  border-bottom: 1px solid var(--color-border-medium);
  padding: 12px 0;
}

.search-category-group:last-child {
  border-bottom: none;
}

.search-category-title {
  margin: 0;
  padding: 8px 16px;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.search-results-list {
  display: flex;
  flex-direction: column;
}

.search-result-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border-medium);
  transition: background-color 0.15s ease;
}

.search-result-item:hover {
  background: rgba(148, 163, 184, 0.08);
}

.search-result-item:last-child {
  border-bottom: none;
}

.search-result-info {
  flex: 1;
}

.search-result-symbol {
  font-weight: 700;
  color: var(--color-text-primary);
  font-size: 0.95rem;
}

.search-result-name {
  color: var(--color-text-secondary);
  font-size: 0.85rem;
  margin-top: 2px;
}

.search-result-type {
  color: var(--color-text-muted);
  font-size: 0.75rem;
  margin-top: 4px;
  font-weight: 600;
  text-transform: uppercase;
}

.search-loading {
  padding: 16px;
  text-align: center;
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

.search-no-results {
  padding: 16px;
  text-align: center;
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

.star-button {
  background: none;
  border: none;
  color: var(--color-text-secondary);
  font-size: 1.4rem;
  cursor: pointer;
  padding: 4px;
  transition: color 0.2s ease, transform 0.2s ease;
  flex-shrink: 0;
}

.star-button:hover {
  color: var(--color-data-amber-bright);
  transform: scale(1.15);
}

.star-button.active {
  color: var(--color-data-amber-bright) !important;
  text-shadow: 0 0 10px rgba(251, 191, 36, 0.6);
  filter: drop-shadow(0 0 3px rgba(251, 191, 36, 0.3));
  animation: star-pulse 2s infinite ease-in-out;
}

@keyframes star-pulse {
  0% { transform: scale(1); text-shadow: 0 0 8px rgba(251, 191, 36, 0.4); }
  50% { transform: scale(1.1); text-shadow: 0 0 15px rgba(251, 191, 36, 0.8); }
  100% { transform: scale(1); text-shadow: 0 0 8px rgba(251, 191, 36, 0.4); }
}

.watchlist-panel,
.portfolio-panel {
  background: var(--color-surface-panel);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  padding: var(--card-padding-large);
}

/* ── Category tabs ─────────────────────────────────────────────────── */
.category-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 20px;
}

.category-tabs button {
  border: 1px solid var(--color-border-medium);
  background: transparent;
  color: var(--color-text-muted);
  padding: 0 12px;
  min-height: 32px;
  border-radius: var(--radius-md);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease;
}

.category-tabs button.active {
  background: var(--color-interactive-soft);
  border-color: var(--color-interactive);
  color: var(--color-interactive);
}

.category-tabs button:hover {
  background: var(--color-surface-hover);
  border-color: var(--color-border-strong);
  color: var(--color-text-primary);
}

/* ── Crypto spot / futures tabs ────────────────────────────────────── */
.market-tabs {
  display: flex;
  gap: 10px;
  margin-bottom: 18px;
}

.market-tabs button {
  border: var(--color-border-medium);
  background: transparent;
  color: var(--color-text-secondary);
  padding: 10px 16px;
  border-radius: var(--radius-full);
  transition: transform 0.2s ease, background-color 0.2s ease;
}

.market-tabs button.active {
  background: var(--color-data-secondary);
  border-color: var(--color-data-secondary);
  color: var(--color-text-primary);
  font-weight: 700;
  transform: translateY(-1px);
}

.market-tabs button:hover {
  background: var(--color-interactive-soft);
  border-color: var(--color-data-secondary);
  color: var(--color-data-secondary);
  transform: translateY(-1px);
}

/* ── Stock theme filter pills ──────────────────────────────────────── */
.theme-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 4px 0 14px;
}

.indicator-controls-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.indicator-country-tabs {
  flex: 1;
  min-width: 0;
}

.theme-pill {
  padding: 5px 13px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-medium);
  background: transparent;
  color: var(--color-text-muted);
  font-size: 0.825rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s, transform 0.15s;
  white-space: nowrap;
}

.theme-pill:hover {
  border-color: var(--color-text-muted);
  color: var(--color-text-muted);
  transform: translateY(-1px);
}

.theme-pill.active {
  background: var(--color-data-secondary);
  border-color: var(--color-data-secondary);
  color: var(--color-text-primary);
  font-weight: 700;
}

/* ── Theme heading ─────────────────────────────────────────────────── */
.theme-heading {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 0 0 12px;
}

.theme-label {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-text-secondary);
  letter-spacing: 0.02em;
}

.theme-count {
  font-size: 0.825rem;
  color: var(--color-text-muted);
}

/* ── Category badge on stock cards ────────────────────────────────── */
.category-badge {
  display: inline-block;
  margin-top: 5px;
  padding: 2px 8px;
  border-radius: var(--radius-md);
  background: rgba(148, 163, 184, 0.1);
  color: var(--color-text-muted);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ── Asset grid ────────────────────────────────────────────────────── */
.asset-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 18px;
}

.watchlist-header-actions {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.asset-card,
.portfolio-card {
  background: var(--color-surface-card-strong);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  padding: 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 16px;
}

.portfolio-card {
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  padding: 16px;
}

.portfolio-left {
  flex: 1;
  min-width: 200px;
}

.portfolio-center {
  text-align: right;
  min-width: 86px;
  margin-left: auto;
}

.portfolio-quantity {
  min-width: 70px;
}

.quantity-readonly {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: rgba(148, 163, 184, 0.04);
  color: var(--color-text-secondary);
  font-size: 0.85rem;
  text-align: center;
  font-weight: 600;
}

.portfolio-value {
  text-align: right;
  min-width: 120px;
}

.price-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.price {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-primary);
}

.change {
  font-size: 0.85rem;
  font-weight: 600;
}

.change.positive {
  color: var(--color-data-green-bright);
}

.change.negative {
  color: var(--color-data-red-bright);
}

.position-value {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-primary);
}

.position-gain {
  font-size: 0.85rem;
  font-weight: 600;
}

.position-gain.positive {
  color: var(--color-data-green-bright);
}

.position-gain.negative {
  color: var(--color-data-red-bright);
}

.portfolio-summary {
  display: flex;
  gap: 24px;
  padding-top: 16px;
  border-top: var(--color-border-medium);
  margin-top: 8px;
}

.summary-item {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  flex: 1;
}

.summary-item span {
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

.summary-item strong {
  color: var(--color-text-primary);
  font-weight: 600;
}

.summary-item strong.positive {
  color: var(--color-data-green-bright);
}

.summary-item strong.negative {
  color: var(--color-data-red-bright);
}

.asset-card strong,
.portfolio-card strong {
  display: block;
  font-size: 1.1rem;
  margin-bottom: 4px;
}

.asset-price {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 10px;
  font-size: 0.98rem;
  color: var(--color-text-primary);
}

/* §5 Watchlist row quote-status badge.
   Text is the primary signal; color is a supporting cue only (Brand v2
   monochrome). Compact, no horizontal page overflow, touch-friendly. */
.quote-status {
  display: inline-flex;
  align-items: center;
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  line-height: 1;
  padding: 3px 7px;
  min-height: 20px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border, #404040);
  color: var(--color-text-secondary, #a1a1a1);
  background: transparent;
  white-space: nowrap;
}
.quote-status-live { color: var(--color-positive, var(--color-success)); border-color: var(--color-positive, var(--color-success)); }
.quote-status-cached { color: var(--color-text-secondary, #a1a1a1); }
.quote-status-stale { color: var(--color-warning, #fbbf24); border-color: var(--color-warning, #fbbf24); }
.quote-status-unavailable { color: var(--color-text-secondary, #a1a1a1); border-style: dashed; }
.quote-status-unknown { color: var(--color-text-secondary, #a1a1a1); border-style: dotted; }

.watchlist-last-cell {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.price-change {
  padding: 4px 10px;
  border-radius: var(--radius-full);
  font-size: 0.88rem;
  font-weight: 700;
}

.price-change.positive {
  background: rgba(34, 197, 94, 0.2);
  color: var(--color-data-green-bright);
}

.price-change.negative {
  background: rgba(248, 113, 113, 0.18);
  color: var(--color-data-red-bright);
}

/* ── Empty state ───────────────────────────────────────────────────── */
.empty-state {
  grid-column: 1 / -1;
  padding: 32px;
  text-align: center;
  color: var(--color-text-muted);
  font-size: 0.875rem;
}

/* ── Loading / error ───────────────────────────────────────────────── */
.loading-state {
  padding: 18px;
  border-radius: var(--radius-md);
  background: rgba(0, 0, 0, 0.96);
  border: 1px solid var(--color-border-medium);
  color: var(--color-text-secondary);
}

.snapshot-inline-note {
  color: var(--color-data-amber-bright);
  font-size: 0.84rem;
  line-height: 1.5;
}

.error {
  padding: 16px;
  border-radius: var(--radius-md);
  background: rgba(248, 113, 113, 0.16);
  color: var(--color-data-red-bright);
}

.stale-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(245, 158, 11, 0.35);
  background: rgba(245, 158, 11, 0.08);
  color: var(--color-data-amber-bright);
  font-size: 0.84rem;
  font-weight: 600;
}

.data-health-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  border: 1px solid var(--color-border-medium);
  color: var(--color-text-secondary);
  background: rgba(15, 23, 42, 0.4);
}

.data-health-badge.ok {
  color: var(--color-data-green-bright);
  border-color: rgba(34, 197, 94, 0.4);
  background: rgba(34, 197, 94, 0.1);
}

.data-health-badge.loading {
  color: var(--color-data-primary);
  border-color: rgba(255, 255, 255, 0.45);
  background: var(--color-surface-selected-strong);
}

.data-health-badge.hazard {
  color: var(--color-data-amber-bright);
  border-color: rgba(245, 158, 11, 0.5);
  background: rgba(245, 158, 11, 0.13);
}

.status-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.status-icon.spinner {
  animation: statusSpin 0.9s linear infinite;
}

@keyframes statusSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.chart-refresh-overlay {
  position: absolute;
  top: 10px;
  right: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-subtle);
  background: var(--color-surface-elevated);
  color: var(--color-data-primary);
}

.asset-modal-more-link {
  border: none;
  background: transparent;
  color: var(--color-data-primary);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  padding: 0;
}

.asset-modal-more-link:hover {
  color: #bae6fd;
  text-decoration: underline;
}

.company-page {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.company-page-header {
  display: flex;
  align-items: flex-start;
  gap: 18px;
  padding: 22px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background:
    radial-gradient(circle at top left, rgba(148, 163, 184, 0.12), transparent 38%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.94), rgba(0, 0, 0, 0.96));
  overflow: hidden;
}

.company-page-back {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-full);
  padding: 9px 14px;
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  font-weight: 700;
}

.company-page-back:hover {
  border-color: var(--color-border-medium);
  background: rgba(148, 163, 184, 0.12);
}

.company-page-title-wrap {
  flex: 1;
  min-width: 0;
}

.company-page-kicker {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.company-page-title-wrap h1 {
  margin: 0;
  font-size: clamp(1.8rem, 3vw, 2.7rem);
  line-height: 1.02;
  color: var(--color-text-primary);
}

.company-page-subtitle {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.company-page-subtitle span {
  padding: 5px 10px;
  border-radius: var(--radius-full);
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-medium);
  color: var(--color-text-secondary);
  font-size: 0.78rem;
  font-weight: 600;
}

.company-page-title-wrap p {
  margin: 14px 0 0;
  max-width: 900px;
  color: var(--color-text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

.company-page-fallback-note {
  margin-top: 12px;
  color: var(--color-data-amber-bright);
  font-size: 0.88rem;
  line-height: 1.5;
}

.company-page-health {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px 14px;
  min-width: 150px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(34, 197, 94, 0.3);
  background: rgba(0, 0, 0, 0.56);
  color: var(--color-data-green-bright);
  font-weight: 700;
  font-size: 0.78rem;
}

.company-page-health span {
  color: var(--color-text-muted);
  font-weight: 600;
}

.company-page-health.hazard {
  color: var(--color-data-amber-bright);
  border-color: rgba(245, 158, 11, 0.35);
}

.company-page-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px;
}

.company-page-briefing {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
}

.company-stat-card,
.company-earnings-card,
.company-page-framework,
.company-page-briefing-card,
.company-page-finviz-card {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: var(--color-surface-card);
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.18);
}

.company-page-finviz-card {
  margin-bottom: 24px;
}

.company-finviz-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 1px;
  background: var(--color-border-subtle);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  margin: 16px;
}

.company-finviz-cell {
  background: var(--color-surface-card);
  padding: 6px 10px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.finviz-label {
  color: var(--color-text-muted);
  font-size: 0.72rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.finviz-value {
  color: var(--color-text-primary);
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
}
.finviz-value.positive { color: var(--color-data-green-bright); }
.finviz-value.negative { color: var(--color-data-red-bright); }

.company-stat-card {
  padding: 16px;
}

.company-stat-card span {
  display: block;
  margin-bottom: 8px;
  color: var(--color-text-muted);
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.company-stat-card strong {
  display: block;
  color: var(--color-text-primary);
  font-size: 1.25rem;
}

.company-stat-subtext {
  display: block;
  margin-top: 4px;
  color: var(--color-text-muted);
  font-size: 0.72rem;
  font-style: normal;
}

.company-page-framework {
  padding: 18px;
}

.company-page-briefing-card {
  padding: 18px;
}

.company-page-briefing-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.company-page-briefing-head h2 {
  margin: 0;
  font-size: 1rem;
  color: var(--color-text-primary);
}

.company-page-source-list,
.company-page-filing-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.company-page-source-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  max-width: 100%;
  padding: 8px 12px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-medium);
  background: rgba(0, 0, 0, 0.66);
  color: var(--color-text-secondary);
  font-size: 0.8rem;
  font-weight: 600;
  text-decoration: none;
}

.company-page-source-pill:hover {
  border-color: var(--color-border-medium);
  color: var(--color-text-secondary);
}

.company-page-filing-row {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) auto auto auto;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  background: rgba(0, 0, 0, 0.52);
  color: var(--color-text-secondary);
}

.company-page-filing-row span {
  color: var(--color-text-muted);
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.company-page-filing-row strong {
  color: var(--color-text-primary);
  font-size: 0.88rem;
}

.company-page-filing-row em {
  color: var(--color-text-secondary);
  font-style: normal;
  font-size: 0.84rem;
}

.company-page-filing-row a {
  color: var(--color-text-secondary);
  font-size: 0.84rem;
  font-weight: 700;
  text-decoration: none;
}

.company-page-filing-row a:hover {
  color: var(--color-text-secondary);
}

.company-page-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
}

.company-page-tab {
  padding: 9px 16px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-medium);
  background: rgba(0, 0, 0, 0.74);
  color: var(--color-text-secondary);
  font-weight: 700;
  font-size: 0.84rem;
  transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease, opacity 0.2s ease, transform 0.2s ease;
  cursor: pointer;
}

.company-page-tab:hover {
  background: rgba(0, 0, 0, 0.9);
  border-color: var(--color-border-medium);
  transform: translateY(-1px);
}

.company-page-tab.active-base {
  border-color: var(--color-success);
  background: rgba(16, 185, 129, 0.15);
  color: #6ee7b7;
  box-shadow: 0 0 15px rgba(16, 185, 129, 0.1);
}

.company-page-tab.active-deep {
  border-color: var(--color-warning);
  background: rgba(245, 158, 11, 0.15);
  color: var(--color-data-amber-bright);
  box-shadow: 0 0 15px rgba(245, 158, 11, 0.1);
}

.company-page-tab.active-intel {
  border-color: var(--color-border-medium);
  background: rgba(148, 163, 184, 0.14);
  color: var(--color-text-secondary);
  box-shadow: 0 0 15px rgba(148, 163, 184, 0.14);
}

.company-page-legend,
.company-page-empty {
  padding: 12px 14px;
  border-radius: var(--radius-md);
  background: rgba(0, 0, 0, 0.6);
  color: var(--color-text-muted);
  line-height: 1.65;
}

.company-page-sections {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 14px;
}

.company-section {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--color-surface-card);
}

.company-section-header {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 16px;
  border: none;
  background: transparent;
  color: inherit;
  text-align: left;
}

.company-section-header:hover {
  background: rgba(148, 163, 184, 0.08);
}

.company-section-icon {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-md);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.78rem;
  font-weight: 600;
  flex-shrink: 0;
}

.company-section-icon.icon-base {
  background: rgba(29, 158, 117, 0.16);
  color: var(--color-data-green-bright);
}

.company-section-icon.icon-deep {
  background: rgba(186, 117, 23, 0.18);
  color: var(--color-data-amber-bright);
}

.company-section-title {
  flex: 1;
  color: var(--color-text-primary);
  font-size: 0.95rem;
  font-weight: 700;
}

.company-section-meta,
.company-section-chevron {
  color: var(--color-text-muted);
  font-size: 0.75rem;
  font-weight: 600;
}

.company-section-body {
  border-top: 1px solid var(--color-border-medium);
}

.company-section-item {
  padding: 14px 16px 14px 58px;
  border-bottom: 1px solid var(--color-border-medium);
}

.company-section-item:last-child {
  border-bottom: none;
}

.company-item-title {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 7px;
  color: var(--color-text-primary);
  font-size: 0.9rem;
  font-weight: 700;
}

.company-item-badge {
  padding: 2px 8px;
  border-radius: var(--radius-full);
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.company-item-badge.badge-context {
  background: rgba(148, 163, 184, 0.14);
  color: var(--color-text-secondary);
}

.company-item-badge.badge-quantitative {
  background: rgba(148, 163, 184, 0.18);
  color: var(--color-text-secondary);
}

.company-item-badge.badge-risk {
  background: rgba(239, 68, 68, 0.16);
  color: var(--color-data-red-bright);
}

.company-item-badge.badge-strength {
  background: rgba(34, 197, 94, 0.16);
  color: var(--color-data-green-bright);
}

.company-item-badge.badge-watch {
  background: rgba(245, 158, 11, 0.16);
  color: var(--color-data-amber-bright);
}

.company-item-description {
  margin: 0 0 8px;
  color: var(--color-text-secondary);
  line-height: 1.65;
}

.company-item-bullets {
  list-style: none;
  margin: 0;
  padding: 0;
}

.company-item-bullets li {
  position: relative;
  padding: 4px 0 4px 14px;
  color: var(--color-text-muted);
  line-height: 1.6;
}

.company-item-bullets li::before {
  content: "·";
  position: absolute;
  left: 2px;
  top: 3px;
  color: var(--color-text-muted);
  font-size: 1rem;
}

.company-earnings-card {
  padding: 18px;
}

.company-earnings-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.company-earnings-head h2 {
  margin: 0;
  font-size: 1.05rem;
  color: var(--color-text-primary);
}

.company-earnings-head span {
  color: var(--color-text-muted);
  font-size: 0.82rem;
  font-weight: 700;
}

.company-earnings-table-wrap {
  overflow-x: auto;
}

.company-earnings-table {
  width: 100%;
  border-collapse: collapse;
}

.company-earnings-table th,
.company-earnings-table td {
  padding: 11px 12px;
  border-bottom: 1px solid var(--color-border-medium);
  text-align: left;
  font-size: 0.84rem;
}

.company-earnings-table th {
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.72rem;
}

.company-earnings-table td {
  color: var(--color-text-secondary);
}

.company-earnings-table td.positive {
  color: var(--color-data-green-bright);
  font-weight: 700;
}

.company-earnings-table td.negative {
  color: var(--color-data-red-bright);
  font-weight: 700;
}

@media (max-width: 900px) {
  .company-page-header {
    flex-wrap: wrap;
  }

  .company-page-health {
    min-width: 0;
    width: 100%;
  }

  .company-page-filing-row {
    grid-template-columns: 1fr;
    justify-items: flex-start;
  }

  .company-section-item {
    padding-left: 16px;
  }
}

/* ── Misc ──────────────────────────────────────────────────────────── */
.meta {
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

.asset-card button,
.portfolio-card button {
  border: none;
  border-radius: var(--radius-full);
  padding: 10px 14px;
  background: var(--color-surface-elevated);
  color: var(--color-text-primary);
  font-weight: 600;
  flex-shrink: 0;
  min-width: 90px;
}

.portfolio-remove-button {
  padding: 0;
  min-width: unset;
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--color-surface-elevated);
  margin-left: 4px;
  font-size: 0.82rem;
}

.portfolio-remove-button:hover {
  background: var(--color-surface-elevated);
}

.portfolio-list {
  display: grid;
  gap: 14px;
}

@media (width <= 960px) {
  .app-layout {
    flex-direction: column;
  }

  .sidebar {
    position: static;
    top: auto;
    height: auto;
    width: 100%;
    padding-bottom: 24px;
    border-bottom: 1px solid var(--color-border-medium);
  }

  .portfolio-card {
    flex-wrap: wrap;
  }

  .pagination-controls {
    flex-direction: column;
    align-items: stretch;
  }
}

.pagination-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 20px;
}

.pagination-button {
  border: 1px solid var(--color-border-medium);
  background: transparent;
  color: var(--color-text-secondary);
  padding: 10px 16px;
  border-radius: var(--radius-full);
  transition: background-color 0.2s ease, transform 0.2s ease;
}

.pagination-button:hover:not(:disabled) {
  background: var(--color-surface-hover);
  transform: translateY(-1px);
}

.pagination-button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.pagination-label {
  color: var(--color-text-muted);
  font-size: 0.95rem;
  font-weight: 600;
}

/* ── Asset Modal ───────────────────────────────────────────────────── */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 20px;
}

.modal-content {
  background: var(--color-surface-card-strong);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  width: 100%;
  max-width: 700px;
  overflow: hidden;
  box-shadow: var(--shadow-3);
  display: flex;
  flex-direction: column;
}

.asset-modal-window {
  width: min(720px, 100%);
  max-width: min(720px, calc(100vw - 32px));
  max-height: min(88vh, 760px);
  overflow-y: auto;
  box-shadow: var(--shadow-2);
}

.asset-modal-window-expanded {
  width: min(1180px, 100%);
  max-width: min(1180px, calc(100vw - 32px));
  max-height: min(94vh, 980px);
}

.modal-content,
.prediction-modal-window,
.watchlist-add-modal,


.modal-header {
  padding: 20px 24px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  border-bottom: 1px solid var(--color-border-subtle);
}

.modal-header .asset-info h2 {
  margin: 0;
  font-size: 1.65rem;
  color: var(--color-text-primary);
}

.modal-header .asset-info p {
  margin: 4px 0 0;
  color: var(--color-text-muted);
}

.modal-header .asset-price {
  text-align: right;
  margin-right: 40px;
}

.modal-header .asset-price .price {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--color-text-primary);
}

.close-btn {
  background: transparent;
  border: none;
  color: var(--color-text-muted);
  font-size: 2rem;
  cursor: pointer;
  padding: 0;
  line-height: 1;
  transition: color 0.2s;
}

.close-btn:hover {
  color: var(--color-text-primary);
}

.chart-section {
  padding: 16px clamp(16px, 2vw, 24px);
  display: grid;
  gap: 14px;
}

.interval-toggle {
  display: flex;
  gap: 8px;
  justify-content: center;
}

.interval-toggle button {
  background: rgba(148, 163, 184, 0.05);
  border: 1px solid var(--color-border-medium);
  color: var(--color-text-muted);
  padding: 6px 14px;
  border-radius: var(--radius-md);
  font-size: 0.85rem;
  font-weight: 600;
  transition: color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s, transform 0.2s;
}

.interval-toggle button:hover {
  background: rgba(148, 163, 184, 0.1);
  color: var(--color-text-secondary);
}

.interval-toggle button.active {
  background: var(--color-surface-elevated);
  border-color: var(--color-text-secondary);
  color: var(--color-text-primary);
}

.chart-container {
  min-height: 220px;
  height: clamp(220px, 32vh, 300px);
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(10, 10, 10, 0.8);
  margin: 0;
  position: relative;
  z-index: 1;
  border-radius: var(--radius-md);
  overflow: hidden;
}

.chart-loading,
.chart-no-data {
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

.asset-modal-loader {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-subtle);
  background: var(--color-surface-elevated);
  color: var(--color-data-primary);
  font-size: 1.2rem;
}

.asset-modal-loader-compact {
  width: 44px;
  height: 44px;
  margin: 0 auto;
}

.modal-footer {
  padding: 18px 24px;
  background: rgba(148, 163, 184, 0.03);
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  border-top: 1px solid var(--color-border-medium);
}

.asset-modal-window .modal-header {
  padding: 14px 18px;
}

.asset-modal-window .modal-footer {
  position: sticky;
  bottom: 0;
  z-index: 2;
  padding: 12px 18px;
  backdrop-filter: blur(10px);
}

/* P9 — Commodity-first modal summary (Brand v2: monochrome, dense) */
.commodity-modal-summary {
  display: grid;
  gap: 10px;
  padding: 12px 18px;
  border-top: 1px solid var(--color-border-subtle);
  border-bottom: 1px solid var(--color-border-subtle);
  background: var(--color-surface-elevated);
}
.commodity-modal-summary .cms-tier {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px 16px;
}
.commodity-modal-summary .cms-tier-4 {
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  font-size: 11px;
  color: var(--color-data-slate);
}
.commodity-modal-summary .cms-metric {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.commodity-modal-summary .cms-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--color-text-secondary);
}
.commodity-modal-summary .cms-value {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-text-primary);
}
.commodity-modal-summary .cms-sub {
  font-size: 11px;
  font-weight: 400;
  color: var(--color-data-slate);
}
.commodity-modal-summary .cms-tone-positive { color: var(--color-data-up); }
.commodity-modal-summary .cms-tone-negative { color: var(--color-data-down); }
.commodity-modal-summary .cms-tone-neutral { color: var(--color-text-primary); }
.commodity-modal-summary .cms-meta { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* P4 — Commodity breadcrumbs (Brand v2: monochrome, clickable) */
.commodity-breadcrumbs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 2px;
  padding: 8px 18px 0;
  font-size: 12px;
  color: var(--color-data-slate);
}
.commodity-breadcrumbs .cb-crumb-wrap { display: inline-flex; align-items: center; gap: 2px; }
.commodity-breadcrumbs .cb-sep { color: var(--color-data-slate-dim); padding: 0 4px; }
.commodity-breadcrumbs .cb-crumb { color: var(--color-data-slate); }
.commodity-breadcrumbs .cb-link {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font: inherit;
  color: var(--color-text-secondary);
}
.commodity-breadcrumbs .cb-link:hover { color: var(--color-interactive); text-decoration: underline; }
.commodity-breadcrumbs .cb-current { color: var(--color-text-primary); font-weight: 600; }

.quantity-input {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.quantity-input label {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.quantity-input input {
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  color: var(--color-text-primary);
  font-size: 1.1rem;
  width: 136px;
}

.quantity-input input:focus {
  outline: none;
  border-color: var(--color-text-secondary);
  background: var(--color-surface-depth);
}

.add-btn {
  background: var(--color-surface-elevated);
  color: white;
  border: none;
  border-radius: var(--radius-md);
  padding: 14px 28px;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.2s, background 0.2s;
}

.add-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  background: #52525b;
}

.add-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ── Order Controls ────────────────────────────────────────────────── */
.order-type-toggle {
  display: flex;
  gap: 12px;
  margin-top: 8px;
  justify-content: center;
  padding: 0;
}

.order-type-toggle button {
  flex: 1;
  max-width: 200px;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  font-weight: 700;
  font-size: 0.95rem;
  border: 1px solid var(--color-border-medium);
  background: rgba(148, 163, 184, 0.05);
  color: var(--color-text-muted);
  cursor: pointer;
  transition: color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s, transform 0.2s;
}

.buy-selector.active {
  background: var(--color-success);
  border-color: var(--color-success);
  color: white;
  box-shadow: 0 0 20px rgba(34, 197, 94, 0.2);
}

.sell-selector.active {
  background: var(--color-danger);
  border-color: var(--color-danger);
  color: white;
  box-shadow: 0 0 20px rgba(239, 68, 68, 0.2);
}

.confirm-order-btn {
  border: none;
  border-radius: var(--radius-md);
  padding: 14px 28px;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  transition: color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s, transform 0.2s;
}

.confirm-order-btn.buy {
  background: var(--color-success);
  color: white;
}

.confirm-order-btn.sell {
  background: var(--color-danger);
  color: white;
}

.confirm-order-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  filter: brightness(1.1);
}

.confirm-order-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ── Chart Header & Toggle ─────────────────────────────────────────── */
.chart-header-controls {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 0;
  padding: 0;
}

.chart-type-toggle {
  display: flex;
  background: rgba(148, 163, 184, 0.05);
  border-radius: var(--radius-md);
  padding: 4px;
  border: 1px solid var(--color-border-medium);
}

.chart-type-toggle button {
  background: transparent;
  border: none;
  color: var(--color-text-muted);
  padding: 6px 14px;
  border-radius: var(--radius-md);
  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
  transition: color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s, transform 0.2s;
}

.chart-type-toggle button.active {
  background: var(--color-data-secondary);
  color: var(--color-text-primary);
}

.asset-chart-toolbar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
}

.asset-chart-toolbar .chart-type-toggle button {
  min-height: 40px;
}

.asset-chart-tool-btn {
  min-height: 40px;
  padding: 0 12px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-medium);
  background: rgba(148, 163, 184, 0.05);
  color: var(--color-text-muted);
  font-size: 0.78rem;
  font-weight: 800;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
}

.asset-chart-tool-btn:hover,
.asset-chart-tool-btn.active {
  background: rgba(255, 255, 255, 0.13);
  border-color: rgba(255, 255, 255, 0.34);
  color: #e0f2fe;
}

.asset-chart-indicator-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.asset-chart-indicator-chip {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 11px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-medium);
  background: rgba(148, 163, 184, 0.04);
  color: var(--color-text-muted);
  font-size: 0.75rem;
  font-weight: 800;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease, opacity 0.18s ease;
}

.asset-chart-indicator-chip span {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  opacity: 0.65;
}

.asset-chart-indicator-chip.active {
  background: rgba(15, 23, 42, 0.74);
  border-color: var(--color-border-medium);
  color: var(--color-text-secondary);
}

.asset-chart-indicator-chip.active span {
  opacity: 1;
}

.asset-chart-container {
  border: 1px solid var(--color-border-medium);
}

.asset-chart-container::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 24%;
  height: 1px;
  background: rgba(148, 163, 184, 0.12);
  pointer-events: none;
  z-index: 2;
}

/* ── Modal Footer Layout ──────────────────────────────────────────── */
.footer-left {
  display: flex;
  gap: 20px;
  align-items: center;
}

.total-value-display {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.total-value-display label {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.total-value-display .value-field {
  background: var(--color-surface-card);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  min-width: 136px;
  transition: color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s, transform 0.2s;
}

.total-value-display .value-field:focus-within {
  border-color: var(--color-text-secondary);
  background: var(--color-surface-card);
}

.total-value-display .value-field input {
  background: transparent;
  border: none;
  color: var(--color-text-primary);
  font-size: 1.1rem;
  font-weight: 700;
  width: 100%;
  outline: none;
  padding: 0;
}

