/* ── Interval Performance Preview ───────────────────────────────── */
.interval-btn-wrapper {
  position: relative;
  display: inline-block;
}

.performance-badge {
  position: absolute;
  top: -24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-surface-card);
  color: var(--color-text-primary);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: var(--radius-md);
  opacity: 0;
  visibility: hidden;
  transition: color 0.2s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.2s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.2s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.2s cubic-bezier(0.4, 0, 0.2, 1), transform 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  border: 1px solid var(--color-border-medium);
  white-space: nowrap;
  pointer-events: none;
  z-index: 100;
}

.interval-btn-wrapper:hover .performance-badge {
  opacity: 1;
  visibility: visible;
  top: -28px;
}

.performance-badge.positive {
  color: var(--color-success);
}

.performance-badge.negative {
  color: var(--color-danger);
}

/* Pulse animation for the hover state */
@keyframes tool-pulse {
  0% {
    transform: translateX(-50%) scale(1);
  }

  50% {
    transform: translateX(-50%) scale(1.05);
  }

  100% {
    transform: translateX(-50%) scale(1);
  }
}

.interval-btn-wrapper:hover .performance-badge {
  animation: tool-pulse 2s infinite ease-in-out;
}

/* ── Interactive Asset Items ─────────────────────────────────────── */
.clickable {
  cursor: pointer;
  transition: transform 0.2s ease, background-color 0.2s ease, box-shadow 0.2s ease;
}

.asset-card.clickable:hover {
  background: rgba(15, 15, 15, 0.7);
  transform: translateY(-4px);
  box-shadow: 0 10px 20px -5px rgba(0, 0, 0, 0.3);
}

@media (prefers-reduced-motion: no-preference) {
  .asset-card.live-up {
    animation: liveFlashUp 1.1s ease;
  }

  .asset-card.live-down {
    animation: liveFlashDown 1.1s ease;
  }
}

@keyframes liveFlashUp {
  0% { box-shadow: 0 0 0 0 rgba(34, 197, 94, 0); }
  25% { box-shadow: 0 0 0 3px rgba(34, 197, 94, 0.28); }
  100% { box-shadow: 0 0 0 0 rgba(34, 197, 94, 0); }
}

@keyframes liveFlashDown {
  0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
  25% { box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.24); }
  100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
}

.search-result-item.clickable:hover {
  background: rgba(148, 163, 184, 0.1);
}

.module-loading-state {
  min-height: 280px;
  display: grid;
  place-items: center;
