/* ── Watchlist Star Button ───────────────────────────────────────── */
.asset-card {
  position: relative;
}

.modal-shake {
  animation: modalShake 0.56s cubic-bezier(.36,.07,.19,.97) both;
}

@keyframes modalShake {
  10%, 90% { transform: translate3d(-1px, 0, 0); }
  20%, 80% { transform: translate3d(2px, 0, 0); }
  30%, 50%, 70% { transform: translate3d(-4px, 0, 0); }
  40%, 60% { transform: translate3d(4px, 0, 0); }
}

.trade-effect-layer {
  pointer-events: none;
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 5;
}

.confetti-piece {
  position: absolute;
  left: var(--x);
  top: -10px;
  width: 8px;
  height: 14px;
  border-radius: var(--radius-sm);
  background: var(--bg);
  animation: confettiDrop 0.95s ease-out forwards;
  animation-delay: var(--delay);
}

@keyframes confettiDrop {
  0% { transform: translateY(0) rotate(0deg); opacity: 0; }
  15% { opacity: 1; }
  100% { transform: translateY(420px) rotate(540deg); opacity: 0; }
}

.firework-burst {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: 6px;
  height: 6px;
  border-radius: var(--radius-full);
  background: var(--bg);
  box-shadow: 0 0 0 rgba(255,255,255,0.7);
  animation: fireworkPop 0.9s ease-out forwards;
  animation-delay: var(--delay);
}

@keyframes fireworkPop {
  0% { transform: scale(0.5); opacity: 0; box-shadow: 0 0 0 rgba(255,255,255,0.7); }
  30% { opacity: 1; }
  100% {
    transform: scale(1.2) translate(0, 0);
    opacity: 0;
    box-shadow: 0 0 28px rgba(255,255,255,0.45);
  }
}

.trade-toast {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 2000;
  min-width: 300px;
  max-width: 450px;
  padding: 16px 20px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-strong);
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(12px) saturate(180%);
  color: var(--color-text-primary);
  font-size: 0.95rem;
  font-weight: 500;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.05);
  animation: tradeToastIn var(--duration-base) var(--ease-out) both;
  transition: transform var(--duration-fast) var(--ease-in), opacity var(--duration-fast) var(--ease-in);
  display: flex;
  align-items: center;
  gap: 12px;
}

.trade-toast.is-closing {
  transform: translateY(8px);
  opacity: 0;
}

.trade-toast.success {
  border-color: rgba(34, 197, 94, 0.4);
  background: rgba(2, 44, 34, 0.85);
  box-shadow: 0 20px 50px rgba(2, 44, 34, 0.4);
}

.trade-toast.error {
  border-color: rgba(239, 68, 68, 0.4);
  background: rgba(69, 10, 10, 0.85);
  box-shadow: 0 20px 50px rgba(69, 10, 10, 0.4);
}

.trade-toast::before {
  content: '';
  display: block;
  width: 4px;
  height: 24px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.trade-toast.success::before { background: var(--color-success); }
.trade-toast.error::before { background: var(--color-danger); }
.trade-toast.info::before { background: var(--color-data-secondary); }

@keyframes tradeToastIn {
  from { transform: translateY(8px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

