  color: var(--color-data-secondary);
  font-size: 1.1rem;
}

.home-asset-item .name {
  font-size: 0.75rem;
  color: var(--color-text-muted);
  text-transform: uppercase;
  font-weight: 600;
}

.home-asset-item .value-info {
  text-align: right;
}

.home-asset-item .price {
  font-weight: 700;
  color: var(--color-text-secondary);
}

.home-asset-item .qty,
.home-asset-item .change {
  font-size: 0.8rem;
  font-weight: 500;
}

.home-asset-item .qty {
  color: var(--color-text-muted);
}

.home-subsection-title {
  font-size: 0.92rem;
}

.home-v2 {
  gap: 18px;
  min-width: 0;
  overflow-x: clip;
}

.home-v2 .positive {
