  flex-direction: column;
  gap: 4px;
}

.home-v2-hero-stat span {
  color: #7f8aa0;
  font-size: 0.84rem;
  font-weight: 600;
}

.home-v2-hero-stat strong {
  color: var(--color-text-primary);
  font-size: 1.25rem;
  font-weight: 700;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.home-v2-attention .section-header {
