}

.home-v2-flow-progress-item {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  padding: 8px 9px;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.home-v2-flow-progress-item span {
  width: 20px;
  height: 20px;
  border-radius: var(--radius-full);
  display: grid;
  place-items: center;
  font-size: 0.72rem;
  font-weight: 700;
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  flex-shrink: 0;
}

.home-v2-flow-progress-item strong {
  color: var(--color-text-muted);
  font-size: 0.78rem;
  font-weight: 600;
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.home-v2-flow-progress-item.active {
  border-color: var(--color-border-strong);
  background: var(--color-surface-elevated);
}

.home-v2-flow-progress-item.active span {
  background: var(--color-text-primary);
  color: var(--color-text-inverse);
}

.home-v2-flow-progress-item.active strong,
.home-v2-flow-progress-item.done strong {
  color: var(--color-text-primary);
}

.home-v2-flow-progress-item.done span {
  background: var(--color-success);
  color: var(--color-text-primary);
}

.home-v2-flow-body {
  min-width: 0;
}

.home-v2-flow-card,
.home-v2-flow-status-card {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: var(--color-surface-elevated);
  padding: 14px;
  min-width: 0;
}

.home-v2-flow-headline {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
  flex-wrap: wrap;
}

.home-v2-flow-headline h3 {
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 1.06rem;
}

.home-v2-flow-headline span {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-full);
  background: var(--color-surface-elevated);
  color: var(--color-text-muted);
  padding: 4px 9px;
  font-size: 0.76rem;
}

.home-v2-flow-card > p {
  margin: 0 0 10px;
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

.home-v2-flow-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.home-v2-flow-list-row {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: var(--color-surface-elevated);
  padding: 9px 10px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
}

.home-v2-flow-list-main,
.home-v2-flow-list-issue {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.home-v2-flow-list-main strong,
.home-v2-flow-list-issue strong {
  color: var(--color-text-secondary);
  font-size: 0.88rem;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.home-v2-flow-list-main span,
.home-v2-flow-list-issue span {
  color: var(--color-text-muted);
  font-size: 0.8rem;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.home-v2-flow-list-pill {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-full);
  font-size: 0.78rem;
  font-weight: 700;
  padding: 3px 9px;
  justify-self: start;
}

.home-v2-flow-list-pill.positive {
  color: var(--color-data-green-bright);
  border-color: var(--color-success);
  background: color-mix(in srgb, var(--color-success) 14%, transparent);
}

.home-v2-flow-list-pill.negative {
  color: var(--color-data-red-bright);
  border-color: var(--color-danger);
  background: color-mix(in srgb, var(--color-danger) 14%, transparent);
}

.home-v2-flow-actions {
  margin-top: 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.home-v2-flow-btn {
  border: 1px solid var(--color-border-subtle);
  border-radius: 9px;
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  font-weight: 600;
  font-size: 0.84rem;
  padding: 8px 12px;
  cursor: pointer;
}

.home-v2-flow-btn.primary {
  background: var(--color-text-primary);
  border-color: var(--color-border-strong);
  color: var(--color-text-inverse);
}

.home-v2-flow-btn.primary.warn {
  background: var(--color-warning);
  border-color: var(--color-warning);
  color: var(--color-text-inverse);
}

.home-v2-flow-btn.primary.risk {
  background: var(--color-danger);
  border-color: var(--color-danger);
  color: var(--color-text-inverse);
}

.home-v2-flow-btn.ghost {
  background: transparent;
  color: var(--color-text-secondary);
}

.home-v2-flow-btn:hover {
  filter: brightness(1.07);
}

.home-v2-flow-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.home-v2-flow-detail-grid strong {
  color: var(--color-text-secondary);
  font-size: 0.85rem;
}

.home-v2-flow-detail-grid p {
  margin: 4px 0 0;
  color: #8ea3be;
  font-size: 0.84rem;
}

.home-v2-flow-metric-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.home-v2-flow-metric-grid div {
  border: 1px solid rgba(51, 65, 85, 0.5);
  border-radius: var(--radius-md);
  background: rgba(15, 23, 42, 0.55);
  padding: 9px 10px;
}

.home-v2-flow-metric-grid span {
  display: block;
  color: var(--color-text-muted);
  font-size: 0.76rem;
}

.home-v2-flow-metric-grid strong {
  display: block;
  color: var(--color-text-primary);
  margin-top: 5px;
  font-size: 0.94rem;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.home-v2-flow-money {
  font-weight: 700;
  text-align: right;
}

.home-v2-flow-money.positive {
  color: var(--color-data-green-bright);
}

.home-v2-flow-money.negative {
  color: var(--color-data-red-bright);
}

.home-v2-flow-summary {
  margin-top: 10px;
  border: 1px solid rgba(51, 65, 85, 0.5);
  border-radius: var(--radius-md);
  background: rgba(2, 12, 31, 0.72);
  padding: 10px 11px;
  color: var(--color-text-muted);
  font-size: 0.87rem;
}

.home-v2-flow-summary strong {
  color: var(--color-text-primary);
}

.home-v2-flow-vol-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.home-v2-flow-vol-grid div {
  border: 1px solid rgba(51, 65, 85, 0.5);
  border-radius: var(--radius-md);
  background: rgba(2, 12, 31, 0.7);
  padding: 9px 10px;
}

.home-v2-flow-vol-grid span {
  color: var(--color-text-muted);
  font-size: 0.8rem;
}

.home-v2-flow-vol-grid strong {
  display: block;
  margin-top: 5px;
  color: var(--color-text-primary);
}

.home-v2-flow-chart-mock {
  margin-top: 10px;
  border: 1px solid rgba(51, 65, 85, 0.45);
  border-radius: var(--radius-md);
  background: rgba(2, 12, 31, 0.72);
  padding: 11px;
  display: flex;
  gap: 8px;
  align-items: flex-end;
  min-height: 72px;
}

.home-v2-flow-chart-mock span {
  display: block;
  height: 4px;
  border-radius: var(--workspace-radius);
  background: var(--color-danger);
}

.home-v2-flow-bullets {
  margin: 0;
  padding-left: 18px;
  color: var(--color-text-muted);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.home-v2-flow-bullets li {
  font-size: 0.86rem;
  line-height: 1.35;
}

.home-v2-flow-status-card {
  text-align: center;
  display: grid;
  gap: 10px;
  justify-items: center;
}

.home-v2-flow-status-card h3 {
  margin: 0;
  color: var(--color-text-secondary);
}

.home-v2-flow-status-card p {
  margin: 0;
  color: var(--color-text-muted);
  max-width: 420px;
}

.home-v2-flow-spinner {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  border: 4px solid rgba(71, 85, 105, 0.4);
  border-top-color: var(--color-data-secondary);
  animation: home-v2-flow-spin 0.9s linear infinite;
}

@keyframes home-v2-flow-spin {
  to {
    transform: rotate(360deg);
  }
}

.home-v2-flow-success-mark {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-full);
  display: grid;
  place-items: center;
  background: rgba(22, 163, 74, 0.3);
  color: var(--color-data-green-bright);
  font-size: 1.55rem;
  font-weight: 800;
}

/* ── Action Workspace (shared centered floating modal) ─────────────────────── */
.aw-overlay {
  position: fixed;
  inset: 0;
  z-index: 1500;
  background: rgba(2, 6, 23, 0.72);
  backdrop-filter: blur(10px) saturate(120%);
  -webkit-backdrop-filter: blur(10px) saturate(120%);
  display: grid;
  place-items: center;
  padding: clamp(12px, 3vw, 28px);
  animation: aw-backdrop-in var(--duration-base) var(--ease-standard);
}

@keyframes aw-backdrop-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

.aw-shell {
  max-height: 90vh;
  width: min(1180px, 100%);
  display: flex;
  flex-direction: column;
  background: var(--color-surface-card);
  border: 1px solid var(--color-border-medium);
  border-radius: 20px;
  box-shadow: var(--shadow-3);
  overflow: hidden;
  transform-origin: center;
  animation: aw-shell-in var(--duration-base) var(--ease-out);
}

@keyframes aw-shell-in {
  from { opacity: 0; transform: translateY(14px) scale(0.95); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

body.light-theme-active .aw-shell {
  background: var(--color-surface-card);
  border-color: var(--color-border-medium);
}

.aw-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 26px 32px 18px;
  border-bottom: 1px solid var(--color-border-subtle);
}

.aw-header-text { min-width: 0; }

.aw-eyebrow {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: 6px;
}

.aw-title {
  margin: 0;
  color: var(--color-text-primary);
  font-size: clamp(1.25rem, 2.4vw, 1.6rem);
  font-weight: 650;
  letter-spacing: -0.01em;
}

.aw-description {
  margin: 8px 0 0;
  color: var(--color-text-secondary);
  font-size: 0.9rem;
  max-width: 72ch;
}

.aw-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.aw-kbd {
  font-family: inherit;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-lg);
  padding: 3px 7px;
  background: var(--color-surface-hover);
}

.aw-close {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border-medium);
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  font-size: 0.95rem;
  cursor: pointer;
  transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard);
}

.aw-close:hover { background: var(--color-surface-hover); color: var(--color-text-primary); }

/* Stepper */
.aw-stepper-wrap {
  padding: 18px 32px 0;
}

.aw-stepper {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(0, 1fr));
  gap: 0;
  position: relative;
}

.aw-stepper::before {
  content: "";
  position: absolute;
  top: 17px;
  left: 8%;
  right: 8%;
  height: 1px;
  background: var(--color-border-medium);
  z-index: 0;
}

.aw-stepper-item { position: relative; z-index: 1; }

.aw-stepper-btn {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  background: transparent;
  border: 0;
  padding: 0;
  cursor: default;
  color: var(--color-text-secondary);
}

.aw-stepper-item.is-clickable .aw-stepper-btn { cursor: pointer; }

.aw-stepper-marker {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-full);
  display: grid;
  place-items: center;
  font-size: 0.8rem;
  font-weight: 700;
  flex-shrink: 0;
  background: var(--color-surface-card);
  border: 1px solid var(--color-border-medium);
  color: var(--color-text-muted);
  transition: background-color var(--duration-base) var(--ease-standard), color var(--duration-base) var(--ease-standard), border-color var(--duration-base) var(--ease-standard);
}

.aw-stepper-label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--color-text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.aw-stepper-item.active .aw-stepper-marker {
  background: var(--color-text-primary);
  border-color: var(--color-text-primary);
  color: var(--color-text-inverse);
  box-shadow: 0 0 0 4px var(--color-surface-hover);
}

.aw-stepper-item.active .aw-stepper-label { color: var(--color-text-primary); }

.aw-stepper-item.done .aw-stepper-marker {
  background: var(--color-surface-elevated);
  border-color: var(--color-border-strong);
  color: var(--color-text-primary);
}

.aw-stepper-item.done .aw-stepper-label { color: var(--color-text-secondary); }

.aw-stepper-item.todo .aw-stepper-label { color: var(--color-text-dim); }

/* Body + diagnostics rail */
.aw-body {
  display: flex;
  gap: 24px;
  padding: 24px 32px;
  overflow-y: auto;
  flex: 1 1 auto;
  min-height: 0;
}

.aw-body.has-rail { align-items: stretch; }

.aw-main { flex: 1 1 auto; min-width: 0; }

.aw-rail {
  flex: 0 0 280px;
  border-left: 1px solid var(--color-border-subtle);
  padding-left: 24px;
  align-self: flex-start;
  position: sticky;
  top: 0;
}

.aw-rail-title {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: 12px;
}

.aw-rail-list { margin: 0; display: flex; flex-direction: column; gap: 10px; }

.aw-rail-list > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 0.82rem;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--color-border-subtle);
}

.aw-rail-list > div:last-child { border-bottom: 0; }

.aw-rail-list dt { color: var(--color-text-muted); margin: 0; }
.aw-rail-list dd { color: var(--color-text-secondary); margin: 0; font-weight: 600; text-align: right; }

/* Footer */
.aw-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 32px;
  border-top: 1px solid var(--color-border-subtle);
  background: var(--color-surface-card);
