  bottom: 0;
}

.aw-footer-left { display: flex; gap: 8px; align-items: center; }
.aw-footer-right { display: flex; gap: 8px; align-items: center; }

.aw-btn {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-xl);
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  font-weight: 600;
  font-size: 0.84rem;
  padding: 9px 16px;
  cursor: pointer;
  transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard);
}

.aw-btn:hover { background: var(--color-surface-hover); color: var(--color-text-primary); }

.aw-btn.ghost { background: transparent; border-color: var(--color-border-subtle); }

.aw-btn.primary {
  background: var(--color-text-primary);
  color: var(--color-text-inverse);
  border-color: var(--color-text-primary);
}

.aw-btn.primary:hover { background: var(--color-interactive-hover); }

/* Rebalancing decision dashboard */
.aw-dash {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 12px;
  margin: 4px 0 20px;
}

.aw-dash-metric {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-xl);
  background: var(--color-surface-elevated);
  padding: 14px 16px;
}

.aw-dash-metric .label {
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.aw-dash-metric .value {
  margin-top: 6px;
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--color-text-primary);
  letter-spacing: -0.01em;
}

.aw-dash-metric .value.pos { color: var(--color-data-green-bright); }
.aw-dash-metric .value.neg { color: var(--color-data-red-bright); }

.aw-reco {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-xl);
  padding: 16px;
  background: var(--color-surface-hover);
  margin-bottom: 16px;
}

.aw-reco h4 { margin: 0 0 6px; color: var(--color-text-primary); font-size: 0.95rem; }
.aw-reco p { margin: 0; color: var(--color-text-secondary); font-size: 0.88rem; line-height: 1.5; }

/* Missing-data remediation table */
.aw-table { width: 100%; border-collapse: collapse; font-size: 0.86rem; }
.aw-table th {
  text-align: left;
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  font-weight: 700;
  padding: 8px 10px;
