}
.aw-pill.unresolved { border-color: rgba(248, 113, 113, 0.4); color: var(--color-data-red-bright); }
.aw-pill.resolving { border-color: var(--color-border-strong); color: var(--color-text-secondary); }

.aw-row-action {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
