}

.portfolio-v2-flow-headline span {
  border: var(--color-border-medium);
  border-radius: var(--radius-full);
  padding: 4px 9px;
  color: var(--color-interactive);
  font-size: 0.78rem;
  font-weight: 700;
}

.portfolio-v2-flow-card p {
  margin: 8px 0 0;
