}

.portfolio-v2-flow-buckets {
  margin-top: 12px;
  display: inline-flex;
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-card);
}
.portfolio-v2-flow-bucket {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--color-text-secondary);
  font: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  padding: 5px 11px;
  border-radius: calc(var(--radius-md) - 2px);
  cursor: pointer;
  white-space: nowrap;
  transition: background 120ms ease, color 120ms ease;
}
.portfolio-v2-flow-bucket:hover { color: var(--color-text-primary); background: var(--color-surface-hover); }
.portfolio-v2-flow-bucket.is-active {
  background: var(--color-surface-elevated);
  color: var(--color-text-primary);
  font-weight: 700;
}
.portfolio-v2-flow-bucket:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 1px; }

/* Monochrome exposure heatmap: cell intensity = weight (not hue). Risk tier
   adds a left accent via border-weight only — never color. */
.portfolio-v2-flow-heatmap {
  margin-top: 12px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(116px, 1fr));
  gap: 6px;
}
.portfolio-v2-flow-heat-cell {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 6px;
  min-height: 64px;
  padding: 9px 10px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--color-text-primary) calc(var(--heat, 10) * 1%), var(--color-surface-elevated));
  color: var(--color-text-primary);
  text-align: left;
  cursor: pointer;
  transition: border-color 120ms ease, transform 120ms ease;
}
.portfolio-v2-flow-heat-cell:hover { border-color: var(--color-text-primary); transform: translateY(-1px); }
.portfolio-v2-flow-heat-cell:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }
.portfolio-v2-flow-heat-name {
  font-size: 0.8rem;
  font-weight: 600;
  line-height: 1.25;
  overflow-wrap: anywhere;
}
.portfolio-v2-flow-heat-weight {
  font-size: 0.92rem;
  font-family: var(--font-mono, monospace);
  font-weight: 700;
}
/* Risk tier → full-surface state, never a decorative side stripe. */
.portfolio-v2-flow-heat-cell.risk-low { border-color: var(--color-border-strong); }
.portfolio-v2-flow-heat-cell.risk-moderate { border-color: var(--color-warning-border); background: var(--color-warning-soft); }
.portfolio-v2-flow-heat-cell.risk-high { border-color: var(--color-warning-border); background: var(--color-warning-soft); }
.portfolio-v2-flow-heat-cell.risk-very-high { border-color: var(--color-danger-border); background: var(--color-danger-soft); }
@media (prefers-reduced-motion: reduce) {
  .portfolio-v2-flow-heat-cell { transition: none; }
  .portfolio-v2-flow-heat-cell:hover { transform: none; }
}

