  gap: 10px;
}

.journal-v2-metric-card {
  border: 1px solid rgba(255, 255, 255, 0.105);
  border-radius: var(--radius-md);
  background: rgba(5, 5, 5, 0.92);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.journal-v2-metric-card span {
  color: var(--color-border-strong);
  font-size: 0.86rem;
}

.journal-v2-metric-card strong {
  color: var(--color-text-primary);
  font-size: 1.8rem;
  line-height: 1.15;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.journal-v2-metric-card em {
  color: var(--color-border-strong);
  font-style: normal;
  font-size: 0.84rem;
}

.journal-v2-metric-card .positive {
  color: var(--color-data-green-bright);
}

.journal-v2-metric-card .negative {
  color: var(--color-data-red-bright);
}

.journal-v2-tabs {
  display: flex;
  gap: 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.488);
  padding-bottom: 4px;
}

.journal-v2-tab {
  border: none;
  background: transparent;
  color: var(--color-text-muted);
  font-weight: 700;
  cursor: pointer;
  padding: 8px 0;
}

.journal-v2-tab.active {
  color: var(--color-text-primary);
  border-bottom: 2px solid var(--color-text-primary);
}

.journal-v2-main-grid {
  display: grid;
  grid-template-columns: minmax(0, 2.3fr) minmax(340px, 1fr);
  gap: 16px;
}

.journal-v2-left,
.journal-v2-right {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.journal-v2-panel {
  border: 1px solid rgba(255, 255, 255, 0.105);
  border-radius: var(--radius-md);
  background: rgba(5, 5, 5, 0.92);
  min-width: 0;
  overflow: hidden;
}

.journal-v2-filter-row {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 10px;
}

.journal-v2-table-wrap {
  overflow-x: auto;
}

.journal-v2-table {
  width: 100%;
  border-collapse: collapse;
}

.journal-v2-table th,
.journal-v2-table td {
  padding: 10px 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.338);
  color: #d9e2ed;
  text-align: left;
  vertical-align: middle;
  font-size: 0.8rem;
}

.journal-v2-table th {
  color: var(--color-text-muted);
  font-size: 0.83rem;
  font-weight: 700;
}

.journal-v2-table tbody tr:hover {
  background: rgba(15, 15, 15, 0.25);
}

.journal-v2-symbol-cell {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.journal-v2-symbol-dot {
  width: 26px;
  height: 26px;
  border-radius: var(--radius-full);
  background: linear-gradient(180deg, var(--color-warning), #f97316);
  display: grid;
  place-items: center;
  color: var(--color-text-primary);
  font-size: 0.86rem;
  font-weight: 700;
}

.journal-v2-symbol-cell strong {
  display: block;
  color: var(--color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 165px;
}

.journal-v2-symbol-cell span {
  display: block;
  color: var(--color-border-strong);
  font-size: 0.78rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 165px;
}

.journal-v2-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  padding: 4px 10px;
  border: 1px solid rgba(255, 255, 255, 0.413);
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--color-text-secondary);
}

.journal-v2-chip.buy {
  color: var(--color-data-green-bright);
  border-color: rgba(16, 185, 129, 0.35);
  background: rgba(6, 78, 59, 0.25);
}

.journal-v2-chip.sell {
  color: var(--color-data-red-bright);
  border-color: rgba(239, 68, 68, 0.35);
  background: rgba(127, 29, 29, 0.25);
}

.journal-v2-chip.status {
  color: var(--color-data-green-bright);
  background: rgba(22, 101, 52, 0.2);
  border-color: rgba(34, 197, 94, 0.3);
}

.journal-v2-footer-row {
  margin-top: 10px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  color: var(--color-border-strong);
  font-size: 0.9rem;
}

.journal-v2-form-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 10px;
}

.journal-v2-form-grid label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: var(--color-border-strong);
  font-size: 0.82rem;
  min-width: 0;
}

.journal-v2-form-grid .full {
  grid-column: 1 / -1;
}

.journal-v2-toggle {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border: 1px solid rgba(255, 255, 255, 0.413);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.journal-v2-toggle button {
  border: none;
  background: color-mix(in srgb, var(--color-surface-elevated) 90%, transparent);
  color: var(--color-text-muted);
  padding: 8px 10px;
  font-weight: 700;
  cursor: pointer;
}

.journal-v2-toggle button.active {
  color: var(--color-text-secondary);
  background: color-mix(in srgb, var(--color-border-medium) 45%, transparent);
}

.journal-v2-conf-row {
  display: grid;
  gap: 6px;
  min-width: 0;
  overflow: hidden;
}

.journal-v2-form-grid .search-input,
.journal-v2-form-grid select,
.journal-v2-form-grid textarea,
.journal-v2-form-grid input[type="range"] {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
}

.journal-v2-notes-list {
  display: grid;
  gap: 10px;
}

.journal-v2-note-row {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  gap: 8px;
}

.journal-v2-note-row span {
  color: var(--color-border-strong);
  font-size: 0.82rem;
}

.journal-v2-note-row strong {
  color: var(--color-text-secondary);
  overflow-wrap: anywhere;
  word-break: break-word;
}

.journal-v2-note-row p {
  margin: 4px 0 0;
  color: var(--color-text-muted);
  font-size: 0.85rem;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.journal-v2-heatmap-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr);
  gap: 12px;
}

.journal-v2-heatmap-panel h3,
.journal-v2-overview-panel h3 {
  margin: 0 0 10px;
  color: var(--color-text-primary);
}

.journal-v2-week-header {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
  margin-bottom: 4px;
}

.journal-v2-week-header span {
  color: var(--color-text-muted);
  font-size: 0.8rem;
  text-align: center;
}

.journal-v2-heat-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
}

.journal-v2-heat-cell {
  min-height: 58px;
  border: 1px solid rgba(255, 255, 255, 0.338);
  border-radius: var(--radius-md);
  padding: 6px;
  background: color-mix(in srgb, var(--color-surface-elevated) 48%, transparent);
}

.journal-v2-heat-cell .day {
  color: var(--color-border-strong);
  font-size: 0.78rem;
}

.journal-v2-heat-cell strong {
  display: block;
  margin-top: 6px;
  font-size: 0.9rem;
}

.journal-v2-heat-cell.positive {
  background: rgba(22, 101, 52, 0.4);
}

.journal-v2-heat-cell.positive strong {
  color: var(--color-data-green-bright);
}

.journal-v2-heat-cell.negative {
  background: rgba(127, 29, 29, 0.4);
}

.journal-v2-heat-cell.negative strong {
  color: var(--color-data-red-bright);
}

.journal-v2-heat-stats {
  margin-top: 10px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.journal-v2-heat-stats div {
  border: 1px solid rgba(255, 255, 255, 0.338);
  border-radius: var(--radius-md);
  padding: 8px;
}

.journal-v2-heat-stats span {
  color: var(--color-border-strong);
  font-size: 0.78rem;
  display: block;
}

.journal-v2-heat-stats strong {
  color: var(--color-text-primary);
}

.journal-v2-heat-stats .positive {
  color: var(--color-data-green-bright);
}

.journal-v2-heat-stats .negative {
  color: var(--color-data-red-bright);
}

.journal-v2-overview-panel {
  display: grid;
  gap: 10px;
}

.journal-v2-donut-wrap {
  border: 1px solid rgba(255, 255, 255, 0.338);
  border-radius: var(--radius-md);
  padding: 8px;
}

.journal-v2-overview-list {
  display: grid;
  gap: 6px;
}

.journal-v2-overview-list div {
  display: flex;
  justify-content: space-between;
}

.journal-v2-overview-list span {
  color: var(--color-text-muted);
  overflow-wrap: anywhere;
  word-break: break-word;
}

.journal-v2-overview-list strong {
  color: var(--color-text-secondary);
  text-align: right;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.journal-v2-market-type {
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  padding: 8px;
  display: grid;
  gap: 8px;
}

.journal-v2-market-type .row {
  display: grid;
  grid-template-columns: 72px 1fr auto;
  gap: 8px;
  align-items: center;
}

.journal-v2-market-type span {
  color: var(--color-text-muted);
  font-size: 0.84rem;
}

.journal-v2-market-type .bar {
  height: 6px;
  border-radius: var(--radius-full);
  background: var(--color-surface-elevated);
  overflow: hidden;
}

.journal-v2-market-type .bar i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--color-text-secondary), var(--color-data-secondary));
}

.journal-v2-market-type strong {
  color: var(--color-text-secondary);
  font-size: 0.85rem;
}

.journal-v2-mini-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.journal-v2-mini-stats div {
  border: 1px solid rgba(255, 255, 255, 0.338);
  border-radius: var(--radius-md);
  padding: 8px;
}

.journal-v2-mini-stats span {
  color: var(--color-border-strong);
  font-size: 0.78rem;
  display: block;
}

.journal-v2-mini-stats strong {
  color: var(--color-text-secondary);
}

.journal-v2-mini-stats .positive {
  color: var(--color-data-green-bright);
}

.journal-v2-mini-stats .negative {
  color: var(--color-data-red-bright);
}

.journal-v2-executions {
  margin-top: 10px;
}

.journal-v2-table.compact th,
.journal-v2-table.compact td {
  padding: 8px 7px;
  font-size: 0.78rem;
}

.tax-v2,
.tax-v2-panel,
.tax-v2-head,
.tax-v2-kpi,
.tax-v2-scenario-card,
.tax-v2-result-card {
  min-width: 0;
}

.tax-v2-head-actions {
  flex-wrap: wrap;
}

.tax-v2-panel h3,
.tax-v2-panel h4,
.tax-v2-live-rows span,
.tax-v2-live-rows strong,
.tax-v2-scenario-card span,
.tax-v2-scenario-card strong,
.tax-v2-source-links a {
  overflow-wrap: anywhere;
  word-break: break-word;
}

@media (max-width: 1500px) {
  .home-v2-main-grid {
    grid-template-columns: minmax(0, 1.55fr) minmax(280px, 1fr);
  }

  .portfolio-v2-attrib-grid,
  .portfolio-v2-heatmap {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .portfolio-v2-main-grid {
    grid-template-columns: minmax(0, 1.45fr) minmax(280px, 1fr);
  }

  .journal-v2-main-grid {
    grid-template-columns: minmax(0, 1.5fr) minmax(290px, 1fr);
  }

  .journal-v2-metrics {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 1280px) {
  .home-v2-hero {
    flex-direction: column;
  }

  .home-v2-hero-stats {
    width: 100%;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .home-v2-attention-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .home-v2-main-grid {
    grid-template-columns: 1fr;
  }

  .home-v2-flow-progress {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .home-v2-flow-list-row {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .home-v2-flow-list-row .home-v2-flow-btn {
    grid-column: 1 / -1;
    justify-self: start;
  }

  .portfolio-v2-head {
    flex-direction: column;
    align-items: flex-start;
  }

  .portfolio-v2-top-cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .portfolio-v2-main-grid {
    grid-template-columns: 1fr;
  }

  .portfolio-v2-two-col {
    grid-template-columns: 1fr;
  }

  .journal-v2-head {
    flex-direction: column;
    align-items: flex-start;
  }

  .journal-v2-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .journal-v2-search {
    width: 100%;
  }

  .journal-v2-main-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 960px) {
  .home-v2-hero-stats {
    grid-template-columns: 1fr;
  }

  .home-v2-attention-grid {
    grid-template-columns: 1fr;
  }

  .home-v2-holding-row {
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
  }

  .home-v2-holding-value,
  .home-v2-holding-change {
    text-align: left;
    min-width: 0;
  }

  .home-v2-flow-overlay {
    padding: 10px;
  }

  .home-v2-flow-shell {
    max-height: calc(100vh - 20px);
    padding: 10px;
  }

  .home-v2-flow-progress {
    grid-template-columns: 1fr;
  }

  .home-v2-flow-detail-grid,
  .home-v2-flow-vol-grid,
  .home-v2-flow-metric-grid {
    grid-template-columns: 1fr;
  }

  .home-v2-flow-list-row {
    grid-template-columns: 1fr;
  }

  .home-v2-flow-list-row .home-v2-flow-btn {
    grid-column: auto;
  }

  .portfolio-v2-top-cards {
    grid-template-columns: 1fr;
  }

  .portfolio-v2-toolbar {
    width: 100%;
    flex-wrap: wrap;
  }

  .portfolio-v2-range {
    overflow-x: auto;
    width: 100%;
  }

  .portfolio-v2-symbol-cell strong,
  .portfolio-v2-symbol-cell span,
  .journal-v2-symbol-cell strong,
  .journal-v2-symbol-cell span {
    max-width: 120px;
  }

  .journal-v2-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .journal-v2-filter-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .journal-v2-form-grid {
    grid-template-columns: 1fr;
  }

  .journal-v2-note-row {
    grid-template-columns: 58px minmax(0, 1fr);
  }
}

@media (max-width: 680px) {
  .home-v2-hero {
    padding: 14px 14px;
  }

  .home-v2-hero-main {
    gap: 8px;
  }

  .home-v2-hero-value {
    font-size: clamp(1.45rem, 8vw, 2rem);
  }

  .home-v2-hero-change {
    font-size: 1rem;
  }

  .home-v2-flow-top h2 {
    font-size: 1rem;
  }

  .home-v2-flow-card,
  .home-v2-flow-status-card {
    padding: 10px;
  }

  .home-v2-flow-actions {
    flex-direction: column;
  }

  .home-v2-flow-btn {
    width: 100%;
  }

  .journal-v2-metrics {
    grid-template-columns: 1fr;
  }

  .journal-v2-tabs {
    overflow-x: auto;
    white-space: nowrap;
  }

  .journal-v2-footer-row {
    flex-direction: column;
    align-items: flex-start;
  }

  .tax-v2-head h2 {
    font-size: 1.45rem;
  }

  .tax-v2-panel h3 {
    font-size: 1.15rem;
  }

  .tax-v2-kpi strong {
    font-size: 1.1rem;
  }
}

/* ── Options Market Switcher ─────────────────────────────────────── */
.market-switcher {
  display: flex;
  background: var(--color-surface-elevated);
  padding: 4px;
  border-radius: var(--radius-md);
  border: var(--color-border-medium);
}

.switcher-btn {
  padding: 6px 16px;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: var(--color-text-muted);
  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
  transition: color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s, transform 0.2s;
}

.switcher-btn.active {
  background: var(--color-data-secondary);
  color: var(--color-text-primary);
}

.live-pill {
  font-size: 0.6rem;
  padding: 2px 6px;
  background: rgba(239, 68, 68, 0.2);
  color: var(--color-data-red-bright);
  border-radius: var(--radius-md);
  margin-left: 8px;
  vertical-align: middle;
  text-transform: uppercase;
  border: 1px solid rgba(239, 68, 68, 0.3);
  animation: live-pill-glow 2s infinite ease-in-out;
}

@keyframes live-pill-glow {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(248, 113, 113, 0);
  }

  50% {
    box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.22);
  }
}

.loading-state {
  padding: 40px;
  text-align: center;
  color: var(--color-text-muted);
  font-style: italic;
}

/* ── Options Layout with Sidebar ────────────────────────────────── */
.options-layout {
  display: grid;
  grid-template-columns: 1fr 280px;
  gap: 24px;
}

.main-chain {
  flex: 1;
}

.options-sidebar {
  padding: 0;
  display: flex;
  flex-direction: column;
}

.options-sidebar .section-header {
  padding: 16px 20px;
  margin-bottom: 0;
}

.top-asset-list {
  display: flex;
  flex-direction: column;
}

.top-asset-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 20px;
  border-bottom: 1px solid var(--color-border-medium);
  transition: color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s, transform 0.2s;
}

.top-asset-item:hover {
  background: rgba(148, 163, 184, 0.03);
}

.top-asset-item.active {
  background: rgba(255, 255, 255, 0.05);
  border-color: var(--color-interactive);
}

.top-asset-item .asset-meta {
  display: flex;
  flex-direction: column;
}

.top-asset-item .symbol {
  font-weight: 800;
  color: var(--color-text-secondary);
  font-size: 1rem;
}

.top-asset-item .vol {
  font-size: 0.7rem;
  color: var(--color-text-muted);
  font-weight: 600;
}

.top-asset-item .asset-price {
  text-align: right;
}

.top-asset-item .price {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--color-data-secondary);
}

.top-asset-item .change {
  font-size: 0.75rem;
  font-weight: 600;
}

/* ── Asset Dropdown Styling ───────────────────────────────────────── */
.asset-dropdown-container select {
  border: 1px solid var(--color-border-medium);
  background: rgba(15, 23, 42, 0.7);
  color: var(--color-text-secondary);
  border-radius: var(--radius-md);
  padding: 8px 12px;
  font-size: 0.86rem;
  font-weight: 700;
}

.asset-dropdown-container select:focus {
  outline: none;
  border-color: var(--color-data-secondary);
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.15);
}

.asset-dropdown-container select option {
  background: var(--color-surface-card);
  color: var(--color-text-secondary);
}

.whale-options-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.options-market-context {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.options-market-structure-pill,
.options-calculator-mode-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border: var(--color-border-medium);
}

.options-market-structure-pill.orderbook,
.options-calculator-mode-pill.orderbook {
  color: var(--color-data-secondary);
  background: var(--color-interactive-soft);
  border-color: var(--color-border-medium);
}

.options-market-structure-pill.rfq,
.options-calculator-mode-pill.rfq {
  color: var(--color-data-amber-bright);
  background: rgba(251, 191, 36, 0.12);
  border-color: rgba(251, 191, 36, 0.3);
}

.options-rfq-banner {
