}
.indicator-v2 .imv2-action.active {
  color: var(--color-data-primary); border-color: var(--color-data-primary);
}
.indicator-v2 .imv2-action:disabled {
  opacity: 0.4; cursor: not-allowed;
}

/* Phase 2/3: asset-aware context banners + honest empty states */
.indicator-context-banner {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  padding: 10px 16px; margin: 0 0 12px;
  border: 1px solid var(--color-border-default); border-radius: var(--radius-md);
  background: var(--color-surface-elevated); color: var(--color-text-secondary);
  font-size: 12px;
}
.indicator-context-banner .link-btn {
  background: none; border: none; color: var(--color-data-primary);
  cursor: pointer; font: inherit; text-decoration: underline; padding: 0;
}
.indicator-exposure-panel { width: 100%; }
.indicator-exposure-rows { display: flex; flex-wrap: wrap; gap: 8px 18px; margin-top: 8px; }
.indicator-exposure-row { display: flex; gap: 8px; align-items: baseline; font-size: 13px; }
.indicator-exposure-row .up { color: var(--color-success); }
.indicator-exposure-row .down { color: var(--color-danger); }
.indicator-exposure-total { margin-top: 6px; font-size: 12px; color: var(--color-text-muted); }
.indicator-exposure-empty { margin-top: 6px; font-size: 12px; color: var(--color-text-muted); max-width: 70ch; }
.decision-empty-state {
  padding: 32px 24px; text-align: center; color: var(--color-text-secondary);
  border: 1px dashed var(--color-border-default); border-radius: var(--radius-lg); margin: 16px 0;
}
.decision-empty-state p { margin: 0 0 6px; }
.decision-empty-state .decision-empty-hint { color: var(--color-text-muted); font-size: 12px; }


@media (max-width: 1024px) {
  .indicator-v2 .imv2-workspace { grid-template-columns: 1fr; }
  .indicator-v2 .imv2-two-col { grid-template-columns: 1fr; }
  .indicator-v2 .imv2-timeline { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .indicator-v2 .imv2-hero { flex-direction: column; align-items: flex-start; }
  .indicator-v2 .imv2-hero-stats { margin-left: 0; }
}
.indicator-metric-stat strong.positive {
  color: var(--color-success);
}

.indicator-metric-stat strong.negative {
  color: var(--color-danger);
}

@media (max-width: 768px) {
  .indicator-controls-row {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .indicator-toolbar {
    flex-direction: row;
    align-items: center;
    justify-content: flex-start;
    width: 100%;
  }

  .indicator-toolbar .modal-action-btn {
    padding: 6px 12px;
    font-size: 0.8rem;
  }

  .indicator-metric-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 0 20px 16px;
  }
}

@media (max-width: 520px) {
  .indicator-metric-summary {
    grid-template-columns: 1fr;
  }
}

.tax-v2 {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-width: 100%;
  overflow-x: clip;
}

.tax-v2-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}

.tax-v2-head h2 {
  margin: 0;
  font-size: clamp(1.5rem, 2.2vw, 2.35rem);
  letter-spacing: -0.02em;
  color: var(--color-text-primary);
}

.tax-v2-head p {
  margin: 4px 0 0;
  color: var(--color-text-secondary);
  font-size: 1rem;
}

.tax-v2-head-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tax-v2-action-btn {
  border: var(--color-border-medium) !important;
  background: var(--color-surface-elevated) !important;
  color: var(--color-text-secondary) !important;
  border-radius: var(--radius-md) !important;
  font-weight: 600 !important;
  min-height: 38px;
  padding: 0 12px !important;
}

.tax-v2-action-btn:hover:not(:disabled) {
  border-color: var(--color-border-medium) !important;
  color: var(--color-text-secondary) !important;
}

.tax-v2-more-btn {
  min-width: 42px;
  padding: 0 10px !important;
}

.tax-v2-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.tax-v2-kpi {
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: rgba(5, 5, 5, 0.92);
  padding: 11px 12px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  grid-template-areas:
    "icon label"
    "icon value"
    "icon sub";
  column-gap: 12px;
  row-gap: 3px;
}

.tax-v2-kpi-icon {
  grid-area: icon;
  width: 42px;
  height: 42px;
  border-radius: var(--radius-md);
  display: grid;
  place-items: center;
  font-size: 1.35rem;
  font-weight: 700;
}

.tax-v2-kpi-icon.blue {
  color: var(--color-text-secondary);
  background: var(--color-interactive-soft);
}


.tax-v2-kpi-icon.violet {
  color: var(--color-data-secondary);
  background: var(--color-interactive-soft);
}

.tax-v2-kpi-icon.green {
  color: var(--color-data-green-bright);
  background: rgba(22, 163, 74, 0.25);
}

.tax-v2-kpi span {
  grid-area: label;
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

.tax-v2-kpi strong {
  grid-area: value;
  color: var(--color-text-primary);
  font-size: clamp(1.2rem, 1.6vw, 1.85rem);
  line-height: 1.15;
}

.tax-v2-kpi strong.positive {
  color: var(--color-data-green-bright);
}

.tax-v2-kpi em {
  grid-area: sub;
  font-style: normal;
  color: var(--color-text-secondary);
  font-size: 0.84rem;
}

.tax-v2-kpi em.positive {
  color: var(--color-success);
}

.tax-loss-panel {
  padding: 14px;
}

.tax-loss-pill {
  border: 1px solid rgba(34, 197, 94, 0.3);
  border-radius: var(--radius-full);
  padding: 4px 10px;
  color: var(--color-data-green-bright);
  background: rgba(22, 163, 74, 0.12);
  font-size: 0.78rem;
  font-weight: 800;
}

.tax-loss-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-top: 12px;
}

.tax-loss-card {
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-elevated);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.tax-loss-card > div:first-child {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tax-loss-card strong {
  color: var(--color-text-primary);
  font-size: 0.8rem;
}

.tax-loss-card span,
.tax-loss-card p,
.tax-loss-card dt {
  color: var(--color-text-muted);
}

.tax-loss-card p {
  margin: 0;
  font-size: 0.66rem;
  line-height: 1.45;
}

.tax-loss-card dl {
  display: grid;
  gap: 6px;
  margin: 0;
}

.tax-loss-card dl div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.tax-loss-card dt,
.tax-loss-card dd {
  margin: 0;
  font-size: 0.66rem;
}

.tax-loss-card dd {
  color: var(--color-text-primary);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.tax-loss-card dd.positive {
  color: var(--color-data-green-bright);
}

.tax-loss-empty {
  margin: 10px 0 0;
  color: var(--color-text-muted);
}

.tax-v2-grid-main {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1.25fr) minmax(0, 1.05fr);
  gap: 12px;
}

.tax-v2-panel {
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: rgba(5, 5, 5, 0.92);
  padding: 12px 13px;
  min-width: 0;
}

.tax-v2-panel h3 {
  margin: 0 0 8px;
  color: var(--color-text-secondary);
  font-size: clamp(0.92rem, 1.4vw, 1.24rem);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.tax-v2-panel h4 {
  margin: 0 0 8px;
  color: var(--color-text-primary);
  font-size: 1.2rem;
}

.tax-v2-panel .sub {
  margin: 0 0 8px;
  color: var(--color-text-muted);
  font-size: 0.93rem;
}

.tax-v2 .num {
  width: 24px;
  height: 24px;
  border-radius: var(--radius-md);
  display: inline-grid;
  place-items: center;
  font-size: 0.85rem;
  background: var(--color-interactive-soft);
  color: var(--color-text-secondary);
}

.tax-v2-input {
  background: var(--color-surface-elevated);
  border: var(--color-border-medium);
  color: var(--color-text-secondary);
  border-radius: 9px;
  padding: 9px 11px;
  width: 100%;
  min-width: 0;
}

.tax-v2-inline-row {
  margin-top: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.tax-v2-inline-row.right {
  justify-content: flex-end;
  margin-top: 0;
  margin-bottom: 8px;
}

.tax-v2-inline-row span {
  color: var(--color-text-secondary);
  font-size: 0.92rem;
}

.tax-v2-inline-row select {
  min-width: 150px;
  width: auto;
  max-width: 100%;
}

.tax-v2-region-tabs {
  margin: 12px 0 10px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tax-v2-pill {
  border: var(--color-border-medium);
  background: var(--color-surface-elevated);
  color: var(--color-text-muted);
  border-radius: var(--radius-md);
  padding: 6px 10px;
  font-size: 0.8rem;
}

.tax-v2-pill.active {
  background: var(--color-interactive-soft);
  border-color: var(--color-border-medium);
  color: var(--color-text-secondary);
}

.tax-v2-jur-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin: 10px 0;
  max-height: 360px;
  overflow: auto;
  padding-right: 2px;
}

.tax-v2-jur-item {
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  padding: 10px 11px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  cursor: pointer;
}

.tax-v2-jur-item.active {
  border-color: var(--color-border-medium);
  background: var(--color-interactive-soft);
}

.tax-v2-jur-main {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 8px;
  row-gap: 1px;
  align-items: center;
  min-width: 0;
}

.tax-v2-jur-flag {
  grid-row: 1 / span 2;
  font-size: 1.1rem;
}

.tax-v2-jur-main strong {
  color: var(--color-text-primary);
  font-size: 0.78rem;
  line-height: 1.2;
}

.tax-v2-jur-main span {
  color: var(--color-text-muted);
  font-size: 0.66rem;
  line-height: 1.2;
}

.tax-v2-jur-item input {
  accent-color: var(--color-text-secondary);
}

.tax-v2-gain-rows {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tax-v2-gain-row {
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  padding: 10px;
  background: var(--color-surface-elevated);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(132px, 154px);
  gap: 10px;
  align-items: center;
}

.tax-v2-gain-row strong {
  display: block;
  color: var(--color-text-primary);
  font-size: 0.77rem;
}

.tax-v2-gain-row span {
  display: block;
  color: var(--color-text-muted);
  font-size: 0.66rem;
  margin-top: 2px;
}

.tax-v2-gain-row input {
  text-align: right;
}

.tax-v2-total-row {
  margin-top: 10px;
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-elevated);
  padding: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.tax-v2-total-row span {
  color: var(--color-text-muted);
}

.tax-v2-total-row strong {
  color: var(--color-data-secondary);
  font-size: clamp(1.1rem, 1.7vw, 1.55rem);
}

.tax-v2-live-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.tax-v2-live-badge {
  font-size: 0.84rem;
  color: var(--color-data-green-bright);
  background: rgba(20, 83, 45, 0.35);
  border: 1px solid rgba(34, 197, 94, 0.35);
  padding: 4px 9px;
  border-radius: var(--radius-full);
}

.tax-v2-live-header {
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  padding: 11px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.tax-v2-live-header span {
  color: var(--color-text-muted);
}

.tax-v2-live-header strong {
  color: var(--color-text-primary);
}

.tax-v2-live-rows {
  display: flex;
  flex-direction: column;
}

.tax-v2-live-rows div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
  border-bottom: var(--color-border-medium);
}

.tax-v2-live-rows div span {
  color: var(--color-text-muted);
  font-size: 0.8rem;
}

.tax-v2-live-rows div strong {
  color: var(--color-text-primary);
  font-size: 0.8rem;
}

.tax-v2-net-row {
  margin-top: 10px;
  border: 1px solid rgba(34, 197, 94, 0.35);
  border-radius: var(--radius-md);
  background: rgba(6, 78, 59, 0.22);
  padding: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.tax-v2-net-row span {
  color: #d1fae5;
}

.tax-v2-net-row strong {
  color: var(--color-data-green-bright);
  font-size: clamp(1.15rem, 1.9vw, 1.65rem);
}

.tax-v2-note {
  margin-top: 10px;
  font-size: 0.86rem;
  color: var(--color-text-muted);
}

.tax-v2-grid-bottom {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
  gap: 12px;
}

.tax-v2-panel-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
  flex-wrap: wrap;
}

.tax-v2-link-btn {
  border: none;
  background: transparent;
  color: var(--color-data-secondary);
  font-weight: 700;
}

.tax-v2-advanced-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.tax-v2-adv-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tax-v2-adv-field > span {
  font-size: 0.82rem;
  color: var(--color-text-secondary);
}

.tax-v2-adv-input {
  width: 100%;
  box-sizing: border-box;
  background: var(--color-surface-elevated);
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  color: var(--color-text-secondary);
  padding: 8px 10px;
}

.tax-v2-notes-field {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: var(--color-text-muted);
  font-size: 0.88rem;
}

.tax-v2-calc-btn {
  margin-top: 10px;
  width: 100%;
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-interactive-soft);
  color: var(--color-text-secondary);
  font-size: 1.05rem;
  font-weight: 700;
  padding: 11px 12px;
}

.tax-v2-warning-list {
  margin-top: 9px;
  border: 1px solid rgba(245, 158, 11, 0.35);
  background: rgba(120, 53, 15, 0.2);
  border-radius: var(--radius-md);
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  color: var(--color-data-amber-bright);
  font-size: 0.84rem;
}

.tax-v2-scenario-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.tax-v2-scenario-card {
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-elevated);
  padding: 12px;
}

.tax-v2-scenario-card h4 {
  margin: 0 0 8px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.tax-v2-base-pill {
  border-radius: var(--radius-md);
  border: var(--color-border-medium);
  color: var(--color-data-secondary);
  background: var(--color-interactive-soft);
  font-size: 0.74rem;
  padding: 2px 8px;
}

.tax-v2-scenario-card div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 5px 0;
}

.tax-v2-scenario-card span {
  color: var(--color-interactive);
}

.tax-v2-scenario-card strong {
  color: var(--color-text-primary);
}

.tax-v2-scenario-card strong.positive {
  color: var(--color-data-green-bright);
}

.tax-v2-save-strip {
  margin-top: 10px;
  border: 1px solid rgba(16, 185, 129, 0.35);
  border-radius: var(--radius-md);
  background: linear-gradient(90deg, rgba(6, 78, 59, 0.35) 0%, rgba(2, 44, 34, 0.25) 100%);
  color: #5eead4;
  font-weight: 600;
  padding: 10px 12px;
}

.tax-v2-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.tax-v2-footer p {
  margin: 4px 0 0;
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

.tax-v2-source-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.tax-v2-source-links a {
  border: var(--color-border-medium);
  border-radius: 9px;
  background: var(--color-interactive-soft);
  color: var(--color-data-secondary);
  text-decoration: none;
  font-size: 0.88rem;
  font-weight: 600;
  padding: 8px 10px;
  max-width: 100%;
  white-space: normal;
}

.tax-v2-results-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 10px;
}

.tax-v2-result-card {
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-elevated);
  padding: 10px;
}

.tax-v2-result-card .head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.tax-v2-result-card .head h4 {
  margin: 0;
}

.tax-v2-result-card .rows {
  display: flex;
  flex-direction: column;
}

.tax-v2-result-card .rows div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 6px 0;
  border-bottom: var(--color-border-medium);
  flex-wrap: wrap;
}

.tax-v2-result-card .rows div:last-child {
  border-bottom: none;
}

.tax-v2-results .tax-v2-panel-head > div {
  display: flex;
  flex-wrap: wrap;
}

@media (max-width: 1280px) {
  .tax-v2-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .tax-loss-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .tax-v2-grid-main {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .tax-v2-grid-main > :last-child {
    grid-column: span 2;
  }

  .tax-v2-grid-bottom {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 900px) {
  .tax-v2-head {
    flex-direction: column;
  }

  .tax-v2-head-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .tax-v2-action-btn {
    flex: 0 1 auto;
  }

  .tax-v2-kpis {
    grid-template-columns: 1fr;
  }

  .tax-loss-grid {
    grid-template-columns: 1fr;
  }

  .tax-v2-grid-main {
    grid-template-columns: 1fr;
  }

  .tax-v2-grid-main > :last-child {
    grid-column: auto;
  }

  .tax-v2-inline-row.right {
    margin-top: 0;
    justify-content: flex-start;
  }

  .tax-v2-inline-row {
    align-items: flex-start;
  }

  .tax-v2-advanced-grid {
    grid-template-columns: 1fr;
  }

  .tax-v2-scenario-grid {
    grid-template-columns: 1fr;
  }

  .tax-v2-footer {
    flex-direction: column;
    align-items: flex-start;
  }

  .tax-v2-source-links {
    justify-content: flex-start;
  }

  .tax-v2-gain-row {
    grid-template-columns: 1fr;
    gap: 8px;
  }

