/* ── Options Executive Grid ───────────────────────────────────────
   Scoped tokens aliased to the global design system so they flip with
   the active theme. Local names retained for compatibility. */
.options-exec {
  --options-exec-bg: var(--color-bg-base);
  --options-exec-surface: var(--color-surface-card);
  --options-exec-surface-2: var(--color-surface-elevated);
  --options-exec-surface-3: var(--color-surface-hover);
  --options-exec-border: var(--color-border-subtle);
  --options-exec-border-strong: var(--color-border-strong);
  --options-exec-text: var(--color-text-primary);
  --options-exec-muted: var(--color-text-secondary);
  --options-exec-dim: var(--color-text-muted);
  --options-exec-accent: var(--color-interactive);
  --options-exec-green: var(--color-success);
  --options-exec-red: var(--color-danger);
  --options-exec-amber: var(--color-warning);
  width: 100%;
  margin: 0;
  padding: 22px clamp(12px, 2vw, 28px) 36px;
  gap: 16px;
  color: var(--options-exec-text);
  background-image:
    linear-gradient(to right, var(--color-border-subtle) 1px, transparent 1px),
    linear-gradient(to bottom, var(--color-border-subtle) 1px, transparent 1px);
  background-size: 24px 24px;
}

.options-exec *,
.options-exec *::before,
.options-exec *::after {
  box-sizing: border-box;
}

.options-exec :is(button, input, select, textarea):focus-visible,
.options-calculator-symbol-option:focus-visible,
.options-exec [role="button"]:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.92);
  outline-offset: 2px;
}

.options-exec-header {
  position: sticky;
  top: 0;
  z-index: 20;
  margin: -22px calc(clamp(12px, 2vw, 28px) * -1) 16px;
  padding: 18px clamp(12px, 2vw, 28px);
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 16px;
  border-bottom: 1px solid var(--color-border-subtle);
  background: rgba(10, 14, 26, 0.96);
  backdrop-filter: blur(14px);
}

.options-exec-eyebrow {
  color: var(--options-exec-accent);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.22em;
  line-height: 1.2;
  text-transform: uppercase;
}

.options-exec-header h1 {
  margin: 4px 0 0;
  color: var(--options-exec-text);
  font-size: clamp(1.35rem, 2vw, 1.65rem);
  line-height: 1.05;
  font-weight: 700;
  letter-spacing: 0;
}

.options-exec-header p {
  margin: 6px 0 0;
  color: var(--color-text-muted);
  font-size: 11px;
  line-height: 1.35;
}

.options-exec-live-badge {
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(239, 68, 68, 0.24);
  background: rgba(239, 68, 68, 0.11);
  color: var(--color-data-red-bright);
  padding: 0 9px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.options-exec-live-badge span {
