.intel-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 12px;
  margin-bottom: 24px;
}

.intel-summary-card {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease, opacity 0.2s ease, transform 0.2s ease;
}

.intel-summary-card:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.3);
  transform: translateY(-2px);
}

.summary-label {
  font-size: 11px;
  text-transform: uppercase;
  color: var(--color-text-muted);
  letter-spacing: 0.05em;
  font-weight: 600;
}

.summary-value {
  font-size: 15px;
  font-weight: 700;
  color: var(--color-text-primary);
}

.summary-value.positive { color: var(--color-data-green-bright); }
.summary-value.negative { color: var(--color-data-red-bright); }

