/* Compact institutional workspace refresh */

.compact-page-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

.compact-page-header-copy {
  min-width: 0;
}

.compact-page-eyebrow {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-secondary);
  margin-bottom: 6px;
}

.compact-page-title-row {
  display: flex;
  align-items: baseline;
  gap: 14px;
  flex-wrap: wrap;
}

.compact-page-title-row h2 {
  margin: 0;
  font-size: clamp(1.35rem, 2vw, 1.9rem);
  line-height: 1;
}

.compact-page-header p {
  margin: 6px 0 0;
  color: var(--color-text-secondary);
  font-size: 0.92rem;
  max-width: 72ch;
}

.compact-page-meta,
.compact-page-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.compact-page-meta {
  color: var(--color-text-secondary);
  font-size: 0.82rem;
}

.metric-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 8px;
}

.metric-strip-item {
  border: 1px solid var(--color-border-subtle);
  background: var(--color-surface-card);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  min-width: 0;
}

.metric-strip-item span {
  display: block;
  color: var(--color-text-secondary);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.metric-strip-item strong {
  display: block;
  margin-top: 5px;
  color: var(--color-text-primary);
  font-size: 1.1rem;
  line-height: 1.05;
  font-variant-numeric: tabular-nums;
}

.metric-strip-item em {
  display: block;
  margin-top: 4px;
  color: var(--color-text-secondary);
  font-size: 0.74rem;
  font-style: normal;
}

.metric-strip-item.positive strong,
.tax-v2-scenario-table-row strong,
.journal-table .positive,
.watchlist-table .positive {
  color: var(--color-data-green-bright);
}

.metric-strip-item.negative strong,
.watchlist-table .negative,
.journal-table .negative {
  color: var(--color-data-red-bright);
}

.dense-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 10px;
}

.dense-panel-copy h3 {
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.2;
}

.dense-panel-copy p,
.dense-panel-meta {
  margin: 4px 0 0;
  color: var(--color-text-secondary);
  font-size: 0.76rem;
}

.dense-panel-actions,
.inline-control-group {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.filter-popover {
  position: relative;
}

.compact-filter-trigger {
  border: 1px solid var(--color-border-subtle);
  background: var(--color-surface-elevated);
  color: var(--color-text-primary);
  min-height: 36px;
  border-radius: var(--radius-md);
  padding: 0 12px;
  font-size: 0.8rem;
  font-weight: 600;
}

.compact-filter-trigger.active {
  border-color: var(--color-border-medium);
}

.compact-filter-surface {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 30;
  min-width: 260px;
  border: 1px solid var(--color-border-subtle);
  background: var(--color-surface-card-strong);
  border-radius: var(--radius-md);
  padding: 12px;
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
}

.right-rail-drawer-overlay {
  position: fixed;
  inset: 0;
  z-index: 80;
  background: rgba(0, 0, 0, 0.72);
  opacity: 1;
  transition: opacity var(--duration-base) var(--ease-out);
  display: flex;
  justify-content: flex-end;
}

.right-rail-drawer-overlay.is-closing {
  opacity: 0;
  transition-duration: var(--duration-fast);
  transition-timing-function: var(--ease-in);
}

.right-rail-drawer {
