/* Premium Journal */
.journal-page {
  width: 100%;
  margin: 0;
  padding: var(--space-6, 24px);
  display: grid;
  gap: var(--space-4, 16px);
  background: var(--color-bg-base);
  color: var(--color-text-primary);
}

.journal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.journal-eyebrow,
.journal-card-label,
.journal-quick-form label > span,
.journal-filter-toolbar label > span {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  font-weight: 800;
}

.journal-header h2 {
  margin: 4px 0 0;
  font-size: 28px;
  line-height: 1.05;
  font-weight: 750;
  color: var(--color-text-primary);
}

.journal-header p,
.journal-section-head p,
.journal-card p,
.journal-empty-state p {
  margin: 4px 0 0;
  color: var(--color-text-muted);
  font-size: 13px;
  line-height: 1.4;
}

.journal-header-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.journal-search {
  width: clamp(280px, 24vw, 340px);
  height: 44px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border-radius: var(--radius-full);
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(0,0,0,0.72);
  color: var(--color-text-muted);
}

.journal-search input,
.journal-filter-toolbar select,
.journal-inline-actions select,
.journal-quick-form input,
.journal-quick-form select,
.journal-quick-form textarea,
.journal-weekly-review textarea {
  width: 100%;
  min-height: 38px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(0,0,0,0.72);
  color: var(--color-text-primary);
  padding: 0 12px;
  font-size: 13px;
}

.journal-search input {
  border: 0;
  background: transparent;
  padding: 0;
  min-height: auto;
}

.journal-quick-form textarea,
.journal-weekly-review textarea {
  padding: 10px 12px;
  min-height: 88px;
  resize: vertical;
}

.journal-search input:focus,
.journal-filter-toolbar select:focus,
.journal-inline-actions select:focus,
.journal-quick-form input:focus,
.journal-quick-form select:focus,
.journal-quick-form textarea:focus,
.journal-weekly-review textarea:focus {
  outline: none;
  border-color: color-mix(in srgb, var(--color-border-strong) 75%, transparent);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.09);
}

.journal-search input:focus {
  box-shadow: none;
}

.journal-btn {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2, 8px);
  padding: 0 var(--space-4, 16px);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md, 6px);
  background: transparent;
  color: var(--color-text-secondary);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background-color 140ms ease,
    border-color 140ms ease,
    color 140ms ease,
    transform 140ms ease;
}

.journal-btn:hover {
  border-color: var(--color-border-strong);
  color: var(--color-text-primary);
  background: var(--color-interactive-soft);
}

.journal-btn:active {
  transform: scale(0.98);
}

.journal-btn:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.journal-btn.primary {
  border-color: var(--color-interactive);
  background: var(--color-interactive);
  color: var(--color-text-inverse);
}

.journal-btn.primary:hover {
  border-color: var(--color-interactive-hover);
  background: var(--color-interactive-hover);
  color: var(--color-text-inverse);
}

.journal-btn.secondary {
  background: var(--color-surface-card);
  color: var(--color-text-primary);
}

.journal-btn.danger {
  color: var(--color-data-red-bright);
  border-color: rgba(239, 68, 68, 0.30);
  background: rgba(127, 29, 29, 0.30);
}

.journal-btn.full {
  width: 100%;
}

.journal-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.journal-export-wrap {
  position: relative;
}

.journal-export-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 20;
  min-width: 210px;
  display: grid;
  gap: 4px;
  padding: 8px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(3,10,24,0.98);
  box-shadow: 0 20px 46px rgba(0,0,0,0.45);
}

.journal-export-menu button {
  min-height: 36px;
  border: 0;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--color-text-secondary);
  text-align: left;
  padding: 0 10px;
  cursor: pointer;
}

.journal-export-menu button:hover {
  background: color-mix(in srgb, var(--color-interactive-soft) 10%, transparent);
}

.journal-card {
  min-width: 0;
  overflow: hidden;
  padding: var(--card-padding-standard, 20px);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-lg, 8px);
  background: var(--color-surface-card);
  color: var(--color-text-primary);
  box-shadow: none;
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.journal-card--primary {
  background: var(--color-surface-elevated);
  border-color: var(--color-border-medium);
}

.journal-stat-card-v3 {
  background: rgba(5, 5, 5, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.105);
  border-radius: var(--card-radius-compact);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04), 0 16px 40px rgba(0,0,0,0.22);
  padding: var(--card-padding-compact);
  transition: border-color 0.2s ease, transform 0.2s ease;
  overflow: hidden;
  min-width: 0;
  min-height: 96px;
  max-height: 112px;
  display: grid;
  align-content: start;
  gap: 4px;
}

.journal-card:hover,
.journal-stat-card-v3:hover {
  border-color: color-mix(in srgb, var(--color-border-strong) 28%, transparent);
  transform: translateY(-1px);
}

.journal-stats-grid-v3 {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 12px;
}

.journal-stat-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.journal-stat-icon {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-md);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--color-data-secondary);
  border: 1px solid rgba(255, 255, 255, 0.105);
  background: rgba(5,5,5,0.82);
  font-weight: 900;
}

.journal-stat-spark {
  display: none;
}

.journal-stat-card-v3 strong {
  font-size: clamp(17px, 1.4vw, 20px);
  font-weight: 750;
  line-height: 1;
  color: var(--color-text-primary);
  font-variant-numeric: tabular-nums;
}

.journal-stat-card-v3 em {
  font-style: normal;
  color: var(--color-text-muted);
  font-size: 9px;
}

.journal-stat-card-v3.positive strong,
.journal-stat-card-v3.positive em,
.positive {
  color: var(--color-success) !important;
}

.journal-stat-card-v3.negative strong,
.journal-stat-card-v3.negative em,
.negative {
  color: var(--color-danger) !important;
}

.journal-stat-card-v3.info strong {
  color: var(--color-data-secondary);
}

.journal-tab-nav {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  border-bottom: 1px solid var(--color-border-subtle);
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.journal-tab-nav::-webkit-scrollbar {
  display: none;
}

.journal-tab-nav button {
  position: relative;
  min-height: 54px;
  min-width: max-content;
  padding: 0 2px 12px;
  border: 0;
  background: transparent;
  color: var(--color-text-muted);
  text-align: left;
  cursor: pointer;
}

.journal-tab-nav button::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 2px;
  border-radius: var(--radius-full);
  background: transparent;
}

.journal-tab-nav button.active {
  color: var(--color-text-primary);
}

.journal-tab-nav button.active::after {
  background: var(--color-text-secondary);
}

.journal-tab-nav button span {
  display: block;
  font-size: 14px;
  font-weight: 850;
}

.journal-tab-nav button small {
  display: block;
  margin-top: 3px;
  font-size: 11px;
  color: var(--color-text-muted);
}

.journal-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  gap: 20px;
  align-items: start;
}

.journal-main-panel {
  min-width: 0;
}

.journal-quick-column {
  position: sticky;
  top: 24px;
  min-width: 0;
}

.journal-section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.journal-section-head h3 {
  margin: 0;
  color: var(--color-text-primary);
  font-size: clamp(1rem, 1.45vw, 1.14rem);
  font-weight: 700;
  letter-spacing: 0;
}

.journal-inline-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 14px;
  color: var(--color-text-secondary);
}

.journal-filter-toolbar,
.journal-secondary-filters {
  display: flex;
  align-items: end;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 14px;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.journal-filter-toolbar::-webkit-scrollbar,
.journal-secondary-filters::-webkit-scrollbar {
  display: none;
}

.journal-filter-toolbar label,
.journal-secondary-filters label {
  min-width: 150px;
  display: grid;
  gap: 6px;
}

.journal-filter-pill {
  min-height: 32px;
  padding: 0 12px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-medium);
  background: transparent;
  color: rgba(255, 255, 255, 0.46);
  font-weight: 800;
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease;
}

.journal-filter-pill.active {
  background: color-mix(in srgb, var(--color-interactive-soft) 12%, transparent);
  border-color: color-mix(in srgb, var(--color-border-strong) 28%, transparent);
  color: var(--color-data-primary);
}


.journal-secondary-filters {
  display: contents;
}

.more-filters {
  display: none;
}

.journal-table-wrap {
  overflow: auto;
  max-height: 640px;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.journal-table-wrap::-webkit-scrollbar {
  display: none;
}

.journal-table {
  width: 100%;
  min-width: 900px;
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
}

.journal-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 0 12px 10px 0;
  background: rgba(3,10,24,0.96);
  color: var(--color-text-muted);
  font-size: 11px;
  text-align: left;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-bottom: 1px solid rgba(255, 255, 255, 0.105);
}

.journal-table td {
  padding: 10px 12px 10px 0;
  color: var(--color-text-secondary);
  font-size: 13px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.075);
}

.journal-table th.numeric,
.journal-table td.numeric {
  text-align: right;
}

.journal-table tbody tr {
  cursor: pointer;
  transition: background 0.16s ease;
}

.journal-table tbody tr:hover {
  background: color-mix(in srgb, var(--color-interactive-soft) 6%, transparent);
}

.journal-symbol-cell {
  display: flex;
  align-items: center;
  gap: 10px;
}

.journal-symbol-cell > span {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-md);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, 0.135);
  background: color-mix(in srgb, var(--color-interactive-soft) 8%, transparent);
  color: var(--color-data-secondary);
  font-weight: 900;
}

.journal-symbol-cell strong,
.journal-entry-card strong {
  display: block;
  color: var(--color-text-primary);
}

.journal-symbol-cell small,
.journal-entry-card-date,
.journal-notes-count {
  color: var(--color-text-muted);
  font-size: 12px;
}

.journal-chip {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 8px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-sm, 4px);
  background: transparent;
  color: var(--color-text-secondary);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.journal-chip.buy,
.journal-chip.status.closed {
  color: var(--color-success);
  border-color: rgba(34,197,94,0.30);
  background: rgba(34,197,94,0.08);
}

.journal-chip.sell {
  color: var(--color-danger);
  border-color: rgba(239,68,68,0.30);
  background: rgba(239,68,68,0.08);
}

.journal-chip.status.open {
  color: var(--color-data-secondary);
  border-color: color-mix(in srgb, var(--color-border-strong) 30%, transparent);
  background: color-mix(in srgb, var(--color-interactive-soft) 8%, transparent);
}

.journal-chip.status.review {
  color: var(--color-warning);
  border-color: rgba(245,158,11,0.30);
  background: rgba(245,158,11,0.08);
}

.journal-confidence {
  color: var(--color-data-secondary);
  letter-spacing: 0.08em;
  font-size: 12px;
}

.journal-kebab {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-full);
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(5,5,5,0.72);
  color: var(--color-text-secondary);
  cursor: pointer;
}

.journal-table-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-top: 14px;
  color: var(--color-text-muted);
  font-size: 13px;
}

.journal-table-footer div {
  display: flex;
  gap: 8px;
}

.journal-entry-card-list {
  display: none;
}

.journal-calendar-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 180px;
  gap: 16px;
  align-items: start;
}

.journal-week-header,
.journal-heat-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.journal-heat-grid::-webkit-scrollbar {
  display: none;
}

.journal-week-header {
  margin-bottom: 8px;
  color: var(--color-text-muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.journal-heat-cell {
  min-height: 72px;
  display: grid;
  align-content: space-between;
  padding: 9px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(5,5,5,0.60);
  color: var(--color-text-secondary);
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  min-width: 0;
}

.journal-heat-cell.blank {
  visibility: hidden;
}

.journal-heat-cell.small-gain { background: rgba(34,197,94,0.09); border-color: rgba(34,197,94,0.18); }
.journal-heat-cell.large-gain { background: rgba(34,197,94,0.18); border-color: rgba(34,197,94,0.30); }
.journal-heat-cell.small-loss { background: rgba(239,68,68,0.09); border-color: rgba(239,68,68,0.18); }
.journal-heat-cell.large-loss { background: rgba(239,68,68,0.18); border-color: rgba(239,68,68,0.30); }
.journal-heat-cell.selected { outline: 2px solid rgba(255, 255, 255, 0.488); }

.journal-heat-cell strong {
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.journal-heat-cell small {
  color: var(--color-text-muted);
  font-size: 9px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.journal-heat-legend {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 12px;
  color: var(--color-text-muted);
  font-size: 12px;
}

.journal-selected-day {
  display: grid;
  gap: 10px;
  padding: 16px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.105);
  background: rgba(0,0,0,0.54);
}

.journal-selected-day h3,
.journal-today-notes h3 {
  margin: 0;
  color: var(--color-text-primary);
}

.journal-selected-day > strong {
  font-size: 26px;
  font-variant-numeric: tabular-nums;
}

.journal-day-view {
  display: grid;
  gap: 16px;
}

.journal-day-view-head,
.journal-day-toolbar,
.journal-day-filter-row,
.journal-day-summary-grid,
.journal-day-layout {
  min-width: 0;
}

.journal-breadcrumb {
  color: var(--color-text-muted);
  font-size: 12px;
  letter-spacing: 0.04em;
}

.journal-breadcrumb span {
  margin: 0 6px;
  color: var(--color-text-muted);
}

.journal-day-view-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-6, 24px);
  padding-bottom: var(--space-4, 16px);
  border-bottom: 1px solid var(--color-border-subtle);
}

.journal-day-view-head h3 {
  margin: var(--space-2, 8px) 0 0;
  color: var(--color-text-primary);
  font-size: clamp(1.5rem, 2vw, 2rem);
  line-height: 1.1;
  letter-spacing: -0.02em;
  font-weight: 600;
}

.journal-day-view-desc {
  margin: var(--space-2, 8px) 0 0;
  max-width: 440px;
  color: var(--color-text-secondary);
  font-size: 13px;
  line-height: 1.45;
}

.journal-day-view-actions {
  display: flex;
  align-items: center;
  gap: var(--space-2, 8px);
  flex-shrink: 0;
}

.journal-day-toolbar {
  display: grid;
  grid-template-columns: auto auto minmax(260px, 1fr) auto;
  gap: var(--space-3, 12px);
  align-items: center;
}

.journal-day-date-nav {
  display: inline-grid;
  grid-template-columns: auto minmax(140px, auto) auto;
  align-items: center;
  gap: 0;
  border-radius: var(--radius-md, 6px);
  border: 1px solid var(--color-border-medium);
  overflow: hidden;
  background: var(--color-surface-elevated);
}

.journal-day-date-nav > div,
.journal-day-date-nav > time {
  min-height: 42px;
  padding: 0 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-primary);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  border-inline: 1px solid var(--color-border-subtle);
}

.journal-day-search {
  width: 100%;
}

.journal-day-search input {
  width: 100%;
}

.journal-day-filter-row {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-3, 12px);
  padding: var(--space-4, 16px);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-lg, 8px);
  background: var(--color-surface-card);
}

.journal-day-filter-row label {
  display: grid;
  gap: var(--space-2, 8px);
  color: var(--color-text-muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.journal-day-filter-row select {
  min-height: 40px;
  width: 100%;
  padding: 0 var(--space-3, 12px);
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md, 6px);
  background: var(--color-surface-elevated);
  color: var(--color-text-primary);
}

.journal-day-summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-3, 12px);
}

.journal-day-stat-card {
  display: grid;
  align-content: start;
  gap: var(--space-2, 8px);
  min-height: 112px;
}

.journal-day-stat-card strong {
  font-family: var(--font-mono);
  font-size: 22px;
  font-weight: 600;
}

.journal-day-stat-card small {
  color: var(--color-text-muted);
  font-size: 11px;
  line-height: 1.35;
}

.journal-day-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 320px);
  gap: var(--space-4, 16px);
  align-items: start;
}

.journal-day-main {
  min-width: 0;
}

.journal-day-aside {
  display: grid;
  gap: var(--space-4, 16px);
  min-width: 0;
}

.journal-day-aside.is-empty {
  opacity: 0.92;
}

.journal-day-trade-log {
  display: grid;
  gap: 14px;
}

.journal-day-trades-list {
  display: grid;
  gap: 14px;
}

.journal-day-trade-row {
  display: grid;
  grid-template-columns: 80px minmax(0, 1fr);
  gap: var(--space-4, 16px);
  padding: var(--space-4, 16px) 0;
  border-top: 1px solid var(--color-border-subtle);
  background: transparent;
}

.journal-day-trade-row:first-child {
  border-top: 0;
}

.journal-day-trade-time {
  display: grid;
  align-content: start;
  gap: 4px;
}

.journal-day-trade-time strong {
  color: var(--color-text-primary);
  font-family: var(--font-mono);
  font-size: 12px;
}

.journal-day-trade-time span,
.journal-day-trade-time small {
  color: var(--color-text-muted);
  font-size: 11px;
}

.journal-day-trade-body {
  min-width: 0;
}

.journal-day-trade-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-4, 16px);
}

.journal-day-trade-metrics {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: var(--space-3, 12px);
  margin-top: var(--space-4, 16px);
}

.journal-day-trade-metrics > div {
  display: grid;
  gap: 4px;
}

.journal-day-trade-metrics span {
  color: var(--color-text-muted);
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.journal-day-trade-metrics strong {
  color: var(--color-text-primary);
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
}

.journal-day-trade-footer {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-4, 16px);
  margin-top: var(--space-4, 16px);
  padding-top: var(--space-3, 12px);
  border-top: 1px solid var(--color-border-subtle);
}

.journal-day-trade-footer p {
  max-width: 70ch;
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 13px;
  line-height: 1.45;
}

.journal-day-breakdown-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.075);
}

.journal-day-breakdown-grid div {
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.075);
}

.journal-day-breakdown-grid div:nth-child(odd) {
  padding-right: 14px;
  border-right: 1px solid rgba(255, 255, 255, 0.075);
}

.journal-day-breakdown-grid div:nth-child(even) {
  padding-left: 14px;
}

.journal-day-breakdown-grid span {
  display: block;
  color: var(--color-text-muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.journal-day-breakdown-grid strong {
  display: block;
  margin-top: 8px;
  color: var(--color-text-primary);
}

.journal-day-notes-list {
  display: grid;
  gap: 12px;
}

.journal-day-notes-list div {
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.075);
}

.journal-day-notes-list div:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.journal-day-notes-list span {
  display: block;
  color: var(--color-text-primary);
  font-size: 13px;
  font-weight: 700;
}

.journal-day-notes-list p {
  margin: 6px 0 0;
  color: var(--color-text-muted);
  line-height: 1.55;
}

.journal-day-attachments {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}

.journal-day-attachment {
  min-height: 108px;
  padding: 14px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.105);
  background: rgba(5,5,5,0.54);
  display: grid;
  align-content: end;
  gap: 8px;
  color: var(--color-text-secondary);
}

.journal-day-attachment strong {
  color: var(--color-text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.journal-day-attachment span {
  color: var(--color-text-muted);
  font-size: 12px;
}

.journal-day-attachment.empty {
  grid-column: 1 / -1;
  border-style: dashed;
}

.journal-month-summary,
.journal-review-summary,
.journal-behavior-grid,
.journal-lesson-grid,
.journal-action-plan {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
  margin-top: 16px;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

@media (max-width: 960px) {
  .journal-day-layout {
    grid-template-columns: 1fr;
  }

  .journal-day-aside {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .journal-day-filter-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {
  .journal-page {
    padding: var(--space-4, 16px);
  }

  .journal-day-view-head {
    display: grid;
    gap: var(--space-4, 16px);
  }

  .journal-day-view-head::after {
    display: none;
  }

  .journal-day-view-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .journal-day-toolbar {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--space-3, 12px);
  }

  .journal-day-filter-row {
    grid-template-columns: 1fr;
  }

  .journal-day-summary-grid {
    grid-template-columns: 1fr;
  }

  .journal-day-aside {
    grid-template-columns: 1fr;
  }

  .journal-day-trade-row {
    grid-template-columns: 1fr;
    gap: var(--space-3, 12px);
  }

  .journal-day-trade-top,
  .journal-day-trade-footer {
    display: grid;
    gap: var(--space-3, 12px);
  }

  .journal-day-trade-metrics {
