}

.home-v3-empty h3 {
  margin: 0;
  color: var(--color-text-primary);
}

.home-v3-drawer-overlay,
.home-v2-flow-overlay {
  position: fixed;
  inset: 0;
  z-index: 1300;
  display: flex;
  justify-content: flex-end;
  background: rgba(0,0,0,0.62);
  backdrop-filter: blur(4px);
}

.home-v3-detail-drawer,
.home-v2-flow-shell {
  width: min(560px, 100vw) !important;
  height: 100vh;
  overflow: auto;
  border-radius: 0 !important;
  border-left: 1px solid var(--color-border-medium) !important;
  background: var(--color-surface-card) !important;
  box-shadow: -24px 0 60px rgba(0,0,0,0.48) !important;
  animation: homeV3DrawerIn 180ms ease-out;
}

.saved-items-drawer {
  background: var(--color-surface-card) !important;
  border-left-color: var(--color-border-medium) !important;
}

@keyframes homeV3DrawerIn {
  from { transform: translateX(28px); opacity: 0.72; }
  to { transform: translateX(0); opacity: 1; }
}

.home-v3-drawer-overlay {
  animation: homeV3OverlayIn var(--duration-base) var(--ease-out) both;
}

@keyframes homeV3OverlayIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.settings-chevron {
  transform: rotate(0deg);
  transition: transform var(--duration-fast) var(--ease-standard);
}

.settings-chevron[data-open="true"] {
  transform: rotate(90deg);
}

#settings-content-panel .flex.flex-col.gap-4.p-5.border-t {
  animation: settingsAccordionIn var(--duration-base) var(--ease-out) both;
}

/* Notification settings use the same clear, balanced switch language as
   onboarding: a 42px track with a 20px thumb. The generic switch is kept
   compact for dense preferences elsewhere in settings. */
.settings-notification-switch {
  flex: 0 0 42px !important;
  width: 42px !important;
  min-width: 42px !important;
  height: 24px !important;
  min-height: 24px !important;
  max-height: 24px !important;
  padding: 0 !important;
  align-self: center;
  position: relative;
  border-radius: 999px !important;
  border: 0 !important;
  background: var(--color-border-medium) !important;
  transition: background-color var(--duration-fast) var(--ease-standard),
    border-color var(--duration-fast) var(--ease-standard) !important;
}

.settings-notification-switch[data-state="checked"] {
  background: #fff !important;
}

.settings-notification-switch::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  z-index: 1;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #0a0a0a;
  transform: translateX(0);
  transition: transform var(--duration-fast) var(--ease-standard);
}

.settings-notification-switch[data-state="checked"]::after {
  transform: translateX(18px);
}

.settings-notification-switch > span {
  display: none !important;
}

.settings-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 24px;
}

.settings-notification-switch:focus-visible {
  outline: 2px solid var(--color-focus) !important;
  outline-offset: 3px;
}

.settings-notification-switch:disabled {
  border-color: var(--color-border) !important;
  background: var(--color-surface-depth) !important;
}

@keyframes settingsAccordionIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 960px) {
  .mobile-sidebar-panel {
    transform: translateX(0);
    transition: transform var(--duration-slow) var(--ease-out), opacity var(--duration-slow) var(--ease-out);
  }

  .mobile-sidebar-panel.collapsed {
    transform: translateX(-100%);
    opacity: .98;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-in);
  }

  .mobile-sidebar-scrim {
    opacity: 1;
    transition: opacity var(--duration-base) var(--ease-out);
  }
}

/* Mobile bottom navigation — thumbs-first primary destinations. Hidden on
   desktop; the hamburger drawer still carries the full hierarchy. */
.mobile-bottom-nav {
  display: none;
}

@media (max-width: 960px) {
  .mobile-bottom-nav {
    display: flex;
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 1085; /* below the drawer scrim (1090) and modals */
    justify-content: space-around;
    gap: 2px;
    padding: 6px 4px max(6px, env(safe-area-inset-bottom));
    background: var(--color-surface-card);
    border-top: 1px solid var(--color-border-medium);
  }

  .mobile-bottom-nav-item {
    flex: 1 1 0;
    min-height: 44px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    padding: 4px 2px;
    border: 0;
    border-radius: var(--radius-md);
    background: transparent;
    color: var(--color-text-secondary);
    font: inherit;
    font-size: 0.68rem;
    font-weight: 600;
    cursor: pointer;
    transition: color 120ms ease, background 120ms ease;
  }

  .mobile-bottom-nav-item:active { background: var(--color-surface-hover); }
  .mobile-bottom-nav-item.active { color: var(--color-interactive); }
  .mobile-bottom-nav-item:disabled { opacity: 0.4; cursor: not-allowed; }
  .mobile-bottom-nav-item:focus-visible { outline: 2px solid var(--color-focus); outline-offset: -2px; }

  .mobile-bottom-nav-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.15rem;
    line-height: 1;
  }
  .mobile-bottom-nav-icon svg { width: 20px; height: 20px; }

  .mobile-bottom-nav-label { line-height: 1; }

  /* Keep content clear of the fixed bar. */
  .main-content {
    padding-bottom: calc(64px + env(safe-area-inset-bottom));
  }
}

@media (prefers-reduced-motion: reduce) {
  .mobile-bottom-nav-item { transition: none; }
}

@media (prefers-reduced-motion: reduce) {
  .right-rail-drawer,
  .right-rail-drawer-overlay,
  .mobile-sidebar-panel,
  .mobile-sidebar-scrim,
  .trade-toast,
  .settings-chevron {
    transition-duration: var(--duration-instant) !important;
    transition-property: opacity, transform !important;
  }

  .right-rail-drawer,
  .mobile-sidebar-panel,
  .trade-toast {
    transform: none !important;
  }
}

