/* ── Shared Brandv2 workspace primitives (Home + Portfolio) ─────────────── */
:root {
  --workspace-surface: var(--color-surface-card);
  --workspace-surface-strong: var(--color-surface-card-strong);
  --workspace-surface-elevated: var(--color-surface-elevated);
  --workspace-border: var(--color-border-medium);
  --workspace-border-subtle: var(--color-border-subtle);

  --workspace-radius: var(--radius-md);
  --workspace-panel-padding: var(--space-4);
  --workspace-section-gap: var(--space-5);
  --workspace-grid-gap: var(--space-4);

  --workspace-title-size: var(--fs-2xl);
  --workspace-section-title-size: var(--fs-md);
  --workspace-body-size: var(--fs-body);
  --workspace-label-size: var(--fs-xs);
  --workspace-metric-size: var(--fs-2xl);
}

.workspace-page {
  min-width: 0;
  overflow-x: clip;
}

.workspace-surface {
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  background: var(--workspace-surface);
  box-shadow: none;
}

.workspace-surface--strong {
  background: var(--workspace-surface-strong);
}

.workspace-label {
  color: var(--color-text-muted);
  font-size: var(--workspace-label-size);
  font-weight: var(--fw-semibold);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.workspace-metric {
  color: var(--color-text-primary);
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-weight: var(--fw-semibold);
  letter-spacing: -0.02em;
}

.workspace-section-title {
  color: var(--color-text-primary);
  font-size: var(--workspace-section-title-size);
  font-weight: var(--fw-semibold);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

.home-exec {
  --home-exec-ease: cubic-bezier(0.23, 1, 0.32, 1);
  width: 100%;
  margin: 0;
  padding: 22px clamp(12px, 2vw, 28px) 36px;
  display: grid;
  gap: 20px;
  background: transparent;
  border: none;
  border-radius: 0;
  box-shadow: none;
  background-image:
    linear-gradient(to right, rgba(255, 255, 255, 0.018) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255, 255, 255, 0.018) 1px, transparent 1px);
  background-size: 28px 28px;
}

.home-exec-page-header,
.home-exec-section-head,
.home-exec-panel-head,
.home-exec-hero-value-row,
.home-exec-holding-top,
.home-exec-legend-row,
.home-exec-metric-row,
.home-exec-triage-topline,
.home-exec-range-row,
.home-exec-header-actions,
