.home-exec-triage-tools button[data-tone="dismiss"] {
  color: var(--color-danger);
  border-color: color-mix(in srgb, var(--color-danger) 32%, transparent);
}

.home-exec-triage-tools button[data-tone="dismiss"]:hover {
  background: var(--color-danger-soft);
  color: var(--color-danger);
}

.home-exec-severity {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 8px;
  border-radius: var(--radius-full);
  border: 1px solid currentColor;
  background: transparent;
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.14em;
}

.home-exec-triage-card h3,
.home-exec-market-panel h3 {
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 14px;
}

.home-exec-triage-meta {
  margin-top: auto;
  padding-top: 10px;
  border-top: 1px solid var(--color-border-subtle);
  color: rgba(255, 255, 255, 0.28);
  font-size: 11px;
}

.home-exec-main-grid {
  display: grid;
  grid-template-columns: minmax(0, 2.3fr) minmax(340px, 1fr);
  gap: 16px;
}

.home-exec-primary-col,
.home-exec-secondary-col {
  display: grid;
  gap: 18px;
}

.home-exec-performance-foot {
  margin-top: 12px;
}

.home-exec-chart-stats {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 14px;
}

.home-exec-performance-panel {
  background: rgba(17, 22, 29, 0.96);
}

.home-exec-performance-panel .home-exec-chart-stats div {
  min-height: auto;
  padding: 10px 0 0;
  border: 0;
  border-top: 1px solid var(--color-border-subtle);
  border-radius: 0;
  background: transparent;
}

.home-exec-log-table-wrap {
  overflow-x: auto;
}

.home-exec-log-table {
  width: 100%;
  border-collapse: collapse;
}

.home-exec-log-table thead tr {
  background: rgba(255, 255, 255, 0.015);
}

.home-exec-log-table th,
.home-exec-log-table td {
  padding: 10px 10px;
  text-align: left;
}

.home-exec-log-table td {
  font-size: 11px;
  color: rgba(248, 250, 252, 0.76);
}

.home-exec-log-table tbody tr {
  border-top: 1px solid var(--color-border-subtle);
  cursor: pointer;
}

.home-exec-log-table tbody tr:hover,
.home-exec-holding-row:hover,
.home-exec-mover-row:hover {
  background: rgba(255, 255, 255, 0.03);
}

.home-exec-log-table tbody tr:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.55);
  outline-offset: -2px;
}

.home-exec-status {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 8px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-subtle);
  background: rgba(255, 255, 255, 0.02);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}

.home-exec-holdings-list,
.home-exec-mover-list {
  display: grid;
}

.home-exec-holdings-list {
  border-top: 1px solid var(--color-border-subtle);
}

.home-exec-holding-row,
.home-exec-mover-row {
  width: 100%;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.home-exec-holding-row {
  display: grid;
  gap: 8px;
  padding: 12px 0;
  border-bottom: 1px solid var(--color-border-subtle);
}

.home-exec-holding-bar {
  height: 2px;
  border-radius: var(--radius-full);
  background: var(--color-surface-selected);
  overflow: hidden;
}

.home-exec-holding-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--color-interactive);
}

.home-exec-holding-top strong,
.home-exec-mover-row strong {
  color: rgba(248, 250, 252, 0.92);
  font-size: 12px;
}

.home-exec-holding-meta {
  display: grid;
  gap: 4px;
}

.home-exec-holding-meta span:last-child,
.home-exec-mover-row span,
.home-exec-market-count {
  color: rgba(255, 255, 255, 0.4);
  font-size: 11px;
  text-transform: none;
  letter-spacing: 0;
  font-weight: 500;
}

.home-exec-allocation-chart {
  position: relative;
}

.home-exec-donut-center {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  pointer-events: none;
  text-align: center;
}

.home-exec-allocation-legend {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}

.home-exec-legend-left {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: rgba(255, 255, 255, 0.48);
  font-size: 11px;
}

.home-exec-warning {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  margin-top: 16px;
  padding: 0 10px;
  border-radius: var(--radius-full);
  border: 1px solid rgba(245, 158, 11, 0.24);
  background: rgba(245, 158, 11, 0.08);
  color: var(--color-warning);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.14em;
}

.home-exec-metrics-grid {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.home-exec-metric-row {
  min-height: 52px;
  align-content: center;
}

.home-exec-market-context {
  display: grid;
  gap: 16px;
}

.home-exec-market-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.home-exec-market-panel {
  display: grid;
  gap: 10px;
}

.home-exec-market-controls select {
  min-height: 32px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-subtle);
  background: rgba(255, 255, 255, 0.02);
  color: var(--color-text-secondary);
  padding: 0 10px;
}

.home-exec-market-count {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  padding: 0 10px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-subtle);
  background: rgba(255, 255, 255, 0.02);
}

.home-exec-mover-row {
  min-height: 58px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 12px;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid var(--color-border-subtle);
}

.home-exec-mover-relevance {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 8px;
  border-radius: var(--radius-full);
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.05);
  color: #72d8ee !important;
  font-size: 9px !important;
  font-weight: 800 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.12em !important;
}

.home-exec-empty {
  min-height: 160px;
}

.home-exec-btn:focus-visible,
.home-exec-link:focus-visible,
.home-exec-timeframe-strip button:focus-visible,
.home-exec-toggle:focus-visible,
.home-exec-triage-tools button:focus-visible,
.home-exec-holding-row:focus-visible,
.home-exec-mover-row:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.6);
  outline-offset: 3px;
}

@media (max-width: 1199px) {
  .home-v2 {
    padding: 20px;
  }

  .home-v3-hero,
  .home-v2-main-grid {
    grid-template-columns: 1fr;
  }

  .home-v2-attention-grid,
  .home-v2-hero-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 767px) {
  .home-v2 {
    padding: 16px;
    border-radius: var(--radius-md);
  }

  .home-v3-page-header h2 {
    font-size: 24px;
  }

  .home-v3-header-actions,
  .home-v3-btn,
  .home-v3-market-controls,
  .home-v3-market-controls select {
    width: 100%;
  }

  .home-v2-attention-grid,
  .home-v2-hero-stats,
  .home-v3-chart-insights,
  .home-v3-market-grid,
  .home-v2-metrics {
    grid-template-columns: 1fr;
  }

  .home-v2-holding-row,
  .home-v2-activity-row,
  .home-v3-mover-row {
    grid-template-columns: 1fr;
  }

  .home-exec {
    padding: 20px;
  }

  .home-exec-top-grid,
  .home-exec-main-grid,
  .home-exec-market-grid,
  .home-exec-market-preview-strip,
  .home-exec-market-preview-grid {
    grid-template-columns: 1fr;
  }

  .home-exec-hero-grid,
  .home-exec-chart-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (prefers-reduced-motion: reduce) {
  .watchlist-panel,
  .glass,
  .home-v2-panel,
  .portfolio-v2-panel,
  .tax-v2-panel,
  .tax-v2-kpi,
  .portfolio-v2-table tbody tr,
  .journal-v2-table tbody tr,
  .option-chain-table tbody tr,
  .whale-trades-table tbody tr {
    transition: none;
  }

  .watchlist-panel:hover,
  .home-v2-panel:hover,
  .portfolio-v2-panel:hover,
  .tax-v2-panel:hover,
  .tax-v2-kpi:hover,
  .portfolio-v2-table tbody tr:hover,
  .journal-v2-table tbody tr:hover,
  .option-chain-table tbody tr:hover,
  .whale-trades-table tbody tr:hover {
    transform: none;
  }
}

@media (max-width: 767px) {
  .home-exec {
    padding: 16px;
    border-radius: var(--radius-md);
  }

  .home-exec-heading h2 {
    font-size: 24px;
  }

  .home-exec-btn,
  .home-exec-market-controls,
  .home-exec-market-controls select,
  .home-exec-market-count,
  .home-exec-command-bar,
  .home-exec-header-actions,
  .home-exec-command-chip {
    width: 100%;
  }

  .home-exec-command-metrics,
  .home-exec-signal-row,
  .home-exec-health-card {
    grid-template-columns: 1fr;
  }

  .home-exec-hero-grid,
  .home-exec-chart-stats,
  .home-exec-market-grid,
  .home-exec-market-preview-strip,
  .home-exec-market-preview-grid {
    grid-template-columns: 1fr;
  }

  .home-exec-hero-value-row,
  .home-exec-section-head,
  .home-exec-panel-head {
    align-items: flex-start;
  }

  .home-exec-range-row {
    flex-direction: column;
  }

  .home-exec-range-track {
    width: 100%;
    margin-left: 0;
  }

  .home-exec-signal-actions,
  .home-exec-command-strip,
  .home-exec-market-context-actions {
    justify-content: flex-start;
  }

  .home-exec-health-card em {
    max-width: none;
    text-align: left;
  }

  .home-exec-log-table {
    min-width: 640px;
  }

  .home-exec-mover-row {
    grid-template-columns: 1fr;
  }
}

/* ═══════════════════════════════════════════════════════════════
   LIGHT MODE — ANALYTICS & JOURNAL SECTION OVERRIDES
   ═══════════════════════════════════════════════════════════════ */

/* Define --color-surface in light mode */
html.light-theme-active {
  --color-surface: rgba(241, 245, 249, 0.7);
}

/* --- Yahoo Style Asset Header --- */
.yahoo-header {
  padding: 16px 20px 12px !important;
  border-bottom: 1px solid var(--color-border-medium);
  display: block !important;
}

.asset-info-yahoo {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.asset-title-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.yahoo-name {
  font-size: 1.05rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  margin: 0;
}

.yahoo-price-row {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-top: 4px;
}

.yahoo-price {
  font-size: 1.9rem;
  font-weight: 700;
  color: var(--color-text-primary);
  line-height: 1;
}

.yahoo-change {
  font-size: 0.95rem;
  font-weight: 600;
}

.yahoo-change.positive { color: var(--color-text-success); }
.yahoo-change.negative { color: var(--color-text-danger); }

.yahoo-currency-label {
  font-size: 0.85rem;
  color: var(--color-text-secondary);
  font-weight: 500;
  opacity: 0.8;
}

.yahoo-market-status {
  font-size: 0.8rem;
  color: var(--color-text-secondary);
  opacity: 0.7;
  margin-top: 4px;
}

.asset-data-status {
  display: flex;
  align-items: center;
  gap: 12px;
}

.chart-range-display {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  margin: 4px 0 8px;
  padding-bottom: 4px;
}

.range-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--color-text-secondary);
  letter-spacing: 0.05em;
  opacity: 0.8;
}

.range-dates {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--color-text-primary);
  opacity: 0.9;
}

/* Layout containers */
body.light-theme-active .analytics-layout,
body.light-theme-active .journal-page {
  background: var(--color-bg-base);
  color: var(--color-text-primary);
}

/* Analytics cards */
