  color: var(--color-text-secondary) !important;
}

body.light-theme-active .whale-trades-table tbody tr:nth-child(even) {
  background: rgba(248, 250, 252, 1) !important;
}

body.light-theme-active .whale-trades-table tbody tr:nth-child(odd) {
  background: rgba(255, 255, 255, 1) !important;
