body.light-theme-active .asset-card {
  color: var(--color-text-primary) !important;
}

body.light-theme-active .asset-card strong {
  color: var(--color-text-primary) !important;
}

body.light-theme-active .asset-card p {
  color: var(--color-text-secondary) !important;
