.market-signal-row span,
.market-event-row span {
  color: var(--color-text-muted);
  font-size: 11px;
}

.market-asset-logo {
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: linear-gradient(135deg, var(--color-text-secondary), var(--color-data-secondary));
  color: var(--color-text-primary);
  font-size: 11px;
  font-weight: 900;
}

.market-asset-logo.commodities,
.market-asset-logo.commodity {
  background: linear-gradient(135deg, var(--color-warning), #facc15);
}

.market-asset-logo.options,
.market-asset-logo.option {
  background: var(--color-interactive-soft);
}

.market-asset-logo.macro {
  background: linear-gradient(135deg, var(--color-surface-card), var(--color-surface-elevated));
}

.market-type-badge,
.market-signal-tone,
.market-event-impact {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: max-content;
  min-height: 22px;
  padding: 0 8px;
  border-radius: var(--radius-lg);
  border: var(--color-border-medium);
  background: var(--color-interactive-soft);
  color: var(--color-data-secondary);
  font-size: 11px;
  font-style: normal;
  font-weight: 800;
}

.market-type-badge.option,
.market-type-badge.options {
  border-color: var(--color-border-medium);
  background: var(--color-interactive-soft);
  color: var(--color-interactive);
}

.market-type-badge.commodity,
.market-type-badge.commodities {
  border-color: rgba(245, 158, 11, 0.32);
  background: rgba(245, 158, 11, 0.12);
  color: var(--color-data-amber-bright);
}

.market-type-badge.macro {
  border-color: var(--color-border-medium);
  background: var(--color-interactive-soft);
  color: var(--color-data-primary);
}

.market-impact-total {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 12px;
  align-items: center;
  padding: 9px 6px 0;
  color: var(--color-text-primary);
}

.market-impact-total em {
  font-style: normal;
  font-weight: 900;
}

.market-mover-tabs {
  display: flex;
  gap: 20px;
  border-bottom: var(--color-border-medium);
  margin-bottom: 8px;
  overflow-x: auto;
}

.market-mover-tabs button {
  min-height: 32px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--color-text-muted);
  text-transform: capitalize;
  font-weight: 800;
  cursor: pointer;
  flex: 0 0 auto;
  white-space: nowrap;
}

.market-mover-tabs button.active {
  color: var(--color-data-secondary);
  border-bottom-color: var(--color-data-secondary);
}

.market-movers-columns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.market-mover-list {
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.market-mover-list h4 {
  margin: 0;
  padding: 8px 10px;
  color: var(--color-text-primary);
  font-size: 12px;
  background: var(--color-surface-elevated);
}

.market-mover-detail-row,
.market-signal-row,
.market-macro-row,
.market-event-row {
  width: 100%;
  display: grid;
  align-items: center;
  gap: 10px;
  border: 0;
  border-bottom: var(--color-border-medium);
  background: transparent;
  color: inherit;
  text-align: left;
}

.market-mover-detail-row {
  grid-template-columns: 30px minmax(0, 1fr) auto auto;
  min-height: 46px;
  padding: 7px 10px;
  cursor: pointer;
}

.market-mover-detail-row:hover,
.market-signal-row:hover,
.market-event-row:hover {
  background: var(--color-interactive-soft);
}

.market-signal-list,
.market-event-list,
.market-macro-table {
  display: grid;
}

.market-signal-row {
  grid-template-columns: 30px minmax(0, 1fr) auto auto auto;
  padding: 8px 0;
}

.market-signal-tone.bullish,
.market-event-impact.low {
  border-color: rgba(34, 197, 94, 0.32);
  background: rgba(34, 197, 94, 0.10);
  color: var(--color-success);
}

.market-signal-tone.bearish,
.market-event-impact.high {
  border-color: rgba(239, 68, 68, 0.32);
  background: rgba(239, 68, 68, 0.10);
  color: var(--color-danger);
}

.market-signal-tone.watch,
.market-event-impact.medium {
  border-color: rgba(245, 158, 11, 0.32);
  background: rgba(245, 158, 11, 0.10);
  color: var(--color-warning);
}

.market-signal-row em {
  color: var(--color-text-muted);
  font-size: 11px;
  font-style: normal;
}

/* Market Signals 2.0 — cross-asset intelligence feed (spec §1) */
.market-signals-2 { gap: 0; }
.market-signal-2-row {
  display: grid;
  grid-template-columns: 84px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
  padding: 12px 0;
  border-bottom: 1px solid var(--color-border-subtle);
}
.market-signal-2-row:last-child { border-bottom: none; }
.market-signal-cat {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-lg);
  padding: 4px 6px;
  text-align: center;
  white-space: nowrap;
}
.market-signal-cat.cat-macro { color: var(--color-data-slate-bright); border-color: rgba(160, 160, 160, 0.28); }
.market-signal-body { min-width: 0; }
.market-signal-body strong { display: block; font-size: 13px; color: var(--color-text-primary); }
.market-signal-summary { display: block; font-size: 12px; color: var(--color-text-secondary); margin-top: 2px; }
.market-signal-meta { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 6px; font-size: 11px; color: var(--color-text-muted); }
.market-signal-impact { color: var(--color-text-secondary); }
.market-signal-impact.positive, .market-signal-impact.risk-on { color: var(--color-success); }
.market-signal-impact.negative, .market-signal-impact.risk-off { color: var(--color-danger); }
.market-signal-assets { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-top: 6px; font-size: 11px; color: var(--color-text-muted); }
.market-signal-asset {
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-subtle);
  color: var(--color-data-slate-bright);
  border-radius: var(--radius-full);
  padding: 2px 8px;
  font-size: 11px;
  cursor: pointer;
}
.market-signal-asset:hover { border-color: var(--color-interactive); }
.market-signal-transmission { margin-top: 6px; font-size: 11px; color: var(--color-text-muted); }
.market-signal-actions { display: flex; flex-direction: column; gap: 6px; }
.market-signal-btn {
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-subtle);
  color: var(--color-text-secondary);
  border-radius: var(--radius-lg);
  padding: 4px 8px;
  font-size: 11px;
  cursor: pointer;
  white-space: nowrap;
}
.market-signal-btn:hover { border-color: var(--color-interactive); color: var(--color-text-primary); }

/* Rich Signal Cards (spec §1–§6, §13, §15) */
.market-signals-2 { gap: 0; }
.msc-group { border-bottom: 1px solid var(--color-border-subtle); }
.msc-group:last-child { border-bottom: none; }
.msc-group-head { display: flex; align-items: center; gap: 8px; width: 100%; background: none; border: none; cursor: pointer; padding: 10px 0; color: var(--color-text-primary); }
.msc-group-caret { color: var(--color-text-muted); font-size: 10px; width: 12px; }
.msc-group-label { font-size: 12px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; }
.msc-group-count { font-size: 11px; color: var(--color-text-muted); margin-left: auto; }
.msc-group-body { display: grid; gap: 0; padding-bottom: 8px; }

.market-signal-card { display: grid; gap: 6px; padding: 12px 0; border-top: 1px solid var(--color-border-subtle); }
.market-signal-card.imp-critical { padding: 16px 0; }
.market-signal-card.imp-low { padding: 8px 0; }
.market-signal-card.fresh-expired { opacity: 0.55; }
.market-signal-card.fresh-expiring { opacity: 0.85; }
.msc-head { display: flex; align-items: center; gap: 10px; }
.msc-time { font-size: 11px; color: var(--color-text-muted); }
.msc-conf { font-size: 11px; color: var(--color-text-secondary); margin-left: auto; }
.imp-critical .msc-headline { font-size: 15px; }
.imp-high .msc-headline { font-size: 14px; }
.imp-medium .msc-headline, .imp-low .msc-headline { font-size: 13px; }
.msc-headline { color: var(--color-text-primary); font-weight: 600; }
.imp-low .msc-headline { font-weight: 500; }
.msc-summary { margin: 0; font-size: 12px; color: var(--color-text-secondary); }
.msc-why { margin: 0; font-size: 12px; color: var(--color-text-secondary); }
.msc-label { display: block; font-size: 9px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-text-muted); margin-bottom: 3px; }
.msc-transmission { display: grid; gap: 3px; }
.msc-tx-path { display: flex; flex-wrap: wrap; gap: 4px 10px; align-items: center; font-size: 11px; color: var(--color-text-secondary); }
.msc-tx-node { display: inline-flex; align-items: center; gap: 4px; }
.msc-tx-dir { color: var(--color-text-muted); }
.msc-assets { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.msc-meta { display: flex; flex-wrap: wrap; gap: 10px; font-size: 10px; color: var(--color-text-muted); }
.msc-meta em { color: var(--color-text-secondary); font-style: normal; }
.msc-freshness.fresh-fresh { color: var(--color-success); }
.msc-freshness.fresh-expiring { color: var(--color-warning); }
.msc-freshness.fresh-expired { color: var(--color-text-muted); }
.msc-actions { display: flex; flex-wrap: wrap; gap: 6px; }
.market-empty-state-calm { text-align: center; padding: 20px 8px; }
.market-calm-title { font-size: 14px; color: var(--color-text-primary); margin: 0 0 4px; }
.market-calm-sub { font-size: 12px; color: var(--color-text-secondary); margin: 0 0 10px; }
.market-calm-list { list-style: none; padding: 0; margin: 0 0 10px; display: flex; flex-wrap: wrap; gap: 6px 14px; justify-content: center; font-size: 12px; color: var(--color-text-secondary); }
.market-calm-list .calm-check { color: var(--color-success); margin-right: 4px; }
.market-calm-foot { font-size: 11px; color: var(--color-text-muted); }
.market-calm-foot em { color: var(--color-text-secondary); font-style: normal; }

/* Enhanced Macro Context (spec §9) */
.macro-ctx-enhanced {
  display: grid;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-xl);
  background: var(--color-surface-depth);
  margin-bottom: 12px;
}
.macro-ctx-label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-text-muted); }
.macro-ctx-regime-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.macro-ctx-regime-value { font-size: 16px; color: var(--color-text-primary); }
.macro-ctx-regime-value.neutral { color: var(--color-text-secondary); }
.macro-ctx-regime-value.risk-off, .macro-ctx-regime-value.bearish { color: var(--color-danger); }
.macro-ctx-regime-value.risk-on, .macro-ctx-regime-value.bullish { color: var(--color-success); }
.macro-ctx-confidence { font-size: 11px; color: var(--color-text-muted); border: 1px solid var(--color-border-subtle); border-radius: var(--radius-full); padding: 2px 8px; }
.macro-ctx-regime-sub { display: flex; gap: 12px; flex-wrap: wrap; font-size: 11px; color: var(--color-text-muted); margin-top: 4px; }
.macro-ctx-regime-sub em { color: var(--color-text-secondary); font-style: normal; }
.macro-ctx-explain { color: var(--color-text-secondary); }
.macro-ctx-factors { display: grid; grid-template-columns: repeat(auto-fit, minmax(92px, 1fr)); gap: 6px; }
.macro-ctx-factor { display: flex; justify-content: space-between; align-items: center; border: 1px solid var(--color-border-subtle); border-radius: var(--radius-lg); padding: 4px 8px; font-size: 11px; color: var(--color-text-secondary); }
.macro-ctx-factor strong { font-size: 12px; }
.macro-ctx-factor.factor-up strong { color: var(--color-success); }
.macro-ctx-factor.factor-down strong { color: var(--color-danger); }
.macro-ctx-transmission { display: grid; gap: 4px; }
.macro-ctx-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.macro-ctx-actions { display: flex; }

/* Expanded Portfolio Impact (spec §8) */
.pf-impact-enhanced { display: grid; gap: 12px; margin-bottom: 12px; }
.pf-impact-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.pf-impact-stat { display: grid; gap: 2px; border: 1px solid var(--color-border-subtle); border-radius: var(--radius-lg); padding: 8px 10px; }
.pf-impact-stat span { font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-muted); }
.pf-impact-stat strong { font-size: 13px; color: var(--color-text-primary); }
.pf-impact-exposure { display: grid; gap: 6px; }
.pf-impact-exp-row { display: grid; grid-template-columns: 64px minmax(0, 1fr); gap: 10px; align-items: center; font-size: 11px; color: var(--color-text-secondary); }
.pf-impact-exp-row em { color: var(--color-text-muted); }
.pf-impact-bar { position: relative; display: flex; align-items: center; height: 16px; background: var(--color-surface-depth); border-radius: var(--radius-md); overflow: hidden; }
.pf-impact-bar-fill { height: 100%; }
.pf-impact-bar-fill.pos { background: rgba(34, 197, 94, 0.28); }
.pf-impact-bar-fill.neg { background: rgba(239, 68, 68, 0.28); }
.pf-impact-exp-val { position: absolute; right: 6px; font-size: 11px; color: var(--color-text-secondary); }
.pf-impact-summary { display: grid; gap: 4px; }
.pf-impact-summary p { margin: 0; font-size: 12px; color: var(--color-text-secondary); }
.pf-impact-actions { display: flex; }
.pf-impact-notmapped { display: flex; flex-wrap: wrap; gap: 6px; }
.pf-notmapped-chip { font-size: 10px; color: var(--color-text-muted); border: 1px dashed var(--color-border-subtle); border-radius: var(--radius-full); padding: 1px 8px; }
.pf-impact-wl { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.pf-wl-col { display: grid; gap: 4px; }
.pf-wl-row { display: flex; justify-content: space-between; font-size: 12px; color: var(--color-text-secondary); border-bottom: 1px solid var(--color-border-subtle); padding: 2px 0; }
.pf-wl-row em.pos { color: var(--color-success); font-style: normal; }
.pf-wl-row em.neg { color: var(--color-danger); font-style: normal; }

/* Upcoming Events 2.0 — Global Market Calendar (spec §10–§16) */
.upcoming-events-2 { display: grid; gap: 10px; }
.ue-filter-row { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.ue-filter-row.ue-filter-cat button, .ue-filter-row.ue-filter-imp button, .ue-filter-row.ue-filter-range button {
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-subtle);
  color: var(--color-text-secondary);
  border-radius: var(--radius-full);
  padding: 3px 10px;
  font-size: 11px;
  cursor: pointer;
}
.ue-filter-row button.active { border-color: var(--color-interactive); color: var(--color-text-primary); }
.ue-filter-secondary { gap: 8px; }
.ue-filter-secondary select {
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-subtle);
  color: var(--color-text-secondary);
  border-radius: var(--radius-lg);
  padding: 3px 8px;
  font-size: 11px;
}
.ue-group { display: grid; gap: 0; }
.ue-group-head {
  font-size: 10px; text-transform: uppercase; letter-spacing: 0.05em;
  color: var(--color-text-muted); padding: 6px 0 2px;
  border-top: 1px solid var(--color-border-subtle); margin-top: 4px;
}
.ue-row { grid-template-columns: 90px minmax(0, 1fr) auto auto; align-items: center; gap: 10px; padding: 8px 0; border-bottom: 1px solid var(--color-border-subtle); }
.ue-assets { color: var(--color-data-slate-bright); }
.ue-row-inst { grid-template-columns: 26px minmax(0, 1fr) auto auto; align-items: start; gap: 10px; padding: 10px 0; }
.ue-flag { font-size: 16px; line-height: 1; }
.ue-main { min-width: 0; display: grid; gap: 3px; }
.ue-title-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ue-title-row strong { font-size: 13px; color: var(--color-text-primary); }
.ue-countdown { font-size: 10px; color: var(--color-text-muted); border: 1px solid var(--color-border-subtle); border-radius: var(--radius-full); padding: 1px 6px; }
.ue-sub { font-size: 11px; color: var(--color-text-muted); }
.ue-pfas { display: flex; flex-wrap: wrap; gap: 10px; font-size: 10px; color: var(--color-text-muted); }
.ue-pfas em { color: var(--color-text-secondary); font-style: normal; margin-left: 2px; }
.ue-tx { font-size: 11px; color: var(--color-text-secondary); }

/* Feed Health diagnostics (spec §12) */
.feed-health { margin-top: 10px; border-top: 1px solid var(--color-border-subtle); padding-top: 10px; }
.feed-health-toggle { display: flex; align-items: center; gap: 8px; width: 100%; background: none; border: none; cursor: pointer; color: var(--color-text-secondary); padding: 4px 0; }
.fh-caret { color: var(--color-text-muted); font-size: 10px; }
.fh-title { font-size: 12px; font-weight: 600; }
.fh-summary { font-size: 11px; color: var(--color-text-muted); margin-left: auto; }
.feed-health-body { margin-top: 8px; }
.fh-legend { display: flex; flex-wrap: wrap; gap: 12px; font-size: 10px; color: var(--color-text-muted); margin-bottom: 6px; }
.fh-legend em.fh-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 4px; vertical-align: middle; }
.fh-dot.live { background: var(--color-success); }
.fh-dot.cached { background: var(--color-warning); }
.fh-dot.offline { background: var(--color-text-muted); }
.fh-latency-note { font-style: italic; }
.fh-grid { display: grid; gap: 2px; }
.fh-row { display: grid; grid-template-columns: 1.4fr 0.7fr 0.9fr 1.1fr; gap: 8px; font-size: 11px; color: var(--color-text-secondary); padding: 3px 0; border-bottom: 1px solid var(--color-border-subtle); }
.fh-name { color: var(--color-text-primary); }
.fh-state.live { color: var(--color-success); }
.fh-state.cached { color: var(--color-warning); }
.fh-state.offline { color: var(--color-text-muted); }
.fh-fallback { color: var(--color-text-muted); }

/* Stable Signal Tables (spec §14) */
.stable-signal-tables { display: grid; gap: 16px; }
.sst-block { display: grid; gap: 6px; }
.sst-head { font-size: 12px; font-weight: 600; color: var(--color-text-primary); }
.sst-table { display: grid; gap: 0; border: 1px solid var(--color-border-subtle); border-radius: var(--radius-lg); overflow: hidden; }
.sst-row { display: grid; grid-template-columns: 1.6fr 0.8fr 0.8fr 0.9fr 0.8fr 0.9fr 1fr; gap: 6px; padding: 5px 8px; font-size: 11px; border-bottom: 1px solid var(--color-border-subtle); }
.sst-row:last-child { border-bottom: none; }
.sst-header { background: var(--color-surface-depth); color: var(--color-text-muted); text-transform: uppercase; font-size: 9px; letter-spacing: 0.04em; }
.sst-cell { color: var(--color-text-secondary); }
.sst-indicator { color: var(--color-text-primary); }
.sst-status.live { color: var(--color-success); }
.sst-status.awaiting-feed { color: var(--color-text-muted); }

.market-macro-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 70px 70px 80px;
  gap: 12px;
  align-items: center;
  padding: 7px 0;
  font-size: 12px;
}

.market-macro-row > span {
  color: var(--color-text-secondary);
}

.market-macro-row em {
  font-style: normal;
  font-weight: 800;
  text-align: right;
}

.market-macro-row strong {
  text-align: right;
}

.market-macro-row em.neutral {
  color: var(--color-text-muted);
}

.market-event-row {
  grid-template-columns: 46px minmax(0, 1fr) auto;
  min-height: 48px;
  padding: 7px 0;
}

.market-event-date {
  width: 42px;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  border: var(--color-border-medium);
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary) !important;
  font-size: 11px !important;
  font-weight: 900;
  text-align: center;
}

.market-empty-row {
  padding: 18px 10px;
  color: var(--color-text-muted);
  font-size: 12px;
  text-align: center;
}

body.light-theme-active .market-context-page {
  color: var(--color-text-primary);
  background:
    var(--color-interactive-soft);
}

body.light-theme-active .market-context-detail-header h2,
body.light-theme-active .market-panel-head h3,
body.light-theme-active .market-summary-value strong,
body.light-theme-active .market-asset-cell strong,
body.light-theme-active .market-mover-detail-row strong,
body.light-theme-active .market-signal-row strong,
body.light-theme-active .market-event-row strong,
body.light-theme-active .market-macro-row strong,
body.light-theme-active .market-mover-list h4,
body.light-theme-active .market-impact-total {
  color: var(--color-text-primary);
}

body.light-theme-active .market-context-detail-header p,
body.light-theme-active .market-panel-head p,
body.light-theme-active .market-summary-card p,
body.light-theme-active .market-summary-card > span,
