/* Market Context refinement */
.market-context-page {
  width: 100%;
  padding: 16px 18px;
  gap: 14px;
  color: var(--color-text-secondary);
  background:
    var(--color-surface-elevated);
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
}

.market-context-detail-header {
  grid-template-columns: minmax(320px, 1fr) minmax(580px, 0.96fr);
  gap: 14px;
  align-items: end;
}

.market-context-detail-copy {
  display: grid;
  gap: 8px;
}

.market-context-page-label {
  color: var(--color-text-secondary);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.market-context-title-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 14px;
}

.market-context-detail-header h2 {
  font-size: clamp(30px, 3.2vw, 40px);
  letter-spacing: -0.04em;
}

.market-context-detail-header p {
  max-width: 72ch;
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 14px;
  line-height: 1.5;
}

.market-context-snapshot {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 10px;
}

.market-context-snapshot span,
.market-context-status {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  border: var(--color-border-medium);
  border-radius: var(--radius-full);
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.market-context-status.live {
  border-color: rgba(34, 197, 94, 0.35);
  color: var(--color-data-green-bright);
}

.market-context-status.stale,
.market-context-status.degraded {
  border-color: rgba(245, 158, 11, 0.34);
  color: var(--color-data-amber-bright);
}

.market-context-status.offline,
.market-context-status.idle {
  border-color: rgba(239, 68, 68, 0.34);
  color: var(--color-data-red-bright);
}

.market-context-back {
  min-height: 28px;
  width: max-content;
  margin-bottom: 0;
  border: var(--color-border-medium);
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  padding: 0 10px;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.market-context-toolbar {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.market-context-toolbar label,
.market-context-refresh {
  min-width: 0;
  max-width: none;
  min-height: 48px;
  border-color: var(--color-border-medium);
  background: var(--color-surface-elevated);
  padding: 8px 10px;
}

.market-context-toolbar span {
  color: var(--color-text-secondary);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.market-context-toolbar select {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.market-context-refresh > span {
  color: var(--color-data-secondary);
  font-size: 16px;
}

.market-context-refresh strong {
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.market-context-refresh em {
  color: var(--color-text-muted);
  font-size: 10px;
}

.market-context-panel {
  border-color: var(--color-border-medium);
  background: var(--color-surface-elevated);
  box-shadow: none;
  padding: 12px;
}

.market-summary-variant--quiet {
  display: grid;
  gap: var(--space-4);
  padding: var(--card-padding-standard);
}

.market-summary-variant--quiet .market-panel-head {
  align-items: end;
  padding-bottom: var(--space-3);
  border-bottom: 1px solid var(--color-border-subtle);
}

.market-summary-variant--quiet .market-panel-head p,
.market-summary-variant--quiet .market-summary-card > p {
  display: none;
}

.market-summary-variant--quiet .market-summary-grid {
  gap: var(--space-3);
}

.market-summary-variant--quiet .market-summary-card {
  min-height: 86px;
  padding: var(--space-3);
  background: var(--color-surface-row);
}

.market-summary-variant--quiet .market-regime-card {
  border-color: color-mix(in oklch, var(--semantic-risk-border) 60%, var(--color-border-medium));
  background: color-mix(in oklch, var(--semantic-risk-surface) 60%, var(--color-surface-row));
}

.market-panel-head {
  min-height: 32px;
  margin-bottom: 10px;
}

.market-panel-head h3 {
  font-size: 18px;
  letter-spacing: -0.02em;
}

.market-panel-head p {
  color: var(--color-text-secondary);
  font-size: 12px;
  line-height: 1.45;
}

.market-panel-head button {
  min-height: 30px;
  padding: 0 10px;
  border: var(--color-border-medium);
  border-radius: var(--radius-full);
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.market-summary-grid {
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 10px;
}

.market-summary-card {
  min-height: 98px;
  gap: 8px;
  padding: 11px 12px;
  border-color: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-elevated);
}

.market-summary-card > span {
  color: var(--color-text-secondary);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.market-summary-value {
  display: grid;
  gap: 6px;
  align-items: start;
}

.market-summary-value strong,
.market-regime-value {
  font-size: 24px;
  letter-spacing: -0.03em;
}

.market-summary-card p {
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 12px;
  line-height: 1.4;
}

.market-summary-value em {
  width: max-content;
  min-height: 22px;
  padding: 0 8px;
  border-radius: var(--radius-full);
  border: var(--color-border-medium);
  background: var(--color-surface-elevated);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.market-regime-card {
  gap: 6px;
}

.market-regime-gauge {
  right: 10px;
  bottom: 12px;
}

.market-sparkline-empty {
  width: 100%;
  height: 32px;
  border-radius: var(--radius-full);
  background: var(--color-surface-elevated);
}

.market-context-main-grid,
.market-context-bottom-grid {
  gap: 12px;
}

.market-impact-row {
  padding: 10px 6px;
  border-bottom-color: var(--color-border-medium);
  font-size: 12px;
}

.market-impact-header {
  background: var(--color-surface-elevated);
  color: var(--color-text-muted);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.market-asset-logo {
  border-radius: var(--radius-md);
  font-size: 10px;
}

.market-mover-tabs {
  gap: 10px;
  margin-bottom: 10px;
  border-bottom-color: var(--color-border-medium);
}

.market-mover-tabs button {
  min-height: 30px;
  padding: 0 2px;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  flex: 0 0 auto;
  white-space: nowrap;
}

.market-mover-list,
.market-signal-list,
.market-event-list,
.market-macro-table {
  border-color: var(--color-border-medium);
}

.market-mover-list h4 {
  background: var(--color-surface-elevated);
  color: var(--color-text-muted);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.market-mover-detail-row,
.market-signal-row,
.market-event-row,
.market-macro-row {
  border-bottom-color: var(--color-border-medium);
}

.market-signal-row {
  grid-template-columns: 30px minmax(0, 1fr) auto auto auto;
  min-height: 58px;
  padding: 10px 0;
}

.market-signal-row em {
  color: var(--color-text-secondary);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.market-powered-by,
.market-context-footnote {
  color: var(--color-text-secondary);
  font-size: 11px;
}

.market-catalyst-preview {
  display: grid;
  gap: 12px;
  min-width: 0;
}

.market-catalyst-hero {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  align-items: stretch;
  min-width: 0;
  padding: 12px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-elevated);
}

.market-catalyst-date {
  display: inline-flex;
  flex-direction: column;
  justify-content: center;
  min-width: 76px;
  max-width: 112px;
  padding: 10px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: var(--color-surface-card);
  text-align: center;
}

.market-catalyst-date strong {
  color: var(--color-text-primary);
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
  line-height: 1.2;
}

.market-catalyst-date span,
.market-catalyst-copy span,
.market-catalyst-copy p,
.market-catalyst-next-row span,
.market-catalyst-next-row em,
.market-catalyst-footer {
  color: var(--color-text-secondary);
  font-size: var(--fs-sm);
  line-height: 1.4;
}

.market-catalyst-copy {
  display: grid;
  align-content: center;
  gap: 4px;
  min-width: 0;
}

.market-catalyst-copy strong {
  overflow: hidden;
  color: var(--color-text-primary);
  font-size: var(--fs-lg);
  font-weight: var(--fw-semibold);
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.market-catalyst-copy p {
  margin: 0;
}

.market-catalyst-next-list {
  display: grid;
  gap: 6px;
}

.market-catalyst-next-row {
  appearance: none;
  display: grid;
  grid-template-columns: 82px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  min-height: 42px;
  padding: 9px 10px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: transparent;
  color: inherit;
  cursor: pointer;
  text-align: left;
  transition: background var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard);
}

.market-catalyst-next-row:hover,
.market-catalyst-next-row:focus-visible {
  border-color: var(--color-border-medium);
  background: var(--color-surface-row);
  outline: none;
}

.market-catalyst-next-row strong {
  overflow: hidden;
  color: var(--color-text-primary);
  font-size: var(--fs-sm);
  font-weight: var(--fw-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.market-catalyst-next-row em {
  font-style: normal;
  white-space: nowrap;
}

.market-catalyst-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.market-catalyst-footer button {
  min-height: 34px;
  padding: 0 10px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-row);
  color: var(--color-text-primary);
  cursor: pointer;
  font-size: var(--fs-sm);
}

