  padding: 6px 10px;
  font-size: var(--fs-xs);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease;
  justify-self: start;
}
.tax-workbench-idea-apply:hover { border-color: var(--color-interactive); }
.tax-workbench-idea-apply[aria-pressed="true"] {
  background: var(--color-interactive-soft);
  border-color: var(--color-interactive);
  color: var(--color-text-primary);
}
.tax-workbench-idea-card.is-applied { border-color: var(--color-border-medium); }

.tax-workbench-liability-bar {
  margin-top: 16px;
  padding: 12px;
  background: var(--color-surface-card);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  display: grid;
  gap: 8px;
}
.tax-workbench-liability-row {
  display: grid;
  grid-template-columns: minmax(110px, 0.9fr) minmax(0, 2fr) minmax(80px, 0.5fr);
  gap: 10px;
  align-items: center;
  font-size: var(--fs-sm);
}
.tax-workbench-liability-label {
  color: var(--color-text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tax-workbench-liability-track {
  display: block;
  height: 8px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: var(--radius-md);
  overflow: hidden;
}
.tax-workbench-liability-track i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--color-interactive), var(--color-amber, #f59e0b));
  border-radius: var(--radius-md);
  transition: opacity var(--duration-base) var(--ease-out);
}
.tax-workbench-liability-value {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.tax-workbench-footer summary {
  cursor: pointer;
  font-weight: 700;
}

.tax-workbench-source-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.tax-workbench-source-links a {
  color: var(--tax-accent);
}

.tax-workbench-saved-row {
  display: grid;
  gap: 12px;
}

.tax-workbench-saved-meta {
  justify-content: flex-start;
  flex-wrap: wrap;
}

.tax-workbench-empty {
  padding: 24px 10px;
  text-align: center;
}

.tax-workbench .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Redesign workspace-shell regions (Tax Estimator Phase 2) ──────────
   New panel classes introduced by the folder refactor. They inherit the
   base `.tax-workbench-panel` surface; the rules below give each region
   its institutional density, sticky inspector behaviour, and the
   persistent 3-column IA the spec calls for. Monochrome only. */
.tax-workbench-workspace-root {
  display: grid;
  gap: 18px;
}

/* Decision Inspector: sticky right rail, compact stat grid. */
.tax-workbench-inspector {
  position: sticky;
  top: 18px;
  align-self: start;
  display: grid;
  gap: 14px;
}
.tax-workbench-inspector-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.tax-workbench-inspector-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.tax-workbench-inspector-stat {
  border: 1px solid var(--tax-line);
  border-radius: var(--radius-xl);
  padding: 12px;
  display: grid;
  gap: 6px;
  background: rgba(255, 255, 255, 0.015);
}
.tax-workbench-inspector-stat span {
  font-size: 0.72rem;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--tax-muted);
  font-weight: 700;
}
.tax-workbench-inspector-stat strong {
  font-size: 1.18rem;
  color: var(--tax-text);
  font-variant-numeric: tabular-nums;
}
.tax-workbench-inspector-stat.positive strong { color: var(--tax-positive); }
.tax-workbench-inspector-stat.negative strong { color: var(--tax-negative); }
.tax-workbench-inspector-stat.warning strong { color: var(--tax-warning); }
.tax-workbench-inspector-secondary,
.tax-workbench-inspector-meta {
  display: grid;
  gap: 8px;
}
.tax-workbench-inspector-meta div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: baseline;
  font-size: 0.85rem;
}
.tax-workbench-inspector-meta span { color: var(--tax-muted); }
.tax-workbench-inspector-actions {
  display: grid;
  gap: 10px;
  margin-top: 4px;
}

/* Results workspace: always-visible Calculated Liabilities (P0-1 fix). */
.tax-workbench-results-workspace {
  display: grid;
  gap: 14px;
}
.tax-workbench-result-list {
  display: grid;
  gap: 10px;
}

/* Optimization / Insights block. */
.tax-workbench-insights-block {
  display: grid;
  gap: 12px;
}
.tax-workbench-insights-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 0.82rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--tax-muted);
  font-weight: 700;
}
.tax-workbench-insight-empty {
  color: var(--tax-muted);
  font-size: 0.86rem;
}

/* Compliance: collapsed-by-default, auto-expands on validation fail. */
.tax-workbench-compliance.is-collapsed .tax-workbench-compliance-collapsed-hint {
  margin: 0;
  color: var(--tax-muted);
  font-size: 0.85rem;
  line-height: 1.5;
}
.tax-workbench-compliance.is-open {
  border-color: var(--color-border-medium);
}

@media (max-width: 1024px) {
  .tax-workbench-primary-grid,
  .tax-workbench-secondary-grid {
    grid-template-columns: 1fr;
  }

  .tax-workbench-context-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1024px) {
  .tax-workbench-toolbar,
  .tax-workbench-actions,
  .tax-workbench-progress,
  .tax-workbench-pill-row {
    flex-wrap: wrap;
  }

  .tax-workbench-ledger-head div,
  .tax-workbench-ledger-row,
  .tax-workbench-ledger-foot,
  .tax-workbench-scenario-head div,
  .tax-workbench-scenario-row {
    grid-template-columns: minmax(160px, 1.25fr) repeat(3, minmax(88px, 1fr));
  }

  .tax-workbench-ledger-head div span:nth-child(n + 5),
  .tax-workbench-ledger-row > :nth-child(n + 5),
  .tax-workbench-ledger-foot > :nth-child(n + 5),
  .tax-workbench-scenario-head div span:nth-child(n + 5),
  .tax-workbench-scenario-row > :nth-child(n + 5) {
    display: none;
  }
}

@media (width <= 720px) {
  .tax-workbench-panel {
    padding: 14px;
    border-radius: 18px;
  }

  .tax-workbench-toolbar,
  .tax-workbench-summary-grid,
  .tax-workbench-context-grid {
    grid-template-columns: 1fr;
    display: grid;
  }

  .tax-workbench-summary-grid {
    gap: 10px;
  }

  .tax-workbench-ledger-head,
  .tax-workbench-scenario-head {
    display: none;
  }

  .tax-workbench-ledger-row,
  .tax-workbench-scenario-row,
  .tax-workbench-ledger-foot {
    grid-template-columns: 1fr;
  }

  .tax-workbench-ledger-row {
    gap: 8px;
  }

  .tax-workbench-ledger-foot strong,
  .tax-workbench-ledger-foot span,
  .tax-workbench-scenario-row span,
  .tax-workbench-scenario-row strong {
    justify-self: start;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tax-workbench-btn,
  .tax-workbench-primary-btn,
  .tax-workbench-link-btn,
  .tax-workbench-pill,
  .tax-workbench-jurisdiction-card,
  .tax-workbench-source-links a,
  .tax-workbench-file-input input::file-selector-button {
    transition: none;
  }

  .tax-workbench-primary-btn:hover:not(:disabled) {
    transform: none;
  }
}

