  font-size: 0.76rem;
  font-weight: 900;
}

.analytics-options-focus-read em,
.analytics-commodity-focus-read em {
  color: var(--color-text-secondary);
  font-size: 0.66rem;
  font-style: normal;
  font-weight: 750;
