}

.analytics-options-route-row {
  grid-template-columns: minmax(120px, 0.85fr) minmax(0, 1.2fr) minmax(72px, auto) minmax(92px, auto);
}

.analytics-options-greeks-panel,
.analytics-options-source-panel,
.analytics-options-route-panel {
  display: grid;
  align-content: start;
}

.analytics-options-greek-grid {
