    linear-gradient(135deg, rgba(23, 14, 7, 0.98), rgba(7, 10, 16, 0.98));
}

.analytics-curve-panel {
  min-height: 455px;
}

.analytics-curve-stage {
  display: grid;
  grid-template-columns: repeat(6, minmax(64px, 1fr));
  gap: 12px;
  align-items: end;
  min-height: 230px;
  margin: 12px;
  padding: 24px 14px 12px;
  border: 1px solid var(--analytics-line);
  border-radius: var(--radius-md);
  background:
    var(--color-surface-elevated);
}

.analytics-curve-node {
  display: grid;
  justify-items: center;
  align-items: end;
  gap: 7px;
  min-height: 185px;
}

.analytics-curve-node div {
  width: 100%;
  min-height: 22px;
  border: 1px solid rgba(255, 184, 107, 0.42);
  border-radius: 4px 4px 2px 2px;
  background: linear-gradient(180deg, rgba(255, 184, 107, 0.84), rgba(98, 215, 247, 0.28));
  box-shadow: 0 0 24px rgba(255, 184, 107, 0.08);
}

.analytics-curve-node strong {
  color: var(--color-text-primary);
  font-size: 0.72rem;
}

.analytics-curve-node span {
  color: var(--color-text-muted);
  font-family: "Geist Mono", "SFMono-Regular", Consolas, monospace;
  font-size: 0.66rem;
}

.analytics-commodity-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 0 12px 12px;
}

.analytics-contract-stack {
  display: grid;
  padding: 13px 14px;
}

.analytics-contract-stack > span {
  margin-bottom: 10px;
}

.analytics-contract-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 10px;
  align-items: center;
  min-height: 52px;
  border-top: var(--color-border-medium);
}

.analytics-contract-row b {
  grid-row: span 2;
  justify-self: end;
  color: var(--color-text-secondary);
  font-family: "Geist Mono", "SFMono-Regular", Consolas, monospace;
  font-size: 0.84rem;
}

.analytics-commodities-terminal {
  gap: 8px;
  padding: 0;
  color: var(--color-text-secondary);
  font-family: var(--font-mono);
}

.analytics-commodities-terminal .analytics-desk-panel {
  border-color: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--analytics-panel);
}

.analytics-commodity-commandbar {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) minmax(320px, auto);
  gap: 16px;
  align-items: start;
  padding: 4px 0 10px;
  border-bottom: var(--color-border-medium);
}

.analytics-commodity-titleblock {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.analytics-commodity-titleblock span,
.analytics-commodity-panel-head span,
.analytics-commodity-regime span,
.analytics-commodity-ticker span,
.analytics-stress-title span,
.analytics-commodity-footer span,
.analytics-commodity-controls span {
  color: var(--color-data-primary);
  font-size: 0.62rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  line-height: 1.1;
  text-transform: uppercase;
  overflow-wrap: anywhere;
}

.analytics-commodity-titleblock h2 {
  margin: 0;
  color: var(--color-text-primary);
  font-family: var(--font-sans);
  font-size: clamp(1.45rem, 2.2vw, 2.05rem);
  font-weight: 850;
  letter-spacing: 0;
  line-height: 1;
  overflow-wrap: anywhere;
}

.analytics-commodity-titleblock p {
  margin: 0;
  color: var(--color-text-secondary);
  font-family: var(--font-sans);
  font-size: 0.76rem;
  line-height: 1.2;
  max-width: 46rem;
  overflow-wrap: anywhere;
}

.analytics-commodity-controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.analytics-commodity-controls label,
.analytics-commodity-controls button {
  min-width: 118px;
  min-height: 42px;
  padding: 7px 11px;
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  font: inherit;
}

.analytics-commodity-controls label {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.analytics-commodity-controls strong {
  color: var(--color-text-primary);
  font-size: 0.68rem;
  font-weight: 850;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.analytics-commodity-controls button {
  cursor: pointer;
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.analytics-commodity-tape {
  display: grid;
  grid-template-columns:
    minmax(190px, 1.15fr)
    minmax(150px, 0.78fr)
    repeat(7, minmax(138px, 1fr));
  min-height: 118px;
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  overflow-x: auto;
  overflow-y: hidden;
  background: var(--color-surface-elevated);
}

.analytics-commodity-regime,
.analytics-commodity-ticker {
  display: grid;
  align-content: center;
  gap: 5px;
  min-width: 0;
  padding: 12px 14px;
  border-right: var(--color-border-medium);
}

.analytics-commodity-regime strong {
  color: var(--color-data-amber-bright);
  max-width: 12ch;
  font-size: 0.96rem;
  font-weight: 950;
  letter-spacing: 0.04em;
  line-height: 1.05;
  text-transform: uppercase;
  overflow-wrap: anywhere;
}

.analytics-commodity-regime-secondary strong {
  color: var(--color-text-primary);
}

.analytics-commodity-regime em,
.analytics-commodity-ticker em,
.analytics-commodity-panel-head em,
.analytics-commodity-footer em {
  color: var(--color-text-secondary);
  font-size: 0.62rem;
  font-style: normal;
  font-weight: 750;
  min-width: 0;
  overflow-wrap: anywhere;
}

.analytics-commodity-ticker {
  grid-template-columns: minmax(64px, 1fr) 54px;
  grid-template-rows: auto auto minmax(16px, auto);
  align-content: center;
  gap: 4px 10px;
  min-width: 138px;
  padding: 11px 12px;
  appearance: none;
  border-top: 0;
  border-bottom: 0;
  border-left: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  text-align: left;
  transition: background 160ms ease, box-shadow 160ms ease;
}

.analytics-commodity-ticker:hover,
.analytics-commodity-ticker.active,
.analytics-commodity-table tbody tr:hover,
.analytics-commodity-table tbody tr.active {
  background: var(--color-interactive-soft);
  box-shadow: rgba(255, 255, 255, 0.08);
}

.analytics-commodity-ticker strong {
  color: var(--color-text-primary);
  font-size: 0.86rem;
  font-weight: 950;
  line-height: 1;
  white-space: nowrap;
}

.analytics-commodity-ticker span,
.analytics-commodity-ticker em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.analytics-commodity-ticker .analytics-mini-spark,
.analytics-commodity-ticker .analytics-mini-curve,
.analytics-commodity-ticker .analytics-curve-placeholder {
  grid-row: 1 / span 3;
  grid-column: 2;
  justify-self: end;
  align-self: center;
  width: 54px;
  pointer-events: none;
}

.analytics-commodity-table tbody tr {
  cursor: pointer;
}

.analytics-curve-sparkline {
  display: block;
  height: 34px;
  overflow: visible;
}

.analytics-curve-placeholder {
  display: grid;
  min-height: 34px;
  place-items: center;
  color: var(--color-text-secondary);
  font-size: 0.48rem;
  font-weight: 850;
  line-height: 1.05;
  text-align: center;
  text-transform: uppercase;
  overflow: hidden;
  text-overflow: ellipsis;
  word-break: break-word;
}

.analytics-mini-curve {
  width: 54px;
}

.analytics-row-curve,
.analytics-curve-placeholder.analytics-row-curve {
  width: 72px;
}

.analytics-curve-sparkline line {
  stroke: var(--color-text-secondary);
  stroke-width: 1;
}

.analytics-curve-sparkline polyline {
  fill: none;
  stroke: #43d36a;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2.4;
}

.analytics-curve-sparkline circle {
  fill: #43d36a;
  stroke: var(--color-text-secondary);
  stroke-width: 1;
}

.analytics-curve-sparkline.negative polyline {
  stroke: #ff4e45;
}

.analytics-curve-sparkline.negative circle {
  fill: #ff4e45;
}

.analytics-mini-spark,
.analytics-row-spark {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 34px;
}

.analytics-mini-spark i,
.analytics-row-spark i {
  display: block;
  width: 5px;
  flex: 0 0 5px;
  border-radius: 999px 999px 0 0;
  background: #46cf6c;
}

.analytics-commodity-ticker strong.negative,
.analytics-commodity-table .negative,
.analytics-stress-row b.negative,
.analytics-inventory-row b.negative,
.analytics-shock-row b.negative,
.analytics-row-spark.negative i,
.analytics-curve-row .negative {
  color: #ff4e45;
}

.analytics-row-spark.negative i,
.analytics-commodity-ticker .negative + em + .analytics-mini-spark i {
  background: #ff4e45;
}

.analytics-commodity-ticker strong.positive,
.analytics-commodity-table .positive,
.analytics-stress-row b.positive,
.analytics-inventory-row b.positive,
.analytics-shock-row b.positive,
.analytics-curve-row .positive {
  color: #43d36a;
}

.analytics-commodity-focus-read {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-top: -1px;
  margin-bottom: 10px;
  border: 1px solid var(--color-border-medium);
  border-top: 0;
  border-radius: 0 0 3px 3px;
  background: var(--color-surface-panel);
}

.analytics-commodity-focus-read > div {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding-right: 12px;
  border-right: 1px solid var(--color-border-subtle);
}

.analytics-commodity-focus-read > div:last-child {
  border-right: 0;
}

.analytics-commodity-table .warning,
.analytics-stress-row b.warning,
.analytics-inventory-row b.warning,
.analytics-shock-row b.warning {
  color: var(--color-data-amber-bright);
}

.analytics-commodity-terminal-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(340px, 420px);
  gap: 8px;
  align-items: stretch;
}

.analytics-commodity-panel-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  min-height: 42px;
  padding: 9px 12px;
  border-bottom: var(--color-border-medium);
}

.analytics-commodity-panel-head > div {
  min-width: 0;
}

.analytics-commodity-panel-head.compact {
  min-height: 40px;
}

.analytics-commodity-panel-head strong {
  display: block;
  margin-top: 4px;
  color: var(--color-text-secondary);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 850;
  letter-spacing: 0.04em;
  line-height: 1.18;
  text-transform: uppercase;
  overflow-wrap: anywhere;
}

.analytics-commodity-table-wrap {
  overflow-x: auto;
}

.analytics-commodity-table {
  width: 100%;
  min-width: 1080px;
  border-collapse: collapse;
}

.analytics-commodity-table th,
.analytics-commodity-table td {
  padding: 8px 10px;
  border-right: var(--color-border-medium);
  border-bottom: var(--color-border-medium);
  color: var(--color-text-secondary);
  font-size: 0.68rem;
  line-height: 1.15;
  text-align: right;
  white-space: nowrap;
}

.analytics-commodity-table th {
  color: var(--color-text-secondary);
  font-size: 0.58rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.analytics-commodity-table th:first-child,
.analytics-commodity-table td:first-child,
.analytics-commodity-table th:nth-child(2),
.analytics-commodity-table td:nth-child(2) {
  text-align: left;
}

.analytics-commodity-table td:first-child {
  min-width: 150px;
}

.analytics-commodity-table td:first-child strong {
  display: block;
  color: var(--color-text-primary);
  font-size: 0.76rem;
}

.analytics-commodity-table td:first-child span {
  display: block;
  margin-top: 3px;
  color: var(--color-text-secondary);
  font-size: 0.58rem;
}

.analytics-commodity-table b {
  font-weight: 850;
}

.analytics-stress-section {
  border-bottom: var(--color-border-medium);
}

.analytics-stress-title,
.analytics-stress-row,
.analytics-inventory-row,
.analytics-shock-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 10px;
  align-items: center;
  min-height: 32px;
  padding: 6px 12px;
  border-bottom: var(--color-border-medium);
}

.analytics-stress-title em {
  grid-column: 3;
  color: var(--color-data-primary);
  font-size: 0.58rem;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.analytics-stress-row strong,
.analytics-inventory-row span,
.analytics-shock-row strong {
  overflow: hidden;
  color: var(--color-text-secondary);
  font-size: 0.68rem;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.analytics-stress-row b,
.analytics-stress-row span,
.analytics-inventory-row strong,
.analytics-inventory-row b,
.analytics-inventory-row em,
.analytics-shock-row span,
.analytics-shock-row em,
.analytics-shock-row b {
  color: var(--color-text-secondary);
  font-size: 0.66rem;
  font-style: normal;
  font-weight: 800;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.analytics-stress-row span {
  display: inline-flex;
  justify-content: flex-end;
  gap: 8px;
}

.analytics-stress-row a,
.analytics-stress-row em {
  color: var(--color-data-primary);
  font-size: 0.6rem;
  font-style: normal;
  font-weight: 900;
  text-decoration: none;
  text-transform: uppercase;
  white-space: nowrap;
}

.analytics-stress-row a:hover {
  text-decoration: underline;
}

.analytics-commodity-bottom-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(260px, 1fr));
  gap: 8px;
}

.analytics-curve-comparison {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  min-height: 260px;
  padding: 10px 12px 12px;
}

.analytics-curve-scale {
  display: grid;
  grid-template-columns: minmax(58px, 0.8fr) repeat(5, minmax(48px, 1fr));
  gap: 8px;
  align-items: center;
  padding: 0 0 8px;
  border-bottom: var(--color-border-medium);
}

.analytics-curve-scale span {
  color: var(--color-text-secondary);
  font-size: 0.56rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-align: right;
  text-transform: uppercase;
}

.analytics-curve-scale span:first-child {
  text-align: left;
}

.analytics-curve-rows {
  display: grid;
  align-content: start;
  gap: 0;
}

.analytics-curve-row {
  display: grid;
  grid-template-columns: minmax(58px, 0.8fr) repeat(5, minmax(48px, 1fr));
  gap: 8px;
  align-items: center;
  min-height: 32px;
  border-bottom: var(--color-border-medium);
  color: var(--color-text-secondary);
  font-size: 0.66rem;
}

.analytics-curve-row strong {
  color: var(--color-text-primary);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.05em;
}

.analytics-curve-row span,
.analytics-curve-row b {
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 0.66rem;
  font-weight: 850;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.analytics-curve-row em {
  grid-column: 1 / -1;
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  height: 14px;
  color: var(--color-text-secondary);
  font-size: 0.56rem;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.analytics-curve-row em::before {
  content: "";
  position: absolute;
  left: 0;
  right: 96px;
  top: 6px;
  height: 2px;
  border-radius: var(--radius-full);
  background: var(--color-surface-elevated);
}

.analytics-curve-row em i {
  display: block;
  height: 2px;
  border-radius: var(--radius-full);
  background: currentColor;
}

.analytics-inventory-row {
  grid-template-columns: minmax(0, 1fr) auto auto auto;
}

.analytics-shock-row {
  grid-template-columns: minmax(0, 1fr) minmax(82px, auto) minmax(92px, auto) auto;
}

.analytics-commodity-footer {
  display: flex;
  align-items: center;
  gap: 18px;
  min-height: 44px;
  padding: 0 12px;
  border-top: var(--color-border-medium);
  color: var(--color-text-secondary);
}

.analytics-commodity-footer strong {
  color: var(--color-text-secondary);
  font-size: 0.64rem;
  font-weight: 800;
}

.analytics-commodity-footer em {
  margin-left: auto;
}

.analytics-commodity-alert-row {
  display: grid;
  grid-template-columns: minmax(88px, auto) minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  min-height: 44px;
  padding: 10px 12px;
  border-bottom: var(--color-border-medium);
}

.analytics-commodity-alert-row:last-child {
  border-bottom: 0;
}

.analytics-commodity-alert-row strong {
  color: var(--color-text-primary);
  font-size: 0.72rem;
  font-weight: 850;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.analytics-commodity-alert-row span {
  color: var(--color-text-secondary);
  font-size: 0.68rem;
}

.analytics-commodity-alert-row em {
  color: var(--color-text-secondary);
  font-size: 0.64rem;
  font-style: normal;
  font-weight: 800;
}

@media (max-width: 1180px) {
  .analytics-research-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .analytics-research-main,
  .analytics-research-bottom,
  .analytics-factor-main,
  .analytics-macro-grid,
  .analytics-commodity-layout,
  .analytics-commodity-terminal-grid,
  .analytics-macro-topline,
