/* Tax Estimator Reference Command Desk */
.tax-workbench {
  max-width: none;
}

.tax-workbench-shell {
  gap: 12px;
}

.tax-workbench-command-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  min-height: 78px;
  padding: 0 0 14px;
  border-bottom: var(--color-border-medium);
}

.tax-workbench-title-block {
  display: grid;
  gap: 4px;
  padding-left: 14px;
  border-left: var(--color-border-medium);
}

.tax-workbench-title-block span,
.tax-workbench-sync-state span,
.tax-workbench-scenario-select span,
.tax-workbench-mini-title span {
  color: var(--color-text-secondary);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  line-height: 1.2;
  text-transform: uppercase;
}

.tax-workbench-title-block h2 {
  margin: 0;
  color: var(--color-text-primary);
  font-size: clamp(1.35rem, 2vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.055em;
  line-height: 0.95;
}

.tax-workbench-title-block p {
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 0.76rem;
}

.tax-workbench-command-actions {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.tax-workbench-sync-state,
.tax-workbench-scenario-select {
  display: grid;
  gap: 5px;
  min-height: 44px;
  padding: 0 14px;
  border-left: var(--color-border-medium);
}

.tax-workbench-sync-state strong {
  color: var(--color-text-primary);
  font-family: var(--font-mono);
  font-size: 0.76rem;
  font-weight: 800;
}

.tax-workbench-sync-state strong::before {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-right: 7px;
  border-radius: var(--radius-full);
  background: #43cd90;
  box-shadow: 0 0 12px rgba(67, 205, 144, 0.7);
  vertical-align: middle;
}

.tax-workbench-scenario-select select {
  min-width: 145px;
  min-height: 30px;
  border: var(--color-border-medium);
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.03);
  color: var(--color-text-secondary);
  font-size: 0.72rem;
  font-weight: 800;
}

.tax-workbench-primary-grid {
  grid-template-columns: 280px minmax(0, 1fr) 270px;
  gap: 10px;
  align-items: stretch;
}

.tax-workbench-panel {
  border-radius: var(--radius-md);
  background:
    var(--color-surface-elevated);
  border-color: var(--color-border-medium);
}

.tax-workbench .dense-panel-header {
  min-height: 42px;
  padding-bottom: 9px;
  border-bottom: var(--color-border-medium);
}

.tax-workbench .dense-panel-copy h3 {
  color: var(--color-data-primary);
}

.tax-workbench-toolbar-ledger {
  grid-template-columns: minmax(0, 1fr) 88px;
  align-items: end;
}

.tax-workbench-jurisdiction-status {
  display: grid;
  gap: 8px;
  margin: 10px 0 12px;
}

.tax-workbench-mini-title {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
}

.tax-workbench-mini-title button {
  border: 0;
  background: transparent;
  color: var(--color-data-primary);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
}

.tax-workbench-selected-inline {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tax-workbench-selected-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 28px;
  padding: 0 8px;
  border: 1px solid var(--analytics-line);
  border-radius: var(--radius-full);
  background: var(--color-surface-elevated);
  color: var(--tax-text);
  cursor: pointer;
}

.tax-workbench-selected-chip.base {
  border-color: var(--color-border-medium);
  background: var(--color-interactive-soft);
}

.tax-workbench-selected-chip strong {
  overflow: hidden;
  max-width: 120px;
  color: var(--tax-text);
  font-size: 0.68rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tax-workbench-selected-chip em {
  color: var(--color-text-secondary);
  font-size: 0.56rem;
  font-style: normal;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.tax-workbench-region-filter {
  margin-top: 0;
  padding-top: 10px;
  border-top: var(--color-border-medium);
}

.tax-workbench-jurisdiction-list {
  gap: 6px;
  max-height: 470px;
  margin-top: 12px;
  overflow-y: auto;
  padding-right: 2px;
}

.tax-workbench-jurisdiction-card {
  min-height: 42px;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  border-color: var(--color-border-subtle);
  background: var(--color-surface-card);
}

.tax-workbench-jurisdiction-card.selected {
  border-color: var(--color-border-medium);
  background: rgba(255, 255, 255, 0.03);
  box-shadow: rgba(255, 255, 255, 0.08);
}

.tax-workbench-jurisdiction-main {
  gap: 8px;
}

.tax-workbench-jurisdiction-main strong {
  font-size: 0.79rem;
}

.tax-workbench-jurisdiction-copy p {
  font-size: 0.61rem;
  letter-spacing: 0.02em;
}

.tax-workbench-jurisdiction-main em {
  display: inline-flex;
  align-items: center;
  min-height: 18px;
  padding: 0 6px;
  border-color: var(--color-border-medium);
  color: var(--tax-accent);
  font-size: 0.54rem;
}

.tax-workbench-jurisdiction-card input {
  width: 14px;
  height: 14px;
}

.tax-workbench-jurisdiction-foot {
  margin-top: 10px;
  color: var(--tax-muted);
  font-size: 0.58rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.72;
}

@media (max-width: 960px) {
  .tax-workbench-toolbar-ledger {
    grid-template-columns: 1fr;
  }

  .tax-workbench-jurisdiction-list {
    max-height: none;
  }
}

.tax-workbench-ledger {
  padding: 12px 0 0;
  overflow: hidden;
}

.tax-workbench-ledger > .dense-panel-header {
  margin: 0 14px;
}

.tax-workbench-ledger-stack {
  overflow-x: auto;
}

.tax-workbench-ledger-section-head {
  padding: 10px 14px;
  background: var(--analytics-panel);
}

.tax-workbench-ledger-section-head h4 {
  margin: 0;
  color: var(--color-text-secondary);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.tax-workbench-ledger-head div,
.tax-workbench-ledger-row,
.tax-workbench-ledger-foot {
  grid-template-columns:
    minmax(170px, 1.35fr)
    minmax(70px, 0.58fr)
    minmax(74px, 0.58fr)
    minmax(96px, 0.78fr)
    minmax(96px, 0.78fr)
    minmax(96px, 0.78fr)
    minmax(86px, 0.65fr)
    minmax(86px, 0.65fr)
    minmax(86px, 0.65fr);
