  top: 0;
  z-index: 2;
  background: var(--color-surface-elevated);
}

.tax-workbench-ledger-row {
  min-height: 44px;
  padding: 8px 14px;
}

.tax-workbench-ledger-foot {
  padding: 11px 14px;
  background: rgba(255, 255, 255, 0.018);
}

.tax-workbench-ledger-input input,
.tax-workbench-ledger-text,
.tax-workbench-ledger-foot-item strong {
  color: var(--color-text-secondary);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 760;
  line-height: 1.2;
  text-align: right;
}

.tax-workbench-ledger-text {
  display: block;
  color: var(--color-text-secondary);
}

.tax-workbench-fee-fx-cell {
  grid-template-columns: 1fr;
}

.tax-workbench-fee-fx-cell .tax-workbench-ledger-input + .tax-workbench-ledger-input {
  margin-top: 3px;
}

.tax-workbench-summary {
  padding: 12px 14px;
}

.tax-workbench-summary-stack {
  border-top: 0;
}

.tax-workbench-summary-stat {
  padding: 13px 0;
}

.tax-workbench-summary-stat strong {
  font-size: 1.08rem;
}

.tax-workbench-summary-stat:first-child strong,
.tax-workbench-summary-stat:nth-child(4) strong {
  font-size: 1.45rem;
}

.tax-workbench-scenarios {
  padding: 12px 14px;
}

.tax-workbench-scenarios .dense-panel-header {
  border-bottom: var(--color-border-medium);
}

.tax-workbench-scenario-table {
  overflow-x: auto;
}

.tax-workbench-scenario-head div,
.tax-workbench-scenario-row {
  min-width: 1080px;
}

@media (max-width: 1024px) {
  .tax-workbench-command-header,
  .tax-workbench-primary-grid {
    grid-template-columns: 1fr;
  }

  .tax-workbench-command-actions {
    justify-content: flex-start;
  }
}

@media (max-width: 760px) {
  .tax-workbench-command-actions,
  .tax-workbench-sync-state,
  .tax-workbench-scenario-select,
  .tax-workbench-command-actions .tax-workbench-btn {
    width: 100%;
  }

  .tax-workbench-sync-state,
  .tax-workbench-scenario-select {
    border-left: 0;
    padding: 0;
  }
}

/* Connect Account Modal Overhaul */
.connect-account-shell {
  display: grid;
  grid-template-columns: minmax(280px, 0.94fr) minmax(0, 1.06fr);
  min-height: 620px;
}

.connect-account-trust-panel {
  display: grid;
  align-content: start;
  gap: 18px;
  padding: 28px;
  border-right: 1px solid var(--color-border-medium);
  background:
    radial-gradient(circle at top left, var(--color-surface-depth), transparent 32%),
    linear-gradient(180deg, var(--color-surface-card), var(--color-surface-card));
}

.connect-account-kicker,
.connect-account-trust-card span,
.connect-account-security-list strong,
.connect-account-header span,
.connect-account-status-strip span {
  color: var(--color-data-primary);
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.16em;
  line-height: 1.2;
  text-transform: uppercase;
}

.connect-account-trust-panel h2 {
  margin: 0;
  color: var(--color-text-primary);
  font-size: clamp(1.9rem, 2.2vw, 2.55rem);
  font-weight: 850;
  letter-spacing: -0.05em;
  line-height: 0.95;
}

.connect-account-trust-panel > p {
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 0.92rem;
  line-height: 1.65;
}

.connect-account-trust-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.connect-account-trust-card,
.connect-account-status-strip > div {
  display: grid;
  gap: 7px;
  min-height: 110px;
  padding: 14px 16px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-overlay);
}

.connect-account-trust-card strong,
.connect-account-status-strip strong,
.connect-account-security-list span,
.connect-account-footnote,
.connect-account-feedback {
  color: var(--color-text-secondary);
  font-size: 0.8rem;
  line-height: 1.55;
}

.connect-account-trust-card strong,
.connect-account-status-strip strong,
.connect-account-header strong {
  color: var(--color-text-primary);
  font-size: 0.92rem;
  font-weight: 780;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.connect-account-security-list {
  display: grid;
  gap: 12px;
}

.connect-account-security-list > div {
  display: grid;
  gap: 6px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--color-border-medium);
}

.connect-account-security-list > div:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.connect-account-provider-preview {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.connect-account-provider-preview span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 30px;
  padding: 0 10px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-overlay);
  color: var(--color-text-secondary);
  font-size: 0.72rem;
  font-weight: 700;
}

.connect-account-provider-preview span.can-sync {
  border-color: rgba(34, 197, 94, 0.24);
}

.connect-account-provider-preview span.save-only {
  border-color: var(--color-border-medium);
}

.connect-account-provider-preview em {
  color: var(--color-data-primary);
  font-size: 0.58rem;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.connect-account-form-panel {
  display: grid;
  grid-template-rows: auto 1fr;
  min-width: 0;
}

.connect-account-header {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 16px;
  padding: 24px 24px 18px;
  border-bottom: 1px solid var(--color-border-medium);
}

.connect-account-header > div {
  display: grid;
  gap: 6px;
}

.connect-account-status-strip {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.connect-account-type-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.connect-account-type-btn {
  min-height: 42px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-overlay);
  color: var(--color-text-secondary);
  font-size: 0.73rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: border-color 140ms ease, background-color 140ms ease, color 140ms ease;
}

.connect-account-type-btn:hover,
.connect-account-type-btn:focus-visible {
  border-color: var(--color-interactive);
  color: var(--color-text-primary);
}

.connect-account-type-btn.active {
  border-color: var(--color-selected);
  background: var(--color-selected);
  color: var(--color-data-primary);
}



.connect-account-footnote {
  margin: 0;
  color: var(--color-text-muted);
}

.connect-account-feedback {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--color-data-red-bright);
  border-radius: var(--radius-md);
  background: var(--color-data-red-bright);
}

.connect-account-feedback.error {
  color: var(--color-data-red-bright);
}

.connect-account-success-panel {
  display: grid;
  align-content: center;
  gap: 14px;
  min-height: 100%;
  padding: 18px 0;
}

.connect-account-success-panel > span,
.connect-account-success-grid span {
  color: var(--color-data-primary);
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.16em;
  line-height: 1.2;
  text-transform: uppercase;
}

.connect-account-success-panel h3 {
  margin: 0;
  color: var(--color-text-primary);
  font-size: clamp(1.9rem, 3vw, 2.7rem);
  font-weight: 850;
  letter-spacing: -0.05em;
  line-height: 0.95;
}

.connect-account-success-panel p {
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 0.92rem;
  line-height: 1.6;
}

.connect-account-success-mark {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-full);
  background: var(--color-surface-overlay);
  color: var(--color-data-primary);
  font-size: 1.45rem;
  font-weight: 900;
}

.connect-account-success-mark.synced {
  border-color: rgba(34, 197, 94, 0.34);
  background: rgba(34, 197, 94, 0.1);
  color: var(--color-data-green-bright);
}

.connect-account-success-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(2, minmax(70px, 0.8fr));
  gap: 10px;
}

.connect-account-success-grid > div {
  display: grid;
  gap: 7px;
  min-height: 86px;
  padding: 13px 14px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-overlay);
}

.connect-account-success-grid strong {
  color: var(--color-text-primary);
  font-size: 0.92rem;
  font-weight: 780;
  line-height: 1.2;
}

.connect-account-actions {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 4px;
}

/* Action buttons now match the Portfolio "Connect Account" CTA
   (portfolio-command-primary-cta) so the overlay feels part of the same
   surface and stays theme-aware. `subtle` keeps them from stretching full
   width inside the form. */
.connect-account-primary,
.connect-account-secondary {
  min-height: 42px;
}
.connect-account-actions .portfolio-command-primary-cta {
  min-height: 42px;
  font-size: 0.84rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  padding: 0 18px;
}
.connect-account-actions .portfolio-command-primary-cta.subtle {
  min-width: 138px;
}
.connect-account-actions .portfolio-command-primary-cta.primary-emphasis {
  min-width: 190px;
}
.connect-account-actions .portfolio-command-primary-cta:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Field labels (Provider / Account label / Wallet address) read as labels,
   not values — so they're bolded while the status-strip value is not. */
.connect-account-body .field-label-strong {
  color: var(--color-text-primary);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

/* "Verified watch-only address" / sync-help should NOT be bold — it's a
   status value, not a heading. Scoped so other <strong>s are untouched. */
.connect-account-status-strip .status-value {
  color: var(--color-text-primary);
  font-size: 0.92rem;
  font-weight: 480;
  letter-spacing: -0.01em;
  line-height: 1.3;
}

.connect-account-window.is-onboarding .close-btn {
  opacity: 0.76;
}

.connect-empty-state {
