body.light-theme-active .tax-workbench-selected-chip em {
  color: var(--color-interactive);
}

body.light-theme-active .tax-workbench-primary-btn:hover:not(:disabled),
body.light-theme-active .tax-workbench-btn:hover:not(:disabled) {
  filter: brightness(0.98);
}

body.light-theme-active .home-signal-modal {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.97));
  border-color: var(--color-border-medium);
  box-shadow: 0 28px 80px rgba(15, 23, 42, 0.18);
}

body.light-theme-active .home-signal-modal-head h2,
body.light-theme-active .home-signal-modal p strong {
  color: var(--color-text-primary);
}

body.light-theme-active .home-signal-modal p {
  color: var(--color-text-secondary);
}

body.light-theme-active .journal-review-mode-banner {
  background: rgba(37, 99, 235, 0.06);
  border-color: rgba(37, 99, 235, 0.18);
  color: var(--color-text-secondary);
}

@media (max-width: 900px) {
  .journal-debrief-action-cluster,
  .home-signal-modal-actions {
    width: 100%;
  }

  .journal-debrief-action-cluster > * {
    flex: 1 1 160px;
  }
}

/* Portfolio Command Center */
.portfolio-command-page {
  max-width: none;
  gap: 14px;
}

.portfolio-command-header,
.portfolio-command-summary,
.portfolio-command-attention,
.portfolio-command-rebalance,
.portfolio-command-analysis,
.portfolio-command-prediction-strip,
.portfolio-command-summary-card,
.portfolio-command-attention-card,
.portfolio-command-drift-card,
.portfolio-command-impact-card,
.portfolio-command-side-card,
.portfolio-command-tab-panel,
.portfolio-v2-panel,
.portfolio-v2-stat-card {
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  background: var(--workspace-surface);
  box-shadow: none;
}

.portfolio-command-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  padding: 18px 20px;
}

.portfolio-command-titleblock {
  display: grid;
  gap: 6px;
}

.portfolio-command-eyebrow,
.portfolio-command-section-head span,
.portfolio-command-column-label,
.portfolio-command-summary-card span,
.portfolio-command-impact-list span,
.portfolio-command-readiness span,
.portfolio-command-side-list span,
.portfolio-command-activity-copy span,
.portfolio-command-market-card span {
  color: var(--color-text-muted);
  font-family: var(--font-brand);
  font-size: var(--workspace-label-size);
  font-weight: var(--fw-semibold);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.portfolio-command-titleblock h1 {
  color: var(--color-text-primary);
  font-family: var(--font-brand);
  font-size: var(--workspace-title-size);
  font-weight: var(--fw-semibold);
  letter-spacing: -0.02em;
  line-height: 1.1;
  white-space: normal;
}

.portfolio-command-titleblock p,
.portfolio-command-panel-head p,
.portfolio-command-empty p,
.portfolio-command-summary-card em,
.portfolio-command-attention-card em,
.portfolio-command-tab-panel > p {
  margin: 0;
  color: var(--color-text-secondary);
  font-size: 0.83rem;
  line-height: 1.45;
}

.portfolio-command-header-actions,
.portfolio-command-inline-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  justify-content: flex-end;
}

.portfolio-command-header-actions .portfolio-v2-link {
  margin-top: 0;
}

.portfolio-brokerage-banner,
.portfolio-connection-strip {
  display: grid;
  gap: 10px;
  padding: 14px 16px;
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  background: var(--workspace-surface);
}

.portfolio-connection-strip {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
}

.portfolio-connection-strip > div,
.portfolio-brokerage-banner-head {
  display: grid;
  gap: 4px;
}

/* Unified multi-source portfolio: source-coverage strip (monochrome, token-only) */
.unified-source-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  padding: 8px 10px;
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  background: var(--workspace-surface);
  font-size: 12px;
  color: var(--color-text-secondary);
}
.unified-source-label {
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 10px;
}
.unified-source-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.unified-source-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border: 1px solid var(--workspace-border);
  border-radius: 999px;
  background: var(--workspace-surface-strong, var(--workspace-surface));
  color: var(--color-text-primary);
}
.unified-source-chip em {
  font-style: normal;
  color: var(--color-text-muted);
}
.unified-source-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-text-secondary);
}
.unified-source-partial {
  color: var(--color-text-muted);
  font-style: italic;
}
.unified-source-manual-excluded {
  color: var(--color-text-muted);
  font-size: 11px;
  opacity: 0.8;
}
.unified-source-sync {
  margin-left: auto;
  padding: 4px 10px;
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  background: transparent;
  color: var(--color-text-primary);
  cursor: pointer;
}
.unified-source-sync:disabled {
  opacity: 0.5;
  cursor: default;
}

/* Portfolio drill-down (unified multi-source breakdown) — monochrome tokens only */
.portfolio-drilldown {
  margin-top: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.pd-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.pd-card {
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  background: var(--workspace-surface, var(--color-bg-secondary));
  padding: 12px 14px;
}
.pd-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}
.pd-card-head h4 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--color-text-primary);
}
.pd-sync {
  padding: 4px 10px;
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  background: transparent;
  color: var(--color-text-primary);
  cursor: pointer;
  font-size: 12px;
}
.pd-sync:disabled { opacity: 0.5; cursor: default; }
.pd-source-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.pd-source-row {
  display: grid;
  grid-template-columns: 12px 1fr auto auto;
  align-items: center;
  gap: 8px;
  font-size: 13px;
}
.pd-source-row.pd-excluded { opacity: 0.6; }
.pd-source-name { color: var(--color-text-primary); }
.pd-source-meta { color: var(--color-text-muted); font-size: 12px; }
.pd-source-val { color: var(--color-text-primary); font-variant-numeric: tabular-nums; }
.pd-status { width: 8px; height: 8px; border-radius: 50%; background: var(--color-text-muted); }
.pd-status-synced, .pd-status-partial { background: var(--color-text-primary); }
.pd-status-error { background: var(--color-text-primary); outline: 2px solid var(--workspace-border); }
.pd-status-stale { background: transparent; border: 1px solid var(--color-text-muted); }
.pd-status-manual { background: transparent; border: 1px dashed var(--color-text-muted); }
.pd-note { color: var(--color-text-muted); font-size: 12px; margin: 8px 0 0; }
.pd-ok { color: var(--color-text-secondary); }
.pd-warn { border: 1px solid var(--workspace-border); border-radius: var(--workspace-radius); padding: 8px 10px; margin-bottom: 8px; }
.pd-warn-tag { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-secondary); }
.pd-dup-list { margin: 6px 0 0; padding-left: 16px; font-size: 12px; color: var(--color-text-primary); }
.pd-dup-note { color: var(--color-text-muted); }
.pd-warn-body { margin: 4px 0 0; font-size: 12px; color: var(--color-text-primary); }
.pd-fx { margin-top: 8px; display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.pd-fx-label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-muted); }
.pd-fx-rate { font-size: 12px; color: var(--color-text-secondary); font-variant-numeric: tabular-nums; }
.pd-snapshots { margin-top: 2px; }
.pd-immutable { font-size: 11px; color: var(--color-text-muted); font-style: italic; }
.pd-snap-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.pd-snap-row { display: grid; grid-template-columns: auto 1fr auto; gap: 10px; font-size: 12px; align-items: baseline; }
.pd-snap-date { color: var(--color-text-muted); font-variant-numeric: tabular-nums; }
.pd-snap-val { color: var(--color-text-primary); font-variant-numeric: tabular-nums; text-align: right; }
.pd-snap-meta { color: var(--color-text-muted); }

@media (max-width: 720px) {
  .pd-grid { grid-template-columns: 1fr; }
}

/* Rollout shadow-compare panel (monochrome tokens) */
.pd-rollout { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; padding: 2px 8px; border-radius: var(--workspace-radius); border: 1px solid var(--workspace-border); }
.pd-rollout-promote { color: var(--color-text-secondary); }
.pd-rollout-hold { color: var(--color-text-primary); }
.pd-shadow-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 8px; }
.pd-shadow-grid > div { display: flex; flex-direction: column; gap: 2px; }
.pd-shadow-k { font-size: 11px; color: var(--color-text-muted); text-transform: uppercase; letter-spacing: 0.04em; }
.pd-shadow-v { font-size: 15px; color: var(--color-text-primary); font-variant-numeric: tabular-nums; }

/* Semantic position filter + table */
.pd-metrics { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; margin-bottom: 12px; }
.pd-metrics > div { display: flex; flex-direction: column; gap: 2px; }
.pd-filters { display: flex; flex-wrap: wrap; gap: 14px; margin-bottom: 12px; }
.pd-filter-group { display: flex; flex-direction: column; gap: 4px; }
.pd-filter-label { font-size: 11px; color: var(--color-text-muted); text-transform: uppercase; letter-spacing: 0.04em; }
.pd-filter-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.pd-filter-chip {
  padding: 3px 8px;
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  background: transparent;
  color: var(--color-text-muted);
  font-size: 12px;
  cursor: pointer;
  text-transform: capitalize;
}
.pd-filter-chip:hover { color: var(--color-text-primary); border-color: var(--color-text-secondary); }
.pd-filter-chip.active { color: var(--color-text-primary); border-color: var(--color-text-primary); background: var(--workspace-border); }
.pd-pos-table-wrap { overflow: auto; max-height: 420px; }
.pd-pos-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.pd-pos-table th,
.pd-pos-table td { padding: 6px 8px; text-align: left; border-bottom: 1px solid var(--workspace-border); }
.pd-pos-table th { color: var(--color-text-muted); font-weight: 500; text-transform: uppercase; letter-spacing: 0.03em; font-size: 11px; }
.pd-pos-table td { color: var(--color-text-primary); }
.pd-pos-table .numeric { text-align: right; }
.pd-pos-table td strong { display: block; color: var(--color-text-primary); }
.pd-pos-sub { display: block; color: var(--color-text-muted); font-size: 11px; }
.pd-lev-badge {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 5px;
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  font-size: 10px;
  color: var(--color-text-muted);
  vertical-align: middle;
}
.pd-liq-sub {
  display: block;
  color: var(--color-text-muted);
  font-size: 10px;
  margin-top: 2px;
}
.pd-freshness {
  font-size: 11px;
  color: var(--color-text-muted);
  font-variant-numeric: tabular-nums;
}
.pd-pos-table td:last-child { white-space: nowrap; }
.pd-pnl-pos { color: var(--color-text-primary); font-variant-numeric: tabular-nums; }
.pd-pnl-neg { color: var(--color-text-primary); font-variant-numeric: tabular-nums; opacity: 0.7; }
.pd-pnl-na { color: var(--color-text-muted); font-variant-numeric: tabular-nums; }

/* Portfolio Activity (provider-neutral) — monochrome tokens only */
.pa-activity { display: flex; flex-direction: column; gap: 14px; }
.pa-filters { display: flex; flex-wrap: wrap; gap: 10px; align-items: flex-end; }
.pa-filter { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: var(--color-text-muted); }
.pa-filter select, .pa-filter input {
  padding: 6px 8px; border: 1px solid var(--workspace-border); border-radius: var(--workspace-radius);
  background: transparent; color: var(--color-text-primary); font-size: 13px; min-width: 120px;
}
.pa-reconcile { border: 1px solid var(--workspace-border); border-radius: var(--workspace-radius); padding: 10px 12px; display: flex; flex-direction: column; gap: 8px; }
.pa-reconcile h4 { margin: 0; font-size: 13px; font-weight: 600; color: var(--color-text-primary); }
.pa-warn { font-size: 12px; color: var(--color-text-primary); }
.pa-warn-tag { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-secondary); margin-right: 6px; }
.pa-warn-note { color: var(--color-text-muted); }
.pa-list-wrap { border: 1px solid var(--workspace-border); border-radius: var(--workspace-radius); overflow: auto; max-height: 340px; }
.pa-list-head { padding: 8px 12px; font-size: 12px; color: var(--color-text-muted); border-bottom: 1px solid var(--workspace-border); }
.pa-empty { padding: 18px 12px; color: var(--color-text-muted); font-size: 13px; }
.pa-list { list-style: none; margin: 0; padding: 0; }
.pa-row { display: grid; grid-template-columns: 84px 1fr 70px 1.4fr auto 110px; gap: 8px; align-items: center; padding: 8px 12px; font-size: 13px; border-bottom: 1px solid var(--workspace-border); }
.pa-row:last-child { border-bottom: none; }
.pa-row-type { color: var(--color-text-secondary); text-transform: capitalize; }
.pa-row-symbol { color: var(--color-text-primary); font-weight: 600; }
.pa-row-qty { color: var(--color-text-muted); font-variant-numeric: tabular-nums; }
.pa-row-meta { color: var(--color-text-muted); font-size: 12px; }
.pa-row-val { color: var(--color-text-primary); font-variant-numeric: tabular-nums; text-align: right; }
.pa-row-date { color: var(--color-text-muted); font-size: 12px; text-align: right; }
@media (max-width: 720px) {
  .pa-row { grid-template-columns: 70px 1fr 60px; }
  .pa-row-meta, .pa-row-val, .pa-row-date { display: none; }
}

/* Connected Accounts: per-account sync health + first-sync import result — monochrome tokens */
.connection-sync-state { font-size: 11px; color: var(--color-text-muted); }
.connection-sync-ok { color: var(--color-text-secondary); }
.connection-sync-error { color: var(--color-text-primary); }
.connection-sync-stale { color: var(--color-text-muted); font-style: italic; }
.connection-import-result { border: 1px solid var(--workspace-border); border-radius: var(--workspace-radius); padding: 10px 12px; }
.connection-import-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.connection-import-grid > div { display: flex; flex-direction: column; gap: 2px; }
.connection-import-k { font-size: 11px; color: var(--color-text-muted); text-transform: uppercase; letter-spacing: 0.04em; }
.connection-import-v { font-size: 15px; color: var(--color-text-primary); font-variant-numeric: tabular-nums; }
.connection-import-notes { margin-top: 8px; display: flex; flex-direction: column; gap: 3px; }
.connection-import-note { font-size: 12px; color: var(--color-text-muted); }
.connection-import-warn { color: var(--color-text-primary); }
@media (max-width: 640px) {
  .connection-import-grid { grid-template-columns: repeat(2, 1fr); }
}

.portfolio-connection-strip strong,
.portfolio-brokerage-banner-title {
  color: var(--color-text-primary);
  font-size: 0.9rem;
  font-weight: 820;
}

.portfolio-connection-strip span,
.portfolio-brokerage-banner-meta,
.portfolio-brokerage-duplicate {
  color: var(--color-text-secondary);
  font-size: 0.8rem;
  line-height: 1.45;
}

.portfolio-brokerage-banner-head {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
}

.portfolio-brokerage-banner-value {
  color: var(--color-text-primary);
  font-size: 1rem;
  font-weight: 820;
  font-variant-numeric: tabular-nums;
}

.portfolio-brokerage-banner-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.portfolio-brokerage-duplicate {
  padding-top: 8px;
  border-top: 1px solid var(--color-border-medium);
}

.portfolio-command-inline-select {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.portfolio-command-inline-select span {
  flex: 0 0 auto;
}

.portfolio-command-section-head,
.portfolio-command-panel-head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
}

.portfolio-command-section-head {
  padding: 16px 18px 0;
}

.portfolio-command-section-head em,
.portfolio-command-panel-head h3,
.portfolio-command-attention-card strong,
.portfolio-command-summary-card strong,
.portfolio-command-side-list strong,
.portfolio-command-activity-values strong,
.portfolio-command-market-card strong,
.portfolio-command-empty h3,
.portfolio-command-change-row strong {
  margin: 0;
  color: var(--color-text-primary);
}

.portfolio-command-section-head em {
  color: var(--color-text-secondary);
  font-size: 0.7rem;
  font-style: normal;
  font-weight: 700;
}

.portfolio-command-summary {
  padding-bottom: 18px;
}

.portfolio-command-summary-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0;
  padding: 10px 18px 0;
}

.portfolio-command-summary-card {
  display: grid;
  gap: 10px;
  min-height: 88px;
  padding: 12px 16px;
  border: 0;
  border-inline-start: 1px solid var(--workspace-border);
  border-radius: 0;
  background: transparent;
}

.portfolio-command-summary-card:first-child {
  border-inline-start: 0;
}

.portfolio-command-summary-card strong {
  font-size: clamp(19px, 1.7vw, 26px);
  font-weight: var(--fw-semibold);
  letter-spacing: -0.02em;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--color-text-primary);
}

.portfolio-command-summary-card.positive strong,
.portfolio-command-impact-list strong.positive,
.portfolio-command-side-list strong.positive,
.portfolio-command-stat-rail strong.positive,
.portfolio-command-activity-values strong.positive {
  color: var(--color-data-green-bright);
}

.portfolio-command-summary-card.negative strong,
.portfolio-command-impact-list strong.negative,
.portfolio-command-side-list strong.negative,
.portfolio-command-stat-rail strong.negative,
.portfolio-command-activity-values strong.negative {
  color: var(--color-data-red-bright);
}

.portfolio-command-attention {
  padding-bottom: 12px;
}

.portfolio-command-attention-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  padding: 10px 18px 0;
}

.portfolio-command-attention-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
  min-height: 74px;
  padding: 10px 12px;
  border: 1px solid var(--workspace-border);
  border-radius: var(--workspace-radius);
  background: var(--workspace-surface);
  text-align: left;
  transition: background var(--duration-fast) var(--ease-standard),
    border-color var(--duration-fast) var(--ease-standard);
}

.portfolio-command-attention-card > div {
  display: grid;
  gap: 0;
  min-width: 0;
}

.portfolio-command-attention-card:hover,
.portfolio-command-attention-card:focus-visible {
  border-color: var(--color-border-strong);
  background: var(--workspace-surface-strong);
  transform: none;
}

.portfolio-command-attention-card:focus-visible,
.home-exec-btn:focus-visible,
.portfolio-command-primary-cta:focus-visible,
.portfolio-command-tab:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.portfolio-command-attention-card > div > span:not(.portfolio-command-attention-head) {
  display: block;
  margin-bottom: 6px;
}

.portfolio-command-attention-head {
  display: flex !important;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.portfolio-command-attention-head .status-indicator {
  margin-left: 2px;
  line-height: 1;
}

.portfolio-command-attention-head .status-indicator__icon {
  width: 16px;
  height: 16px;
  border: 1px solid color-mix(in srgb, currentColor 38%, transparent);
  font-size: 10px;
}

.portfolio-command-attention-card strong {
  display: block;
  margin-bottom: 3px;
  font-family: var(--font-brand);
  font-size: 1.05rem;
  font-weight: var(--fw-semibold);
  letter-spacing: -0.01em;
  color: var(--color-text-primary);
}

.portfolio-command-attention-card b {
  color: var(--color-interactive);
  font-size: 0.78rem;
  font-weight: 800;
  align-self: center;
  white-space: nowrap;
}

.portfolio-command-attention-card em {
  display: block;
  max-width: 32ch;
  overflow: hidden;
  font-size: 0.76rem;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.portfolio-command-attention-card.risk strong,
.portfolio-command-column-label.risk,
.portfolio-command-drift-legend i.risk {
  color: #fda4af;
}

.portfolio-command-attention-card.warning strong,
.portfolio-command-drift-legend i.info {
  color: var(--color-data-primary);
}

.portfolio-command-attention-card.accent strong,
.portfolio-command-column-label.positive,
.portfolio-command-drift-legend i.neutral {
  color: var(--color-data-primary);
}

.portfolio-command-rebalance {
  padding: 18px;
}

.portfolio-command-rebalance-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(300px, 0.85fr);
  gap: 12px;
  margin-top: 14px;
}

/* Keep the chart controls in the card's top-right corner instead of letting
   their wrapped rows determine the height of the section header. */
.portfolio-command-rebalance-inner > .portfolio-command-section-head {
  position: relative;
  min-height: 72px;
}

.portfolio-command-rebalance-inner > .portfolio-command-section-head > .portfolio-command-inline-actions {
  position: absolute;
  top: 14px;
  right: 18px;
  max-width: none;
  flex-wrap: nowrap;
  white-space: nowrap;
}

.portfolio-command-rebalance-inner > .portfolio-command-section-head > .portfolio-command-inline-actions .portfolio-v2-link {
  margin-top: 0;
}

.portfolio-command-drift-card,
.portfolio-command-impact-card,
.portfolio-command-side-card,
.portfolio-command-tab-panel {
  border: var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-elevated);
}

.portfolio-command-panel-head {
  padding: 15px 16px 12px;
  border-bottom: var(--color-border-medium);
}

.portfolio-command-panel-head h3 {
  font-size: 0.95rem;
  font-weight: 820;
}

.portfolio-command-drift-visual {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
  padding: 16px 12px 12px;
}

.portfolio-command-drift-visual .apexcharts-canvas,
.portfolio-command-drift-visual svg {
  width: 100% !important;
  max-width: none !important;
}

.portfolio-command-drift-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  justify-content: center;
  color: var(--color-text-secondary);
  font-size: 0.68rem;
}

.portfolio-command-drift-legend span {
  display: inline-flex;
  gap: 7px;
  align-items: center;
}

.portfolio-command-drift-legend i {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  background: currentColor;
}

/* Trim/Add is part of the recommendation, not a competing third card. */
.portfolio-command-change-summary {
  border-top: var(--color-border-medium);
}

.portfolio-command-change-summary .portfolio-command-panel-head {
  border-bottom: 0;
  padding-bottom: 6px;
}

.portfolio-command-change-summary .portfolio-command-change-grid {
  padding-top: 10px;
}

.portfolio-command-change-empty {
  margin: 0;
  padding: 0 16px 16px;
  color: var(--color-text-secondary);
  font-size: 0.78rem;
  line-height: 1.45;
}

.portfolio-command-stat-rail {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  padding: 0 14px 14px;
}

.portfolio-command-stat-rail div {
  display: grid;
  gap: 5px;
  padding: 10px 12px;
  border: var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-elevated);
}

.portfolio-command-stat-rail span {
  color: var(--color-text-secondary);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.portfolio-command-stat-rail strong {
  font-size: 0.84rem;
  font-weight: 800;
}

.portfolio-command-change-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 16px;
}

.portfolio-command-column-label {
  display: block;
  margin-bottom: 10px;
}

.portfolio-command-change-list {
  display: grid;
  gap: 8px;
}

.portfolio-command-change-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 10px;
  align-items: center;
  padding: 11px 12px;
  border: var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  font-size: 0.74rem;
  text-align: left;
}

.portfolio-command-change-row:hover,
.portfolio-command-change-row:focus-visible {
  border-color: var(--color-interactive);
  background: var(--color-surface-elevated);
}

.portfolio-command-change-row em,
.portfolio-command-change-row b {
  color: var(--color-text-secondary);
  font-style: normal;
  font-weight: 700;
}

.portfolio-command-impact-card {
  display: grid;
}

.portfolio-command-impact-list,
.portfolio-command-side-list {
  display: grid;
  gap: 0;
  padding: 12px 16px 0;
}

.portfolio-command-impact-list div,
.portfolio-command-side-list div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  min-height: 42px;
  border-bottom: var(--color-border-medium);
}

.portfolio-command-impact-list strong,
.portfolio-command-side-list strong {
  font-size: 0.82rem;
  font-weight: 780;
}

.portfolio-command-readiness {
  padding: 14px 16px 4px;
}

.portfolio-command-readiness ul {
  display: grid;
  gap: 8px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}

.portfolio-command-readiness li {
  color: var(--color-text-secondary);
  font-size: 0.76rem;
}

.portfolio-command-readiness li.positive {
  color: var(--color-data-green-bright);
}

.portfolio-command-readiness li.negative {
  color: var(--color-data-red-bright);
}

/* §7 — classified instrument exposure is shown beside rebalance readiness so
   investors can see the allocation basis before opening a trade workflow. */
.portfolio-command-exposure-buckets {
  margin: 14px 16px 0;
  border-top: 1px solid var(--color-border-medium);
  padding-top: 12px;
}

.portfolio-command-exposure-buckets__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.portfolio-command-exposure-buckets__head span {
  color: var(--color-text-muted);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.portfolio-command-exposure-buckets__head em {
  color: var(--color-text-secondary);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-style: normal;
  font-variant-numeric: tabular-nums;
}

.portfolio-command-exposure-buckets table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.72rem;
}

.portfolio-command-exposure-buckets th,
.portfolio-command-exposure-buckets td {
  padding: 6px 0;
  border-bottom: 1px solid var(--color-border-subtle);
  color: var(--color-text-secondary);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.portfolio-command-exposure-buckets thead th {
  color: var(--color-text-muted);
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.portfolio-command-exposure-buckets th:first-child,
.portfolio-command-exposure-buckets tbody th {
  color: var(--color-text-secondary);
  text-align: left;
}

.portfolio-command-exposure-buckets tbody tr:last-child th,
.portfolio-command-exposure-buckets tbody tr:last-child td {
  border-bottom: 0;
}

.portfolio-command-exposure-buckets__note,
.portfolio-command-rebalance-blocked {
  margin: 12px 16px 0;
  color: var(--color-text-secondary);
  font-size: 0.74rem;
  line-height: 1.45;
}

.portfolio-command-exposure-buckets__note {
  margin: 8px 0 0;
}

.portfolio-command-rebalance-blocked {
  display: grid;
  gap: 4px;
  border-left: 2px solid var(--color-border-strong);
  padding-left: 10px;
}

.portfolio-command-rebalance-blocked strong {
  color: var(--color-text-primary);
  font-size: 0.72rem;
  font-weight: 700;
}

.portfolio-command-primary-cta:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.portfolio-command-primary-cta,
.portfolio-command-tab button,
.portfolio-command-tab,
.portfolio-command-market-card,
.portfolio-command-summary-card,
.portfolio-command-side-card,
.portfolio-command-tab-panel {
  font-family: inherit;
}

.portfolio-command-primary-cta {
  width: calc(100% - 32px);
  margin: 12px 16px 16px;
  min-height: 44px;
  border: var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-elevated);
  color: var(--color-text-primary);
  font-size: 0.84rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.portfolio-command-primary-cta:hover,
.portfolio-command-primary-cta:focus-visible {
  border-color: var(--color-border-medium);
  background: var(--color-surface-elevated);
}

.portfolio-command-primary-cta.subtle {
  width: auto;
  margin: 0;
  min-width: 150px;
}

.portfolio-command-analysis {
  padding: 18px;
}

.portfolio-command-tabs {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  gap: 8px;
  padding-bottom: 14px;
  position: sticky;
  top: 0;
  z-index: 5;
  background: var(--color-bg-base);
  /* Hide the scrollbar on the tab strip — keeps the layout clean while remaining scrollable. */
  scrollbar-width: thin;
}
.portfolio-command-tabs::-webkit-scrollbar { height: 4px; }
.portfolio-command-tabs::-webkit-scrollbar-thumb { background: var(--color-border-medium); border-radius: var(--radius-sm); }

.portfolio-command-tab {
  display: inline-flex;
  gap: 8px;
  align-items: center;
  min-height: 38px;
  padding: 0 14px;
  border: var(--color-border-medium);
  border-radius: 8px;
  background: transparent;
  color: var(--color-text-secondary);
  font-size: 0.78rem;
  font-weight: 760;
  flex: 0 0 auto;
  white-space: nowrap;
  transition: background-color 140ms ease, border-color 140ms ease, color 140ms ease;
}

.portfolio-command-tab:active {
  transform: none;
}

.portfolio-command-tab:hover,
.portfolio-command-tab:focus-visible,
.portfolio-command-tab:active {
  transform: none !important;
  box-shadow: none;
  animation: none !important;
}

section.portfolio-command-analysis .portfolio-command-tabs .portfolio-command-tab,
section.portfolio-command-analysis .portfolio-command-tabs .portfolio-command-tab:active,
section.portfolio-command-analysis .portfolio-command-tabs .portfolio-command-tab:focus,
section.portfolio-command-analysis .portfolio-command-tabs .portfolio-command-tab:focus-visible {
  transform: none !important;
  animation: none !important;
}

.portfolio-command-tab small,
.portfolio-command-beta-pill {
  display: inline-flex;
  align-items: center;
  min-height: 20px;
  padding: 0 7px;
  border-radius: var(--radius-full);
  background: var(--color-interactive-soft);
  color: var(--color-interactive);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.portfolio-command-tab.active {
  border-color: var(--color-interactive);
  background: var(--color-surface-elevated);
  color: var(--color-text-primary);
  box-shadow: none;
}

.portfolio-command-analysis-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(300px, 0.72fr);
  gap: 12px;
}

.portfolio-command-analysis-grid.no-rail {
  grid-template-columns: minmax(0, 1fr);
}

.portfolio-command-analysis-main,
.portfolio-command-analysis-rail {
  display: grid;
  gap: 12px;
}

.portfolio-command-tab-panel {
  padding: 0;
  overflow: hidden;
}

.portfolio-command-tab-panel > p,
.portfolio-command-tab-panel > .portfolio-command-card-grid,
.portfolio-command-tab-panel > .portfolio-command-table-wrap,
.portfolio-command-tab-panel > .portfolio-command-market-grid,
.portfolio-command-tab-panel > .portfolio-command-empty,
.portfolio-command-tab-panel > .portfolio-command-side-list,
.portfolio-command-tab-panel > .portfolio-command-activity-list {
  padding: 16px;
}

.portfolio-command-card-grid {
  display: grid;
  gap: 10px;
}

.portfolio-command-card-grid.three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.portfolio-command-card-grid.four {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.portfolio-command-mini-card,
.portfolio-command-market-card {
  display: grid;
  gap: 8px;
  min-height: 104px;
  padding: 14px;
  border: var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-elevated);
}

.portfolio-command-mini-card strong,
.portfolio-command-market-card strong {
  font-size: 1rem;
  font-weight: 800;
}

.portfolio-command-mini-card em,
.portfolio-command-market-card em {
  color: var(--color-text-secondary);
  font-size: 0.73rem;
  font-style: normal;
}

.portfolio-command-table-wrap {
  overflow: auto;
  max-height: 520px;
  position: relative;
}

.portfolio-command-table {
  width: 100%;
  min-width: 860px;
  border-collapse: collapse;
}

.portfolio-command-table th,
.portfolio-command-table td {
  padding: 11px 12px;
  border-bottom: var(--color-border-medium);
  color: var(--color-text-secondary);
  font-size: 0.75rem;
  text-align: left;
  vertical-align: middle;
}

.portfolio-command-table th {
  color: var(--color-text-secondary);
  font-size: 0.62rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.portfolio-command-table td strong {
  color: var(--color-text-primary);
  font-size: 0.8rem;
}

.portfolio-command-table td span {
  display: block;
  margin-top: 4px;
  color: var(--color-text-secondary);
  font-size: 0.66rem;
}

.portfolio-history-toolbar {
  display: grid;
  grid-template-columns: minmax(150px, 0.8fr) minmax(130px, 0.65fr) minmax(120px, 0.55fr);
  gap: 10px;
  padding: 0 16px 16px;
}

.portfolio-history-toolbar select,
.portfolio-history-toolbar input {
  width: 100%;
  min-height: 40px;
  border: var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: rgba(5, 5, 5, 0.72);
  color: var(--color-text-secondary);
  font-size: 0.78rem;
  font-weight: 720;
  padding: 0 12px;
}

.portfolio-history-table tbody tr {
  cursor: pointer;
}

.portfolio-history-table tbody tr:hover {
  background: rgba(255, 255, 255, 0.035);
}

.portfolio-history-table .positive {
  color: #7dd3a8;
}

.portfolio-history-table .negative {
  color: var(--color-data-red-bright);
}

.portfolio-history-pings {
  border-top: var(--color-border-medium);
}

.portfolio-execution-detail-modal {
  max-width: 760px;
}

.portfolio-execution-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.portfolio-execution-detail-grid > div {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 12px;
  border: var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: rgba(5, 5, 5, 0.58);
}

.portfolio-execution-detail-grid span {
  color: var(--color-text-secondary);
  font-size: 0.64rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.portfolio-execution-detail-grid strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--color-text-secondary);
  font-size: 0.86rem;
}

.portfolio-execution-detail-grid strong.positive {
  color: #7dd3a8;
}

.portfolio-execution-detail-grid strong.negative {
  color: var(--color-data-red-bright);
}

.portfolio-command-allocation-cell {
  display: grid;
  gap: 7px;
}

.portfolio-command-allocation-bar {
  position: relative;
  height: 5px;
  border-radius: var(--radius-full);
  background: var(--color-surface-elevated);
  overflow: hidden;
}

.portfolio-command-allocation-bar i {
  position: absolute;
  inset: 0 auto 0 0;
  border-radius: var(--radius-full);
  background: var(--color-interactive-soft);
}

.portfolio-command-table .action-link,
.portfolio-command-side-card .portfolio-v2-link {
  color: var(--color-interactive);
  font-size: 0.74rem;
  font-weight: 750;
}

.portfolio-command-side-card .portfolio-v2-link {
  margin: 12px 16px 16px;
}

.portfolio-command-activity-list {
  display: grid;
  gap: 8px;
  padding: 16px;
}

.portfolio-command-activity-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border: var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-elevated);
}

.portfolio-command-activity-copy,
.portfolio-command-activity-values {
  display: grid;
  gap: 4px;
}

.portfolio-command-activity-copy strong {
  color: var(--color-text-primary);
  font-size: 0.78rem;
}

.portfolio-command-activity-values {
  text-align: right;
}

.portfolio-command-prediction-strip {
  padding: 0 0 18px;
}

.portfolio-command-prediction-strip .portfolio-command-panel-head {
  padding: 16px 18px 12px;
}

.portfolio-command-prediction-strip .portfolio-command-card-grid,
.portfolio-command-prediction-strip .portfolio-command-empty {
  padding: 0 18px;
}

.portfolio-command-empty {
  display: grid;
  gap: 6px;
  min-height: 120px;
  align-content: center;
  justify-items: start;
}

.portfolio-command-empty.compact {
  min-height: 84px;
}

@media (max-width: 1280px) {
  .portfolio-command-summary-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .portfolio-command-summary-card:nth-child(3n + 1) {
    border-inline-start: 0;
  }

  .portfolio-command-card-grid.four,
  .portfolio-command-stat-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1180px) {
  .portfolio-command-header,
  .portfolio-command-rebalance-grid,
  .portfolio-command-analysis-grid {
    grid-template-columns: 1fr;
  }

  .portfolio-command-header-actions {
    justify-content: flex-start;
  }

  .portfolio-connection-strip,
  .portfolio-brokerage-banner-head {
    grid-template-columns: 1fr;
  }

  .portfolio-command-attention-grid,
  .portfolio-command-card-grid.three {
    grid-template-columns: 1fr;
  }

  .portfolio-command-change-grid {
    grid-template-columns: 1fr;
  }
}

/* ── Workspace Scope selector (account-level context; coexists with asset-class filter) ── */
.workspace-scope {
  position: relative;
  display: inline-flex;
}

.workspace-scope-trigger {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 140px;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--color-text-secondary);
  background: var(--color-surface-card);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-lg);
  padding: 0 12px;
  height: 30px;
  cursor: pointer;
}

.workspace-scope-trigger:hover {
  border-color: var(--color-border-strong, var(--color-border-subtle));
  color: var(--color-text-primary);
}

.workspace-scope-trigger-label {
  flex: 1;
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.workspace-scope-caret {
  font-size: 0.7em;
  opacity: 0.7;
}

.workspace-scope-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  z-index: 1200;
  min-width: 240px;
  max-height: 360px;
  overflow-y: auto;
  padding: 6px;
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--color-shadow, 0 12px 32px rgba(0, 0, 0, 0.45));
}

.workspace-scope-group + .workspace-scope-option,
.workspace-scope-group {
  margin-top: 2px;
}

.workspace-scope-group-label {
  padding: 6px 8px 2px;
  font-size: 0.62rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-muted, var(--color-text-secondary));
}

.workspace-scope-option {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 7px 8px;
  border: none;
  background: transparent;
  border-radius: var(--radius-lg);
  cursor: pointer;
  text-align: left;
  color: var(--color-text-primary);
  font-size: 0.82rem;
}

.workspace-scope-option:hover {
  background: var(--color-surface-card);
}

.workspace-scope-option.is-selected {
  background: var(--color-surface-card);
}

.workspace-scope-option-label {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.workspace-scope-option-meta {
  font-size: 0.7rem;
  color: var(--color-text-secondary);
}

.workspace-scope-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex: none;
  background: var(--color-text-secondary);
}

.workspace-scope-dot--success {
  background: var(--color-data-positive, var(--color-success));
}

.workspace-scope-dot--sync_unavailable,
.workspace-scope-dot--unknown {
  background: transparent;
  border: 1px solid var(--color-text-secondary);
}

.workspace-scope-empty {
  padding: 10px 8px;
  font-size: 0.78rem;
  color: var(--color-text-secondary);
}

@media (max-width: 760px) {
  .workspace-scope-trigger {
    min-width: 120px;
  }
}

@media (max-width: 760px) {
  .portfolio-command-page {
    gap: 12px;
  }

  .portfolio-command-header,
  .portfolio-command-summary-grid,
  .portfolio-command-attention-grid,
  .portfolio-command-rebalance,
  .portfolio-command-analysis,
  .portfolio-command-prediction-strip {
    padding-left: 14px;
    padding-right: 14px;
  }

  .portfolio-command-summary-grid,
  .portfolio-command-card-grid.four,
  .portfolio-command-stat-rail {
    grid-template-columns: 1fr;
  }

  .portfolio-command-summary-card {
    min-height: auto;
    border-inline-start: 0;
    border-block-end: 1px solid var(--workspace-border);
  }

  .portfolio-command-summary-card:last-child {
    border-block-end: 0;
  }

  .portfolio-command-section-head,
  .portfolio-command-panel-head,
  .portfolio-command-inline-actions {
    align-items: flex-start;
  }

  .portfolio-command-rebalance-inner > .portfolio-command-section-head {
    min-height: 0;
  }

  .portfolio-command-rebalance-inner > .portfolio-command-section-head > .portfolio-command-inline-actions {
    position: static;
    max-width: none;
  }

  .portfolio-command-tabs {
    overflow-x: auto;
    flex-wrap: nowrap;
    padding-bottom: 10px;
    scrollbar-width: none;
  }

  .portfolio-command-table {
    min-width: 720px;
  }

  .portfolio-history-toolbar,
  .portfolio-execution-detail-grid {
    grid-template-columns: 1fr;
  }

.portfolio-command-attention-card,
.portfolio-command-activity-row {
  grid-template-columns: 1fr;
}
}

.indicator-metric-header,
.indicator-metric-value-cell {
  display: grid;
  gap: 2px;
}

.indicator-metric-header small,
.indicator-metric-value-cell small {
  color: var(--color-text-muted);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.indicator-metric-value-cell span {
  display: block;
}

.tax-workbench-ledger {
  overflow: visible;
}

.tax-workbench-ledger-stack {
  overflow-x: auto;
  overflow-y: visible;
  padding-bottom: 6px;
  scrollbar-gutter: stable both-edges;
}

.tax-workbench-ledger-table {
  overflow-x: auto;
  overflow-y: hidden;
}

.tax-workbench-ledger-head > div,
.tax-workbench-ledger-row,
.tax-workbench-ledger-foot {
  width: max-content;
  min-width: 100%;
}

.tax-workbench-accountant-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
  padding: 14px 16px;
  border: var(--color-border-medium);
  border-radius: var(--radius-xl);
  background:
    var(--color-surface-elevated);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.tax-workbench-accountant-banner > div {
  display: grid;
  gap: 4px;
}

.tax-workbench-accountant-banner strong {
  color: var(--color-text-secondary);
  font-size: 0.96rem;
  letter-spacing: 0.01em;
}

.tax-workbench-accountant-banner span {
  color: var(--color-text-secondary);
  font-size: 0.78rem;
  line-height: 1.5;
}

.tax-workbench-accountant-banner-meta {
  min-width: 132px;
  align-items: flex-end;
  text-align: right;
}

.view-container.home-dashboard.home-exec .home-exec-severity.warn {
  background: var(--color-warning-soft);
  border-color: color-mix(in srgb, var(--color-warning) 42%, transparent);
  color: var(--color-warning);
}

.view-container.home-dashboard.home-exec .home-exec-severity.info {
  background: var(--color-interactive-soft);
  border-color: var(--color-border-medium);
  color: var(--color-text-secondary);
}

.view-container.home-dashboard.home-exec .home-exec-severity.risk {
  background: var(--color-danger-soft);
  border-color: color-mix(in srgb, var(--color-danger) 34%, transparent);
  color: var(--color-danger);
}

/* Light theme: soft tints are too faint for dark status text — use stronger
   fills so WARNING/RISK badges stay AA-readable on white. */
body.light-theme-active .view-container.home-dashboard.home-exec .home-exec-severity.warn {
  background: rgba(217, 119, 6, 0.18);
  color: #92400e;
}
body.light-theme-active .view-container.home-dashboard.home-exec .home-exec-severity.risk {
  background: rgba(220, 38, 38, 0.16);
  color: #b91c1c;
}
body.light-theme-active .view-container.home-dashboard.home-exec .home-exec-severity.info {
  background: rgba(2, 132, 199, 0.12);
  color: #075985;
}

/* Unified dark black app theme
   This late layer wins over older module-specific slate/navy styles. */
body:not(.light-theme-active) {
  --color-bg-base: #000000;
  --color-surface-card: #080808;
  --color-surface-card-strong: #0d0d0d;
  --color-surface-panel: #090909;
  --color-surface-elevated: #111111;
  --color-surface-depth: #000000;
  --color-border-subtle: rgba(255, 255, 255, 0.08);
  --color-border-medium: rgba(255, 255, 255, 0.12);
  --color-border-strong: rgba(255, 255, 255, 0.18);
}

html.page-dark-theme:not(.light-theme-active),
body.page-dark-theme:not(.light-theme-active),
body.page-dark-theme:not(.light-theme-active) #root,
body:not(.light-theme-active) .app-layout,
body:not(.light-theme-active) .main-content,
body:not(.light-theme-active) .page-shell,
body:not(.light-theme-active) .view-container,
body:not(.light-theme-active) .portfolio-shell-view,
body:not(.light-theme-active).portfolio-active,
html:not(.light-theme-active).portfolio-active,
body:not(.light-theme-active).portfolio-active #root,
body:not(.light-theme-active) .portfolio-active #root,
body:not(.light-theme-active) .view-container:has(.portfolio-exec-page),
body:not(.light-theme-active).portfolio-active .view-container {
  background: var(--color-surface-depth) !important;
  background-image: none !important;
}



body:not(.light-theme-active) .home-exec,
body:not(.light-theme-active) .portfolio-exec-page,
body:not(.light-theme-active) .analytics-layout {
  --home-exec-surface: #090909;
  --home-exec-surface-soft: rgba(12, 12, 12, 0.82);
  --home-exec-border: rgba(255, 255, 255, 0.1);
  --portfolio-exec-surface: #090909;
  --portfolio-exec-surface-soft: rgba(12, 12, 12, 0.82);
  --portfolio-exec-border: rgba(255, 255, 255, 0.1);
  --analytics-bg: #000000;
  --analytics-panel: #090909;
  --analytics-panel-2: #050505;
  --analytics-line: rgba(255, 255, 255, 0.1);
  --analytics-line-strong: rgba(255, 255, 255, 0.18);
}

body:not(.light-theme-active) .home-exec-btn.primary,
body:not(.light-theme-active) .home-exec-toggle.active,
body:not(.light-theme-active) .home-exec-timeframe-strip button.active,
body:not(.light-theme-active) .portfolio-exec-btn.primary,
body:not(.light-theme-active) .portfolio-exec-page .portfolio-v2-range-btn.active,
body:not(.light-theme-active) .portfolio-command-primary-cta,
body:not(.light-theme-active) .nav-btn.active,
body:not(.light-theme-active) .analytics-tab-pill.active,
body:not(.light-theme-active) .journal-btn.primary,
body:not(.light-theme-active) .journal-v2-tab.active {
  background: rgba(255, 255, 255, 0.1) !important;
  background-image: none !important;
  border-color: var(--color-border-strong) !important;
  color: var(--color-text-primary) !important;
}

body:not(.light-theme-active) .nav-btn:hover,
body:not(.light-theme-active) .sidebar-theme-row:hover,
body:not(.light-theme-active) .sidebar-footer:hover,
body:not(.light-theme-active) .sidebar-logout-row:hover,
body:not(.light-theme-active) .home-exec-btn:hover,
body:not(.light-theme-active) .home-exec-link:hover,
body:not(.light-theme-active) .home-exec-toggle:hover,
body:not(.light-theme-active) .portfolio-command-attention-card:hover,
body:not(.light-theme-active) .portfolio-command-change-row:hover,
body:not(.light-theme-active) .portfolio-command-primary-cta:hover,
body:not(.light-theme-active) .analytics-tab-pill:hover {
  background: var(--color-surface-elevated) !important;
  background-image: none !important;
  border-color: var(--color-border-strong) !important;
}

/* Research knowledge base workspace
   Scoped tokens aliased to the global design system so they flip with
   the active theme. Local names retained for compatibility. */

.research-workspace {
  --research-bg: var(--color-bg-base);
  --research-panel: var(--color-surface-card);
  --research-panel-soft: var(--color-surface-panel);
  --research-line: var(--color-border-medium);
  --research-line-strong: var(--color-border-strong);
  --research-text: var(--color-text-primary);
  --research-muted: var(--color-text-muted);
  --research-accent: var(--color-data-primary);
  --research-good: var(--color-data-green-bright);
  --research-warn: var(--color-data-amber-bright);
  min-height: 100%;
  padding: 24px 28px 48px;
  color: var(--research-text);
  background:
    linear-gradient(var(--color-border-subtle) 1px, transparent 1px),
    linear-gradient(90deg, var(--color-border-subtle) 1px, transparent 1px),
    var(--research-bg);
  background-size: 34px 34px;
}

.research-workspace .compact-page-title-row h2 {
  font-size: clamp(1.7rem, 2.4vw, 2.45rem);
  letter-spacing: -0.035em;
}

.research-file-input {
  display: none;
}

.research-metric-strip {
  margin: 16px 0 10px;
}

.research-guidance-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 12px;
  margin: 0 0 10px;
  border: 1px solid var(--color-interactive-soft);
  background: var(--research-panel);
  border-radius: var(--radius-md);
}

.research-guidance-banner strong {
  color: var(--research-accent);
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  white-space: nowrap;
}

.research-guidance-banner span {
  color: var(--research-muted);
  font-size: 0.8rem;
  line-height: 1.45;
}

.research-view-nav {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 0 0 12px;
  min-width: 0;
}

.research-view-tabs,
.research-view-subtabs {
  display: flex;
  overflow-x: auto;
}

.research-view-tabs {
  flex: 0 0 auto;
  gap: 6px;
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: thin;
  scroll-snap-type: x mandatory;
}
.research-view-tabs::-webkit-scrollbar { height: 4px; }
.research-view-tabs::-webkit-scrollbar-thumb { background: var(--color-border-medium); border-radius: var(--radius-sm); }
.research-view-tabs > * { scroll-snap-align: start; }

.research-view-subtabs {
  flex: 1 1 auto;
  gap: 6px;
  padding: 5px;
  border: 1px solid var(--research-line);
  background: var(--color-surface-overlay);
  border-radius: var(--radius-md);
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: thin;
}
.research-view-subtabs::-webkit-scrollbar { height: 4px; }
.research-view-subtabs::-webkit-scrollbar-thumb { background: var(--color-border-medium); border-radius: var(--radius-sm); }

.research-conviction {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  margin-right: 6px;
  vertical-align: middle;
}
.research-conviction i {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-surface-elevated);
  border: 1px solid transparent;
}
.research-conviction i.filled {
  background: var(--color-interactive);
  border-color: var(--color-border-medium);
}

.research-view-tabs button,
.research-view-subtabs button {
  border: 1px solid var(--research-line);
  background: var(--color-surface-overlay);
  color: var(--research-muted);
  border-radius: var(--radius-md);
  min-height: 32px;
  padding: 0 10px;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
  cursor: pointer;
}

.research-view-tabs button {
  min-height: 34px;
}

.research-view-subtabs button {
  flex: 0 0 auto;
  min-height: 28px;
  padding: 0 10px;
  border-color: transparent;
  background: transparent;
  font-size: 0.72rem;
  letter-spacing: 0.06em;
}

.research-view-tabs button.active,
.research-view-subtabs button.active {
  color: var(--color-text-primary);
  border-color: var(--color-border-strong);
  background: var(--color-surface-overlay);
  box-shadow: inset 0 0 0 1px var(--color-selected);
}

.research-view-subtabs button.active {
  background: var(--color-selected);
  box-shadow: none;
}

.research-grid {
  display: grid;
  grid-template-columns: minmax(260px, 0.85fr) minmax(420px, 1.7fr) minmax(280px, 0.9fr);
  gap: 14px;
  align-items: start;
}

.research-view-grid {
  display: grid;
  grid-template-columns: minmax(300px, 0.92fr) minmax(420px, 1.55fr);
  gap: 14px;
  align-items: start;
}

.research-view-grid-wide {
  grid-template-columns: minmax(520px, 1.55fr) minmax(280px, 0.72fr);
}

.research-panel {
  border: 1px solid var(--research-line);
  background: linear-gradient(180deg, rgba(14, 14, 14, 0.96), rgba(8, 8, 8, 0.98));
  border-radius: var(--radius-md);
  padding: 12px;
  box-shadow: none;
}

.research-source-cards {
  display: grid;
  gap: 8px;
}

.research-source-card {
  border: 1px solid var(--research-line);
  background: rgba(255, 255, 255, 0.025);
  padding: 12px;
  border-radius: var(--radius-md);
}

.research-source-card div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.research-source-card strong,
.research-readiness-list strong,
.research-obsidian-box strong,
.research-handoff-box strong {
  color: var(--research-text);
  font-size: 0.95rem;
}

.research-source-card span,
.research-pill {
  color: var(--research-accent);
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 800;
}

.research-source-card p,
.research-readiness-list span,
.research-source-row span,
.research-compose-actions span,
.research-doc-table td,
.research-obsidian-box label span {
  color: var(--research-muted);
  font-size: 0.78rem;
  line-height: 1.45;
}

.research-source-form,
.research-obsidian-box,
.research-handoff-box {
  display: grid;
  gap: 10px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid var(--research-line);
}

.research-source-form label,
.research-obsidian-box label {
  display: grid;
  gap: 6px;
}

.research-source-form label span,
.research-compose-head strong,
.research-obsidian-box label span {
  color: var(--research-muted);
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 800;
}

.research-source-form input,
.research-source-form select,
.research-compose input,
.research-compose textarea,
.research-compose select,
.research-inline-select,
.research-search,
.research-obsidian-box input {
  width: 100%;
  border: 1px solid var(--research-line);
  background: rgba(0, 0, 0, 0.34);
  color: var(--research-text);
  border-radius: var(--radius-md);
  min-height: 38px;
  padding: 9px 10px;
  outline: none;
  font: inherit;
}

.research-source-form input:focus,
.research-source-form select:focus,
.research-compose input:focus,
.research-compose textarea:focus,
.research-compose select:focus,
.research-inline-select:focus,
.research-search:focus,
.research-obsidian-box input:focus {
  border-color: var(--color-border-medium);
  box-shadow: rgba(255, 255, 255, 0.08);
}

.research-source-list {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}

.research-source-row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--research-line);
  background: rgba(255, 255, 255, 0.018);
  padding: 10px;
}

.research-source-row div {
  display: grid;
  gap: 4px;
}

.research-source-row em {
  color: var(--research-good);
  font-style: normal;
  font-variant-numeric: tabular-nums;
}

.research-compose {
  display: grid;
  gap: 8px;
  border: 1px solid var(--color-interactive-soft);
  background: var(--research-panel);
  border-radius: var(--radius-md);
  padding: 10px;
  margin-bottom: 10px;
}

.research-compose-head,
.research-compose-actions,
.research-notice {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.research-compose-head select {
  max-width: 240px;
}

.research-compose-toolbar {
  display: flex;
  gap: 8px;
  width: min(380px, 100%);
}

.research-compose-toolbar select {
  flex: 1;
}

.research-compose textarea {
  resize: vertical;
  min-height: 92px;
}

.research-btn,
.research-link-btn,
.research-handoff-box button,
.research-notice button {
  border: 1px solid var(--research-line-strong);
  background: var(--color-surface-overlay);
  color: var(--research-text);
  border-radius: var(--radius-md);
  min-height: 38px;
  padding: 0 13px;
  font-weight: 800;
  letter-spacing: 0.04em;
  cursor: pointer;
}

.research-btn.primary {
  border-color: var(--color-border-medium);
  background: var(--color-interactive);
  color: var(--color-text-inverse);
}

.research-btn.secondary.full {
  width: 100%;
}

.research-btn.danger {
  color: var(--color-data-red-bright);
  border-color: var(--color-data-red-bright);
}

.research-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.research-link-btn.active {
  border-color: var(--color-selected);
  color: var(--research-text);
}

.research-doc-table-wrap {
  border: 1px solid var(--research-line);
  border-radius: var(--radius-md);
  overflow: auto;
}

.research-doc-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 760px;
}

.research-doc-table th,
.research-doc-table td {
  border-bottom: 1px solid var(--research-line);
  padding: 11px 12px;
  text-align: left;
  vertical-align: top;
}

.research-doc-table th {
  color: var(--research-muted);
  font-size: 0.68rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--color-surface-overlay);
}

.research-doc-title {
  display: block;
  border: 0;
  background: transparent;
  color: var(--research-text);
  padding: 0;
  margin-bottom: 4px;
  font-weight: 700;
  text-align: left;
  cursor: pointer;
}

.research-doc-table td > span {
  display: block;
  max-width: 46ch;
}

.research-symbol-row,
.research-detail-symbols {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.research-symbol-row span,
.research-detail-symbols span {
  border: 1px solid var(--research-line);
  background: var(--color-surface-hover);
  color: var(--research-muted);
  border-radius: var(--radius-full);
  padding: 3px 8px;
  font-size: 0.68rem;
  font-weight: 800;
}

.research-symbol-row span.tracked {
  color: var(--research-good);
  border-color: rgba(74, 222, 128, 0.28);
  background: rgba(74, 222, 128, 0.08);
}

.research-symbol-chip {
  border: 1px solid var(--research-line);
  background: var(--color-surface-overlay);
  color: var(--research-muted);
  border-radius: var(--radius-full);
  min-height: 28px;
  padding: 0 9px;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  cursor: pointer;
}

.research-status-pill {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--research-line);
  border-radius: var(--radius-full);
  min-height: 24px;
  padding: 0 8px;
  color: var(--research-muted);
  background: var(--color-surface-overlay);
  font-size: 0.66rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.research-status-pill.unread {
  color: var(--color-data-amber-bright);
  border-color: rgba(245, 158, 11, 0.22);
}

.research-status-pill.reviewed,
.research-status-pill.linked,
.research-status-pill.upcoming {
  color: var(--research-accent);
  border-color: var(--color-border-medium);
}

.research-status-pill.archived,
.research-status-pill.complete {
  color: var(--research-muted);
}

.research-readiness-list {
  display: grid;
  gap: 10px;
}

.research-readiness-list div {
  display: grid;
  gap: 5px;
  border-bottom: 1px solid var(--research-line);
  padding-bottom: 10px;
}

.research-handoff-box button {
  text-align: left;
}

.research-notice {
  border: 1px solid var(--color-border-medium);
  background: var(--color-surface-overlay);
  color: var(--color-text-primary);
  padding: 10px 12px;
  margin: 12px 0;
  border-radius: var(--radius-md);
}

.research-document-detail {
  display: grid;
  gap: 14px;
}

.research-promotion-box {
  display: grid;
  gap: 10px;
  border: 1px solid var(--research-line);
  background: var(--color-surface-overlay);
  border-radius: var(--radius-md);
  padding: 12px;
}

.research-promotion-box strong {
  color: var(--research-text);
}

.research-promotion-box span {
  color: var(--research-muted);
  font-size: 0.78rem;
  line-height: 1.5;
}

.research-drawer-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

.research-document-detail a {
  color: var(--research-accent);
}

.research-document-detail pre {
  white-space: pre-wrap;
  margin: 0;
  border: 1px solid var(--research-line);
  background: rgba(0, 0, 0, 0.3);
  border-radius: var(--radius-md);
  padding: 14px;
  color: var(--research-text);
  line-height: 1.55;
  font-family: inherit;
}

body:not(.light-theme-active) .research-panel,
body:not(.light-theme-active) .research-source-card,
body:not(.light-theme-active) .research-compose,
body:not(.light-theme-active) .research-source-row,
body:not(.light-theme-active) .research-doc-table-wrap,
body:not(.light-theme-active) .research-document-detail pre {
  background-color: var(--color-surface-panel) !important;
  border-color: var(--color-border-medium) !important;
}

.research-card-stack,
.research-mini-list,
.research-ticker-list {
  display: grid;
  gap: 8px;
}

.research-inbox-card,
.research-mini-row,
.research-dossier-card,
.research-dossier-surface {
  border: 1px solid var(--research-line);
  background: rgba(255, 255, 255, 0.02);
  border-radius: var(--radius-md);
}

.research-inbox-card,
.research-dossier-card,
.research-dossier-surface {
  padding: 10px;
}

.research-inbox-head,
.research-action-row,
.research-inline-pills,
.research-thesis-foot {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.research-inbox-head > div:first-child,
.research-thesis-foot > div {
  display: grid;
  gap: 4px;
}

.research-inbox-card p,
.research-muted-copy {
  color: var(--research-muted);
  font-size: 0.8rem;
  line-height: 1.42;
  margin: 8px 0 0;
}

.research-inline-pills {
  flex-wrap: wrap;
  justify-content: flex-end;
}

.research-action-row {
  flex-wrap: wrap;
  margin-top: 8px;
}

.research-summary-list {
  display: grid;
  gap: 10px;
}

.research-summary-list div,
.research-dossier-card {
  display: grid;
  gap: 4px;
}

.research-summary-list strong,
.research-dossier-card strong {
  color: var(--research-text);
  font-size: 1.1rem;
}

.research-summary-list span,
.research-dossier-card span,
.research-dossier-card em {
  color: var(--research-muted);
  font-style: normal;
  line-height: 1.4;
}

.research-ticker-list-panel {
  min-width: 0;
}

.research-ticker-row {
  width: 100%;
  border: 1px solid var(--research-line);
  background: var(--research-panel);
  color: inherit;
  border-radius: var(--radius-md);
  padding: 12px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  text-align: left;
  cursor: pointer;
}

.research-ticker-row.active {
  border-color: var(--color-interactive);
  background: var(--color-interactive-soft);
}

.research-ticker-row div:first-child,
.research-ticker-meta {
  display: grid;
  gap: 4px;
}

.research-ticker-row strong {
  color: var(--research-text);
  font-size: 0.98rem;
}

.research-ticker-row span,
.research-ticker-meta em {
  color: var(--research-muted);
  font-size: 0.76rem;
  font-style: normal;
  line-height: 1.45;
}

.research-dossier-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.research-dossier-surface {
  grid-column: span 3;
}

.research-mini-row {
  width: 100%;
  display: grid;
  gap: 4px;
  text-align: left;
  padding: 10px 12px;
  color: inherit;
  cursor: pointer;
}

.research-mini-row.static {
  cursor: default;
}

.research-mini-row.active {
  border-color: var(--color-interactive);
  background: var(--color-interactive-soft);
}

.research-mini-row strong {
  color: var(--research-text);
  font-size: 0.82rem;
}

.research-mini-row span {
  color: var(--research-muted);
  font-size: 0.76rem;
  line-height: 1.45;
}

.research-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.research-form-grid label {
  display: grid;
  gap: 6px;
}

.research-form-grid label.wide {
  grid-column: 1 / -1;
}

.research-form-grid label span,
.research-thesis-foot span {
  color: var(--research-muted);
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 800;
}

.research-form-grid input,
.research-form-grid select,
.research-form-grid textarea {
  width: 100%;
  border: 1px solid var(--research-line);
  background: rgba(0, 0, 0, 0.34);
  color: var(--research-text);
  border-radius: var(--radius-md);
  min-height: 38px;
  padding: 9px 10px;
  outline: none;
  font: inherit;
}

.research-form-grid textarea {
  resize: vertical;
}

.research-form-grid input:focus,
.research-form-grid select:focus,
.research-form-grid textarea:focus {
  border-color: var(--color-border-medium);
  box-shadow: rgba(255, 255, 255, 0.08);
}

.research-brief-preview {
  margin-top: 14px;
  border: 1px solid var(--research-line);
  border-radius: var(--radius-md);
  padding: 12px;
  background: rgba(255, 255, 255, 0.02);
}

.research-brief-preview pre {
  margin: 0;
  white-space: pre-wrap;
  color: var(--research-text);
  line-height: 1.6;
  font-family: inherit;
}

.research-brief-section-grid,
.research-template-grid,
.research-honesty-grid {
  display: grid;
  gap: 12px;
}

.research-brief-section-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 14px;
}

.research-brief-section,
.research-ownership-row,
.research-timeline-row {
  border: 1px solid var(--research-line);
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.02);
}

.research-brief-section {
  padding: 12px;
}

.research-brief-section strong,
.research-ownership-row strong,
.research-timeline-row strong {
  color: var(--research-text);
  display: block;
  margin-bottom: 8px;
}

.research-brief-section pre {
  margin: 0;
  white-space: pre-wrap;
  font-family: inherit;
  color: var(--research-muted);
  line-height: 1.55;
}

.research-brief-section textarea {
  width: 100%;
  border: 1px solid var(--research-line);
  background: rgba(0, 0, 0, 0.3);
  color: var(--research-text);
  border-radius: var(--radius-md);
  min-height: 160px;
  padding: 10px 12px;
  font: inherit;
  line-height: 1.55;
  resize: vertical;
}

.research-template-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.research-honesty-grid {
  margin-bottom: 14px;
}

.research-ownership-list,
.research-timeline-list {
  display: grid;
  gap: 10px;
}

.research-ownership-row,
.research-timeline-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  padding: 12px;
  align-items: center;
}

.research-ownership-row div,
.research-timeline-row div {
  display: grid;
  gap: 4px;
}

.research-ownership-row span,
.research-timeline-row em {
  color: var(--research-muted);
  font-style: normal;
  font-size: 0.78rem;
  line-height: 1.45;
}

.research-ownership-row select {
  min-width: 140px;
  border: 1px solid var(--research-line);
  background: rgba(0, 0, 0, 0.34);
  color: var(--research-text);
  border-radius: var(--radius-md);
  min-height: 38px;
  padding: 8px 10px;
  font: inherit;
}

.research-ownership-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.research-timeline-row {
  grid-template-columns: 140px minmax(0, 1fr);
}

.research-timeline-row > span {
  color: var(--research-muted);
  font-size: 0.78rem;
  letter-spacing: 0.04em;
}

body.light-theme-active .research-workspace {
  --research-bg: var(--color-text-secondary);
  --research-panel: #ffffff;
  --research-panel-soft: rgba(255, 255, 255, 0.9);
  --research-line: var(--color-text-secondary);
  --research-line-strong: var(--color-text-secondary);
  --research-text: var(--color-text-secondary);
  --research-muted: var(--color-text-secondary);
  --research-accent: var(--color-text-secondary);
  color: var(--research-text);
  background:
    var(--color-surface-elevated);
}

body.light-theme-active .research-panel,
body.light-theme-active .research-source-card,
body.light-theme-active .research-compose,
body.light-theme-active .research-source-row,
body.light-theme-active .research-doc-table-wrap {
  background: rgba(255, 255, 255, 0.94);
  border-color: var(--color-border-medium);
}

body.light-theme-active .research-guidance-banner {
  background: var(--color-surface-elevated);
  border-color: var(--color-border-medium);
}

body.light-theme-active .research-source-form input,
body.light-theme-active .research-source-form select,
body.light-theme-active .research-compose input,
body.light-theme-active .research-compose textarea,
body.light-theme-active .research-compose select,
body.light-theme-active .research-inline-select,
body.light-theme-active .research-search,
body.light-theme-active .research-obsidian-box input,
body.light-theme-active .research-form-grid input,
body.light-theme-active .research-form-grid select,
body.light-theme-active .research-form-grid textarea {
  background: var(--color-surface-card);
  color: var(--color-text-primary);
  border-color: var(--color-border-medium);
}

body.light-theme-active .research-document-detail pre {
  background: var(--color-surface-panel);
  color: var(--color-text-primary);
  border-color: var(--color-border-medium);
}

body.light-theme-active .research-promotion-box,
body.light-theme-active .research-brief-section textarea {
  background: rgba(255, 255, 255, 0.94);
  border-color: var(--color-border-medium);
  color: var(--color-text-primary);
}

body.light-theme-active .research-doc-table th {
  background: var(--color-surface-elevated);
}

body.light-theme-active .research-brief-section,
body.light-theme-active .research-ownership-row,
body.light-theme-active .research-timeline-row {
  background: rgba(255, 255, 255, 0.94);
  border-color: var(--color-border-medium);
}

body.light-theme-active .research-ownership-row select {
  background: var(--color-surface-card);
  color: var(--color-text-primary);
  border-color: var(--color-border-medium);
}

/* Light-mode QA repairs for dense app surfaces. */
body.light-theme-active,
body.light-theme-active #root {
  background: #eef3f8 !important;
}

body.light-theme-active .app-layout {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.42), rgba(255, 255, 255, 0)),
    #eef3f8 !important;
}

body.light-theme-active .main-content {
  color: var(--color-text-primary);
}

body.light-theme-active .view-container,
body.light-theme-active .analytics-layout,
body.light-theme-active .research-workspace {
  background:
    var(--color-surface-elevated) !important;
  border: var(--color-border-medium);
  box-shadow: rgba(255, 255, 255, 0.08);
}

.sidebar.sidebar-overhaul-v2 .sidebar-brand-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 4px 4px 6px;
}

.sidebar.sidebar-overhaul-v2 .sidebar-brand-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.sidebar.sidebar-overhaul-v2 .sidebar-brand-mark {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.sidebar.sidebar-overhaul-v2 .sidebar-brand-type {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1.1;
  min-width: 0;
}

.sidebar.sidebar-overhaul-v2 .sidebar-brand-name {
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--color-text-primary);
}

.sidebar.sidebar-overhaul-v2 .sidebar-brand-meta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 2px;
  font-size: 0.72rem;
  color: var(--color-text-muted);
}

.sidebar.sidebar-overhaul-v2 .sidebar-brand-aside {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.64rem;
  color: var(--color-text-secondary);
}

.sidebar.sidebar-overhaul-v2 .sidebar-brand-aside::before {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-success);
  opacity: 0.9;
}

.sidebar.sidebar-overhaul-v2 .sidebar-brand-muted {
  color: var(--color-text-muted);
}

.sidebar.sidebar-overhaul-v2 .sidebar-nav {
  gap: 7px;
  flex: 0 1 auto;
}

/* ── Sidebar overhaul v2 — structural repair (Brand.md conformant) ── */
.sidebar.sidebar-overhaul-v2 {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 250px;
  height: 100vh;
  max-height: none;
  padding: 14px 10px;
  background: var(--color-bg-base) !important;
  border-right: 1px solid var(--color-border-subtle);
  border-radius: 0;
  box-shadow: none;
}

/* Single divider only — remove the per-section rule lines. */
.sidebar.sidebar-overhaul-v2 .sidebar-section-header:before,
.sidebar.sidebar-overhaul-v2 .sidebar-live-title:before {
  display: none;
}

/* Navigation groups — whitespace rhythm, no heavy separators */
.sidebar.sidebar-overhaul-v2 .sidebar-nav-group + .sidebar-nav-group {
  margin-top: 10px;
}
.sidebar.sidebar-overhaul-v2 .sidebar-section-header {
  margin: 0 0 4px;
  padding: 0 10px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

/* Navigation rows — single horizontal flex, icon + label centered */
.sidebar.sidebar-overhaul-v2 .nav-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 38px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--sidebar-text);
  font-weight: 500;
  font-size: 0.95rem;
  text-decoration: none;
  transition: background-color 140ms ease, color 140ms ease, border-color 140ms ease;
}
.sidebar.sidebar-overhaul-v2 .nav-icon-wrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
}
.sidebar.sidebar-overhaul-v2 .nav-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  color: inherit;
}
.sidebar.sidebar-overhaul-v2 .nav-icon svg {
  width: 18px;
  height: 18px;
  stroke-width: 2;
  color: inherit;
  stroke: currentColor;
  fill: none;
}
.sidebar.sidebar-overhaul-v2 .nav-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.2;
  color: inherit;
}
.sidebar.sidebar-overhaul-v2 .nav-full {
  font-size: 0.95rem;
  font-weight: 500;
  color: inherit;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sidebar.sidebar-overhaul-v2 .nav-description {
  font-size: 0.7rem;
  color: var(--color-text-muted);
}

/* Active — monochrome inversion: bg + text + icon all flip together. */
.sidebar.sidebar-overhaul-v2 .nav-btn.active {
  background: var(--sidebar-active-bg);
  color: var(--sidebar-active-text);
  border-color: transparent;
}
.sidebar.sidebar-overhaul-v2 .nav-btn.active .nav-copy,
.sidebar.sidebar-overhaul-v2 .nav-btn.active .nav-full,
.sidebar.sidebar-overhaul-v2 .nav-btn.active .nav-icon,
.sidebar.sidebar-overhaul-v2 .nav-btn.active .nav-icon svg {
  color: var(--sidebar-active-text);
  stroke: currentColor;
  fill: none;
}

/* Hover — subtle elevation, text + icon become primary. No scale/position animation. */
.sidebar.sidebar-overhaul-v2 .nav-btn:hover {
  background: var(--sidebar-hover-bg);
  color: var(--sidebar-hover-text);
  border-color: transparent;
}
.sidebar.sidebar-overhaul-v2 .nav-btn:hover .nav-icon,
.sidebar.sidebar-overhaul-v2 .nav-btn:hover .nav-icon svg {
  color: var(--sidebar-hover-text);
  stroke: currentColor;
}

/* Theme / Account / Logout utility rows — same treatment as nav items. */
.sidebar.sidebar-overhaul-v2 .sidebar-utility-row {
  border-radius: var(--radius-md);
  transition: background-color 140ms ease, color 140ms ease;
  color: var(--sidebar-text);
}
.sidebar.sidebar-overhaul-v2 .sidebar-utility-row .sidebar-theme-label,
.sidebar.sidebar-overhaul-v2 .sidebar-utility-row .sidebar-theme-icon,
.sidebar.sidebar-overhaul-v2 .sidebar-utility-row .user-icon {
  color: inherit;
}
.sidebar.sidebar-overhaul-v2 .sidebar-theme-row:hover,
.sidebar.sidebar-overhaul-v2 .sidebar-account-row:hover,
.sidebar.sidebar-overhaul-v2 .sidebar-logout-row:hover {
  background: var(--sidebar-hover-bg);
  color: var(--sidebar-hover-text);
}

/* Live status — structured metadata, compact, muted, no card chrome */
.sidebar.sidebar-overhaul-v2 .sidebar-live-status {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-top: auto;
  padding: 10px 5px 4px;
  border: 0;
  border-radius: 0;
  background: transparent;
}
.sidebar.sidebar-overhaul-v2 .sidebar-live-title {
  font-size: 0.64rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}
.sidebar.sidebar-overhaul-v2 .sidebar-live-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 0.78rem;
  color: var(--color-text-muted);
}
.sidebar.sidebar-overhaul-v2 .sidebar-live-row strong {
  color: var(--color-text-secondary);
  font-weight: 600;
  font-size: 0.82rem;
}
.sidebar.sidebar-overhaul-v2 .sidebar-live-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-success);
  margin-right: 6px;
}

/* Footer — single divider, whitespace separation from nav */
.sidebar.sidebar-overhaul-v2 .sidebar-bottom {
  margin-top: 4px;
  padding-top: 6px;
  border-top: 1px solid var(--color-border-subtle);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

/* Utility rows — identical to nav rows, never a horizontal strip */
.sidebar.sidebar-overhaul-v2 .sidebar-utility-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 38px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--color-text-secondary);
  font-weight: 500;
  font-size: 0.86rem;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 140ms ease, color 140ms ease, border-color 140ms ease;
}
.sidebar.sidebar-overhaul-v2 .sidebar-utility-left {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.sidebar.sidebar-overhaul-v2 .sidebar-theme-icon,
.sidebar.sidebar-overhaul-v2 .user-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
}
.sidebar.sidebar-overhaul-v2 .sidebar-theme-icon svg,
.sidebar.sidebar-overhaul-v2 .user-icon svg {
  width: 18px;
  height: 18px;
  stroke-width: 2;
}
.sidebar.sidebar-overhaul-v2 .sidebar-theme-label {
  font-size: 0.86rem;
  font-weight: 500;
  color: var(--color-text-secondary);
}
.sidebar.sidebar-overhaul-v2 .sidebar-theme-right {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--color-text-muted);
}
.sidebar.sidebar-overhaul-v2 .sidebar-theme-chip {
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-full);
  padding: 1px 8px;
}
.sidebar.sidebar-overhaul-v2 .sidebar-theme-arrow,
.sidebar.sidebar-overhaul-v2 .sidebar-account-chevron {
  color: var(--color-text-muted);
  font-size: 1rem;
  line-height: 1;
}
.sidebar.sidebar-overhaul-v2 .sidebar-utility-row:hover {
  background: var(--color-surface-overlay);
  color: var(--color-text-primary);
}
.sidebar.sidebar-overhaul-v2 .sidebar-utility-row:hover .sidebar-theme-label {
  color: var(--color-text-primary);
}

/* Collapsed rail: the expand control has no default chrome, so give it a
   visible button affordance in both themes. */
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-collapsed-brand {
  display: flex;
  justify-content: center;
  padding: 2px 0 10px;
}
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-collapsed-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-lg);
  color: var(--color-text-secondary);
  background: var(--color-surface-overlay);
  border: 1px solid var(--color-border-subtle);
  cursor: pointer;
  transition: background-color 140ms ease, color 140ms ease, border-color 140ms ease;
}
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-collapsed-mark:hover {
  color: var(--color-text-primary);
  background: var(--color-surface-elevated);
  border-color: var(--color-border-strong);
}

/* Z monogram — centered 40x40 wordmark surrogate in collapsed mode */
.sidebar.sidebar-overhaul-v2 .sidebar-z-monogram {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--color-text-primary);
  line-height: 1;
}

/* Collapse toggle — 40x40, always visible, beside the logo */
.sidebar.sidebar-overhaul-v2 .sidebar-collapse-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  color: var(--color-text-secondary);
  background: var(--color-surface-overlay);
  border: 1px solid var(--color-border-subtle);
  cursor: pointer;
  transition: background-color 140ms ease, color 140ms ease, border-color 140ms ease;
}
.sidebar.sidebar-overhaul-v2 .sidebar-collapse-toggle:hover {
  background: var(--color-surface-elevated);
  color: var(--color-text-primary);
  border-color: var(--color-border-strong);
}

/* Collapsed mode — icon-only, labels hidden, three-region flex layout */
.sidebar.sidebar-overhaul-v2.collapsed {
  width: var(--workspace-sidebar-width-collapsed);
  align-items: stretch;
}
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-header.sidebar-brand-row {
  flex-direction: column;
  align-items: center;
  gap: 6px;
}
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-collapse-toggle {
  display: none;
}
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-section-header,
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-brand-type,
.sidebar.sidebar-overhaul-v2.collapsed .nav-copy,
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-utility-copy,
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-theme-right {
  display: none;
}
/* Whitespace grouping between nav clusters instead of heavy dividers */
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-nav-group + .sidebar-nav-group {
  margin-top: 18px;
}
.sidebar.sidebar-overhaul-v2.collapsed .nav-btn,
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-utility-row {
  justify-content: center;
  padding: 0;
}
/* Active = a 44x44 pill that hugs the icon, not a full-width bar */
.sidebar.sidebar-overhaul-v2.collapsed .nav-btn.active {
  width: 44px;
  min-height: 44px;
  margin: 0 auto;
  border-radius: var(--radius-xl);
  background: var(--sidebar-active-bg);
  color: var(--sidebar-active-text);
  border-color: transparent;
}
.sidebar.sidebar-overhaul-v2.collapsed .nav-btn.active .nav-icon,
.sidebar.sidebar-overhaul-v2.collapsed .nav-btn.active .nav-icon svg {
  color: var(--sidebar-active-text);
  stroke: currentColor;
  fill: none;
}
/* Hover — subtle, opacity-only lift, no position/scale animation */
.sidebar.sidebar-overhaul-v2.collapsed .nav-btn:hover,
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-utility-row:hover {
  background: var(--sidebar-hover-bg);
  color: var(--sidebar-hover-text);
}
.sidebar.sidebar-overhaul-v2.collapsed .nav-btn.active:hover {
  background: var(--sidebar-active-bg);
  color: var(--sidebar-active-text);
}
/* Icon container normalized to 40x40 for identical center alignment */
.sidebar.sidebar-overhaul-v2.collapsed .nav-icon-wrap {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
}
.sidebar.sidebar-overhaul-v2.collapsed .nav-icon,
.sidebar.sidebar-overhaul-v2.collapsed .nav-icon svg {
  width: 20px;
  height: 20px;
}
/* Market status — dot only in collapsed mode, tooltip carries detail */
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-live-status {
  margin-top: auto;
  padding: 10px 0 4px;
  align-items: center;
  justify-content: center;
}
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-live-rail {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.sidebar.sidebar-overhaul-v2.collapsed .sidebar-live-dot {
  width: 10px;
  height: 10px;
  background: var(--color-success);
}

.sidebar.sidebar-overhaul-v2 .sidebar-nav-group,
.sidebar.sidebar-overhaul-v2 .sidebar-nav-stack {
  gap: 4px;
}

.sidebar.sidebar-overhaul-v2 .nav-btn {
  min-height: 34px;
  padding-top: 5px;
  padding-bottom: 5px;
}

.sidebar.sidebar-overhaul-v2 .nav-btn.active .nav-description {
  max-height: 0;
  opacity: 0;
  transform: translateY(-2px);
}

