.tax-scenario-command,
.watchlist-intent-main {
  display: grid;
  gap: 5px;
}

.guest-mission-copy span,
.tax-scenario-command span,
.watchlist-intent-main span,
.tax-scenario-delta span {
  color: var(--color-data-primary);
  font: 800 10px/1.2 "JetBrains Mono", "SFMono-Regular", monospace;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.guest-mission-copy strong,
.watchlist-intent-main h3,
.tax-scenario-command h3 {
  margin: 0;
  color: var(--color-text-primary);
  font-size: 15px;
  line-height: 1.25;
}

.guest-mission-steps,
.tax-scenario-delta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.guest-mission-steps button,
button {
  min-height: 56px;
  padding: 10px;
  border: 1px solid rgba(255, 255, 255, 0.135);
  border-radius: var(--radius-lg);
  background: color-mix(in srgb, var(--color-surface-elevated) 64%, transparent);
  color: var(--color-text-secondary);
  text-align: left;
  cursor: pointer;
  min-width: 0;
}

button {
  overflow-wrap: anywhere;
  word-break: break-word;
  white-space: normal;
}

.guest-mission-steps button.active,
button:hover,
button:focus-visible {
  border-color: color-mix(in srgb, var(--color-border-strong) 44%, transparent);
  background: color-mix(in srgb, var(--color-border-medium) 22%, transparent);
  color: var(--color-text-primary);
}

.guest-mission-steps i {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  margin-right: 6px;
  border-radius: var(--radius-full);
  background: var(--color-interactive-soft);
  color: var(--color-data-primary);
  font-style: normal;
  font-size: 10px;
}

.guest-mission-steps span,
strong {
  display: block;
  color: inherit;
  font-size: 12px;
  font-weight: 800;
}

.guest-mission-steps small,
.watchlist-intent-main p,
.tax-scenario-command p {
  color: var(--color-text-secondary);
  font-size: 11px;
  line-height: 1.4;
}

.watchlist-row-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 6px;
}

.watchlist-action-btn,
.watchlist-intent-actions button,
.watchlist-intent-actions a {
  min-height: 32px;
  padding: 7px 10px;
  border: 1px solid var(--color-border-medium);
  border-radius: 7px;
  background: var(--color-surface-elevated);
  color: var(--color-text-secondary);
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
  cursor: pointer;
}

.watchlist-action-btn:hover,
.watchlist-action-btn:focus-visible,
.watchlist-intent-actions button:hover,
.watchlist-intent-actions button:focus-visible,
.watchlist-intent-actions a:hover,
.watchlist-intent-actions a:focus-visible {
  border-color: var(--color-interactive);
  color: var(--color-text-primary);
}

.watchlist-import-trigger,
.watchlist-import-primary {
  min-height: 40px;
  padding: 0 13px;
  border: 1px solid var(--color-interactive);
  border-radius: 7px;
  background: var(--color-interactive-soft);
  color: var(--color-interactive);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
}

.watchlist-import-trigger:hover,
.watchlist-import-trigger:focus-visible,
.watchlist-import-primary:hover:not(:disabled),
.watchlist-import-primary:focus-visible:not(:disabled) {
  border-color: var(--color-interactive);
  background: var(--color-interactive);
  color: var(--color-text-inverse);
}

.watchlist-import-primary:disabled {
  cursor: not-allowed;
  opacity: 0.52;
}

.watchlist-import-panel {
  display: grid;
  gap: 12px;
  margin: 0 0 12px;
  padding: 13px;
  border: 1px solid var(--color-border-medium);
  border-radius: 7px;
  background: rgba(2, 6, 23, 0.56);
}

.watchlist-import-head,
.watchlist-import-actions,
.watchlist-import-preview-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.watchlist-import-head span,
.watchlist-import-preview-head span,
.watchlist-import-upload > span,
.watchlist-import-textarea > span {
  display: block;
  color: var(--color-data-primary);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.watchlist-import-head strong {
  display: block;
  margin-top: 4px;
  color: var(--color-text-primary);
  font-size: 14px;
}

.watchlist-import-source-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.watchlist-import-source-grid button {
  min-height: 82px;
  height: auto;
  padding: 10px;
  border: 1px solid var(--color-border-medium);
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.58);
  color: var(--color-text-secondary);
  text-align: left;
  cursor: pointer;
  white-space: normal;
}

.watchlist-import-source-grid button.active {
  border-color: var(--color-border-medium);
  background: var(--color-interactive-soft);
}

.watchlist-import-source-grid strong,
.watchlist-import-preview-list strong {
  display: block;
  color: var(--color-text-primary);
  font-size: 12px;
}

.watchlist-import-source-grid span,
.watchlist-import-preview p,
.watchlist-import-preview-list span,
.watchlist-import-preview-list em,
.watchlist-import-preview-list small,
.watchlist-import-preview-head em {
  display: block;
  margin-top: 4px;
  color: rgba(203, 213, 225, 0.72);
  font-size: 11px;
  font-style: normal;
  line-height: 1.35;
  white-space: normal;
  overflow-wrap: break-word;
}

.watchlist-import-body {
  display: grid;
  grid-template-columns: minmax(170px, 0.55fr) minmax(260px, 1fr) minmax(220px, 0.72fr);
  gap: 10px;
  align-items: stretch;
}

.watchlist-import-upload,
.watchlist-import-textarea,
.watchlist-import-preview {
  min-height: 144px;
  padding: 11px;
  border: 1px solid var(--color-border-medium);
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.46);
}

.watchlist-import-upload {
  display: grid;
  align-content: start;
  gap: 12px;
}

.watchlist-import-upload input {
  width: 100%;
  color: rgba(226, 232, 240, 0.86);
  font-size: 12px;
}

.watchlist-import-textarea {
  display: grid;
  gap: 8px;
}

.watchlist-import-textarea textarea {
  width: 100%;
  min-height: 104px;
  resize: vertical;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: rgba(2, 6, 23, 0.54);
  color: var(--color-text-primary);
  padding: 10px;
  font: inherit;
  font-size: 12px;
  line-height: 1.45;
}

.watchlist-import-textarea textarea:focus-visible,
.watchlist-import-source-grid button:focus-visible,
.watchlist-import-upload input:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px rgba(7, 11, 20, 0.94), 0 0 0 4px var(--color-focus);
}

.watchlist-import-preview-list {
  display: grid;
  gap: 6px;
  margin-top: 10px;
  max-height: 180px;
  overflow: auto;
}

.watchlist-import-preview-list > div {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  gap: 8px;
  padding: 7px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: rgba(2, 6, 23, 0.46);
}

.watchlist-import-preview-list em {
  grid-column: 2;
  margin-top: 0;
}

.watchlist-import-status {
  padding: 9px 11px;
  border: 1px solid rgba(34, 197, 94, 0.24);
  border-radius: var(--radius-lg);
  background: rgba(34, 197, 94, 0.1);
  color: var(--color-data-green-bright);
  font-size: 12px;
  font-weight: 800;
}

.watchlist-import-status.error {
  border-color: rgba(248, 113, 113, 0.32);
  background: rgba(127, 29, 29, 0.18);
  color: var(--color-data-red-bright);
}

.watchlist-import-actions {
  flex-wrap: wrap;
  gap: 10px;
}

.watchlist-import-actions button {
  white-space: normal;
  overflow-wrap: break-word;
}

.watchlist-alert-chip {
  display: inline-flex;
  justify-content: center;
  min-width: 48px;
  padding: 4px 7px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-full);
  color: rgba(203, 213, 225, 0.74);
  font-size: 10px;
  font-weight: 800;
}

.watchlist-alert-chip.active {
  border-color: rgba(250, 204, 21, 0.42);
  background: rgba(250, 204, 21, 0.1);
  color: var(--color-data-amber-bright);
}

.watchlist-alert-chip.snoozed {
  border-color: var(--color-border-medium);
  background: rgba(148, 163, 184, 0.12);
  color: var(--color-text-secondary);
}

.watchlist-alert-chip.archived {
  border-color: rgba(34, 197, 94, 0.36);
  background: rgba(34, 197, 94, 0.08);
  color: var(--color-data-green-bright);
}

.watchlist-action-btn.primary {
  border-color: var(--color-interactive);
  background: var(--color-interactive-soft);
  color: var(--color-interactive);
}

.watchlist-action-btn:disabled {
  cursor: wait;
  opacity: 0.55;
}

.watchlist-intent-panel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 12px;
  padding: 13px;
}

.watchlist-intent-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.watchlist-intent-actions a {
  border-color: var(--color-border-medium);
  background: var(--color-text-primary);
  color: #020617;
}

.tax-scenario-workbench {
  display: grid;
  gap: 12px;
  margin-bottom: 14px;
  padding: 14px;
}

small {
  color: var(--color-text-muted);
  font-size: 11px;
}

/* Action buttons sit at the bottom-right of the primary column and match the
   header Save Snapshot button height (40px) so the two CTAs read as one set. */
.journal-btn {
  height: 40px;
  min-height: 40px;
  min-width: 146px;
  padding: 0 14px;
  white-space: nowrap;
}

.tax-scenario-workbench {
  grid-template-columns: minmax(0, 1fr);
  align-items: stretch;
}

.tax-scenario-controls {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.tax-scenario-controls label {
  display: grid;
  gap: 5px;
}

.tax-scenario-controls label span {
  color: var(--tax-muted);
  font-size: 0.73rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.tax-scenario-controls select {
  min-height: 38px;
  width: 100%;
  border: 1px solid var(--tax-line);
  border-radius: var(--radius-xl);
  background: rgba(255, 255, 255, 0.02);
  color: var(--tax-text);
  padding: 0 12px;
  font-size: 0.92rem;
}

.tax-scenario-controls .tax-workbench-primary-btn {
  grid-column: 1 / -1;
}

.tax-scenario-delta > div {
  display: grid;
  gap: 5px;
  padding: 10px;
  border: var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-elevated);
}

.tax-scenario-delta strong {
  color: var(--color-text-primary);
  font-size: 15px;
}

body.light-theme-active .tax-scenario-workbench {
  border-color: var(--color-border-medium);
  background: var(--color-surface-card);
}

body.light-theme-active .guest-mission-copy strong,
body.light-theme-active .watchlist-intent-main h3,
body.light-theme-activeh3,
body.light-theme-activestrong,
body.light-theme-active .tax-scenario-command h3,
body.light-theme-active .tax-scenario-delta strong {
  color: var(--color-text-primary);
}

body.light-theme-active .guest-mission-steps button,
body.light-theme-activebutton,
body.light-theme-active
body.light-theme-active .tax-scenario-delta > div,
body.light-theme-active .tax-scenario-controls select {
  background: var(--color-surface-elevated);
  border-color: var(--color-border-medium);
  color: var(--color-text-secondary);
}

body.light-theme-active .guest-mission-steps small,
body.light-theme-activespan,
body.light-theme-active .watchlist-intent-main p,
body.light-theme-activep,
body.light-theme-active .tax-scenario-command p,
body.light-theme-activesmall {
  color: var(--color-text-secondary);
}

@media (max-width: 1100px) {
  .guest-mission-bar,
  .tax-scenario-workbench {
    grid-template-columns: 1fr;
  }

  .tax-scenario-controls,
  .tax-scenario-delta {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .guest-mission-steps {
    grid-template-columns: 1fr;
  }

  .watchlist-intent-panel {
    align-items: stretch;
    flex-direction: column;
  }

  .watchlist-intent-actions {
    justify-content: flex-start;
  }
}

body.light-theme-active .guest-data-banner span:not(.guest-status-chip),
body.light-theme-active .guest-workspace-hero p,
body.light-theme-active .guest-contextual-signup p,
body.light-theme-active .guest-preview-card p,
body.light-theme-active .guest-workflow-card ol,
body.light-theme-active .guest-preview-card ul,
body.light-theme-active .guest-preview-table div {
  color: var(--color-text-secondary);
}

body.light-theme-active .guest-preview-metrics span {
  color: var(--color-text-muted);
}

body.light-theme-active .guest-preview-table em {
  color: var(--color-data-secondary);
}

body.light-theme-active .guest-preview-table,
body.light-theme-active .guest-preview-table div,
body.light-theme-active .guest-preview-metrics {
  border-color: rgba(15, 23, 42, 0.12);
}

body.light-theme-active .guest-status-chip {
  background: rgba(248, 250, 252, 0.9);
  color: var(--color-text-secondary);
}

/* Predictions desk: probability/risk surface */
.prediction-desk {
  display: grid;
  gap: 12px;
}

.prediction-desk-command,
.prediction-market-panel,
.prediction-whale-panel,
.prediction-risk-card {
  border: var(--color-border-medium);
  border-radius: 5px;
  background:
    var(--color-surface-elevated);
  box-shadow: none;
}

.prediction-desk-command {
  display: grid;
  grid-template-columns: minmax(260px, 0.82fr) minmax(0, 1.18fr);
  gap: 14px;
  align-items: stretch;
  padding: 16px;
}

.prediction-desk-copy {
  display: grid;
  align-content: center;
  gap: 6px;
  min-width: 0;
}

.prediction-desk-copy span,
.prediction-desk-strip span,
.prediction-risk-card span,
.prediction-filter-bar label > span {
  color: var(--color-data-primary);
  font-size: 0.64rem;
  font-weight: 900;
  letter-spacing: 0.16em;
  line-height: 1.2;
  text-transform: uppercase;
}

.prediction-desk-copy h2 {
  margin: 0;
  color: var(--color-text-primary);
  font-size: clamp(1.65rem, 2.6vw, 2.65rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1;
}

.prediction-desk-copy p {
  max-width: 52ch;
  margin: 0;
  color: rgba(203, 213, 225, 0.68);
  font-size: 0.82rem;
  line-height: 1.48;
}

.prediction-desk-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  border: 1px solid var(--color-border-medium);
  background: rgba(2, 6, 23, 0.32);
}

.prediction-desk-strip > div {
  display: grid;
  align-content: center;
  gap: 6px;
  min-width: 0;
  min-height: 76px;
  padding: 10px 12px;
  border-right: 1px solid var(--color-border-medium);
}

.prediction-desk-strip > div:last-child {
  border-right: 0;
}

.prediction-desk-strip strong,
.prediction-risk-card strong {
  color: var(--color-text-primary);
  font-family: "Geist Mono", "SFMono-Regular", Consolas, monospace;
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: -0.035em;
  line-height: 1.1;
}

.prediction-desk-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 330px);
  gap: 12px;
  align-items: stretch;
}

.prediction-market-panel,
.prediction-whale-panel {
  padding: 0 !important;
  overflow: hidden;
}

.prediction-panel-head {
  min-height: 58px;
  padding: 12px 14px;
  margin: 0 !important;
  border-bottom: 1px solid var(--color-border-medium);
}

.prediction-panel-head .header-left h2 {
  color: var(--color-text-primary);
  font-size: 0.96rem;
  font-weight: 850;
  letter-spacing: -0.02em;
}

.prediction-panel-status,
.prediction-filter-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.prediction-panel-status {
  justify-content: flex-end;
}

.prediction-desk-tabs {
  margin: 0;
  padding: 10px 12px;
  border-bottom: 1px solid var(--color-border-medium);
}

.prediction-desk-tabs button {
  min-height: 32px;
  border-radius: var(--radius-md);
}

.prediction-desk-notice {
  margin: 0;
}

.prediction-category-card {
  border: 0;
  border-radius: 0;
  padding: 12px;
  background: transparent;
}

.prediction-category-card h3 {
  display: none;
}

.prediction-market-list {
  gap: 6px;
}

.prediction-market-row {
  min-height: 86px;
  border-color: var(--color-border-medium);
  background: var(--color-surface-elevated);
  padding: 10px 12px;
}

.prediction-market-row:hover,
.prediction-market-row:focus-visible {
  outline: 0;
  border-color: var(--color-border-medium) !important;
  background: var(--color-interactive-soft) !important;
}

.prediction-market-title {
  margin: 0;
  min-width: 0;
  flex: 1;
  overflow-wrap: anywhere;
  word-break: break-word;
  color: var(--color-text-secondary);
  font-size: 0.88rem;
  font-weight: 780;
  line-height: 1.35;
}

.prediction-prob-gauge {
  width: 84px;
  min-width: 84px;
  height: 54px;
}

.prediction-gauge-svg {
  left: 0;
  width: 84px;
  height: 50px;
}

.prediction-gauge-track,
.prediction-gauge-fill {
  stroke-width: 7;
}

.prediction-gauge-value {
  margin-top: 12px;
  color: var(--color-text-primary);
  font-size: 1.12rem;
  font-weight: 900;
  letter-spacing: -0.04em;
}

.prediction-gauge-label,
.prediction-market-meta {
  color: var(--color-text-secondary);
  font-size: 0.68rem;
}

.prediction-risk-rail {
  display: grid;
  gap: 10px;
}

.prediction-risk-card {
  display: grid;
  align-content: space-between;
  gap: 8px;
  min-height: 108px;
  padding: 12px;
}

.prediction-risk-card em {
  color: rgba(203, 213, 225, 0.64);
  font-size: 0.7rem;
  font-style: normal;
  font-weight: 720;
  line-height: 1.45;
}

.prediction-filter-bar {
  justify-content: flex-end;
}

.prediction-filter-bar label {
  display: grid;
  gap: 5px;
  min-width: 120px;
}

.prediction-filter-bar select {
  min-height: 34px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: rgba(2, 6, 23, 0.72);
  color: var(--color-text-secondary);
  font: inherit;
  font-size: 0.78rem;
}

.prediction-whale-panel .table-scroll {
  border: 0;
  border-radius: 0;
  background: transparent;
}

.prediction-whale-panel .option-chain-table th,
.prediction-whale-panel .option-chain-table td {
  padding: 9px 12px;
  text-align: left;
}

body.light-theme-active .prediction-desk-command,
body.light-theme-active .prediction-market-panel,
body.light-theme-active .prediction-whale-panel,
body.light-theme-active .prediction-risk-card {
  border-color: var(--color-border-medium);
  background: rgba(255, 255, 255, 0.96);
}

body.light-theme-active .prediction-desk-copy h2,
body.light-theme-active .prediction-desk-strip strong,
body.light-theme-active .prediction-risk-card strong,
body.light-theme-active .prediction-panel-head .header-left h2,
body.light-theme-active .prediction-market-title {
  color: var(--color-text-primary);
}

body.light-theme-active .prediction-desk-copy span,
body.light-theme-active .prediction-desk-strip span,
body.light-theme-active .prediction-risk-card span,
body.light-theme-active .prediction-filter-bar label > span,
body.light-theme-active .prediction-filter-bar .asset-dropdown-container span {
  color: var(--color-text-secondary);
}

body.light-theme-active .prediction-desk-copy p,
body.light-theme-active .prediction-risk-card em,
body.light-theme-active .prediction-market-meta,
body.light-theme-active .prediction-gauge-label {
  color: var(--color-text-secondary);
}

body.light-theme-active .prediction-desk-strip,
body.light-theme-active .prediction-market-row,
body.light-theme-active .prediction-filter-bar select {
  border-color: var(--color-border-medium);
  background: var(--color-surface-elevated);
  color: var(--color-text-primary);
}

@media (max-width: 1100px) {
  .prediction-desk-command,
  .prediction-desk-grid {
    grid-template-columns: 1fr;
  }

  .prediction-desk-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .prediction-desk-strip,
