.tax-workbench .journal-btn { padding:7px 14px;min-height:0;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;border-radius: var(--radius-sm);background:var(--color-interactive-soft);color:var(--color-text-secondary);border-color:var(--color-border-subtle)}

/* covers: .tax-workbench .journal-btn:hover */
.tax-workbench .journal-btn:hover { border-color:var(--color-border-strong);background:var(--color-interactive-soft);color:var(--color-text-primary)}

/* covers: .tax-workbench .journal-btn.primary */
.tax-workbench .journal-btn.primary { background:var(--color-interactive);color:var(--color-text-inverse);border-color:var(--color-border-medium)}

/* covers: .tax-workbench .journal-btn.primary:hover:not(:disabled) */
.tax-workbench .journal-btn.primary:hover:not(:disabled) { background:var(--color-interactive);color:var(--color-text-inverse)}

/* covers: .tax-workbench .journal-btn.danger */
.tax-workbench .journal-btn.danger { color:var(--color-data-red-bright);border-color:#ef44444d;background:#7f1d1d4d}

/* covers: body.light-theme-active .tax-workbench .journal-btn */
body.light-theme-active .tax-workbench .journal-btn { background:var(--color-interactive-soft);color:var(--color-text-secondary);border-color:var(--color-border-subtle)}

/* covers: body.light-theme-active .tax-workbench .journal-btn.primary */
body.light-theme-active .tax-workbench .journal-btn.primary { background:var(--color-interactive);color:var(--color-text-inverse);border-color:var(--color-border-medium)}

/* covers: .tax-workbench-idea-apply[aria-pressed=true] */
.tax-workbench-idea-apply[aria-pressed=true] { background:var(--color-interactive-soft);border-color:var(--color-border-medium);color:var(--color-interactive)}

/* covers: .tax-workbench-cell:before */
.tax-workbench-cell:before { display:none;content:attr(data-label);font-size:.58rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:#ffffff5c}

/* covers: .analytics-curve-row em:before */
.analytics-curve-row em:before { content:"";position:absolute;left:0;right:96px;top:6px;height:2px;border-radius: var(--radius-full);background:var(--analytics-line)}

/* covers: body.light-theme-active .analytics-equities-matrix-table tbody tr:nth-child(2n), body.light-theme-active .analytics-commodity-table tbody tr:nth-child(2n) */
body.light-theme-active .analytics-equities-matrix-table tbody tr:nth-child(2n),body.light-theme-active .analytics-commodity-table tbody tr:nth-child(2n) { background:var(--color-surface-panel)!important}

/* covers: .guest-data-banner button[aria-busy=true] */
.guest-data-banner button:disabled,.guest-data-banner button[aria-busy=true] { opacity:.72;cursor:progress;transform:none}

/* covers: body.light-theme-active span, body.light-theme-active span */
body.light-theme-active .guest-workspace-hero span,body.light-theme-active .guest-preview-card header span,body.light-theme-active .guest-workflow-card header span,body.light-theme-active .guest-mission-copy span,body.light-theme-active  span,body.light-theme-active .tax-scenario-command span,body.light-theme-active .watchlist-intent-main span,body.light-theme-active  span,body.light-theme-active .tax-scenario-delta span { color:var(--color-text-secondary)}

/* covers: h3 */
.guest-mission-copy strong,.watchlist-intent-main h3, h3,.tax-scenario-command h3 { margin:0;color:var(--color-text-primary);font-size:15px;line-height:1.25}

/* covers: .tax-jurisdiction-combobox */
.tax-jurisdiction-combobox { display:grid;gap:5px;position:relative}

/* covers: .tax-jurisdiction-combobox>span */
.tax-jurisdiction-combobox>span { color:var(--color-text-muted);font-size:10px;font-weight:800;text-transform:uppercase}

/* covers: .tax-jurisdiction-trigger */
.tax-jurisdiction-trigger { display:inline-flex;align-items:center;gap:8px;min-height:38px;width:100%;padding:0 12px;border:1px solid var(--color-border-medium);border-radius:7px;background:var(--color-surface-elevated);color:var(--color-text-primary);font-weight:700;cursor:pointer;text-align:left}

/* covers: .tax-jurisdiction-trigger:hover */
.tax-jurisdiction-trigger:hover { border-color:var(--color-border-strong)}

/* covers: .tax-jurisdiction-caret */
.tax-jurisdiction-caret { margin-left:auto;color:var(--color-text-muted);font-size:10px}

/* covers: .tax-jurisdiction-popover */
.tax-jurisdiction-popover { position:absolute;z-index:40;top:calc(100% + 6px);left:0;right:0;min-width:240px;padding:8px;border:1px solid var(--color-border-medium);border-radius: var(--radius-xl);background:var(--color-surface-card);box-shadow:0 12px 32px #0006}

/* covers: .tax-jurisdiction-search */
.tax-jurisdiction-search { width:100%;min-height:34px;margin-bottom:6px;padding:0 10px;border:1px solid var(--color-border-medium);border-radius:7px;background:var(--color-surface-elevated);color:var(--color-text-primary)}

/* covers: .tax-jurisdiction-options */
.tax-jurisdiction-options { list-style:none;margin:0;padding:0;max-height:240px;overflow-y:auto;display:grid;gap:2px}

/* covers: .tax-jurisdiction-options button */
.tax-jurisdiction-options button { display:flex;align-items:center;gap:8px;width:100%;padding:8px 10px;border:0;border-radius:7px;background:transparent;color:var(--color-text-secondary);cursor:pointer;text-align:left}

/* covers: .tax-jurisdiction-options button:hover */
.tax-jurisdiction-options button:hover { background:var(--color-interactive-soft);color:var(--color-text-primary)}

/* covers: .tax-jurisdiction-options em */
.tax-jurisdiction-options em { margin-left:auto;font-style:normal;font-size:10px;color:var(--color-text-muted);text-transform:uppercase}

/* covers: .tax-jurisdiction-empty */
.tax-jurisdiction-empty { padding:10px;color:var(--color-text-muted);font-size:12px}

/* covers: body.light-theme-active .tax-jurisdiction-trigger */
body.light-theme-active .tax-jurisdiction-trigger { background:var(--color-surface-elevated);border-color:var(--color-border-medium);color:var(--color-text-primary)}

/* covers: body.light-theme-active .tax-jurisdiction-popover */
body.light-theme-active .tax-jurisdiction-popover { background:var(--color-surface-card);border-color:var(--color-border-medium);box-shadow:0 12px 32px #0000001f}

/* covers: body.light-theme-active .tax-jurisdiction-search */
body.light-theme-active .tax-jurisdiction-search { background:var(--color-surface-elevated);border-color:var(--color-border-medium);color:var(--color-text-primary)}

/* covers: body.light-theme-active .guest-mission-bar, body.light-theme-active .watchlist-intent-panel */
body.light-theme-active .guest-mission-bar,body.light-theme-active .watchlist-intent-panel,body.light-theme-active ,body.light-theme-active .tax-scenario-workbench { border-color:var(--color-border-medium);background:var(--color-surface-card)}

/* covers: body.light-theme-active strong */
body.light-theme-active .guest-mission-copy strong,body.light-theme-active .watchlist-intent-main h3,body.light-theme-active  h3,body.light-theme-active  strong,body.light-theme-active .tax-scenario-command h3,body.light-theme-active .tax-scenario-delta strong { color:var(--color-text-primary)}

/* covers: body.light-theme-active button, body.light-theme-active .tax-scenario-delta>div */
body.light-theme-active .guest-mission-steps button,body.light-theme-active  button,body.light-theme-active ,body.light-theme-active .tax-scenario-delta>div,body.light-theme-active .tax-scenario-controls select { background:var(--color-surface-card);border-color:var(--color-border-medium);color:var(--color-text-primary);opacity:1}

/* covers: body.light-theme-active span */
body.light-theme-active .guest-mission-steps small,body.light-theme-active  span,body.light-theme-active .watchlist-intent-main p,body.light-theme-active  p,body.light-theme-active .tax-scenario-command p,body.light-theme-active  small { color:var(--color-text-secondary)}

/* covers: body.page-dark-theme input:not([type=checkbox]):not([type=radio]) */
body.page-dark-theme input:not([type=checkbox]):not([type=radio]),body.page-dark-theme select,body.page-dark-theme textarea,body.page-dark-theme .search-controls,body.page-dark-theme .search-type-buttons { background:var(--color-surface-card)!important;border-color:var(--color-border-medium)!important}

/* covers: body.light-theme-active .journal-debrief-head .journal-btn, body.light-theme-active .journal-review-grid .journal-btn, body.light-theme-active .journal-day-view .journal-btn */
body.light-theme-active  .journal-btn,body.light-theme-active .journal-debrief-head .journal-btn,body.light-theme-active .journal-review-grid .journal-btn,body.light-theme-active .journal-day-view .journal-btn { background:var(--color-interactive)!important;border-color:var(--color-border-medium)!important;color:var(--color-text-inverse)!important}

/* covers: body.light-theme-active .journal-debrief-head .journal-btn:hover, body.light-theme-active .journal-review-grid .journal-btn:hover, body.light-theme-active .journal-day-view .journal-btn:hover */
body.light-theme-active  .journal-btn:hover,body.light-theme-active .journal-debrief-head .journal-btn:hover,body.light-theme-active .journal-review-grid .journal-btn:hover,body.light-theme-active .journal-day-view .journal-btn:hover { background:var(--color-interactive)!important;border-color:var(--color-border-strong)!important;color:var(--color-text-inverse)!important}


/* ─────────────────────────────────────────────────────────────────────────
   Asset Modal Refresh v2.0 — floating institutional research popup
   Monochrome, semantic tokens only. Spacing scale: 4/8/12/16/24px.
   ───────────────────────────────────────────────────────────────────────── */
.asset-modal-window {
  width: min(1160px, 100%);
  max-width: min(1160px, calc(100vw - 32px));
  max-height: 85vh;
  border-radius: var(--radius-2xl);
  border: 1px solid var(--color-border-medium);
  box-shadow: var(--shadow-3);
  background: var(--color-surface-card-strong);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  overflow: hidden;
  padding: 0;
}
.asset-modal-window-expanded {
  width: min(1240px, 100%);
  max-width: min(1240px, calc(100vw - 32px));
  max-height: 92vh;
}

/* Header — compact 72–88px */
.am-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border-subtle);
  min-height: 72px;
  max-height: 88px;
}
.am-header-main {
  display: flex;
  align-items: center;
  gap: 20px;
  min-width: 0;
}
.am-header-id { display: flex; flex-direction: column; gap: 2px; }
.am-name {
  margin: 0;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.1;
  color: var(--color-text-primary);
  letter-spacing: -0.01em;
}
.am-sub { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.am-company {
  font-size: 12px;
  color: var(--color-text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 320px;
  min-width: 0;
}
.am-exchange {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-muted);
  white-space: nowrap;
}
.am-provenance {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-full);
  padding: 1px 7px;
  white-space: nowrap;
}
.am-price-block {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding-left: 16px;
  margin-left: 4px;
  border-left: 1px solid var(--color-border-subtle);
}
.am-price {
  font-size: 18px;
  font-weight: 600;
  color: var(--color-text-primary);
  line-height: 1;
}
.am-change { font-size: 13px; font-weight: 600; line-height: 1; }
.am-change-pct { opacity: 0.8; margin-left: 4px; }
.am-pos { color: var(--color-success); }
.am-neg { color: var(--color-danger); }
.am-status { display: flex; flex-direction: column; gap: 1px; align-items: flex-start; }
.am-market-badge {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-medium);
}
.am-market-badge.am-open { color: var(--color-success); border-color: #10b98140; background: #10b98114; }
.am-market-badge.am-closed { color: var(--color-text-muted); }
.am-live { font-size: 10px; color: var(--color-text-dim); letter-spacing: 0.04em; }
.am-header-actions { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
.am-star-active { color: var(--color-warning) !important; }

/* Body grid — chart (65–70%) | portfolio context */
.am-body-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.9fr) minmax(280px, 320px);
  gap: 16px;
  padding: 16px;
  /* Context scrolls with the modal body (no independent trap). */
  overflow: visible;
  flex: 1 1 auto;
  min-height: 0;
}
/* Regulatory context (spec §3) spans the full grid width below chart+context. */
.am-regulatory-card {
  grid-column: 1 / -1;
  border: 1px solid var(--border-soft, rgba(255,255,255,0.08));
  border-radius: var(--radius-xl);
  padding: 12px 14px;
  background: var(--panel-2, rgba(255,255,255,0.02));
}
.am-regulatory-card--empty { opacity: 0.7; }
.am-regulatory-head {
  display: flex; justify-content: space-between; align-items: baseline;
  margin-bottom: 8px;
}
.am-regulatory-title { font-weight: 600; font-size: 12px; letter-spacing: 0.04em; text-transform: uppercase; color: var(--text-dim, #9aa0a6); }
.am-freshness { font-size: 11px; color: var(--text-dim, #9aa0a6); }
.am-freshness--unavailable { color: var(--warn, #d9a441); }
.am-regulatory-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin: 0; }
.am-regulatory-row { display: flex; flex-direction: column; gap: 2px; }
.am-regulatory-row dt { font-size: 11px; color: var(--text-dim, #9aa0a6); }
.am-regulatory-row dd { margin: 0; font-size: 13px; font-weight: 600; }
.am-insider--buy { color: var(--pos, #4caf80); }
.am-insider--sell { color: var(--neg, #e06b6b); }
@media (max-width: 720px) {
  .am-regulatory-grid { grid-template-columns: repeat(2, 1fr); }
}
.asset-modal-window:not(.asset-modal-window-expanded) .am-body-grid {
  overflow-y: auto;
}

/* Chart section */
.am-chart-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
}
.am-chart-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
.am-data-health { display: flex; align-items: center; gap: 8px; }
.am-source-chip {
  font-size: 10px;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-full);
  padding: 2px 8px;
}
.am-health-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-muted);
}
.am-health-badge.ok { color: var(--color-success); }
.am-health-badge.hazard { color: var(--color-warning); }
.am-health-badge.loading { color: var(--color-text-muted); }
.am-spinner { display: inline-block; }
.am-spinner.spin { animation: am-spin 0.8s linear infinite; }
@keyframes am-spin { to { transform: rotate(360deg); } }
.am-chart-controls { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.am-type-toggle, .am-interval-pill { display: inline-flex; gap: 2px; background: var(--color-surface-elevated); border: 1px solid var(--color-border-subtle); border-radius: var(--radius-md); padding: 2px; }
.am-type-toggle button, .am-interval-pill button {
  background: transparent;
  border: none;
  color: var(--color-text-muted);
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.am-type-toggle button:hover, .am-interval-pill button:hover { color: var(--color-text-secondary); background: var(--color-surface-hover); }
.am-type-toggle button.active, .am-interval-pill button.active {
  background: var(--color-interactive-soft);
  color: var(--color-text-primary);
}
.am-ind-group {
  display: inline-flex;
  gap: 2px;
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  padding: 2px;
}
.am-ind-toggle {
  background: transparent;
  border: none;
  color: var(--color-text-muted);
  min-width: 38px;
  height: 26px;
  font-size: 11px;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
  padding: 5px 10px;
  transition: background 0.15s, color 0.15s;
}
.am-ind-toggle:hover { color: var(--color-text-secondary); background: var(--color-surface-hover); }
.am-ind-toggle.on { color: var(--color-text-primary); border-color: var(--color-border-medium); background: var(--color-interactive-soft); }
.am-expand-btn {
  background: var(--color-surface-elevated);
  border: 1px solid var(--color-border-subtle);
  color: var(--color-text-muted);
  width: 30px; height: 26px;
  font-size: 14px;
  border-radius: var(--radius-sm);
  cursor: pointer;
}
.am-expand-btn:hover { color: var(--color-text-primary); }
.am-chart-container {
  position: relative;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: var(--color-surface-depth);
  overflow: hidden;
  min-height: 300px;
}
.am-chart-loader, .am-chart-refresh {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  color: var(--color-text-muted);
  font-size: 24px;
}
.am-chart-empty { display: flex; align-items: center; justify-content: center; height: 100%; color: var(--color-text-muted); font-size: 13px; }
.am-chart-empty--compact { padding: 16px; text-align: center; }
.am-chart-range { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--color-text-muted); }
.am-range-label { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 600; }
.am-interval-row { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.am-interval-pill {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding-top: 6px;
  padding-bottom: 6px;
}
.am-perf-badge {
  font-size: 9px;
  line-height: 1;
  color: var(--color-text-dim);
  font-weight: 500;
}
.am-perf-badge.am-pos { color: var(--color-success); }
.am-perf-badge.am-neg { color: var(--color-danger); }

/* Portfolio context (right column) */
.am-context {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: var(--color-surface-panel);
  padding: 12px;
  /* Spec §1: context is a readable 280–320px column that scrolls WITH the
     modal body (no independent scroll region that can trap the keyboard). */
  align-self: start;
  width: 100%;
  max-width: 320px;
  min-width: 280px;
  position: sticky;
  top: 0;
  max-height: none;
  overflow: visible;
}
.am-context-head {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--color-text-muted);
  margin-bottom: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--color-border-subtle);
}
.am-context-list { margin: 0; display: flex; flex-direction: column; gap: 8px; }
.am-context-group { margin-top: 12px; }
.am-context-group:first-of-type { margin-top: 4px; }
.am-context-group-head {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-text-dim);
  padding-top: 10px;
  margin-bottom: 8px;
  border-top: 1px solid var(--color-border-subtle);
}
.am-context-group:first-of-type .am-context-group-head { border-top: none; padding-top: 0; }
.am-context-row { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.am-context-label { font-size: 11px; color: var(--color-text-muted); }
.am-context-value { margin: 0; font-size: 12px; font-weight: 600; color: var(--color-text-primary); text-align: right; }
.am-context-emphasis { font-size: 13px; }
.am-na { color: var(--color-text-dim); font-weight: 400; }

/* ── Kind-specific modal summaries (FX pair / currency / ETF) ──
   Brand v2 monochrome: no color-coded metrics, no fabricated data.
   Tier layout mirrors CommodityModalSummary for visual consistency. */
.fx-pair-summary,
.currency-modal-summary,
.etf-modal-summary {
  margin: 0 16px;
  padding: 14px 0 4px;
  border-bottom: 1px solid var(--color-border-subtle);
}
.fxs-tier,
.cms-tier,
.ems-tier { margin-bottom: 12px; }
.fxs-metrics,
.cms-metrics,
.ems-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 8px 20px;
  margin: 8px 0 0;
}
.fxs-row,
.cms-row,
.ems-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px dotted var(--color-border-subtle);
  padding-bottom: 4px;
}
.fxs-label,
.cms-label,
.ems-label {
  font-size: 11px;
  color: var(--color-text-muted);
  white-space: nowrap;
}
.fxs-value,
.cms-value,
.ems-value {
  margin: 0;
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text-primary);
  text-align: right;
}
.fxs-pair,
.ems-sym { font-size: 15px; font-weight: 700; letter-spacing: 0.02em; }
.fxs-name,
.ems-name { display: block; font-size: 12px; margin-top: 2px; }
.fxs-identity,
.ems-head { margin-bottom: 8px; }
.fxs-meta,
.cms-notes { font-size: 11px; color: var(--color-text-muted); margin-top: 6px; }

/* Currency research-only banner (spec §4) */
.cms-banner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-sm);
  background: var(--color-surface-raised);
  margin-bottom: 10px;
}
.cms-banner-tag {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 2px 8px;
  border: 1px solid var(--color-border-strong);
  border-radius: var(--radius-full);
}
.cms-sub { color: var(--color-text-muted); font-weight: 400; font-size: 10px; }
.cms-crosses { list-style: none; margin: 8px 0 0; padding: 0; display: flex; flex-wrap: wrap; gap: 6px; }
.cms-cross-btn {
  font-size: 12px;
  font-weight: 600;
  font-family: var(--font-mono);
  padding: 4px 10px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-sm);
  background: var(--color-surface-panel);
  color: var(--color-text-primary);
  cursor: pointer;
}
.cms-cross-btn:hover { border-color: var(--color-border-strong); }
.cms-crosses-head { font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.1em; color: var(--color-text-muted); margin-bottom: 4px; }
.ems-note { font-size: 11px; margin-top: 6px; }
.etf-modal-summary .ems-tier-2 {
  padding-top: 8px;
  border-top: 1px solid var(--color-border-subtle);
}
.am-etf-overview-note {
  color: var(--color-text-muted) !important;
  font-size: 12px !important;
}

/* Research tabs */
.am-tabs { border-top: 1px solid var(--color-border-subtle); display: flex; flex-direction: column; }
.am-tab-bar {
  display: flex;
  gap: 2px;
  padding: 0 16px;
  border-bottom: 1px solid var(--color-border-subtle);
  overflow-x: auto;
}
.am-tab {
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--color-text-muted);
  padding: 10px 14px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: color 0.15s, border-color 0.15s;
}
.am-tab:hover { color: var(--color-text-secondary); }
.am-tab.active { color: var(--color-text-primary); border-bottom-color: var(--color-interactive); }
.am-tab-panel { padding: 16px; overflow-y: auto; max-height: 38vh; }
.am-tab-content { display: flex; flex-direction: column; gap: 16px; }
.am-summary p { margin: 0 0 8px; font-size: 13px; line-height: 1.5; color: var(--color-text-secondary); }
.am-link-btn {
  background: none; border: none; color: var(--color-interactive);
  font-size: 12px; font-weight: 600; cursor: pointer; padding: 0;
}
.am-link-btn:hover { text-decoration: underline; }
.am-stat-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.am-stat { display: flex; flex-direction: column; gap: 4px; }
.am-stat-label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--color-text-muted); }
.am-stat-value { font-size: 14px; font-weight: 600; color: var(--color-text-primary); }

/* Financials */
.am-fin-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px 24px; }
.am-fin-group { display: flex; flex-direction: column; gap: 4px; }
.am-fin-title { font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.12em; color: var(--color-text-muted); margin-bottom: 4px; }
.am-fin-row { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; padding: 4px 0; border-bottom: 1px solid var(--color-border-subtle); }
.am-fin-label { font-size: 12px; color: var(--color-text-secondary); }
.am-fin-value { font-size: 12px; font-weight: 600; color: var(--color-text-primary); }
.am-stale-note { font-size: 11px; color: var(--color-warning); margin-bottom: 8px; }

/* Empty states (no fabricated data) */
.am-empty-state { display: flex; flex-direction: column; gap: 8px; padding: 8px 0; }
.am-empty-title { margin: 0; font-size: 13px; font-weight: 600; color: var(--color-text-primary); }
.am-empty-hint { margin: 0; font-size: 12px; line-height: 1.5; color: var(--color-text-muted); }
.am-empty-list { margin: 4px 0 0; padding-left: 16px; display: flex; flex-direction: column; gap: 4px; }
.am-empty-item { font-size: 12px; color: var(--color-text-secondary); }

/* Research toolbar */
.am-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  border-top: 1px solid var(--color-border-subtle);
  background: var(--color-surface-panel);
  position: sticky;
  bottom: 0;
}
.am-toolbar-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.am-action-active { border-color: var(--color-border-medium) !important; }
.am-toolbar-overflow { position: relative; }
.am-toolbar-overflow summary {
  list-style: none;
  cursor: pointer;
  min-height: 32px;
  padding: 7px 10px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  color: var(--color-text-secondary);
  font-size: 12px;
  font-weight: 600;
}
.am-toolbar-overflow summary::-webkit-details-marker { display: none; }
.am-toolbar-overflow[open] summary { border-color: var(--color-border-medium); color: var(--color-text-primary); }
.am-toolbar-overflow-menu {
  position: absolute;
  z-index: 3;
  bottom: calc(100% + 8px);
  left: 0;
  display: grid;
  min-width: 188px;
  padding: 6px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: var(--color-surface-card-strong);
  box-shadow: var(--shadow-2);
}
.am-toolbar-overflow-menu button { justify-content: flex-start; }

/* Responsive */
@media (max-width: 900px) {
  .am-body-grid { grid-template-columns: 1fr; }
  .am-context { max-height: none; }
  .am-stat-grid { grid-template-columns: repeat(2, 1fr); }
  .am-fin-grid { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .asset-modal-window { width: 100%; max-width: 100%; max-height: 100vh; height: 100vh; border-radius: 0; }
  .am-header { flex-direction: column; align-items: flex-start; gap: 8px; max-height: none; }
  .am-body-grid { overflow-y: auto; }
  .am-stat-grid { grid-template-columns: 1fr; }
  .am-tab-panel { max-height: none; }
  .am-toolbar { position: sticky; bottom: 0; }
  .etf-modal-summary { margin: 0 12px; padding-top: 12px; }
  .etf-modal-summary .ems-metrics { grid-template-columns: 1fr; gap: 6px; }
  .am-toolbar-actions { width: 100%; }
  .am-toolbar-actions > button { flex: 1 1 calc(50% - 4px); }
  .am-toolbar-overflow { flex: 1 1 calc(50% - 4px); }
  .am-toolbar-overflow summary { display: flex; align-items: center; justify-content: center; }
  .am-toolbar-overflow-menu { left: auto; right: 0; }
}

/* ════════════════════════════════════════════════════════════════════════
   Asset Comparison Workspace
   Full-page research mode (never a modal). Dark monochrome, Brandv2 tokens.
   Layout: header (full) → body (sidebar | canvas | insights rail).
   ════════════════════════════════════════════════════════════════════════ */
.cmp-view-container { height: 100%; }
.cmp-workspace {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  background: var(--color-surface-card-strong);
  color: var(--color-text-primary);
}
.cmp-workspace-empty,
.cmp-workspace-picking {
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  gap: 16px;
}
.cmp-empty-title { font-size: 22px; font-weight: 600; margin: 0; }
.cmp-empty-copy { color: var(--color-text-muted); margin: 0; max-width: 460px; text-align: center; }

/* Header */
.cmp-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 24px;
  border-bottom: 1px solid var(--color-border-medium);
  flex-wrap: wrap;
}
.cmp-header-assets { display: flex; align-items: center; gap: 14px; }
.cmp-header-asset { display: flex; flex-direction: column; min-width: 120px; }
.cmp-header-sym { font-size: 18px; font-weight: 700; letter-spacing: 0.02em; }
.cmp-header-name { font-size: 12px; color: var(--color-text-muted); }
.cmp-header-vs { font-size: 13px; font-weight: 700; color: var(--color-text-muted); padding: 4px 8px; border: 1px solid var(--color-border-medium); border-radius: var(--radius-full); }
.cmp-header-actions { display: flex; gap: 10px; flex-wrap: wrap; }

/* Body: 3 columns */
.cmp-body {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr) 280px;
  flex: 1 1 auto;
  min-height: 0;
}
.cmp-sidebar {
  border-right: 1px solid var(--color-border-medium);
  padding: 16px 14px;
  overflow-y: auto;
}
.cmp-sidebar-title { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--color-text-muted); padding: 0 8px 8px; }
.cmp-sidebar-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.cmp-sidebar-item {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  color: var(--color-text-secondary, #b8b8b8);
  padding: 9px 12px;
  border-radius: var(--radius-lg);
  font-size: 13px;
  cursor: pointer;
}
.cmp-sidebar-item:hover { background: rgba(255,255,255,0.05); color: var(--color-text-primary); }
.cmp-sidebar-item.active { background: rgba(255,255,255,0.08); color: var(--color-text-primary); font-weight: 600; }

.cmp-canvas { padding: 24px 28px; overflow-y: auto; min-width: 0; }
.cmp-section { display: flex; flex-direction: column; gap: 14px; }
.cmp-section-title { font-size: 18px; font-weight: 600; margin: 0 0 4px; }
.cmp-section-empty {
  padding: 18px;
  border: 1px dashed var(--color-border-medium);
  border-radius: var(--radius-lg);
  color: var(--color-text-muted);
  font-size: 13px;
  background: rgba(255,255,255,0.02);
}
.cmp-section-note { font-size: 12px; color: var(--color-text-muted); padding: 8px 0; }

/* Metric table: Asset A | Δ | Asset B */
.cmp-metric-table { display: flex; flex-direction: column; border: 1px solid var(--color-border-medium); border-radius: var(--radius-lg); overflow: hidden; }
.cmp-metric-caption { padding: 8px 12px; font-size: 12px; color: var(--color-text-muted); border-bottom: 1px solid var(--color-border-medium); background: rgba(255,255,255,0.02); }
.cmp-metric-head, .cmp-metric-row { display: grid; grid-template-columns: 1fr 90px 1fr; align-items: center; }
.cmp-metric-head { padding: 8px 12px; font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--color-text-muted); border-bottom: 1px solid var(--color-border-medium); }
.cmp-metric-row { padding: 11px 14px; border-bottom: 1px solid rgba(255,255,255,0.05); font-size: 14px; }
.cmp-metric-row:last-child { border-bottom: none; }
.cmp-col { font-variant-numeric: tabular-nums; }
.cmp-col-diff { text-align: center; color: var(--color-text-muted); font-size: 12px; }
.cmp-col-a { text-align: left; }
.cmp-col-b { text-align: right; }
.cmp-win { font-weight: 700; color: var(--color-text-primary); }
.cmp-win::after { content: " ◄"; color: var(--color-data-up); font-size: 10px; }

/* Performance chart */
.cmp-chart { border: 1px solid var(--color-border-medium); border-radius: var(--radius-lg); padding: 10px; }
.cmp-chart-svg { width: 100%; height: 260px; display: block; }
.cmp-chart-empty { padding: 24px; text-align: center; color: var(--color-text-muted); border: 1px dashed var(--color-border-medium); border-radius: var(--radius-lg); }
.cmp-chart-legend { display: flex; gap: 16px; margin-top: 8px; font-size: 12px; color: var(--color-text-muted); }
.cmp-legend-a::before { content: "■ "; color: var(--color-data-up); }
.cmp-legend-b::before { content: "■ "; color: var(--color-data-down); }

/* Overview verdict */
.cmp-overview-verdict { display: flex; gap: 18px; align-items: baseline; }
.cmp-overview-winner { font-size: 16px; }
.cmp-overview-confidence { font-size: 13px; color: var(--color-text-muted); }
.cmp-overview-reasons { margin: 8px 0 0; padding-left: 18px; display: flex; flex-direction: column; gap: 4px; font-size: 14px; }

/* Insights rail */
.cmp-insights { border-left: 1px solid var(--color-border-medium); padding: 18px 16px; overflow-y: auto; }
.cmp-insights-title { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--color-text-muted); margin-bottom: 10px; }
.cmp-insights-verdict { border: 1px solid var(--color-border-medium); border-radius: var(--radius-lg); padding: 12px; margin-bottom: 14px; }
.cmp-insights-winner { font-size: 15px; }
.cmp-insights-confidence { font-size: 12px; color: var(--color-text-muted); margin: 4px 0 8px; }
.cmp-insights-reasons { margin: 0; padding-left: 16px; font-size: 13px; display: flex; flex-direction: column; gap: 3px; }
.cmp-insights-empty { font-size: 13px; color: var(--color-text-muted); }
.cmp-insights-actions { display: flex; flex-direction: column; gap: 6px; }
.cmp-insights-btn { background: transparent; border: 1px solid var(--color-border-medium); color: var(--color-text-secondary, #b8b8b8); border-radius: var(--radius-lg); padding: 8px; font-size: 13px; cursor: pointer; }
.cmp-insights-btn:hover { background: rgba(255,255,255,0.05); color: var(--color-text-primary); }

/* Picker */
.cmp-picker { width: 420px; max-width: 92vw; background: var(--color-surface-card-strong); border: 1px solid var(--color-border-medium); border-radius: var(--radius-xl); padding: 16px; display: flex; flex-direction: column; gap: 12px; }
.cmp-picker-head { display: flex; justify-content: space-between; align-items: center; font-size: 15px; font-weight: 600; }
.cmp-picker-cancel { background: transparent; border: none; color: var(--color-text-muted); font-size: 16px; cursor: pointer; }
.cmp-picker-input { background: rgba(255,255,255,0.04); border: 1px solid var(--color-border-medium); border-radius: var(--radius-lg); padding: 10px 12px; color: var(--color-text-primary); font-size: 14px; }
.cmp-picker-status { font-size: 13px; color: var(--color-text-muted); }
.cmp-picker-error { color: var(--color-data-down); }
.cmp-picker-results { display: flex; flex-direction: column; gap: 6px; max-height: 320px; overflow-y: auto; }
.cmp-picker-item { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; background: rgba(255,255,255,0.03); border: 1px solid var(--color-border-medium); border-radius: var(--radius-lg); padding: 10px 12px; cursor: pointer; text-align: left; }
.cmp-picker-item:hover { background: rgba(255,255,255,0.07); }
.cmp-picker-sym { font-weight: 700; font-size: 14px; }
.cmp-picker-name { font-size: 12px; color: var(--color-text-muted); }

/* Misc section bits */
.cmp-ai-prompts { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px; }
.cmp-ai-prompt { padding: 8px 10px; border: 1px solid var(--color-border-medium); border-radius: var(--radius-lg); font-size: 13px; color: var(--color-text-secondary, #b8b8b8); }
.cmp-decision-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.cmp-decision-btn { background: rgba(255,255,255,0.03); border: 1px solid var(--color-border-medium); color: var(--color-text-muted); border-radius: var(--radius-lg); padding: 8px 12px; font-size: 13px; cursor: not-allowed; }
.cmp-toast { position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); background: var(--color-surface-card-strong); border: 1px solid var(--color-border-medium); color: var(--color-text-primary); padding: 10px 18px; border-radius: var(--radius-lg); font-size: 13px; z-index: 200; box-shadow: 0 8px 24px rgba(0,0,0,0.4); }

/* Responsive: stack on narrow widths */
@media (max-width: 1080px) {
  .cmp-body { grid-template-columns: 180px minmax(0, 1fr); }
  .cmp-insights { display: none; }
}
@media (max-width: 720px) {
  .cmp-body { grid-template-columns: 1fr; }
  .cmp-sidebar { display: none; }
  .cmp-metric-head, .cmp-metric-row { grid-template-columns: 1fr 64px 1fr; }
}

/* ═══ Workspace shared primitives (ARW) — monochrome, token-driven ═══ */
.workspace-layout {
  display: flex;
  flex-direction: column;
  min-height: 0;
  height: 100%;
}
.workspace-layout-header {
  flex: 0 0 auto;
  border-bottom: 1px solid var(--color-border-subtle);
  background: var(--color-surface-raised);
}
.workspace-layout-body {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: 232px minmax(0, 1fr) 320px;
  min-height: 0;
  overflow: hidden;
}
.workspace-layout-sidebar {
  border-right: 1px solid var(--color-border-subtle);
  background: var(--color-surface-raised);
  padding: 14px 12px;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.workspace-layout-main {
  min-width: 0;
  overflow: auto;
  padding: 22px 28px;
}
.workspace-layout-rail {
  border-left: 1px solid var(--color-border-subtle);
  background: var(--color-surface-raised);
  padding: 16px 14px;
  overflow: auto;
}
.ws-nav-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  text-align: left;
  background: transparent;
  border: 0;
  border-radius: var(--radius-lg);
  padding: 9px 12px;
  color: var(--color-text-secondary);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.ws-nav-item:hover { background: var(--color-surface-card); }
.ws-nav-item.active {
  background: var(--color-surface-card-strong);
  color: var(--color-text-primary);
}
.ws-nav-item .ws-nav-count {
  font-size: 11px;
  color: var(--color-text-muted);
  font-weight: 700;
}

.ws-section { margin-bottom: 22px; }
.ws-section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 12px;
  margin-bottom: 10px;
}
.ws-section-head h2 { font-size: 16px; margin: 0; }
.ws-section-head p { margin: 2px 0 0; color: var(--color-text-muted); font-size: 12px; }

.ws-panel {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-xl);
  background: var(--color-surface-card);
  margin-bottom: 16px;
  overflow: hidden;
}
.ws-panel-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--color-border-subtle);
}
.ws-panel-head h3 { font-size: 14px; margin: 0; }
.ws-panel-meta { color: var(--color-text-muted); font-size: 12px; }
.ws-panel-body { padding: 14px; }
.ws-panel-footer { padding: 10px 14px; border-top: 1px solid var(--color-border-subtle); }

.ws-metric-card {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 12px 14px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-xl);
  background: var(--color-surface-card);
  min-width: 150px;
}
.ws-metric-label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-muted); }
.ws-metric-value { font-size: 20px; }
.ws-metric-helper { font-size: 12px; color: var(--color-text-muted); }

.ws-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-subtle);
  font-size: 11px;
  font-weight: 700;
  background: var(--color-surface-card);
  color: var(--color-text-secondary);
}
.ws-badge.positive,
.ws-badge.negative,
.ws-badge.warning { border-color: var(--color-border-strong); color: var(--color-text-primary); }

.ws-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-subtle);
  font-size: 11px;
  background: var(--color-surface-card);
  color: var(--color-text-secondary);
}
.ws-tag-remove {
  border: 0; background: transparent; cursor: pointer;
  color: var(--color-text-muted); font-size: 13px; line-height: 1; padding: 0;
}

.ws-insight-card {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-xl);
  background: var(--color-surface-card);
  padding: 12px 14px;
  margin-bottom: 10px;
}
.ws-insight-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; margin-bottom: 6px; }
.ws-insight-head h4 { font-size: 13px; margin: 0; }
.ws-insight-meta { font-size: 11px; color: var(--color-text-muted); }
.ws-insight-body { font-size: 12px; color: var(--color-text-secondary); }

.ws-skeleton { display: flex; flex-direction: column; gap: 8px; padding: 4px 0; }
.ws-skeleton-line {
  height: 10px;
  border-radius: var(--radius-lg);
  background: var(--color-surface-card-strong);
  opacity: 0.7;
}

.ws-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.ws-table th, .ws-table td {
  text-align: left;
  padding: 8px 10px;
  border-bottom: 1px solid var(--color-border-subtle);
}
.ws-table th { color: var(--color-text-muted); font-weight: 700; }

@media (max-width: 1100px) {
  .workspace-layout-body { grid-template-columns: 200px minmax(0, 1fr); }
  .workspace-layout-rail { display: none; }
}
@media (max-width: 768px) {
  .workspace-layout-body { grid-template-columns: minmax(0, 1fr); }
  .workspace-layout-sidebar { display: none; }
}

/* ============================================================
   vNext shared primitives (ARW + Compare) — monochrome, Brandv2
   Reuses existing --color-* tokens; no bespoke colors.
   ============================================================ */

/* ResearchCard — linked research object */
.ws-research-card {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg, 12px);
  background: var(--color-surface-card-strong, #141414);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  cursor: default;
}
.ws-research-card[role="button"] { cursor: pointer; }
.ws-research-card[role="button"]:hover { border-color: var(--color-border-strong); }
.ws-research-card-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ws-research-card-head h4 { margin: 0; font-size: 13px; font-weight: 700; color: var(--color-text-primary); }
.ws-research-card-meta { margin: 0; font-size: 12px; color: var(--color-text-secondary); }
.ws-research-card-facts { display: flex; flex-wrap: wrap; gap: 10px 16px; font-size: 11px; color: var(--color-text-secondary); }
.ws-research-card-facts em { color: var(--color-text-muted, #6b6b6b); font-style: normal; margin-right: 4px; text-transform: uppercase; letter-spacing: 0.04em; font-size: 10px; }
.ws-research-card-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.ws-research-card-links { display: flex; flex-wrap: wrap; gap: 6px; }
.ws-link-chip { font-size: 10px; color: var(--color-text-secondary); border: 1px solid var(--color-border-subtle, #1f1f1f); border-radius: var(--radius-full); padding: 2px 8px; }

/* EvidenceCard */
.ws-evidence-card {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md, 8px);
  background: var(--color-surface-card, #111111);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ws-evidence-card.weight-low { border-left-color: var(--color-border-strong); }
.ws-evidence-card.weight-med { border-left-color: var(--color-text-secondary); }
.ws-evidence-card.weight-high { border-left-color: var(--color-text-primary); }
.ws-evidence-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ws-evidence-head h5 { margin: 0; font-size: 12px; font-weight: 700; color: var(--color-text-primary); }
.ws-evidence-card p { margin: 0; font-size: 12px; color: var(--color-text-secondary); }
.ws-evidence-foot { display: flex; justify-content: space-between; gap: 8px; font-size: 10px; color: var(--color-text-muted, #6b6b6b); text-transform: uppercase; letter-spacing: 0.04em; }

/* RiskCard */
.ws-risk-card {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md, 8px);
  background: var(--color-surface-card, #111111);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ws-risk-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ws-risk-head h5 { margin: 0; font-size: 12px; font-weight: 700; color: var(--color-text-primary); }
.ws-risk-likelihood, .ws-risk-mitigation { margin: 0; font-size: 12px; color: var(--color-text-secondary); }
.ws-risk-likelihood em { color: var(--color-text-muted, #6b6b6b); font-style: normal; margin-right: 4px; }

/* CatalystCard */
.ws-catalyst-card {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md, 8px);
  background: var(--color-surface-card, #111111);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.ws-catalyst-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ws-catalyst-head h5 { margin: 0; font-size: 12px; font-weight: 700; color: var(--color-text-primary); }
.ws-catalyst-date { font-size: 11px; color: var(--color-text-secondary); }
.ws-catalyst-note { margin: 0; font-size: 12px; color: var(--color-text-secondary); }

/* NewsCard */
.ws-news-card { border-bottom: 1px solid var(--color-border-subtle, #1f1f1f); padding: 10px 0; }
.ws-news-link { text-decoration: none; color: inherit; display: block; }
.ws-news-link:hover .ws-news-head h5 { text-decoration: underline; }
.ws-news-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.ws-news-head h5 { margin: 0; font-size: 13px; font-weight: 600; color: var(--color-text-primary); }
.ws-news-source { font-size: 11px; color: var(--color-text-muted, #6b6b6b); white-space: nowrap; }
.ws-news-summary { margin: 4px 0 0; font-size: 12px; color: var(--color-text-secondary); }

/* DocumentCard */
.ws-doc-card { border: 1px solid var(--color-border-medium); border-radius: var(--radius-md, 8px); background: var(--color-surface-card, #111111); padding: 10px 12px; }
.ws-doc-card[role="button"] { cursor: pointer; }
.ws-doc-card[role="button"]:hover { border-color: var(--color-border-strong); }
.ws-doc-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ws-doc-head h5 { margin: 0; font-size: 12px; font-weight: 700; color: var(--color-text-primary); }
.ws-doc-meta { margin: 4px 0 0; font-size: 11px; color: var(--color-text-secondary); }

/* Timeline */
.ws-timeline { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.ws-timeline-item { display: grid; grid-template-columns: 14px 1fr; gap: 10px; padding: 10px 0; border-bottom: 1px solid var(--color-border-subtle, #1f1f1f); }
.ws-timeline-marker { width: 10px; height: 10px; border-radius: 50%; border: 1px solid var(--color-border-strong); background: var(--color-surface-raised, #1a1a1a); margin-top: 4px; }
.ws-timeline-item.kind-decision .ws-timeline-marker,
.ws-timeline-item.kind-earnings .ws-timeline-marker { background: var(--color-text-primary); }
.ws-timeline-item.kind-risk .ws-timeline-marker,
.ws-timeline-item.kind-news .ws-timeline-marker { border-color: var(--color-text-secondary); }
.ws-timeline-row { display: flex; align-items: center; gap: 8px; }
.ws-timeline-kind { font-size: 10px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-text-muted, #6b6b6b); }
.ws-timeline-time { font-size: 11px; color: var(--color-text-secondary); }
.ws-timeline-content h5 { margin: 2px 0 0; font-size: 13px; font-weight: 600; color: var(--color-text-primary); }
.ws-timeline-meta { margin: 2px 0 0; font-size: 12px; color: var(--color-text-secondary); }
.ws-timeline-empty { color: var(--color-text-muted, #6b6b6b); font-size: 12px; padding: 12px 0; }

/* ComparisonMatrix — decision-matrix centerpiece */
.ws-comparison-matrix { border: 1px solid var(--color-border-medium); border-radius: var(--radius-lg, 12px); background: var(--color-surface-card, #111111); overflow: hidden; }
.ws-matrix-grid { display: grid; grid-template-columns: minmax(140px, 1.4fr) 1fr 84px 1fr; }
.ws-matrix-head, .ws-matrix-row { display: contents; }
.ws-matrix-head > span {
  padding: 10px 12px; font-size: 10px; text-transform: uppercase; letter-spacing: 0.05em;
  color: var(--color-text-muted, #6b6b6b); border-bottom: 1px solid var(--color-border-medium); background: var(--color-surface-card-strong, #141414);
}
.ws-matrix-head .ws-matrix-winner { text-align: center; }
.ws-matrix-row > span {
  padding: 14px; border-bottom: 1px solid var(--color-border-subtle, #1f1f1f); font-size: 13px;
  display: flex; flex-direction: column; gap: 5px; justify-content: center;
}
.ws-matrix-dim strong { color: var(--color-text-primary); font-weight: 600; }
.ws-matrix-weight { font-size: 10px; color: var(--color-text-muted, #6b6b6b); font-style: normal; margin-left: 6px; }
.ws-matrix-score { color: var(--color-text-secondary); }
.ws-matrix-score strong { color: var(--color-text-primary); font-size: 15px; font-family: var(--font-mono, monospace); }
.ws-matrix-score.is-winner { background: var(--color-surface-raised, #1a1a1a); }
.ws-matrix-score.is-winner::before { content: "▲ "; color: var(--color-text-primary); font-size: 10px; }
.ws-matrix-winner-cell { align-items: center; text-align: center; }
.ws-matrix-confidence { font-size: 10px; color: var(--color-text-muted, #6b6b6b); font-style: normal; }
.ws-matrix-evidence { font-size: 11px; color: var(--color-text-muted, #6b6b6b); font-weight: 400; }
.ws-matrix-explanations { padding: 12px; display: flex; flex-direction: column; gap: 6px; border-top: 1px solid var(--color-border-medium); }
.ws-matrix-explanation-row { margin: 0; font-size: 12px; color: var(--color-text-secondary); }
.ws-matrix-explanation-row strong { color: var(--color-text-primary); }
.ws-matrix-empty { color: var(--color-text-muted, #6b6b6b); font-size: 12px; padding: 16px; }

@media (max-width: 1100px) {
  .ws-matrix-grid { grid-template-columns: minmax(110px, 1.2fr) 1fr 70px 1fr; }
}

/* ============================================================
   ARW (Asset Research Workspace) vNext — rich header + layout
   Monochrome, Brandv2; reuse .ws-* tokens.
   ============================================================ */
.font-mono { font-family: var(--font-mono, "JetBrains Mono", monospace); }

.arw-header-meta { display: inline-flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.arw-header-meta strong { font-size: 16px; color: var(--color-text-primary); }

.arw-asset-header {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg, 12px);
  background: var(--color-surface-card-strong, #141414);
  padding: 16px 18px;
  margin-bottom: 18px;
}
.arw-asset-facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 12px 20px;
}
.arw-asset-facts span { display: flex; flex-direction: column; font-size: 12px; color: var(--color-text-secondary); }
.arw-asset-facts em { font-style: normal; text-transform: uppercase; letter-spacing: 0.04em; font-size: 10px; color: var(--color-text-muted, #6b6b6b); margin-bottom: 2px; }
.arw-asset-foot { margin-top: 10px; display: flex; justify-content: space-between; font-size: 11px; color: var(--color-text-muted, #6b6b6b); }
.arw-asset-loading { color: var(--color-text-secondary); }

.arw-sidebar { display: flex; flex-direction: column; gap: 2px; }

/* ── CapabilityStatusCard (Corrections 1/13) ─────────────────────────
   Replaces all Ghost / "Provider Pending" placeholders. Monochrome; state
   accent via left border using token colors. */
.capability-card { background: var(--color-surface-card, #111111); border: 1px solid var(--color-border-subtle, rgba(255,255,255,0.06)); border-radius: var(--radius-xl, 12px); padding: var(--space-5, 20px); display: flex; flex-direction: column; gap: 14px; }
.capability-card.cap-positive { background: var(--color-success-soft, var(--color-surface-card, #111111)); border-color: var(--color-success-border, var(--color-border-subtle)); }
.capability-card.cap-watch { background: var(--color-warning-soft, var(--color-surface-card, #111111)); border-color: var(--color-warning-border, var(--color-border-subtle)); }
.capability-card.cap-negative { background: var(--color-risk-soft, var(--color-surface-card, #111111)); border-color: var(--color-risk-border, var(--color-border-subtle)); }
.capability-card-head { display: flex; align-items: center; gap: 12px; }
.capability-card-glyph { font-size: 20px; line-height: 1; color: var(--color-text-secondary, #d4d4d4); }
.capability-card-cap { display: block; font-size: 15px; font-weight: 600; color: var(--color-text-primary, #fff); }
.capability-card-status { margin-top: 4px; }
.capability-card-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px 24px; margin: 0; }
.capability-card-grid > div { display: flex; flex-direction: column; gap: 2px; }
.capability-card-grid dt { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-muted, #8a8a8a); }
.capability-card-grid dd { margin: 0; font-size: 13px; color: var(--color-text-primary); }
.capability-card-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; border-top: 1px solid var(--color-border-subtle, rgba(255,255,255,0.06)); padding-top: 12px; }
.capability-card-btn { background: transparent; border: 1px solid var(--color-border-subtle, rgba(255,255,255,0.06)); border-radius: var(--radius-lg); padding: 6px 14px; font-size: 12px; color: var(--color-text-primary, #fff); cursor: pointer; }
.capability-card-btn:hover { border-color: var(--color-text-secondary); }
.capability-card-docs { font-size: 11px; color: var(--color-muted); }

/* ── Provider Health dashboard (Correction 11) ─────────────────────── */
.provider-health { display: flex; flex-direction: column; gap: 16px; }
.provider-health-title { font-size: 18px; font-weight: 600; color: var(--color-text-primary); margin: 0; }
.provider-health-sub { font-size: 12px; color: var(--color-muted); margin: 0; }
.provider-health-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.provider-health-table th { text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-muted); padding: 8px 12px; border-bottom: 1px solid var(--border-subtle); }
.provider-health-table td { padding: 10px 12px; border-bottom: 1px solid var(--border-subtle); color: var(--color-text-primary); }

/* Workspace notifications — persistent inbox using the shared right-rail shell. */
.sidebar-notification-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: var(--radius-full);
  background: var(--color-text-primary);
  color: var(--color-text-inverse);
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}

.notification-center-drawer.right-rail-drawer {
  width: min(420px, calc(100vw - 24px));
  height: auto;
  max-height: min(560px, calc(100dvh - var(--global-navbar-height) - 24px));
  margin: 0;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-lg);
  padding: 20px;
}

/* Transparent, top-right popover — the preview never takes over the workspace. */
.notification-center-overlay.right-rail-drawer-overlay {
  align-items: flex-start;
  box-sizing: border-box;
  padding: calc(var(--global-navbar-height) + var(--space-2)) var(--space-3) var(--space-3);
  background: transparent;
}

.notification-center-mark-all,
.notification-center-refresh-icon,
.notification-center-toolbar button,
.notification-center-state button,
.notification-center-item__read {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-text-secondary);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.notification-center-mark-all,
.notification-center-toolbar button,
.notification-center-state button {
  min-height: 34px;
  padding: 0 10px;
}

.notification-center-mark-all {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 34px;
  white-space: nowrap;
}

.notification-center-refresh-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  min-width: 34px;
  padding: 0;
}

.notification-center-mark-all:hover,
.notification-center-refresh-icon:hover,
.notification-center-toolbar button:hover,
.notification-center-state button:hover,
.notification-center-item__read:hover {
  border-color: var(--color-text-primary);
  color: var(--color-text-primary);
  background: var(--color-surface-hover);
}

.notification-center-mark-all:focus-visible,
.notification-center-refresh-icon:focus-visible,
.notification-center-toolbar button:focus-visible,
.notification-center-state button:focus-visible,
.notification-center-item__main:focus-visible,
.notification-center-item__read:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.notification-center-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 14px;
  margin-bottom: 8px;
  border-bottom: 1px solid var(--color-border-subtle);
  color: var(--color-text-secondary);
  font-size: 12px;
}

.notification-center-toolbar__status {
  color: var(--color-text-muted);
  font-size: 11px;
}

.notification-center-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.notification-center-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: var(--color-surface-card);
}

.notification-center-item.is-unread {
  border-color: var(--color-border-medium);
  background: var(--color-surface-elevated);
}

.notification-center-item__main {
  display: flex;
  flex: 1;
  align-items: flex-start;
  gap: 10px;
  min-width: 0;
  padding: 13px;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.notification-center-item__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 30px;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--color-surface-hover);
  color: var(--color-text-secondary);
}

.notification-center-item.tone-success .notification-center-item__icon { color: var(--color-success); }
.notification-center-item.tone-warning .notification-center-item__icon { color: var(--color-warning); }
.notification-center-item.tone-risk .notification-center-item__icon { color: var(--color-danger); }
.notification-center-item.tone-info .notification-center-item__icon { color: var(--color-info); }

.notification-center-item__copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  gap: 3px;
}

.notification-center-item__meta {
  color: var(--color-text-muted);
  font-size: 11px;
}

.notification-center-item__copy strong {
  color: var(--color-text-primary);
  font-size: 13px;
  line-height: 1.35;
}

.notification-center-item__copy > span:last-child {
  color: var(--color-text-secondary);
  font-size: 12px;
  line-height: 1.45;
}

.notification-center-item__unread {
  flex: 0 0 7px;
  width: 7px;
  height: 7px;
  margin-top: 5px;
  border-radius: 50%;
  background: var(--color-info);
}

.notification-center-item__read {
  align-self: center;
  flex: 0 0 auto;
  min-height: 30px;
  margin: 0 10px 0 0;
  padding: 0 8px;
}

.notification-center-state {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  margin-top: 32px;
  padding: 20px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  color: var(--color-text-secondary);
}

.notification-center-state > svg { color: var(--color-text-muted); }
.notification-center-state strong { color: var(--color-text-primary); }
.notification-center-state p { margin: 0; font-size: 13px; line-height: 1.5; }
.notification-center-state.tone-risk { border-color: color-mix(in srgb, var(--color-danger) 45%, var(--color-border-subtle)); }

.notification-center-loading {
  display: grid;
  gap: 8px;
  padding-top: 8px;
}

.notification-center-loading span {
  display: block;
  height: 72px;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: var(--color-surface-elevated);
}

.notification-center-footer {
  margin-top: auto;
  padding-top: 14px;
}

.notification-center-footer button {
  width: 100%;
  min-height: 44px;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--color-text-primary);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.notification-center-footer button:hover {
  background: var(--color-surface-hover);
  border-color: var(--color-text-primary);
}

.notification-center-footer button:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.notification-inbox-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(0, 0, 0, 0.72);
}

.notification-inbox-modal {
  display: flex;
  flex-direction: column;
  width: min(760px, calc(100vw - 48px));
  max-height: min(720px, calc(100dvh - 48px));
  overflow: hidden;
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-card-strong);
  box-shadow: 0 24px 72px rgba(0, 0, 0, 0.5);
}

.notification-inbox-modal__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 20px 16px;
  border-bottom: 1px solid var(--color-border-subtle);
}

.notification-inbox-modal__head h2 {
  margin: 0;
  color: var(--color-text-primary);
  font-size: var(--fs-lg);
}

.notification-inbox-modal__head p {
  margin: 5px 0 0;
  color: var(--color-text-secondary);
  font-size: var(--fs-sm);
}

.notification-inbox-modal__actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.notification-inbox-modal > .notification-center-toolbar {
  flex: 0 0 auto;
  margin: 0;
  padding: 12px 20px;
}

.notification-inbox-modal__tabs {
  display: flex;
  flex: 0 0 auto;
  gap: var(--space-1);
  padding: 0 20px;
  border-bottom: 1px solid var(--color-border-subtle);
}

.notification-inbox-modal__tabs button {
  min-height: 42px;
  padding: 0 var(--space-3);
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--color-text-muted);
  font: inherit;
  font-size: var(--fs-sm);
  font-weight: var(--fw-medium);
  cursor: pointer;
}

.notification-inbox-modal__tabs button:hover,
.notification-inbox-modal__tabs button.is-active {
  color: var(--color-text-primary);
}

.notification-inbox-modal__tabs button.is-active {
  border-bottom-color: var(--color-text-primary);
}

.notification-inbox-modal__tabs button:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: -2px;
}

.notification-inbox-modal__body {
  min-height: 0;
  overflow: auto;
  padding: 0 20px 20px;
}

.notification-inbox-modal .notification-center-list {
  gap: 0;
}

.notification-inbox-modal .notification-center-item {
  gap: 8px;
  border: 0;
  border-bottom: 1px solid var(--color-border-subtle);
  border-radius: 0;
  background: transparent;
}

.notification-inbox-modal .notification-center-item:first-child {
  border-top: 0;
}

.notification-inbox-modal .notification-center-item.is-unread {
  border-color: var(--color-border-subtle);
  background: color-mix(in srgb, var(--color-info) 5%, transparent);
}

.notification-inbox-modal .notification-center-item__main {
  padding: 12px 0;
}

.notification-inbox-modal .notification-center-item__icon {
  flex-basis: 24px;
  width: 24px;
  height: 24px;
  background: transparent;
}

.notification-inbox-modal .notification-center-item__read {
  margin-right: 0;
}

@media (max-width: 640px) {
  .notification-center-drawer.right-rail-drawer {
    width: min(384px, calc(100vw - 24px));
    max-height: min(520px, calc(100dvh - var(--global-navbar-height-mobile) - 24px));
    padding: 16px;
  }
  .notification-center-overlay.right-rail-drawer-overlay { padding-top: calc(var(--global-navbar-height-mobile) + var(--space-2)); }
  .notification-inbox-modal-overlay { padding: 12px; }
  .notification-inbox-modal { width: calc(100vw - 24px); max-height: calc(100dvh - 24px); }
  .notification-inbox-modal__head { padding: 16px; }
  .notification-inbox-modal > .notification-center-toolbar { padding: 12px 16px; }
  .notification-inbox-modal__tabs { padding: 0 16px; overflow-x: auto; }
  .notification-inbox-modal__tabs button { flex: 0 0 auto; }
  .notification-inbox-modal__body { padding: 0 16px 16px; }
  .notification-center-item__read { display: none; }
  .notification-center-item__main { min-height: 68px; }
}

/* Notification preferences (monochrome, token-only) */
.notification-center-prefs { margin-top: 16px; border-top: 1px solid var(--workspace-border); padding-top: 12px; }
.np-panel { display: flex; flex-direction: column; gap: 12px; }
.np-title { margin: 0; font-size: 13px; font-weight: 600; color: var(--color-text-primary); letter-spacing: 0.01em; }
.np-loading { color: var(--color-text-muted); font-size: 12px; }
.np-toggle-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; cursor: pointer; }
.np-toggle-text { display: flex; flex-direction: column; gap: 2px; }
.np-toggle-label { font-size: 13px; color: var(--color-text-primary); }
.np-toggle-hint { font-size: 11px; color: var(--color-text-muted); }
.np-switch { position: relative; display: inline-flex; align-items: center; }
.np-switch input { position: absolute; opacity: 0; width: 36px; height: 20px; margin: 0; cursor: pointer; }
.np-switch-track { width: 36px; height: 20px; border-radius: 999px; background: var(--color-surface-elevated, var(--color-bg-secondary)); border: 1px solid var(--workspace-border); transition: background 0.15s ease; }
.np-switch input:checked + .np-switch-track { background: var(--color-text-primary); }
.np-switch input:checked + .np-switch-track::after { content: ""; position: absolute; top: 2px; left: 18px; width: 14px; height: 14px; border-radius: 50%; background: var(--color-bg, var(--color-bg-primary)); transition: left 0.15s ease; }
.np-switch-track::after { content: ""; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%; background: var(--color-text-muted); transition: left 0.15s ease; }
.np-field { display: flex; flex-direction: column; gap: 4px; }
.np-input { width: 160px; padding: 6px 8px; border: 1px solid var(--workspace-border); border-radius: var(--workspace-radius); background: transparent; color: var(--color-text-primary); font-size: 13px; }
.np-mute { display: flex; flex-direction: column; gap: 6px; }
.np-mute-row { display: flex; flex-wrap: wrap; gap: 6px; }
.np-mute-chip { padding: 4px 10px; border: 1px solid var(--workspace-border); border-radius: var(--workspace-radius); background: transparent; color: var(--color-text-primary); font-size: 12px; cursor: pointer; text-transform: capitalize; }
.np-mute-chip.is-muted { opacity: 0.5; text-decoration: line-through; }
.np-foot { font-size: 11px; color: var(--color-text-muted); }
.np-saved { color: var(--color-text-secondary); }
.np-error { color: var(--color-text-primary); }


/* Monochrome, token-driven. Severity/status via white→gray, never color. */
.etf-sidebar { gap: 10px; }
.etf-cap { display: flex; flex-direction: column; gap: 6px; }
.etf-cap-row { display: flex; justify-content: space-between; gap: 12px; font-size: 12px; }
.etf-cap-row i { color: var(--color-text-muted); font-style: normal; text-transform: uppercase; letter-spacing: 0.06em; font-size: 10px; }
.etf-cap-row b { color: var(--color-text-secondary); font-weight: 600; }
.etf-note { font-size: 13px; color: var(--color-text-secondary); margin: 0 0 8px; }
.etf-note.muted { color: var(--color-text-muted); }

/* Research Coverage Score (Rec 13) */
.etf-cov-score { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
.etf-cov-bar { flex: 1; height: 8px; border-radius: var(--radius-full); background: rgba(148,163,184,0.18); overflow: hidden; }
.etf-cov-bar span { display: block; height: 100%; background: var(--color-text-primary); border-radius: var(--radius-full); transition: opacity var(--duration-base) var(--ease-out); }
.etf-cov-pct { font-size: 18px; font-weight: 700; color: var(--color-text-primary); font-family: var(--font-mono, monospace); }
.etf-cov-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 5px; }
.etf-cov-list li { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--color-text-secondary); }
.etf-cov-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--color-text-muted); flex: none; }
.etf-cov-complete .etf-cov-dot { background: var(--color-data-green, var(--color-success)); }
.etf-cov-partial .etf-cov-dot { background: var(--color-text-secondary); }
.etf-cov-missing .etf-cov-dot { background: transparent; border: 1px solid var(--color-text-muted); }
.etf-cov-list em { margin-left: auto; font-style: normal; font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--color-text-muted); }

/* Relationship Graph (Rec 5) */
.etf-graph { display: flex; flex-wrap: wrap; gap: 8px; }
.etf-node { display: inline-flex; flex-direction: column; align-items: flex-start; gap: 2px; padding: 8px 12px; border-radius: var(--radius-xl); border: 1px solid var(--border-subtle, rgba(148,163,184,0.2)); background: rgba(255,255,255,0.02); color: var(--color-text-primary); cursor: pointer; font-size: 13px; font-weight: 600; transition: border-color .15s ease, background .15s ease; }
.etf-node:hover { border-color: var(--color-border-medium); background: rgba(255,255,255,0.05); }
.etf-node-type { font-size: 9px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--color-text-muted); }
.etf-node.etf-commodity { border-color: var(--color-text-secondary); background: var(--color-surface-hover); }
.etf-node.etf-country { border-color: var(--color-text-muted); background: var(--color-surface-hover); }

/* Navigable lists (Rec 3) */
.etf-nav-list { display: flex; flex-direction: column; gap: 4px; }
.etf-nav-row { display: flex; align-items: center; justify-content: space-between; width: 100%; padding: 8px 10px; border-radius: var(--radius-lg); border: 1px solid var(--border-subtle, rgba(148,163,184,0.2)); background: none; color: var(--color-text-secondary); cursor: pointer; font-size: 13px; text-align: left; transition: border-color .15s ease, background .15s ease; }
.etf-nav-row:hover { border-color: rgba(148,163,184,0.45); background: rgba(255,255,255,0.05); color: var(--color-text-primary); }
.etf-rel-go { color: var(--color-text-muted); font-size: 12px; }

/* Fund Timeline (Rec 2) */
.etf-timeline { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.etf-tl-row { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--color-text-secondary); }
.etf-tl-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--color-text-muted); flex: none; }
.etf-tl-open { margin-left: auto; font-size: 11px; color: var(--color-text-muted); }

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .etf-cov-bar span, .etf-node, .etf-nav-row { transition: none; }
}

@media (max-width: 1100px) {
  .arw-asset-facts { grid-template-columns: repeat(auto-fit, minmax(100px, 1fr)); }
}

/* ARW vNext — Knowledge Graph + Scenario (monochrome, token-only) */
.arw-kg { display: flex; flex-direction: column; align-items: flex-start; gap: 12px; margin-bottom: 16px; }
.arw-kg-node { border: 1px solid var(--color-border-medium); border-radius: var(--radius-lg); padding: 6px 10px; font-size: 12px; color: var(--color-text-primary); background: var(--color-surface-card, #111111); }
.arw-kg-root { background: var(--color-surface-card-strong, #141414); font-weight: 700; }
.arw-kg-edges { display: flex; flex-wrap: wrap; gap: 8px; }

.arw-scenarios { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; margin-bottom: 12px; }
.arw-scenario { border: 1px solid var(--color-border-medium); border-radius: var(--radius-xl); padding: 12px; display: flex; flex-direction: column; gap: 4px; background: var(--color-surface-card, #111111); }
.arw-scenario span { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-muted, #6b6b6b); }
.arw-scenario strong { font-size: 16px; color: var(--color-text-primary); }

/* Compare vNext — Decision Matrix verdict + reasons */
.cmp-decision-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 12px; }
.cmp-decision-verdict { display: inline-flex; align-items: baseline; gap: 10px; }
.cmp-decision-winner strong { font-size: 18px; }
.cmp-decision-confidence { font-size: 12px; color: var(--color-text-secondary); }
.cmp-decision-verdict--muted { color: var(--color-text-muted, #6b6b6b); }
.cmp-decision-reasons { margin-top: 12px; }
.cmp-decision-reasons h3 { font-size: 12px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-text-muted, #6b6b6b); margin: 0 0 6px; }
.cmp-decision-reasons ul { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 4px; }
.cmp-decision-reasons li { font-size: 13px; color: var(--color-text-secondary); }
.cmp-canvas-decision { max-width: 1100px; }

/* ════════════════════════════════════════════════════════════════════════
   vNext ARW + Compare — shared primitives & sections (monochrome, token-only)
   ════════════════════════════════════════════════════════════════════════ */

/* Shared SidebarGroup + SidebarItem (used by ARW + Compare) */
.ws-sidebar-group { margin-bottom: 10px; }
.ws-sidebar-group-label {
  font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--color-text-muted, #6b6b6b); padding: 4px 12px; font-weight: 700;
}
.ws-sidebar-group-items { display: flex; flex-direction: column; gap: 2px; }
.ws-sidebar-item {
  display: flex; align-items: center; gap: 8px; width: 100%; text-align: left;
  background: transparent; border: 0; border-left: 2px solid transparent;
  border-radius: var(--radius-lg); padding: 8px 12px; color: var(--color-text-secondary, #b8b8b8);
  font-size: 13px; font-weight: 600; cursor: pointer;
  transition: background var(--duration-fast, 120ms) var(--ease-standard, ease), border-color var(--duration-fast, 120ms) ease;
}
.ws-sidebar-item:hover { background: var(--color-surface-hover, rgba(255,255,255,0.04)); color: var(--color-text-primary); }
.ws-sidebar-item.active {
  background: var(--color-interactive-soft, rgba(255,255,255,0.08));
  border-left-color: var(--color-interactive, #FFFFFF);
  color: var(--color-text-primary); font-weight: 700;
}
.ws-sidebar-item-icon { font-size: 12px; opacity: 0.8; }
.ws-sidebar-item-label { flex: 1; }
.ws-sidebar-item-badge {
  min-width: 18px; height: 18px; padding: 0 5px; display: inline-flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 700; border-radius: var(--radius-full);
  background: var(--color-surface-elevated, #171717); color: var(--color-text-secondary, #b8b8b8);
  border: 1px solid var(--color-border-medium, #262626);
}

/* ScoreGauge — circular SVG gauge */
.ws-gauge { position: relative; display: inline-flex; align-items: center; justify-content: center; }
.ws-gauge-svg { display: block; }
.ws-gauge-track { stroke: var(--color-border-medium, #262626); }
.ws-gauge-fill { stroke: var(--color-text-dim, #808080); transition: stroke-dasharray var(--duration-base, 180ms) ease; }
.ws-gauge.tone-mid .ws-gauge-fill { stroke: var(--color-warning, #f59e0b); }
.ws-gauge.tone-high .ws-gauge-fill { stroke: var(--color-success, #10b981); }
.ws-gauge.tone-low .ws-gauge-fill { stroke: var(--color-text-dim, #808080); }
.ws-gauge-readout {
  position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center;
  pointer-events: none;
}
.ws-gauge-readout strong { font-size: 20px; color: var(--color-text-primary); line-height: 1; font-variant-numeric: tabular-nums; }
.ws-gauge-label { font-size: 9px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-text-muted, #6b6b6b); margin-top: 2px; }

/* ConfidenceBadge — pill + thin meter bar (semantic tint) */
.ws-confidence-badge {
  display: inline-flex; align-items: center; gap: 8px; padding: 4px 10px; border-radius: var(--radius-full);
  border: 1px solid var(--color-border-medium, #262626); background: var(--color-surface-elevated, #171717);
  font-size: 12px; margin-top: 4px;
}
.ws-confidence-badge-label { color: var(--color-text-muted, #6b6b6b); text-transform: uppercase; letter-spacing: 0.04em; font-size: 10px; }
.ws-confidence-badge-value { font-weight: 700; color: var(--color-text-primary); font-variant-numeric: tabular-nums; }
.ws-confidence-meter { flex: 1; min-width: 60px; height: 4px; border-radius: var(--radius-full); background: var(--color-border-subtle, rgba(255,255,255,0.06)); overflow: hidden; }
.ws-confidence-meter-fill { display: block; height: 100%; border-radius: var(--radius-full); background: var(--color-text-dim, #808080); }
.ws-confidence-badge.tone-mid .ws-confidence-meter-fill { background: var(--color-warning, #f59e0b); }
.ws-confidence-badge.tone-high .ws-confidence-meter-fill { background: var(--color-success, #10b981); }
.ws-confidence-badge.tone-low .ws-confidence-meter-fill { background: var(--color-danger, #ef4444); }

/* PlaceholderMetric — em-dash → skeleton gauge (honest "awaiting data") */
.ws-metric-card.placeholder { align-items: flex-start; gap: 8px; }
.ws-placeholder-gauge { width: 100%; height: 26px; display: flex; align-items: center; }
.ws-placeholder-gauge-ring {
  width: 100%; height: 14px; border-radius: var(--radius-full);
  border: 1px dashed var(--color-border-strong, #404040); background: repeating-linear-gradient(90deg, transparent, transparent 6px, var(--color-border-subtle, rgba(255,255,255,0.06)) 6px, var(--color-border-subtle, rgba(255,255,255,0.06)) 12px);
}

/* AssetSummaryCard — Compare Overview */
.ws-asset-summary {
  border: 1px solid var(--color-border-medium, #262626); border-radius: var(--radius-lg, 8px);
  background: var(--color-surface-card, #111111); padding: 16px; display: flex; flex-direction: column; gap: 14px;
}
.ws-asset-summary-head { display: flex; flex-direction: column; gap: 2px; }
.ws-asset-summary-id { display: flex; align-items: baseline; gap: 8px; }
.ws-asset-summary-sym { font-size: 22px; font-weight: 800; letter-spacing: 0.02em; }
.ws-asset-summary-name { font-size: 12px; color: var(--color-text-muted, #6b6b6b); }
.ws-asset-summary-meta { display: flex; gap: 6px; font-size: 12px; color: var(--color-text-secondary, #b8b8b8); }
.ws-asset-summary-price { display: flex; align-items: baseline; gap: 10px; }
.ws-asset-summary-price strong { font-size: 24px; font-variant-numeric: tabular-nums; }
.ws-asset-summary-no-price { font-size: 24px; color: var(--color-text-muted, #6b6b6b); }
.ws-asset-summary-change { font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; }
.ws-asset-summary-change.up { color: var(--color-success, #10b981); }
.ws-asset-summary-change.down { color: var(--color-danger, #ef4444); }
.ws-asset-summary-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.ws-asset-summary-cell { display: flex; flex-direction: column; gap: 2px; padding: 8px; border: 1px solid var(--color-border-subtle, rgba(255,255,255,0.06)); border-radius: var(--radius-lg); background: var(--color-surface-card-strong, #141414); }
.ws-asset-summary-cell-label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-muted, #6b6b6b); }
.ws-asset-summary-cell-value { font-size: 14px; color: var(--color-text-primary); font-variant-numeric: tabular-nums; }
.ws-asset-summary-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding-top: 4px; border-top: 1px solid var(--color-border-subtle, rgba(255,255,255,0.06)); }
.ws-asset-summary-link { background: none; border: 0; color: var(--color-text-secondary, #b8b8b8); font-size: 13px; font-weight: 600; cursor: pointer; padding: 0; text-decoration: underline; text-underline-offset: 3px; }
.ws-asset-summary-link:hover { color: var(--color-text-primary); }

/* ResultBanner — decision summary */
.ws-result-banner {
  display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
  border: 1px solid var(--color-border-medium, #262626); border-radius: var(--radius-lg, 8px);
  padding: 16px 18px; margin-bottom: 16px; background: var(--color-surface-card, #111111);
}
.ws-result-banner.insufficient { border-style: dashed; }
.ws-result-banner.winner { border-color: var(--color-success, #10b981); background: var(--color-success-soft, var(--color-surface-card, #111111)); }
.ws-result-banner-copy { display: flex; flex-direction: column; gap: 4px; }
.ws-result-banner-eyebrow { font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--color-text-muted, #6b6b6b); }
.ws-result-banner h3 { margin: 0; font-size: 18px; }
.ws-result-banner-breakdown { margin: 0; font-size: 13px; color: var(--color-text-secondary, #b8b8b8); }
.ws-result-banner-actions { display: flex; gap: 10px; flex-wrap: wrap; }

/* DecisionMatrixEmpty — structured preview when no verdict */
.ws-decision-empty { border: 1px solid var(--color-border-medium, #262626); border-radius: var(--radius-lg, 8px); overflow: hidden; }
.ws-decision-empty-rows { display: flex; flex-direction: column; }
.ws-decision-empty-row {
  display: grid; grid-template-columns: minmax(120px, 1.4fr) 1fr 84px 1fr; gap: 0;
  align-items: center; border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,0.06));
}
.ws-decision-empty-row > * { padding: 12px; }
.ws-decision-empty-dim { font-size: 13px; color: var(--color-text-primary); font-weight: 600; }
.ws-decision-empty-win { display: flex; justify-content: center; }
.ws-decision-empty-foot { padding: 14px; display: flex; flex-direction: column; gap: 10px; background: var(--color-surface-card-strong, #141414); }
.ws-decision-empty-foot p { margin: 0; font-size: 13px; color: var(--color-text-secondary, #b8b8b8); }
.ws-decision-empty-actions { display: flex; gap: 10px; flex-wrap: wrap; }

/* ComparisonMatrix — relative fill bars per score cell */
.ws-matrix-score { display: flex; flex-direction: column; gap: 3px; }
.ws-matrix-bar { display: block; height: 4px; border-radius: var(--radius-full); background: var(--color-surface-elevated, #171717); overflow: hidden; margin-bottom: 2px; }
.ws-matrix-bar-fill { display: block; height: 100%; background: var(--color-border-strong, #404040); border-radius: var(--radius-full); }
.ws-matrix-score.is-winner .ws-matrix-bar { background: var(--color-success-soft, rgba(16,185,129,0.14)); }
.ws-matrix-score.is-winner .ws-matrix-bar-fill { background: var(--color-success, #10b981); }

/* ARW curated Overview */
.arw-overview { display: flex; flex-direction: column; gap: 18px; }
.arw-overview-hero { display: grid; grid-template-columns: 1fr auto; gap: 18px; align-items: stretch; }
.arw-overview-hero-copy { min-width: 0; }
.arw-overview-hero-stats { display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 12px; }
.arw-overview-hero-gauge { display: flex; align-items: center; justify-content: center; padding: 8px 12px; border: 1px solid var(--color-border-medium, #262626); border-radius: var(--radius-lg, 8px); background: var(--color-surface-card-strong, #141414); }
.arw-overview-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.arw-metric-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }

/* Compare header — lettermark + quote */
.cmp-header-mark {
  width: 40px; height: 40px; border-radius: var(--radius-lg); flex: 0 0 auto;
  display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid var(--color-border-medium, #262626); background: var(--color-surface-elevated, #171717);
  font-size: 18px; font-weight: 600; color: var(--color-text-primary); letter-spacing: 0.02em;
}
.cmp-header-asset { display: flex; align-items: center; gap: 12px; }
.cmp-header-asset-copy { display: flex; flex-direction: column; gap: 1px; }
.cmp-header-quote { display: flex; align-items: baseline; gap: 8px; font-size: 13px; }
.cmp-header-change { font-variant-numeric: tabular-nums; font-weight: 600; }
.cmp-header-change.up { color: var(--color-success, #10b981); }
.cmp-header-change.down { color: var(--color-danger, #ef4444); }

/* Compare Overview dual cards */
.cmp-overview-cards { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }

/* Compare Shared Intelligence grid */
.cmp-shared-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; margin: 16px 0 12px; }

/* Compare Insights — grouped + sticky */
.cmp-insights { border-left: 1px solid var(--color-border-medium, #262626); padding: 18px 16px; overflow-y: auto; position: sticky; top: 0; align-self: start; }
.cmp-insights-group { margin-bottom: 18px; display: flex; flex-direction: column; gap: 10px; }
.cmp-insights-group:last-child { margin-bottom: 0; }

@media (max-width: 1100px) {
  .arw-overview-hero { grid-template-columns: 1fr; }
  .arw-overview-cols { grid-template-columns: 1fr; }
  .cmp-overview-cards { grid-template-columns: 1fr; }
  .cmp-shared-grid { grid-template-columns: 1fr; }
  .ws-asset-summary-grid { grid-template-columns: repeat(2, 1fr); }
  .ws-decision-empty-row { grid-template-columns: minmax(90px, 1.2fr) 1fr 64px 1fr; }
}

/* Ghost — token-driven inline "not yet synced" placeholder (em-dash replacement
   in ARW header/fact strips). Monochrome: muted text token + soft pulse. */
.ws-ghost {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-style: italic;
  line-height: 1;
  color: var(--color-text-muted, #808080);
  letter-spacing: 0.01em;
}
.ws-ghost-pulse {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-text-muted, #808080);
  opacity: 0.55;
  animation: ws-ghost-pulse 1.6s ease-in-out infinite;
}
@keyframes ws-ghost-pulse {
  0%, 100% { opacity: 0.25; transform: scale(0.85); }
  50% { opacity: 0.6; transform: scale(1); }
}
@media (prefers-reduced-motion: reduce) {
  .ws-ghost-pulse { animation: none; opacity: 0.5; }
}

/* Sparkline — Massive daily series in ARW Overview / Technicals. Monochrome,
   token-driven (no new color values). */
.ws-sparkline {
  display: block;
  width: 100%;
  height: auto;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: var(--color-surface-depth);
}
.arw-overview-series { margin-top: var(--space-5); }
.arw-overview-series-foot {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  margin-top: var(--space-2);
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
  letter-spacing: 0.04em;
}
.arw-technicals-series { margin-bottom: var(--space-4); }
.arw-technicals-realtime {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--grid-gap);
  margin-top: var(--space-3);
}


/* =============================================================================
   Portfolio Intelligence Rail (Smart Alerts) — Brand v2 monochrome
   Reuses existing tokens; no page-specific colors. Lives in the Analysis
   Workspace right rail and is independently refreshable.
   ========================================================================== */
.portfolio-intelligence-rail {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
}

.portfolio-intelligence-rail .portfolio-command-panel-head {
  align-items: flex-start;
}

.portfolio-intelligence-rail .portfolio-command-panel-head > div:first-child {
  min-width: 0;
  flex: 1 1 auto;
}

.portfolio-intelligence-rail .portfolio-command-panel-head p {
  margin: 4px 0 0;
  font-size: 0.76rem;
  color: var(--color-text-muted);
  line-height: 1.35;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.portfolio-intelligence-alert strong {
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--color-text-primary);
  overflow-wrap: anywhere;
  word-break: break-word;
}

.portfolio-intelligence-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 0 16px;
  font-size: 0.72rem;
  color: var(--color-text-secondary);
}

.portfolio-intelligence-summary .critical { color: var(--color-danger); }
.portfolio-intelligence-summary .warning { color: var(--color-warning); }
.portfolio-intelligence-summary .info { color: var(--color-text-secondary); }

.portfolio-intelligence-list {
  display: grid;
  gap: 10px;
  padding: 0 16px 16px;
  max-height: 640px;
  overflow-y: auto;
}

.portfolio-intelligence-alert {
  border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg);
  background: var(--color-surface-elevated);
  padding: 10px 12px;
  display: grid;
  gap: 6px;
}

.portfolio-intelligence-alert.severity-critical { border-color: var(--color-danger); background: var(--color-risk-soft, var(--color-surface-elevated)); }
.portfolio-intelligence-alert.severity-warning { border-color: var(--color-warning); background: var(--color-warning-soft, var(--color-surface-elevated)); }
.portfolio-intelligence-alert.severity-info { border-color: var(--color-border-strong); }
.portfolio-intelligence-alert.severity-positive { border-color: var(--color-success); background: var(--color-success-soft, var(--color-surface-elevated)); }

.portfolio-intelligence-alert-head {
  display: flex;
  align-items: center;
  gap: 8px;
}

.portfolio-intelligence-alert-cat {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--color-text-muted);
}

.portfolio-intelligence-alert strong {
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--color-text-primary);
}

.portfolio-intelligence-alert p {
  margin: 0;
  font-size: 0.76rem;
  color: var(--color-text-secondary);
  line-height: 1.35;
}

.portfolio-intelligence-alert-meta {
  margin: 0;
  display: grid;
  gap: 4px;
  font-size: 0.72rem;
}

.portfolio-intelligence-alert-meta > div {
  display: grid;
  grid-template-columns: 84px 1fr;
  gap: 8px;
}

.portfolio-intelligence-alert-meta dt {
  color: var(--color-text-muted);
  text-transform: uppercase;
  font-size: 0.64rem;
  letter-spacing: 0.04em;
  align-self: start;
  padding-top: 2px;
}

.portfolio-intelligence-alert-meta dd {
  margin: 0;
  color: var(--color-text-secondary);
}

.portfolio-intelligence-alert-action dd {
  color: var(--color-text-primary);
}

.portfolio-intelligence-alert-time {
  font-size: 0.66rem;
  color: var(--color-text-muted);
}

/* ===== Zenin V2 Desk IA layer (Macro & Commodities) ===== */
/* Dense, monochrome, decision-first. No gradients, no glass, no marketing cards. */

.deskv2-signal-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 10px 0 8px;
  padding: 0;
}

.deskv2-tile {
  flex: 1 1 132px;
  min-width: 132px;
  border: 1px solid var(--color-border-medium);
  background: var(--color-surface-card);
  border-radius: var(--radius-md);
  padding: 7px 9px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.deskv2-tile-label {
  font-size: 10px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}
.deskv2-tile-reading {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text-primary);
  white-space: nowrap;
}
.deskv2-tile-reading > span:first-child {
  font-size: 10px;
}
.deskv2-tile-meta {
  font-size: 10px;
  color: var(--color-text-muted);
  line-height: 1.1;
}
.deskv2-tile-positive { border-color: var(--color-data-up); background: var(--color-success-soft, inherit); }
.deskv2-tile-negative { border-color: var(--color-data-down); background: var(--color-risk-soft, inherit); }
.deskv2-tile-neutral { border-color: rgba(160, 160, 160, 0.3); }

.deskv2-decision-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 12px;
  padding: 8px 12px;
  border: 1px solid rgba(160, 160, 160, 0.18);
  border-color: var(--color-interactive, var(--color-warning));
  background: rgba(20, 16, 8, 0.35);
  border-radius: var(--radius-md);
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-primary);
}
.deskv2-decision-glyph {
  color: var(--color-interactive, var(--color-warning));
  font-size: 14px;
}
.deskv2-decision-text {
  letter-spacing: 0.01em;
}

.deskv2-quality {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 10px;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-top: 6px;
}
.deskv2-quality-src { color: var(--color-data-slate-bright); }

/* Hero height reduction (~35%): tighten macro/commodities hero padding + gaps */
.analytics-macro-hero,
.analytics-commodity-titleblock {
  padding-top: 10px !important;
  padding-bottom: 10px !important;
}
.analytics-macro-topline {
  gap: 10px !important;
}
.analytics-desk-hero p,
.analytics-commodity-titleblock p {
  margin: 4px 0 6px !important;
  font-size: 12px !important;
  line-height: 1.35 !important;
}

/* ===== Zenin V2 desk modules (Phase 2/3/4) ===== */
.deskv2-panel {
  border: 1px solid var(--color-border-medium);
  background: var(--color-surface-card);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  margin: 10px 0;
}
.deskv2-panel-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 8px;
  font-size: 11px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}
.deskv2-panel-head em { font-style: normal; color: var(--color-data-slate-dim); font-size: 10px; }

.deskv2-unavailable-body { padding: 6px 0; }
.deskv2-unavailable-body strong { color: var(--color-data-amber-bright); font-size: 12px; }
.deskv2-unavailable-body p { font-size: 12px; color: var(--color-text-secondary); margin: 4px 0; }
.deskv2-unavailable-body small { font-size: 10px; color: var(--color-text-muted); text-transform: uppercase; letter-spacing: 0.04em; }

.deskv2-quadrant {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  grid-template-rows: repeat(2, 1fr);
  gap: 6px;
  min-height: 160px;
}
.deskv2-quad {
  border: 1px solid rgba(160, 160, 160, 0.14);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  color: var(--color-text-muted);
  background: rgba(8, 8, 8, 0.4);
}
.deskv2-quad.active {
  border-color: var(--color-interactive, var(--color-warning));
  color: var(--color-text-primary);
  background: rgba(20, 16, 8, 0.5);
  font-weight: 700;
}
.deskv2-quadrant-legend { display: flex; gap: 12px; margin-top: 6px; font-size: 11px; color: var(--color-text-secondary); }

.deskv2-crossasset { display: flex; flex-direction: column; gap: 4px; }
.deskv2-ca-row { display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: 6px; font-size: 12px; padding: 3px 0; border-bottom: 1px solid rgba(160,160,160,0.08); }
.deskv2-ca-name { color: var(--color-text-secondary); }
.deskv2-ca-val { color: var(--color-text-primary); font-weight: 600; }
.deskv2-ca-sig { text-align: right; }
.deskv2-ca-row.positive .deskv2-ca-sig { color: var(--color-data-up); }
.deskv2-ca-row.negative .deskv2-ca-sig { color: var(--color-data-down); }

.deskv2-wl { display: flex; flex-direction: column; gap: 2px; max-height: 280px; overflow: auto; }
.deskv2-wl-row { display: grid; grid-template-columns: 22px 1.6fr 1fr 1fr; gap: 6px; font-size: 12px; align-items: center; padding: 2px 0; }
.deskv2-wl-pin { background: none; border: none; cursor: pointer; color: var(--color-data-slate-dim); font-size: 13px; }
.deskv2-wl-name { color: var(--color-text-secondary); }
.deskv2-wl-val { color: var(--color-text-primary); font-weight: 600; }
.deskv2-wl-chg { text-align: right; color: var(--color-data-slate-dim); }

.deskv2-chain { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.deskv2-chain-node { border: 1px solid rgba(160,160,160,0.18); border-radius: var(--radius-md); padding: 4px 8px; font-size: 12px; color: var(--color-text-secondary); }
.deskv2-chain-node.negative { border-color: var(--color-data-down); color: var(--color-data-down); }
.deskv2-chain-node.positive { border-color: var(--color-data-up); color: var(--color-data-up); }
.deskv2-chain-arrow { color: var(--color-text-muted); }
.deskv2-chain-note { font-size: 10px; color: var(--color-text-muted); margin-top: 6px; line-height: 1.4; }

.deskv2-heatmap { display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 6px; }
.deskv2-heat-cell { border-radius: var(--radius-md); padding: 8px; display: flex; flex-direction: column; gap: 2px; border: 1px solid var(--color-border-medium); }
.deskv2-heat-name { font-size: 12px; font-weight: 600; color: var(--color-text-primary); }
.deskv2-heat-daily { font-size: 13px; font-weight: 700; color: var(--color-text-primary); }
.deskv2-heat-ytd { font-size: 10px; color: var(--color-text-secondary); }

.deskv2-disclosure { margin: 8px 0; }
.deskv2-disclosure-toggle { background: none; border: 1px solid rgba(160,160,160,0.2); border-radius: var(--radius-md); color: var(--color-text-secondary); font-size: 11px; padding: 4px 8px; cursor: pointer; }
.deskv2-disclosure-body { margin-top: 6px; }

/* ===== Rates / Growth Terminal (compact macro terminal) ===== */
.deskv2-macro-terminal { border: 1px solid var(--color-border-medium); border-radius: var(--radius-md); background: var(--color-surface-elevated); overflow: hidden; outline: none; }
.deskv2-macro-terminal:focus-within { border-color: var(--color-border-strong); }
.deskv2-mterminal-head, .deskv2-mrow {
  display: grid;
  grid-template-columns: 1.7fr 0.9fr 0.9fr 0.5fr 1.5fr 1fr 0.9fr;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
}
.deskv2-mterminal-head {
  height: 28px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-muted);
  border-bottom: 1px solid var(--color-border-subtle);
  background: var(--color-surface-card-strong);
  position: sticky;
  top: 0;
  z-index: 2;
}
.deskv2-mterminal-head .col-sort { text-align: right; cursor: pointer; color: var(--color-interactive, var(--color-warning)); }
.deskv2-mterminal-body { max-height: 300px; overflow-y: auto; }
.deskv2-mrow {
  height: 38px;
  font-size: 13px;
  border-bottom: 1px solid rgba(160,160,160,0.07);
  cursor: pointer;
  color: var(--color-text-secondary);
}
.deskv2-mrow:hover { background: rgba(255,255,255,0.03); }
.deskv2-mrow.focused { background: rgba(201,162,39,0.08); outline: 1px solid rgba(201,162,39,0.35); }
.deskv2-mrow.open { background: rgba(255,255,255,0.04); }
.deskv2-mrow .col-name { color: var(--color-text-primary); font-weight: 600; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.deskv2-mrow .col-val { color: var(--color-text-primary); font-weight: 700; font-size: 15px; }
.deskv2-mrow .col-delta { font-size: 11px; }
.deskv2-mrow .col-trend { font-size: 13px; text-align: center; }
.deskv2-mrow .col-contrib { font-size: 11px; color: var(--color-text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.deskv2-mrow .col-date { font-size: 10px; color: var(--color-text-muted); }
.deskv2-mrow .col-source { font-size: 10px; color: var(--color-data-slate-dim); text-transform: uppercase; letter-spacing: 0.03em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.deskv2-mrow.tone-pos .col-delta, .deskv2-mrow.tone-pos .col-trend { color: var(--color-data-up); }
.deskv2-mrow.tone-neg .col-delta, .deskv2-mrow.tone-neg .col-trend { color: var(--color-data-down); }
.deskv2-mrow.tone-neutral .col-delta, .deskv2-mrow.tone-neutral .col-trend { color: var(--color-text-secondary); }
.deskv2-mrow-detail {
  padding: 8px 12px;
  font-size: 11px;
  background: var(--color-surface-elevated);
  border-bottom: 1px solid var(--color-border-subtle);
}
.mr-detail-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 6px 14px; }
.mr-detail-grid label { display: block; color: var(--color-text-muted); font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; }
.mr-detail-grid span { color: var(--color-text-primary); font-weight: 600; }
.mr-detail-note { margin-top: 8px; font-size: 10px; color: var(--color-data-amber-bright); line-height: 1.4; }
.deskv2-macro-empty { padding: 16px; display: flex; flex-direction: column; gap: 4px; }
.deskv2-macro-empty strong { color: var(--color-data-amber-bright); font-size: 13px; }
.deskv2-macro-empty span { font-size: 11px; color: var(--color-text-secondary); }

/* ===== Commodity Allocation Guidance (replaces Portfolio Tilt) ===== */
.deskv2-alloc { margin: 12px 0; border: 1px solid var(--color-border-medium); border-radius: var(--radius-md); background: var(--color-surface-elevated); padding: 12px 14px; }
.deskv2-alloc-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 12px; margin-bottom: 10px; }
.deskv2-alloc-head h3 { font-size: 14px; letter-spacing: 0.04em; color: var(--color-text-primary); margin: 0; }
.deskv2-alloc-star { color: var(--color-interactive, var(--color-warning)); font-size: 11px; }
.deskv2-alloc-head p { font-size: 11px; color: var(--color-text-secondary); margin: 3px 0 0; max-width: 560px; }
.deskv2-alloc-head em { font-size: 10px; color: var(--color-text-muted); white-space: nowrap; }
.deskv2-alloc-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 10px; }
.deskv2-alloc-card { text-align: left; background: var(--color-surface-card); border: 1px solid var(--color-border-medium); border-radius: var(--radius-md); padding: 10px 12px; cursor: pointer; color: var(--color-text-secondary); transition: background .12s; }
.deskv2-alloc-card:hover { background: var(--color-surface-hover); }
.deskv2-alloc-card.tone-increase { border-color: var(--color-data-up); background: var(--color-success-soft, var(--color-surface-card)); }
.deskv2-alloc-card.tone-reduce { border-color: var(--color-data-down); background: var(--color-risk-soft, var(--color-surface-card)); }
.deskv2-alloc-card.tone-monitor, .deskv2-alloc-card.tone-watch { border-color: var(--color-data-slate-dim); }
.deskv2-alloc-card-top { display: flex; align-items: center; gap: 8px; }
.deskv2-alloc-glyph { font-size: 15px; font-weight: 700; color: var(--color-interactive, var(--color-warning)); }
.deskv2-alloc-title { font-size: 13px; font-weight: 600; color: var(--color-text-primary); }
.deskv2-alloc-pin { margin-left: auto; color: var(--color-interactive, var(--color-warning)); font-size: 11px; }
.deskv2-alloc-meta { display: flex; justify-content: space-between; margin: 6px 0; font-size: 11px; }
.deskv2-alloc-conf b { color: var(--color-text-primary); }
.deskv2-alloc-horizon { color: var(--color-text-muted); }
.deskv2-alloc-reason { display: flex; flex-direction: column; gap: 2px; }
.deskv2-alloc-bullet { font-size: 11px; color: var(--color-text-secondary); }
.deskv2-alloc-empty { padding: 14px; display: flex; flex-direction: column; gap: 4px; }
.deskv2-alloc-empty strong { color: var(--color-data-amber-bright); font-size: 13px; }
.deskv2-alloc-empty span { font-size: 11px; color: var(--color-text-secondary); }
.deskv2-alloc-history { margin-top: 10px; font-size: 11px; }
.deskv2-alloc-history summary { cursor: pointer; color: var(--color-text-muted); }
.deskv2-alloc-history ul { margin: 6px 0 0; padding-left: 16px; color: var(--color-text-secondary); }
.deskv2-alloc-activefilter { font-size: 11px; color: var(--color-text-secondary); margin: 8px 0; display: flex; align-items: center; gap: 8px; }
.deskv2-alloc-activefilter button { background: none; border: 1px solid rgba(160,160,160,0.25); border-radius: var(--radius-md); color: var(--color-interactive, var(--color-warning)); font-size: 10px; padding: 2px 8px; cursor: pointer; }

/* Slide-over drawer */
.deskv2-drawer-scrim { position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 80; display: flex; justify-content: flex-end; }
.deskv2-drawer { width: min(480px, 94vw); height: 100%; background: var(--color-surface-card); border-left: 1px solid var(--color-border-medium); overflow-y: auto; padding: 18px 20px; outline: none; }
.deskv2-drawer-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; border-bottom: 1px solid rgba(160,160,160,0.16); padding-bottom: 12px; margin-bottom: 14px; }
.deskv2-drawer-head div { display: flex; align-items: center; gap: 8px; }
.deskv2-drawer-head h4 { font-size: 15px; color: var(--color-text-primary); margin: 0; }
.deskv2-drawer-close { background: none; border: none; color: var(--color-text-muted); font-size: 16px; cursor: pointer; }
.deskv2-drawer-stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px 16px; margin-bottom: 16px; }
.deskv2-drawer-stats label, .deskv2-drawer-sec h5, .deskv2-impact label { display: block; font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-muted); }
.deskv2-drawer-stats span { font-size: 14px; font-weight: 600; color: var(--color-text-primary); }
.deskv2-drawer-sec { margin-bottom: 16px; }
.deskv2-drawer-sec h5 { margin: 0 0 8px; font-size: 11px; color: var(--color-text-secondary); border-bottom: 1px solid rgba(160,160,160,0.1); padding-bottom: 4px; }
.deskv2-impact { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.deskv2-impact span { font-size: 15px; font-weight: 700; color: var(--color-text-primary); }
.deskv2-impact span.pos { color: var(--color-data-up); }
.deskv2-impact span.neg { color: var(--color-data-down); }
.deskv2-driver-list { margin: 0; padding-left: 16px; font-size: 12px; color: var(--color-text-secondary); line-height: 1.6; }
.deskv2-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.deskv2-chip { font-size: 11px; padding: 2px 8px; border: 1px solid rgba(160,160,160,0.22); border-radius: var(--radius-md); color: var(--color-text-secondary); }
.deskv2-crosslinks { display: flex; flex-direction: column; gap: 6px; }
.deskv2-crosslinks button { text-align: left; background: none; border: 1px solid rgba(160,160,160,0.18); border-radius: var(--radius-md); color: var(--color-interactive, var(--color-warning)); font-size: 12px; padding: 7px 10px; cursor: pointer; }
.deskv2-crosslinks button:hover { background: rgba(201,162,39,0.08); }
.deskv2-status-row { display: flex; gap: 8px; margin-bottom: 8px; }
.deskv2-status-row button { background: none; border: 1px solid rgba(160,160,160,0.22); border-radius: var(--radius-md); color: var(--color-text-secondary); font-size: 11px; padding: 5px 12px; cursor: pointer; }
.deskv2-history-list { margin: 0; padding-left: 16px; font-size: 11px; color: var(--color-text-secondary); }
.deskv2-history-list em { color: var(--color-text-muted); }

/* ===== Commodity Research Workspace + Profile (Brand v2) ===== */
.cw-hero { margin-bottom: 12px; }
.cw-primary-btn { background: var(--color-interactive, var(--color-warning)); color: #0a0a0a; border: 1px solid var(--color-interactive, var(--color-warning)); border-radius: var(--radius-md); font-size: 12px; padding: 6px 12px; cursor: pointer; font-weight: 600; }
.cw-ghost-btn { background: none; color: var(--color-text-secondary); border: 1px solid rgba(160,160,160,0.25); border-radius: var(--radius-md); font-size: 12px; padding: 6px 12px; cursor: pointer; }
.cw-ghost-btn:hover { background: rgba(255,255,255,0.05); }
.cw-rec { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
.cw-signal { font-size: 12px; font-weight: 600; padding: 2px 8px; border-radius: var(--radius-md); border: 1px solid rgba(160,160,160,0.2); }
.cw-signal.tone-pos { color: var(--color-data-up); border-color: var(--color-data-up); }
.cw-signal.tone-neg { color: var(--color-data-down); border-color: var(--color-data-down); }
.cw-note { font-size: 12px; color: var(--color-text-secondary); line-height: 1.5; }
.cw-tri { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 12px; }
.cw-ai-row { display: flex; flex-wrap: wrap; gap: 8px; }
.cw-rel-row { font-size: 12px; color: var(--color-text-secondary); padding: 5px 0; border-bottom: 1px solid rgba(160,160,160,0.1); cursor: pointer; display: flex; justify-content: space-between; }
.cw-rel-row:hover { color: var(--color-text-primary); }
.cw-rel-go { color: var(--color-interactive, var(--color-warning)); }
.cw-rel-grid { display: flex; flex-wrap: wrap; gap: 6px; }
.cw-src { font-size: 11px; color: var(--color-text-secondary); line-height: 1.6; padding-left: 16px; }

/* Company Profile -> Related Commodities (bidirectional nav) */
.company-related-commodities { margin-top: 16px; border-top: 1px solid rgba(160,160,160,0.12); padding-top: 12px; }
.company-related-commodities h4 { font-size: 12px; color: var(--color-text-secondary); margin: 0 0 8px; text-transform: uppercase; letter-spacing: 0.04em; }
.company-related-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.company-related-chip { background: none; border: 1px solid rgba(160,160,160,0.25); border-radius: var(--radius-md); color: var(--color-text-secondary); font-size: 12px; padding: 5px 10px; cursor: pointer; }
.company-related-chip:hover { background: rgba(255,255,255,0.05); color: var(--color-text-primary); }

/* ─────────────────────────────────────────────────────────────
   Macro Desk Phase II — country-aware terminal styles (monochrome)
   ───────────────────────────────────────────────────────────── */

/* 🌍 Country selector (toolbar) */
.macro-country-selector { display: inline-flex; }
.macro-country-trigger {
  display: inline-flex; align-items: center; gap: 6px;
  background: rgba(160,160,160,0.06); border: 1px solid rgba(160,160,160,0.22);
  border-radius: var(--radius-md); color: var(--color-text-secondary); font-size: 12px;
  padding: 5px 10px; cursor: pointer; line-height: 1;
}
.macro-country-trigger strong { color: var(--color-text-primary); font-weight: 800; }
.macro-country-trigger:hover { border-color: rgba(160,160,160,0.4); }
.macro-country-menu {
  position: absolute; top: calc(100% + 4px); left: 0; z-index: 50;
  width: 280px; max-height: 360px; overflow-y: auto;
  background: var(--color-surface-card); border: 1px solid var(--color-border-medium);
  border-radius: var(--radius-lg); box-shadow: var(--shadow-2); padding: 4px;
}
.macro-country-option {
  display: grid; grid-template-columns: 18px 1fr auto; align-items: center; gap: 8px;
  width: 100%; text-align: left; background: none; border: 0; border-radius: var(--radius-md);
  padding: 7px 8px; cursor: pointer; color: var(--color-text-primary); font-size: 12px;
}
.macro-country-option:hover { background: rgba(160,160,160,0.08); }
.macro-country-option.active { background: rgba(160,160,160,0.12); }
.macro-country-option.coming-soon { opacity: 0.45; cursor: not-allowed; }
.macro-country-flag { font-size: 14px; }
.macro-country-name { font-weight: 600; }
.macro-coverage-count { font-size: 10px; color: var(--color-text-muted); grid-column: 2 / 4; }

/* Coverage + provider badges (monochrome tokens) */
.macro-coverage-badge {
  font-size: 9px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase;
  padding: 2px 6px; border-radius: var(--radius-md); border: 1px solid transparent; white-space: nowrap;
}
.macro-coverage-badge.positive { color: var(--color-data-up, var(--color-success)); border-color: rgba(74,222,128,0.3); background: rgba(74,222,128,0.08); }
.macro-coverage-badge.info { color: var(--color-text-secondary); border-color: rgba(160,160,160,0.3); background: rgba(160,160,160,0.06); }
.macro-coverage-badge.watch { color: var(--color-data-watch, #eab308); border-color: rgba(234,179,8,0.3); background: rgba(234,179,8,0.08); }
.macro-coverage-badge.negative { color: var(--color-data-down, #ef4444); border-color: rgba(239,68,68,0.3); background: rgba(239,68,68,0.08); }
.macro-coverage-dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; }
.macro-coverage-dot.positive { background: var(--color-data-up, var(--color-success)); }
.macro-coverage-dot.info { background: var(--color-text-secondary); }
.macro-coverage-dot.watch { background: var(--color-data-watch, #eab308); }
.macro-coverage-dot.negative { background: var(--color-data-down, #ef4444); }

/* Per-panel metadata strap */
.macro-country-meta-strip {
  display: flex; flex-wrap: wrap; gap: 14px; margin-top: 8px;
  padding-top: 8px; border-top: 1px solid rgba(160,160,160,0.1);
}
.macro-meta-item { display: inline-flex; flex-direction: column; gap: 1px; font-size: 10px; }
.macro-meta-item em { color: var(--color-text-muted); font-style: normal; letter-spacing: 0.08em; text-transform: uppercase; font-size: 9px; }
.macro-meta-item strong { color: var(--color-text-secondary); font-weight: 700; }

/* Compact terminal table (Objective 7) */
.analytics-macro-terminal-table td,
.analytics-macro-terminal-table th { padding-top: 5px !important; padding-bottom: 5px !important; }
.analytics-macro-terminal-table th { height: 22px; }
.analytics-macro-terminal-table .mono { font-variant-numeric: tabular-nums; }

/* ~35% shorter Growth Matrix (Objective 8) */
.deskv2-quadrant { padding: 10px 12px !important; min-height: 0 !important; }
.deskv2-quadrant-grid { gap: 6px !important; }
.deskv2-quadrant-legend { font-size: 10px !important; gap: 8px !important; margin-top: 6px !important; }
.deskv2-quadrant-cell { padding: 6px !important; }

/* Loading state: keep previous country visible (Objective 13) */
.macro-country-loading { opacity: 0.6; transition: opacity 0.2s; }

@media (max-width: 800px) {
  .macro-country-menu { width: 240px; }
  .macro-country-meta-strip { gap: 10px; }
}


/* ─────────────────────────────────────────────────────────────
   Transmission Intelligence Platform (monochrome, Brand v2)
   ───────────────────────────────────────────────────────────── */

/* Explorer drawer (reuses RightRailDrawer) */
.transmission-explorer-drawer .tx-explorer { font-size: 12px; color: var(--color-text-primary); }
.tx-section { border-top: 1px solid rgba(160,160,160,0.12); padding: 10px 2px; }
.tx-section:first-child { border-top: 0; }
.tx-section-head { display: flex; align-items: center; gap: 6px; cursor: pointer; margin-bottom: 6px; }
.tx-section-head strong { font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--color-text-secondary); }
.tx-chevron { color: var(--color-text-muted); font-size: 10px; }
.tx-empty { color: var(--color-text-muted); font-style: italic; padding: 8px 0; }

.tx-chain { list-style: none; margin: 0; padding: 0; }
.tx-chain-node { list-style: none; }
.tx-chain-btn { display: flex; align-items: center; gap: 8px; width: 100%; text-align: left; background: none; border: 0; padding: 5px 6px; border-radius: var(--radius-md); color: var(--color-text-primary); cursor: pointer; }
.tx-chain-btn:hover { background: rgba(160,160,160,0.08); }
.tx-node-label { font-weight: 600; }
.tx-confidence-chip { margin-left: auto; font-size: 10px; color: var(--color-text-muted); }
.tx-glyph.up { color: var(--color-data-up, var(--color-success)); }
.tx-glyph.down { color: var(--color-data-down, #ef4444); }
.tx-glyph.flat { color: var(--color-text-muted); }

.tx-confidence-row { display: flex; align-items: baseline; gap: 10px; }
.tx-confidence-big { font-size: 22px; font-weight: 800; }
.tx-stars { color: var(--color-text-muted); letter-spacing: 1px; }

.tx-horizons { list-style: none; margin: 0; padding: 0; }
.tx-horizon-row { display: grid; grid-template-columns: 90px 1fr; gap: 8px; padding: 4px 0; align-items: baseline; }
.tx-horizon-label { font-weight: 700; font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; }
.tx-horizon-window { color: var(--color-text-secondary); font-size: 11px; }

.tx-affected-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(90px, 1fr)); gap: 8px; }
.tx-affected-col { display: flex; flex-direction: column; gap: 2px; }
.tx-affected-title { font-size: 9px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--color-text-muted); }
.tx-affected-list { margin: 0; padding-left: 14px; font-size: 11px; }
.tx-affected-empty { color: var(--color-text-muted); }

.tx-evidence-row { display: grid; grid-template-columns: 80px 1fr; gap: 8px; padding: 3px 0; }
.tx-evidence-row em { color: var(--color-text-muted); font-style: normal; font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; }
.tx-evidence-row span { color: var(--color-text-secondary); font-size: 11px; }

.tx-related { display: flex; flex-wrap: wrap; gap: 6px; }
.tx-related-btn { background: rgba(160,160,160,0.06); border: 1px solid rgba(160,160,160,0.22); border-radius: var(--radius-md); color: var(--color-text-secondary); font-size: 11px; padding: 5px 9px; cursor: pointer; }
.tx-related-btn:hover { border-color: rgba(160,160,160,0.4); color: var(--color-text-primary); }
.tx-decision-context { display: flex; gap: 12px; }
.tx-dc-link { color: var(--color-text-secondary); font-size: 11px; border-bottom: 1px dotted rgba(160,160,160,0.4); }

/* Compact contextual cards (reused across workspaces) */
.tx-active-card .tx-mini-chain, .tx-mini-chain { list-style: none; margin: 8px 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
.tx-mini-node { display: flex; align-items: center; gap: 6px; font-size: 12px; }
.tx-mini-arrow { color: var(--color-text-muted); margin-left: 2px; }
.tx-active-foot { display: flex; align-items: center; justify-content: space-between; margin-top: 8px; gap: 8px; }
.tx-open-explorer { background: none; border: 0; color: var(--color-interactive, var(--color-warning)); font-size: 11px; font-weight: 700; cursor: pointer; padding: 0; }
.tx-open-explorer:hover { text-decoration: underline; }
.tx-confidence-badge { font-size: 10px; color: var(--color-text-secondary); }
.tx-horizon-tag { font-size: 10px; color: var(--color-text-muted); text-transform: uppercase; letter-spacing: 0.04em; }
.tx-kv { display: flex; justify-content: space-between; gap: 8px; padding: 3px 0; font-size: 11px; }
.tx-kv em { color: var(--color-text-muted); font-style: normal; text-transform: uppercase; letter-spacing: 0.04em; font-size: 10px; }
.tx-kv strong { font-weight: 700; }
.tx-pos { color: var(--color-data-up, var(--color-success)); }
.tx-neg { color: var(--color-data-down, #ef4444); }
.tx-neu { color: var(--color-text-secondary); }
.tx-dep-list { list-style: none; margin: 6px 0; padding: 0; }
.tx-dep-row { display: flex; justify-content: space-between; padding: 3px 0; font-size: 11px; border-bottom: 1px solid rgba(160,160,160,0.08); }
.tx-status-pill { font-size: 10px; color: var(--color-text-secondary); border: 1px solid rgba(160,160,160,0.25); border-radius: var(--radius-md); padding: 2px 6px; }
.tx-watchlist-count { background: none; border: 0; color: var(--color-interactive, var(--color-warning)); font-size: 10px; cursor: pointer; }
.tx-watchlist-count.tx-muted { color: var(--color-text-muted); }
.tx-notif { background: none; border: 0; color: var(--color-text-secondary); font-size: 11px; cursor: pointer; text-align: left; padding: 4px 0; }
.tx-briefing-card { border: 1px solid rgba(160,160,160,0.18); border-radius: var(--radius-lg); padding: 10px; }
.tx-briefing-label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--color-text-muted); display: block; margin-bottom: 6px; }
.tx-ledger-snapshot { border-left: 2px solid rgba(160,160,160,0.25); padding-left: 10px; }

@media (max-width: 800px) {
  .transmission-explorer-drawer { width: 92vw; max-width: 420px; }
  .tx-affected-grid { grid-template-columns: repeat(2, 1fr); }
}

/* Decision Reasoning panel (Phase 6) — monochrome, token-driven, explainable. */
.decision-reasoning-panel {
  border: 1px solid var(--color-border-medium, #262626);
  border-radius: var(--radius-lg, 8px);
  background: var(--color-surface-card, #141414);
  padding: 14px 16px;
  margin: 14px 0;
}
.decision-reasoning-panel-empty { opacity: 0.85; }
.decision-reasoning-rationale {
  margin: 8px 0 10px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--color-text-secondary, #b8b8b8);
}
.decision-reasoning-steps { list-style: none; margin: 0 0 10px; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.decision-reasoning-step {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: baseline;
  gap: 10px;
  padding: 6px 8px;
  border: 1px solid var(--color-border-strong, #3a3a3a);
  background: rgba(160,160,160,0.04);
  border-radius: 0 4px 4px 0;
  font-size: 12px;
}
.decision-reasoning-step.regime { border-color: var(--color-interactive, var(--color-warning)); }
.decision-reasoning-step.signal { border-color: var(--color-data-up, var(--color-success)); }
.decision-reasoning-step.recommendation { border-color: var(--color-interactive, var(--color-warning)); }
.decision-reasoning-step-label { font-weight: 600; color: var(--color-text-primary, #ededed); }
.decision-reasoning-step-detail { color: var(--color-text-secondary, #b8b8b8); }
.decision-reasoning-step-conf { color: var(--color-text-muted, #7a7a7a); font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; }
.decision-reasoning-holdings { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-bottom: 10px; }
.decision-reasoning-holdings-label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-muted, #7a7a7a); }
.decision-reasoning-holding-chip {
  font-size: 11px;
  padding: 2px 8px;
  border: 1px solid var(--color-border-medium, #262626);
  border-radius: var(--radius-md);
  color: var(--color-text-secondary, #b8b8b8);
}
.decision-reasoning-actions { display: flex; }

/* Transmission Explorer v2 — institutional 4-tier intelligence explorer.
   Brand v3: monochrome, dense, token-driven. Width ≈620px desktop, never >40vw on large screens. */
.transmission-explorer-drawer { width: min(620px, 40vw); }

/* Transmission Explorer is a focused review surface, not a persistent rail. */
.right-rail-drawer-overlay:has(.transmission-explorer-drawer) {
  justify-content: center;
  align-items: center;
  padding: 20px;
  background: rgba(2, 6, 23, 0.62);
  backdrop-filter: blur(10px);
}

.right-rail-drawer-overlay:has(.transmission-explorer-drawer) .transmission-explorer-drawer {
  width: min(720px, 100%) !important;
  height: auto;
  max-height: min(760px, calc(100dvh - 40px));
  overflow: auto;
  padding: 18px;
  border: 1px solid var(--color-border-medium);
  border-radius: 16px;
  box-shadow: 0 24px 70px rgba(2, 6, 23, 0.34);
  animation: transmissionExplorerModalIn 180ms ease-out;
}

@keyframes transmissionExplorerModalIn {
  from { transform: translateY(12px) scale(0.985); opacity: 0; }
  to { transform: translateY(0) scale(1); opacity: 1; }
}

@media (max-width: 640px) {
  .right-rail-drawer-overlay:has(.transmission-explorer-drawer) {
    padding: 10px;
  }

  .right-rail-drawer-overlay:has(.transmission-explorer-drawer) .transmission-explorer-drawer {
    max-height: calc(100dvh - 20px);
    padding: 14px;
    border-radius: 14px;
  }
}

/* Transmission Explorer density pass: modal, not drawer. */
.right-rail-drawer-overlay:has(.transmission-explorer-drawer) .transmission-explorer-drawer {
  width: min(640px, calc(100vw - 40px)) !important;
  max-height: min(620px, calc(100dvh - 72px));
  padding: 14px 16px 16px;
}

.transmission-explorer-drawer .right-rail-drawer-head {
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--color-border-subtle, rgba(160, 160, 160, 0.12));
}

.transmission-explorer-drawer .right-rail-drawer-head h2 {
  font-size: 18px;
  line-height: 1.15;
  margin: 0 0 4px;
}

.transmission-explorer-drawer .right-rail-drawer-head p {
  font-size: 12px;
  line-height: 1.25;
