}

.transmission-explorer-drawer .tx-evidence-row em,
.transmission-explorer-drawer .tx-evidence-weight {
  font-size: 9px;
}

.transmission-explorer-drawer .tx-mini-graph,
.transmission-explorer-drawer .tx-deeplinks {
  display: none;
}

@media (max-width: 760px) {
  .right-rail-drawer-overlay:has(.transmission-explorer-drawer) .transmission-explorer-drawer {
    width: min(520px, calc(100vw - 24px)) !important;
    max-height: calc(100dvh - 28px);
    padding: 12px;
  }

  .transmission-explorer-drawer .tx-cards,
  .transmission-explorer-drawer .tx-evidence {
    grid-template-columns: 1fr;
  }
}
.tx-explorer { display: flex; flex-direction: column; gap: 14px; }
.tx-section { border-top: 1px solid var(--color-border-subtle, rgba(160,160,160,0.12)); padding-top: 10px; }
.tx-section:first-child { border-top: 0; padding-top: 0; }

/* Tier 1 — Executive summary */
.tx-exec-summary p { margin: 0; font-size: 13px; line-height: 1.5; color: var(--color-text-secondary, #b8b8b8); }

/* Tier 2 — Transmission timeline (horizontal, clickable) */
.tx-timeline { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.tx-timeline-node { background: rgba(160,160,160,0.06); border: 1px solid var(--color-border-medium, #262626); border-radius: var(--radius-md); color: var(--color-text-primary, #ededed); font-size: 12px; padding: 5px 9px; cursor: pointer; display: inline-flex; flex-direction: column; align-items: flex-start; gap: 2px; }
.tx-timeline-node.active { border-color: var(--color-interactive, var(--color-warning)); }
.tx-timeline-label { font-weight: 600; }
.tx-timeline-arrow { color: var(--color-text-muted, #7a7a7a); }

/* Tier 3 — Transmission cards */
.tx-cards { display: flex; flex-direction: column; gap: 8px; }
.tx-card { border: 1px solid var(--color-border-medium, #262626); border-radius: var(--radius-lg); padding: 10px; background: var(--color-surface-card, #141414); cursor: pointer; }
.tx-card:focus-visible { outline: 2px solid var(--color-interactive, var(--color-warning)); outline-offset: 1px; }
.tx-card-head { display: flex; align-items: center; gap: 6px; margin-bottom: 6px; }
.tx-card-from { color: var(--color-text-muted, #7a7a7a); font-size: 12px; }
.tx-card-arrow { color: var(--color-text-muted, #7a7a7a); }
.tx-card-to { font-size: 13px; }
.tx-card-reason { margin: 0 0 6px; font-size: 12px; color: var(--color-text-secondary, #b8b8b8); }
.tx-card-affected { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 6px; }
.tx-chip { background: rgba(160,160,160,0.06); border: 1px solid var(--color-border-medium, #262626); border-radius: var(--radius-md); color: var(--color-text-secondary, #b8b8b8); font-size: 11px; padding: 2px 7px; cursor: pointer; }
.tx-chip:hover { color: var(--color-text-primary, #ededed); border-color: var(--color-interactive, var(--color-warning)); }
.tx-card-foot { display: flex; justify-content: space-between; font-size: 11px; color: var(--color-text-muted, #7a7a7a); }

/* Tier 4 — Relationship evidence */
.tx-evidence { display: flex; flex-direction: column; gap: 4px; }
.tx-evidence-row { display: grid; grid-template-columns: 110px 1fr auto; gap: 8px; font-size: 12px; padding: 4px 0; border-bottom: 1px solid var(--color-border-subtle, rgba(160,160,160,0.08)); }
.tx-evidence-row em { color: var(--color-text-muted, #7a7a7a); font-style: normal; text-transform: uppercase; letter-spacing: 0.04em; font-size: 10px; }
.tx-evidence-row span { color: var(--color-text-secondary, #b8b8b8); }
.tx-evidence-weight { color: var(--color-interactive, var(--color-warning)); font-size: 10px; text-transform: uppercase; }

/* Mini dependency graph (compact, top-right) */
.tx-mini-graph { border: 1px solid var(--color-border-subtle, rgba(160,160,160,0.12)); border-radius: var(--radius-lg); padding: 10px; }
.tx-graph-nodes { display: flex; flex-direction: column; align-items: flex-start; gap: 4px; }
.tx-graph-node { background: rgba(160,160,160,0.06); border: 1px solid var(--color-border-medium, #262626); border-radius: var(--radius-md); color: var(--color-text-primary, #ededed); font-size: 11px; padding: 3px 8px; cursor: pointer; }
.tx-graph-node.active { border-color: var(--color-interactive, var(--color-warning)); }
.tx-graph-edge { color: var(--color-text-muted, #7a7a7a); padding-left: 6px; }

/* Deep links + empty/loading */
.tx-related { display: flex; flex-wrap: wrap; gap: 6px; }
.tx-related-btn { background: rgba(160,160,160,0.06); border: 1px solid var(--color-border-medium, #262626); border-radius: var(--radius-md); color: var(--color-text-secondary, #b8b8b8); font-size: 11px; padding: 5px 9px; cursor: pointer; }
.tx-related-btn:hover { border-color: var(--color-interactive, var(--color-warning)); color: var(--color-text-primary, #ededed); }
.tx-confidence-chip { font-size: 10px; color: var(--color-text-muted, #7a7a7a); }
.tx-empty-state { border: 0; padding-top: 0; }
.tx-empty-title { margin: 0 0 6px; font-size: 14px; }
.tx-empty-reason { margin: 0 0 8px; font-size: 12px; color: var(--color-text-secondary, #b8b8b8); }
.tx-empty-reasons, .tx-empty-followup ul { margin: 0 0 10px; padding-left: 18px; font-size: 12px; color: var(--color-text-secondary, #b8b8b8); }
.tx-empty-followup span { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-muted, #7a7a7a); }
.tx-loading .tx-skeleton-graph { height: 80px; border: 1px solid var(--color-border-subtle, rgba(160,160,160,0.12)); border-radius: var(--radius-lg); margin-bottom: 10px; background: linear-gradient(90deg, rgba(160,160,160,0.04), rgba(160,160,160,0.08)); }
.tx-skeleton-cards .tx-skel-line { display: block; height: 12px; margin-bottom: 6px; border-radius: var(--radius-md); background: rgba(160,160,160,0.08); }

/* Commodity desk row action buttons (Phase 0) */
.commodity-row-actions { display: inline-flex; gap: 4px; flex-wrap: wrap; }
.commodity-action-btn { background: rgba(160,160,160,0.06); border: 1px solid var(--color-border-medium, #262626); border-radius: var(--radius-md); color: var(--color-text-secondary, #b8b8b8); font-size: 10px; padding: 2px 6px; cursor: pointer; }
.commodity-action-btn:hover { border-color: var(--color-interactive, var(--color-warning)); color: var(--color-text-primary, #ededed); }

/* ── Macro Tier-1 intelligence rail (Phase 1: Liquidity/Rates/Growth/Inflation) ── */
.macro-tier-rail { display: grid; gap: 12px; }
.macro-tier-rail-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; padding: 0 2px; }
.macro-tier-module { display: grid; gap: 12px; }
.macro-tier-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.macro-tier-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 10px; }
.macro-tier-metric { display: grid; gap: 4px; padding: 10px 12px; border: 1px solid var(--color-border-subtle, #262626); border-radius: var(--radius-lg); background: var(--color-surface-elevated, #141414); }
.macro-tier-metric-label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-text-secondary, #b8b8b8); }
.macro-tier-metric-value { font-size: 20px; font-variant-numeric: tabular-nums; color: var(--color-text-primary, #ededed); }
.macro-tier-unit { font-size: 12px; color: var(--color-data-slate, #8a8a8a); }
.macro-tier-metric-sub { display: flex; gap: 12px; font-size: 11px; font-variant-numeric: tabular-nums; color: var(--color-data-slate, #8a8a8a); }
.macro-tier-empty { grid-column: 1 / -1; padding: 14px; font-size: 12px; color: var(--color-data-slate, #8a8a8a); border: 1px dashed var(--color-border-subtle, #262626); border-radius: var(--radius-lg); text-align: center; }

/* ── Macro Phase 2: FX / Central Bank / Financial Conditions ───────────────── */
.macro-fx-module, .macro-cb-module, .macro-fc-module { margin-top: 12px; }
.macro-fx-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; padding: 10px 12px; }
.macro-fx-col-head { font-size: 11px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--color-text-muted, #8a8a8a); margin: 4px 0 6px; }
.macro-fx-row, .macro-cb-row, .macro-fc-row { display: flex; align-items: center; gap: 8px; justify-content: space-between; padding: 4px 0; border-bottom: 1px solid var(--color-border-subtle, #1d1d1d); }
.macro-fx-pair, .macro-cb-name, .macro-fc-label { font-size: 12px; color: var(--color-text-primary, #ededed); flex: 1; }
.macro-fx-value, .macro-cb-rate, .macro-fc-value { font-size: 13px; font-variant-numeric: tabular-nums; color: var(--color-data-neutral, #cfcfcf); }
.macro-fx-note, .macro-cb-next { font-size: 11px; color: var(--color-text-muted, #8a8a8a); }
.macro-fx-dollar { padding: 4px 0 8px; }
.macro-fx-heatmap { padding: 8px 12px 12px; }
.macro-fx-heatmap-row { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
.macro-fx-heat-cell { font-size: 11px; padding: 4px 8px; border: 1px solid var(--color-border-subtle, #262626); border-radius: var(--radius-lg); color: var(--color-text-muted, #8a8a8a); }
.macro-cb-grid, .macro-fc-grid { padding: 10px 12px; }
.macro-cb-rate { font-weight: 600; }

/* ── Macro Phase 4: Cross-Asset + Transmission ─────────────────────────────── */
.macro-ca-module, .macro-tx-module { margin-top: 12px; }
.macro-ca-grid, .macro-tx-grid { padding: 10px 12px; display: grid; gap: 4px; }
.macro-ca-row, .macro-tx-row { display: flex; align-items: center; gap: 8px; justify-content: space-between; padding: 4px 0; border-bottom: 1px solid var(--color-border-subtle, #1d1d1d); }
.macro-ca-symbol, .macro-tx-symbol { font-size: 12px; color: var(--color-text-primary, #ededed); flex: 1; font-variant-numeric: tabular-nums; }
.macro-ca-price, .macro-tx-channel { font-size: 11px; color: var(--color-text-muted, #8a8a8a); }

/* ── Macro Phase 5: Country Profile + Research Workspace ───────────────────── */
.macro-country-profile, .macro-rw-module { margin-top: 12px; }
.macro-cp-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 16px; padding: 12px; }
.macro-cp-item { display: flex; flex-direction: column; gap: 2px; }
.macro-cp-item em { font-size: 10px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--color-text-muted, #8a8a8a); }
.macro-cp-item strong { font-size: 13px; color: var(--color-text-primary, #ededed); }
.macro-coverage-badge { font-size: 11px; padding: 1px 6px; border-radius: var(--radius-md); align-self: flex-start; }
.macro-cp-cross { padding: 0 12px 12px; }
.macro-cp-cross em { font-size: 10px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--color-text-muted, #8a8a8a); }
.macro-cp-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
.macro-cp-chip { font-size: 11px; padding: 3px 8px; border: 1px solid var(--color-border-subtle, #262626); border-radius: var(--radius-lg); color: var(--color-text-secondary, #b9b9b9); }
.macro-cp-chip.muted { color: var(--color-text-muted, #8a8a8a); }
.macro-rw-body { padding: 12px; }
.macro-rw-note { font-size: 12px; color: var(--color-text-muted, #8a8a8a); margin: 0 0 10px; }
.macro-rw-cta { font-size: 12px; padding: 8px 14px; border: 1px solid var(--color-border-subtle, #262626); border-radius: var(--radius-lg); background: transparent; color: var(--color-text-primary, #ededed); cursor: pointer; }
.macro-rw-cta:hover { border-color: var(--color-border-strong, #3a3a3a); }

